# Auto-migrate database on startup
def _env_flag(name):
    return os.environ.get(name, '').strip().lower() in ('1', 'true', 'yes', 'on')


def startup_db_upgrade_disabled():
    """Return True when startup schema/data bootstrap must be skipped."""
    base_dir = os.path.dirname(__file__)
    no_touch_markers = (
        os.path.join(base_dir, 'WMS_NO_DB_TOUCH.flag'),
        os.path.join(base_dir, 'instance', 'WMS_NO_DB_TOUCH.flag'),
    )
    return (
        _env_flag('WMS_SKIP_STARTUP_DB_UPGRADE')
        or _env_flag('WMS_NO_DB_TOUCH')
        or any(os.path.exists(path) for path in no_touch_markers)
    )


def auto_migrate_database():
    """自动迁移数据库，添加缺失的字段"""
    conn = None
    try:
        db_path = os.path.join(os.path.dirname(__file__), 'instance', 'inventory.db')
        if not os.path.exists(db_path):
            return

        import sqlite3
        conn = sqlite3.connect(db_path, timeout=60)
        cursor = conn.cursor()
        cursor.execute('PRAGMA journal_mode=WAL')
        cursor.execute('PRAGMA busy_timeout=60000')
        # Serialize startup schema inspection and DDL across worker processes.
        # Without this transaction two workers can both observe a missing column
        # and then race to execute the same ALTER TABLE statement.
        cursor.execute('BEGIN EXCLUSIVE')

        modified = False

        # out_order 字段迁移
        cursor.execute("PRAGMA table_info(out_order)")
        columns = [row[1] for row in cursor.fetchall()]
        if 'department_id' not in columns:
            cursor.execute("ALTER TABLE out_order ADD COLUMN department_id INTEGER")
            modified = True
        if 'business_type' not in columns:
            cursor.execute("ALTER TABLE out_order ADD COLUMN business_type VARCHAR(50)")
            modified = True
        if 'warehouse' not in columns:
            cursor.execute("ALTER TABLE out_order ADD COLUMN warehouse VARCHAR(100)")
            modified = True
        if 'customer' not in columns:
            cursor.execute("ALTER TABLE out_order ADD COLUMN customer VARCHAR(100)")
            modified = True
        if 'source_sales_order_id' not in columns:
            cursor.execute("ALTER TABLE out_order ADD COLUMN source_sales_order_id INTEGER")
            modified = True
            # 回填：从 purpose 字符串 '来源销售订单 {order_no}' 解析并关联到 sales_order.id
            try:
                cursor.execute("""
                    UPDATE out_order
                    SET source_sales_order_id = (
                        SELECT s.id FROM sales_order s
                        WHERE s.order_no = REPLACE(REPLACE(out_order.purpose, '来源销售订单 ', ''), '来源销售订单', '')
                          AND out_order.purpose LIKE '来源销售订单%'
                    )
                    WHERE out_order.source_sales_order_id IS NULL
                      AND out_order.purpose LIKE '来源销售订单%'
                """)
            except Exception:
                pass  # 回填失败不阻塞启动，sync 函数仍有 purpose 字符串兜底

        # in_order 字段迁移
        cursor.execute("PRAGMA table_info(in_order)")
        in_columns = [row[1] for row in cursor.fetchall()]
        if in_columns and 'warehouse' not in in_columns:
            cursor.execute("ALTER TABLE in_order ADD COLUMN warehouse VARCHAR(100)")
            modified = True
        if in_columns and 'source_purchase_order_id' not in in_columns:
            cursor.execute("ALTER TABLE in_order ADD COLUMN source_purchase_order_id INTEGER")
            modified = True
        if in_columns and 'business_type' not in in_columns:
            cursor.execute("ALTER TABLE in_order ADD COLUMN business_type VARCHAR(50)")
            cursor.execute("""
                UPDATE in_order
                SET business_type = CASE
                    WHEN order_no LIKE 'PI%' OR purpose LIKE '%产品入库%' THEN '产品入库'
                    ELSE '采购入库'
                END
                WHERE business_type IS NULL OR business_type = ''
            """)
            modified = True
        elif in_columns and 'business_type' in in_columns:
            cursor.execute("""
                UPDATE in_order
                SET business_type = CASE
                    WHEN order_no LIKE 'PI%' OR purpose LIKE '%产品入库%' THEN '产品入库'
                    ELSE '采购入库'
                END
                WHERE business_type IS NULL OR business_type = ''
            """)
            if cursor.rowcount and cursor.rowcount > 0:
                modified = True

        cursor.execute("PRAGMA table_info(in_order_item)")
        in_item_columns = [row[1] for row in cursor.fetchall()]
        if in_item_columns and 'source_purchase_order_item_id' not in in_item_columns:
            cursor.execute("ALTER TABLE in_order_item ADD COLUMN source_purchase_order_item_id INTEGER")
            modified = True
        if in_item_columns and 'remark' not in in_item_columns:
            cursor.execute("ALTER TABLE in_order_item ADD COLUMN remark VARCHAR(500)")
            modified = True

        # out_order_item / after_sale_out_order_item / transfer_order_item 新增行备注
        cursor.execute("PRAGMA table_info(out_order_item)")
        out_item_columns = [row[1] for row in cursor.fetchall()]
        if out_item_columns and 'remark' not in out_item_columns:
            cursor.execute("ALTER TABLE out_order_item ADD COLUMN remark VARCHAR(500)")
            modified = True

        cursor.execute("PRAGMA table_info(after_sale_out_order_item)")
        aso_item_columns = [row[1] for row in cursor.fetchall()]
        if aso_item_columns and 'remark' not in aso_item_columns:
            cursor.execute("ALTER TABLE after_sale_out_order_item ADD COLUMN remark VARCHAR(500)")
            modified = True

        cursor.execute("PRAGMA table_info(transfer_order_item)")
        tf_item_columns = [row[1] for row in cursor.fetchall()]
        if tf_item_columns and 'remark' not in tf_item_columns:
            cursor.execute("ALTER TABLE transfer_order_item ADD COLUMN remark VARCHAR(500)")
            modified = True

        # material 新增 remark 字段
        cursor.execute("PRAGMA table_info(material)")
        material_columns = [row[1] for row in cursor.fetchall()]
        if material_columns and 'remark' not in material_columns:
            cursor.execute("ALTER TABLE material ADD COLUMN remark VARCHAR(500)")
            modified = True

        # material_category 新增 code 字段
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS ai_material_alias (
                id INTEGER PRIMARY KEY,
                alias VARCHAR(100) NOT NULL,
                alias_key VARCHAR(120) UNIQUE NOT NULL,
                material_id INTEGER NOT NULL,
                source VARCHAR(50),
                use_count INTEGER DEFAULT 0,
                created_by INTEGER,
                created_at DATETIME,
                updated_at DATETIME
            )
        """)
        cursor.execute("CREATE INDEX IF NOT EXISTS idx_ai_material_alias_material ON ai_material_alias(material_id)")

        # AI_TASK: AI-R07 新增：ai_material_alias 软删除字段（修复 revoke_alias bug）
        cursor.execute("PRAGMA table_info(ai_material_alias)")
        alias_columns = [row[1] for row in cursor.fetchall()]
        if 'disabled' not in alias_columns:
            cursor.execute("ALTER TABLE ai_material_alias ADD COLUMN disabled BOOLEAN DEFAULT 0")
            modified = True
        if 'disabled_reason' not in alias_columns:
            cursor.execute("ALTER TABLE ai_material_alias ADD COLUMN disabled_reason VARCHAR(100) DEFAULT ''")
            modified = True

        # AI_TASK: AI-R17-F01 ai_tool_call 扩展字段（灰度拒绝审计：用户/角色/原因/来源/阶段）
        cursor.execute("PRAGMA table_info(ai_tool_call)")
        ai_tc_columns = [row[1] for row in cursor.fetchall()]
        if ai_tc_columns:
            if 'user_id' not in ai_tc_columns:
                cursor.execute("ALTER TABLE ai_tool_call ADD COLUMN user_id INTEGER")
                modified = True
            if 'role' not in ai_tc_columns:
                cursor.execute("ALTER TABLE ai_tool_call ADD COLUMN role VARCHAR(20)")
                modified = True
            if 'denied_reason' not in ai_tc_columns:
                cursor.execute("ALTER TABLE ai_tool_call ADD COLUMN denied_reason VARCHAR(300)")
                modified = True
            if 'source' not in ai_tc_columns:
                cursor.execute("ALTER TABLE ai_tool_call ADD COLUMN source VARCHAR(20)")
                modified = True
            if 'denied_stage' not in ai_tc_columns:
                cursor.execute("ALTER TABLE ai_tool_call ADD COLUMN denied_stage VARCHAR(20)")
                modified = True
            # 拒绝审计索引（不阻塞已存在表）
            try:
                cursor.execute("CREATE INDEX IF NOT EXISTS idx_ai_tool_call_denied ON ai_tool_call(permission_allowed, created_at)")
                cursor.execute("CREATE INDEX IF NOT EXISTS idx_ai_tool_call_user_source ON ai_tool_call(user_id, source, created_at)")
            except Exception:
                pass
        # AI_TASK: AI-R17-F01 新表：回滚事件、人工降级任务、灰度审计
        # （SQLAlchemy db.create_all() 会在启动时创建缺失的表，这里只补索引兜底）
        # AI_TASK: AI-R17-F02 新表：每日验收快照、七天证据包
        # （SQLAlchemy db.create_all() 会在启动时创建缺失的表，这里只补索引兜底）
        try:
            cursor.execute("CREATE INDEX IF NOT EXISTS idx_ai_acceptance_snapshot_created ON ai_acceptance_daily_snapshot(created_at)")
            cursor.execute("CREATE INDEX IF NOT EXISTS idx_ai_evidence_package_dates ON ai_acceptance_evidence_package(start_date, end_date)")
            cursor.execute("CREATE INDEX IF NOT EXISTS idx_ai_evidence_package_decision ON ai_acceptance_evidence_package(go_no_go_decision)")
        except Exception:
            pass

        cursor.execute("PRAGMA table_info(material_category)")
        cat_columns = [row[1] for row in cursor.fetchall()]
        if 'code' not in cat_columns:
            cursor.execute("ALTER TABLE material_category ADD COLUMN code VARCHAR(50)")
            cursor.execute("UPDATE material_category SET code = 'CAT-' || id WHERE code IS NULL OR code = ''")
            modified = True
        if 'parent_id' not in cat_columns:
            cursor.execute("ALTER TABLE material_category ADD COLUMN parent_id INTEGER")
            modified = True

        # unit 新增 code 字段
        cursor.execute("PRAGMA table_info(unit)")
        unit_columns = [row[1] for row in cursor.fetchall()]
        if 'code' not in unit_columns:
            cursor.execute("ALTER TABLE unit ADD COLUMN code VARCHAR(50)")
            cursor.execute("UPDATE unit SET code = 'U-' || id WHERE code IS NULL OR code = ''")
            modified = True

        # supplier 新增 code 字段
        cursor.execute("PRAGMA table_info(supplier)")
        sup_cols = [row[1] for row in cursor.fetchall()]
        if 'code' not in sup_cols:
            cursor.execute("ALTER TABLE supplier ADD COLUMN code VARCHAR(50)")
            cursor.execute("UPDATE supplier SET code = 'SUP-' || id WHERE code IS NULL OR code = ''")
            modified = True

        # customer master data table
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS customer (
                id INTEGER PRIMARY KEY,
                code VARCHAR(50) UNIQUE NOT NULL,
                name VARCHAR(100) UNIQUE NOT NULL,
                contact VARCHAR(50),
                phone VARCHAR(20),
                address VARCHAR(200),
                created_at DATETIME
            )
        """)
        cursor.execute("SELECT id FROM customer LIMIT 1")
        has_customer_rows = cursor.fetchone() is not None
        if not has_customer_rows:
            names = []
            cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='out_order'")
            if cursor.fetchone():
                cursor.execute("SELECT DISTINCT customer FROM out_order WHERE customer IS NOT NULL AND TRIM(customer) <> ''")
                names.extend(row[0].strip() for row in cursor.fetchall() if row and row[0])
            cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='after_sale_out_order'")
            if cursor.fetchone():
                cursor.execute("SELECT DISTINCT customer FROM after_sale_out_order WHERE customer IS NOT NULL AND TRIM(customer) <> ''")
                names.extend(row[0].strip() for row in cursor.fetchall() if row and row[0])
            seen = set()
            next_no = 1
            for name in names:
                key = name.lower()
                if key in seen:
                    continue
                seen.add(key)
                cursor.execute(
                    "INSERT OR IGNORE INTO customer (code, name, created_at) VALUES (?, ?, CURRENT_TIMESTAMP)",
                    (f"CUS-{next_no:03d}", name)
                )
                next_no += 1
            if seen:
                modified = True

        # purchase_request_item 新增 supplier_name 字段，保存手工输入的推荐供应商
        cursor.execute("PRAGMA table_info(purchase_request_item)")
        purchase_request_item_cols = [row[1] for row in cursor.fetchall()]
        if purchase_request_item_cols and 'supplier_name' not in purchase_request_item_cols:
            cursor.execute("ALTER TABLE purchase_request_item ADD COLUMN supplier_name VARCHAR(100)")
            cursor.execute("""
                UPDATE purchase_request_item
                SET supplier_name = (
                    SELECT supplier.name
                    FROM supplier
                    WHERE supplier.id = purchase_request_item.supplier_id
                )
                WHERE supplier_id IS NOT NULL
            """)
            modified = True

        # transfer_order_item 新增价格/金额字段，兼容调拨详情页的明细显示和编辑
        cursor.execute("PRAGMA table_info(transfer_order_item)")
        transfer_item_cols = [row[1] for row in cursor.fetchall()]
        if transfer_item_cols:
            if 'price' not in transfer_item_cols:
                cursor.execute("ALTER TABLE transfer_order_item ADD COLUMN price FLOAT DEFAULT 0")
                modified = True
            if 'amount' not in transfer_item_cols:
                cursor.execute("ALTER TABLE transfer_order_item ADD COLUMN amount FLOAT DEFAULT 0")
                modified = True

        # 微信分享配置字段
        cursor.execute("PRAGMA table_info(wechat_share_config)")
        wechat_share_cols = [row[1] for row in cursor.fetchall()]
        if wechat_share_cols and 'auto_send' not in wechat_share_cols:
            cursor.execute("ALTER TABLE wechat_share_config ADD COLUMN auto_send BOOLEAN DEFAULT 0")
            modified = True

        # sales_order 字段扩展：业务员、项目号、币别、结算方式、未税/税额/已发货/未发货金额
        cursor.execute("PRAGMA table_info(sales_order)")
        sales_order_cols = [row[1] for row in cursor.fetchall()]
        if sales_order_cols:
            if 'salesperson_id' not in sales_order_cols:
                cursor.execute("ALTER TABLE sales_order ADD COLUMN salesperson_id INTEGER")
                modified = True
            if 'project_no' not in sales_order_cols:
                cursor.execute("ALTER TABLE sales_order ADD COLUMN project_no VARCHAR(100)")
                modified = True
            if 'currency' not in sales_order_cols:
                cursor.execute("ALTER TABLE sales_order ADD COLUMN currency VARCHAR(20) DEFAULT 'CNY'")
                modified = True
            if 'settlement_method' not in sales_order_cols:
                cursor.execute("ALTER TABLE sales_order ADD COLUMN settlement_method VARCHAR(50)")
                modified = True
            if 'untaxed_amount' not in sales_order_cols:
                cursor.execute("ALTER TABLE sales_order ADD COLUMN untaxed_amount FLOAT DEFAULT 0")
                modified = True
            if 'tax_amount' not in sales_order_cols:
                cursor.execute("ALTER TABLE sales_order ADD COLUMN tax_amount FLOAT DEFAULT 0")
                modified = True
            if 'shipped_amount' not in sales_order_cols:
                cursor.execute("ALTER TABLE sales_order ADD COLUMN shipped_amount FLOAT DEFAULT 0")
                modified = True
            if 'remaining_amount' not in sales_order_cols:
                cursor.execute("ALTER TABLE sales_order ADD COLUMN remaining_amount FLOAT DEFAULT 0")
                modified = True

        # sales_order_item 字段扩展：税率、未税单价/未税金额/税额/含税金额、批次号、序列号
        cursor.execute("PRAGMA table_info(sales_order_item)")
        sales_item_cols = [row[1] for row in cursor.fetchall()]
        if sales_item_cols:
            if 'tax_rate' not in sales_item_cols:
                cursor.execute("ALTER TABLE sales_order_item ADD COLUMN tax_rate FLOAT DEFAULT 0.13")
                modified = True
            if 'untaxed_price' not in sales_item_cols:
                cursor.execute("ALTER TABLE sales_order_item ADD COLUMN untaxed_price FLOAT DEFAULT 0")
                modified = True
            if 'untaxed_amount' not in sales_item_cols:
                cursor.execute("ALTER TABLE sales_order_item ADD COLUMN untaxed_amount FLOAT DEFAULT 0")
                modified = True
            if 'tax_amount' not in sales_item_cols:
                cursor.execute("ALTER TABLE sales_order_item ADD COLUMN tax_amount FLOAT DEFAULT 0")
                modified = True
            if 'tax_included_amount' not in sales_item_cols:
                cursor.execute("ALTER TABLE sales_order_item ADD COLUMN tax_included_amount FLOAT DEFAULT 0")
                modified = True
            if 'batch_no' not in sales_item_cols:
                cursor.execute("ALTER TABLE sales_order_item ADD COLUMN batch_no VARCHAR(100)")
                modified = True
            if 'serial_no' not in sales_item_cols:
                cursor.execute("ALTER TABLE sales_order_item ADD COLUMN serial_no VARCHAR(200)")
                modified = True
            # 旧数据补齐：amount 已存在，把 tax_included_amount=amount, tax_rate=0.13, 反推 untaxed_amount/tax_amount
            cursor.execute("""
                UPDATE sales_order_item
                SET tax_included_amount = amount,
                    untaxed_amount = ROUND(amount / (1 + COALESCE(tax_rate, 0.13)), 2),
                    tax_amount = ROUND(amount - amount / (1 + COALESCE(tax_rate, 0.13)), 2),
                    untaxed_price = CASE WHEN quantity > 0 THEN ROUND(amount / (1 + COALESCE(tax_rate, 0.13)) / quantity, 4) ELSE 0 END
                WHERE tax_included_amount IS NULL OR tax_included_amount = 0
            """)
            if cursor.rowcount and cursor.rowcount > 0:
                modified = True

        # 修复物料空分类/单位：设默认值
        default_unit_id = None
        default_cat_id = None
        cursor.execute("SELECT id FROM unit WHERE name='个' LIMIT 1")
        row = cursor.fetchone()
        if row:
            default_unit_id = row[0]
        if not default_unit_id:
            cursor.execute("SELECT id FROM unit LIMIT 1")
            row = cursor.fetchone()
            if row:
                default_unit_id = row[0]
        cursor.execute("SELECT id FROM material_category WHERE name='默认分类' LIMIT 1")
        row = cursor.fetchone()
        if row:
            default_cat_id = row[0]
        if not default_cat_id:
            cursor.execute("SELECT id FROM material_category LIMIT 1")
            row = cursor.fetchone()
            if row:
                default_cat_id = row[0]
        if default_unit_id:
            cursor.execute("UPDATE material SET unit_id = ? WHERE unit_id IS NULL OR unit_id = 0", (default_unit_id,))
            modified = True
        if default_cat_id:
            cursor.execute("UPDATE material SET category_id = ? WHERE category_id IS NULL OR category_id = 0", (default_cat_id,))
            modified = True

        if modified:
            conn.commit()
    except Exception as e:
        # 迁移失败必须记录日志，避免管理员无法感知迁移异常导致后续运行时才暴露问题
        try:
            logging.getLogger(__name__).error(f'auto_migrate_database 迁移失败: {e}', exc_info=True)
        except Exception:
            pass
        raise
    finally:
        # 连接关闭必须放在 finally，避免中途异常导致 sqlite3 连接泄漏（WAL 锁、备份失败）
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass

app = Flask(__name__)

# Run auto-migration before app configuration unless explicitly disabled.
if startup_db_upgrade_disabled():
    print('[DB] Startup database upgrade skipped by environment.', flush=True)
else:
    auto_migrate_database()

# Use config.py settings uniformly
env = os.environ.get('FLASK_ENV', 'production')
app.config.from_object(config_dict.get(env, config_dict['default']))
if env == 'production' and not os.environ.get('SECRET_KEY') and not _env_flag('WMS_ALLOW_AUTO_SECRET_KEY'):
    raise RuntimeError(
        'SECRET_KEY is required in production. Set the SECRET_KEY environment variable, '
        'or set WMS_ALLOW_AUTO_SECRET_KEY=1 only for a controlled local/offline deployment.'
    )
if not app.config.get('SECRET_KEY'):
    # 未显式配置 SECRET_KEY 时，尝试从 instance/secret_key 文件读取持久化密钥；
    # 文件不存在则随机生成并写入，避免每次重启 session 失效，同时不依赖硬编码默认值。
    _secret_key_file = os.path.join(os.path.dirname(__file__), 'instance', 'secret_key')
    _persisted_key = None
    try:
        with open(_secret_key_file, 'r', encoding='utf-8') as _sk_f:
            _persisted_key = _sk_f.read().strip()
    except OSError:
        _persisted_key = None
    if _persisted_key and len(_persisted_key) >= 32:
        app.config['SECRET_KEY'] = _persisted_key
    else:
        _new_key = secrets.token_hex(32)
        app.config['SECRET_KEY'] = _new_key
        try:
            os.makedirs(os.path.dirname(_secret_key_file), exist_ok=True)
            with open(_secret_key_file, 'w', encoding='utf-8') as _sk_f:
                _sk_f.write(_new_key)
            try:
                os.chmod(_secret_key_file, 0o600)
            except OSError:
                pass
        except OSError as _sk_err:
            app.logger.error(f'无法持久化 SECRET_KEY: {_sk_err}')
        app.logger.warning('SECRET_KEY not set. A random key was generated and persisted to instance/secret_key. Set the SECRET_KEY environment variable for explicit control.')

# WECHAT_HELPER_TOKEN 未显式配置时，同样从 instance/wechat_helper_token 读取或随机生成并持久化，
# 避免使用公开默认值导致微信助手接口可被任意访问
if not app.config.get('WECHAT_HELPER_TOKEN'):
    _wh_token_file = os.path.join(os.path.dirname(__file__), 'instance', 'wechat_helper_token')
    _persisted_wh_token = None
    try:
        with open(_wh_token_file, 'r', encoding='utf-8') as _wh_f:
            _persisted_wh_token = _wh_f.read().strip()
    except OSError:
        _persisted_wh_token = None
    if _persisted_wh_token and len(_persisted_wh_token) >= 16:
        app.config['WECHAT_HELPER_TOKEN'] = _persisted_wh_token
    else:
        _new_wh_token = secrets.token_hex(16)
        app.config['WECHAT_HELPER_TOKEN'] = _new_wh_token
        try:
            os.makedirs(os.path.dirname(_wh_token_file), exist_ok=True)
            with open(_wh_token_file, 'w', encoding='utf-8') as _wh_f:
                _wh_f.write(_new_wh_token)
            try:
                os.chmod(_wh_token_file, 0o600)
            except OSError:
                pass
        except OSError as _wh_err:
            app.logger.error(f'无法持久化 WECHAT_HELPER_TOKEN: {_wh_err}')
        app.logger.warning('WECHAT_HELPER_TOKEN not set. A random token was generated and persisted to instance/wechat_helper_token.')

# Log directory and file
