def purchase_request_item_has_material(item):
    return bool(
        getattr(item, 'material_id', None) or
        (getattr(item, 'material_code', None) or '').strip() or
        (getattr(item, 'material_name', None) or '').strip()
    )


def purchase_request_item_data_has_material(item_data):
    if not isinstance(item_data, dict):
        return False
    return bool(
        item_data.get('material_id') or
        (item_data.get('material_code') or item_data.get('code') or '').strip() or
        (item_data.get('material_name') or item_data.get('name') or '').strip()
    )


def update_purchase_order_status(order):
    if not order:
        return
    if order.status == 'closed':
        return
    items = list(order.items or [])
    if not items:
        order.status = 'pending'
        order.total_amount = 0
        return
    total_amount = 0
    total_qty = 0
    received_qty = 0
    completed_by_item = {}
    item_ids = [item.id for item in items if item.id]
    if item_ids:
        completed_rows = db.session.query(
            InOrderItem.source_purchase_order_item_id,
            func.coalesce(func.sum(InOrderItem.quantity), 0),
        ).join(InOrder, InOrderItem.in_order_id == InOrder.id).filter(
            InOrderItem.source_purchase_order_item_id.in_(item_ids),
            InOrder.status == 'completed',
        ).group_by(InOrderItem.source_purchase_order_item_id).all()
        completed_by_item = {
            item_id: round_to_2_decimals(quantity or 0)
            for item_id, quantity in completed_rows
        }
    for item in items:
        item.amount = round_to_2_decimals((item.quantity or 0) * (item.price or 0))
        total_amount += item.amount or 0
        total_qty += item.quantity or 0
        received_qty += completed_by_item.get(item.id, 0)
    order.total_amount = round_to_2_decimals(total_amount)
    if received_qty <= 0:
        order.status = 'pending'
    elif received_qty + STOCK_COMPARE_EPSILON >= total_qty:
        order.status = 'completed'
    else:
        order.status = 'partial'


def is_purchase_in_order(order):
    return (getattr(order, 'business_type', None) or '采购入库') == '采购入库'


def validate_purchase_in_order_source(order):
    if not order or not is_purchase_in_order(order) or not purchase_in_order_requires_order():
        return True, None
    items = list(order.items or [])
    if not items:
        return True, None
    if any(not item.source_purchase_order_item_id for item in items):
        return False, '采购入库必须关联采购订单，请从采购订单下推或选单生成入库单'
    return True, None


def should_block_purchase_over_receive():
    return purchase_receipt_strict_order() and purchase_over_receive_control_mode() == 'forbid'


def validate_purchase_receive_quantity(source_item, receive_qty, material_code=None):
    if not source_item or not should_block_purchase_over_receive():
        return True, None
    remain_qty = round_to_2_decimals((source_item.quantity or 0) - (source_item.received_quantity or 0))
    if receive_qty - remain_qty > STOCK_COMPARE_EPSILON:
        code = material_code or (source_item.material.code if source_item.material else source_item.material_id)
        return False, f'物料 {code} 入库数量不能大于采购单未入库数量'
    return True, None


def find_duplicate_in_order_item(order, material_id, source_purchase_order_item_id=None):
    for item in order.items or []:
        if item.material_id != material_id:
            continue
        if (item.source_purchase_order_item_id or None) == (source_purchase_order_item_id or None):
            return item
    return None


def build_purchase_request_execution(valid_items):
    item_ids = [item.id for item in valid_items if item.id]
    ordered_by_item = {item_id: 0 for item_id in item_ids}
    received_by_item = {item_id: 0 for item_id in item_ids}
    if item_ids:
        rows = db.session.query(
            PurchaseOrderItem.purchase_request_item_id,
            func.coalesce(func.sum(PurchaseOrderItem.quantity), 0),
            func.coalesce(func.sum(PurchaseOrderItem.received_quantity), 0),
        ).join(PurchaseOrder, PurchaseOrderItem.purchase_order_id == PurchaseOrder.id).filter(
            PurchaseOrderItem.purchase_request_item_id.in_(item_ids),
            PurchaseOrder.status != 'closed',
        ).group_by(PurchaseOrderItem.purchase_request_item_id).all()
        for item_id, ordered_qty, received_qty in rows:
            ordered_by_item[item_id] = round_to_2_decimals(ordered_qty or 0)
            received_by_item[item_id] = round_to_2_decimals(received_qty or 0)

    execution = {}
    for item in valid_items:
        request_qty = round_to_2_decimals(item.quantity or 0)
        ordered_qty = round_to_2_decimals(ordered_by_item.get(item.id, 0))
        received_qty = round_to_2_decimals(received_by_item.get(item.id, 0))
        remaining_to_order = round_to_2_decimals(max(request_qty - ordered_qty, 0))
        remaining_to_receive = round_to_2_decimals(max(ordered_qty - received_qty, 0))
        if received_qty + STOCK_COMPARE_EPSILON >= request_qty and request_qty > 0:
            status = 'completed'
        elif ordered_qty > 0 or received_qty > 0:
            status = 'partial'
        else:
            status = 'pending'
        execution[item.id] = {
            'request_quantity': request_qty,
            'ordered_quantity': ordered_qty,
            'received_quantity': received_qty,
            'remaining_to_order': remaining_to_order,
            'remaining_to_receive': remaining_to_receive,
            'status': status,
        }
    return execution


def build_purchase_order_execution(order):
    items = list(order.items or [])
    item_ids = [item.id for item in items if item.id]
    completed_by_item = {item_id: 0 for item_id in item_ids}
    if item_ids:
        rows = db.session.query(
            InOrderItem.source_purchase_order_item_id,
            func.coalesce(func.sum(InOrderItem.quantity), 0),
        ).join(InOrder, InOrderItem.in_order_id == InOrder.id).filter(
            InOrderItem.source_purchase_order_item_id.in_(item_ids),
            InOrder.status == 'completed',
        ).group_by(InOrderItem.source_purchase_order_item_id).all()
        for item_id, completed_qty in rows:
            completed_by_item[item_id] = round_to_2_decimals(completed_qty or 0)

    execution = {}
    for item in items:
        order_qty = round_to_2_decimals(item.quantity or 0)
        pushed_qty = round_to_2_decimals(item.received_quantity or 0)
        completed_qty = round_to_2_decimals(completed_by_item.get(item.id, 0))
        pending_receive_qty = round_to_2_decimals(max(pushed_qty - completed_qty, 0))
        remaining_to_push = round_to_2_decimals(max(order_qty - pushed_qty, 0))
        if order.status == 'closed':
            status = 'closed'
        elif completed_qty + STOCK_COMPARE_EPSILON >= order_qty and order_qty > 0:
            status = 'completed'
        elif completed_qty > 0:
            status = 'partial_completed'
        elif pushed_qty > 0:
            status = 'pushed'
        else:
            status = 'pending'
        execution[item.id] = {
            'order_quantity': order_qty,
            'pushed_quantity': pushed_qty,
            'completed_quantity': completed_qty,
            'pending_receive_quantity': pending_receive_qty,
            'remaining_to_push': remaining_to_push,
            'status': status,
        }
    return execution


def purchase_order_status_label(status):
    return {
        'pending': '未入库',
        'partial': '部分入库',
        'completed': '已入库',
        'closed': '已关闭',
    }.get(status, status or '-')


def build_purchase_order_todo_summary():
    summary_rows = db.session.query(
        PurchaseOrder.status,
        func.count(PurchaseOrder.id),
        func.coalesce(func.sum(PurchaseOrder.total_amount), 0)
    ).group_by(PurchaseOrder.status).all()
    summary = {
        'pending_count': 0,
        'partial_count': 0,
        'completed_count': 0,
        'closed_count': 0,
        'pending_amount': 0,
        'partial_amount': 0,
        'completed_amount': 0,
        'closed_amount': 0,
        'open_count': 0,
        'open_amount': 0,
        'overdue_count': 0,
        'remaining_qty': 0,
    }
    for status, count, amount in summary_rows:
        summary[f'{status}_count'] = count or 0
        summary[f'{status}_amount'] = round_to_2_decimals(amount or 0)
    remaining_row = db.session.query(
        func.coalesce(func.sum(PurchaseOrderItem.quantity - PurchaseOrderItem.received_quantity), 0)
    ).join(PurchaseOrder, PurchaseOrderItem.purchase_order_id == PurchaseOrder.id).filter(
        PurchaseOrder.status.in_(('pending', 'partial'))
    ).first()
    summary['remaining_qty'] = round_to_2_decimals(remaining_row[0] if remaining_row else 0)
    summary['overdue_count'] = PurchaseOrder.query.filter(
        PurchaseOrder.status.in_(('pending', 'partial')),
        PurchaseOrder.expected_date.isnot(None),
        PurchaseOrder.expected_date < date.today()
    ).count()
    summary['open_count'] = summary['pending_count'] + summary['partial_count']
    summary['open_amount'] = round_to_2_decimals(summary['pending_amount'] + summary['partial_amount'])
    return summary


