def ensure_bootstrap_admin_user():
    """Create an initial admin account when the user table is empty."""
    if User.query.count() > 0:
        return None

    username = (os.environ.get('WMS_BOOTSTRAP_USERNAME') or 'admin').strip() or 'admin'
    # 禁止系统生成随机密码（AGENTS.md 规则）：未设置环境变量时使用固定默认 'admin' 并警告弱密码
    password = os.environ.get('WMS_BOOTSTRAP_PASSWORD') or 'admin'
    if not os.environ.get('WMS_BOOTSTRAP_PASSWORD'):
        app.logger.warning(
            "WMS_BOOTSTRAP_PASSWORD not set. Using default password 'admin'. "
            "Please set WMS_BOOTSTRAP_PASSWORD environment variable for a secure password."
        )
    user = User(
        username=username,
        password_hash=generate_password_hash(password),
        role='admin',
        status='normal',
        created_at=datetime.now(),
    )
    db.session.add(user)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f"Failed to create bootstrap admin user: {e}")
        raise
    app.logger.warning("Bootstrap admin account created: username=%s. Please change the password after first login.", username)
    return user


def ensure_admin_user_exists():
    """Ensure admin user exists; create if missing, unlock only if disabled."""
    user = User.query.filter_by(username='admin').first()
    if user:
        # 仅在账号被显式 disabled 时启动期解锁；is_locked（因登录失败次数过多触发的临时锁定）
        # 应等待 locked_until 自然到期，避免攻击者通过触发重启重置锁定计数绕过暴力破解保护。
        if user.status == 'disabled':
            user.status = 'normal'
            try:
                db.session.commit()
            except Exception as e:
                db.session.rollback()
                app.logger.error(f"Failed to unlock admin account: {e}")
            app.logger.info("Admin account unlocked (was disabled)")
        return user

    bootstrap_password = os.environ.get('WMS_BOOTSTRAP_PASSWORD') or 'admin'
    if not os.environ.get('WMS_BOOTSTRAP_PASSWORD'):
        app.logger.warning(
            "WMS_BOOTSTRAP_PASSWORD not set. Using default password 'admin'. "
            "Please set WMS_BOOTSTRAP_PASSWORD environment variable for a secure password."
        )
    user = User(
        username='admin',
        password_hash=generate_password_hash(bootstrap_password),
        role='admin',
        status='normal',
        created_at=datetime.now(),
    )
    db.session.add(user)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f"Failed to create admin user: {e}")
        raise
    app.logger.warning("Admin user created with default password 'admin'. Please set WMS_BOOTSTRAP_PASSWORD for a secure password.")
    return user


def initialize_database():
    """Create missing tables and ensure the bootstrap admin account exists."""
    if startup_db_upgrade_disabled():
        app.logger.warning('Startup database initialization skipped by environment.')
        return

    # SQLite 并发优化：WAL 允许读写并发，busy_timeout 避免短暂写锁直接失败。
    from sqlalchemy import event as sa_event
    @sa_event.listens_for(db.engine, 'connect')
    def set_sqlite_pragma(dbapi_connection, connection_record):
        cursor = dbapi_connection.cursor()
        cursor.execute('PRAGMA journal_mode=WAL')
        cursor.execute('PRAGMA busy_timeout=30000')
        cursor.execute('PRAGMA foreign_keys=ON')
        cursor.close()

    db.create_all()
    ensure_bootstrap_admin_user()
    ensure_admin_user_exists()
    ensure_default_warehouses()
    ensure_default_system_settings()
    ensure_default_print_templates()
    ensure_material_category_tree_defaults()
    _wechat_share_default_config()
    # 修复已有物料的空分类/单位
    try:
        default_unit = Unit.query.filter_by(name='个').first() or Unit.query.first()
        default_cat = MaterialCategory.query.filter_by(name='默认分类').first() or MaterialCategory.query.first()
        if default_unit:
            cnt = Material.query.filter(db.or_(Material.unit_id.is_(None), Material.unit_id == 0)).update(
                {Material.unit_id: default_unit.id}, synchronize_session=False)
            if cnt:
                app.logger.info(f'修复物料单位: {cnt} 条 → "{default_unit.name}"')
        if default_cat:
            cnt = Material.query.filter(db.or_(Material.category_id.is_(None), Material.category_id == 0)).update(
                {Material.category_id: default_cat.id}, synchronize_session=False)
            if cnt:
                app.logger.info(f'修复物料分类: {cnt} 条 → "{default_cat.name}"')
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.warning(f'修复物料字段跳过: {e}')


# ==================== Login management ====================

@login_manager.user_loader
def load_user(user_id):
    return db.session.get(User, int(user_id))


def get_request_ip():
    """Return the client IP, respecting reverse proxy headers."""
    forwarded_for = request.headers.get('X-Forwarded-For', '')
    if forwarded_for:
        return forwarded_for.split(',')[0].strip()
    return request.remote_addr or ''


def get_next_target():
    if request.query_string:
        return f'{request.path}?{request.query_string.decode("utf-8")}'
    return request.path


def is_safe_redirect_target(target):
    if not target:
        return False

    ref_url = urlparse(request.host_url)
    test_url = urlparse(urljoin(request.host_url, target))

    if test_url.scheme not in {'http', 'https'}:
        return False
    if test_url.netloc != ref_url.netloc:
        return False
    if test_url.path in {url_for('login'), url_for('logout')}:
        return False
    return True


def resolve_redirect_target(target, default_endpoint='index'):
    if is_safe_redirect_target(target):
        return target
    return url_for(default_endpoint)


def add_login_log(status, username, user=None, fail_reason=None):
    db.session.add(LoginLog(
        user_id=user.id if user else None,
        username=username,
        login_ip=get_request_ip(),
        user_agent=request.headers.get('User-Agent', '')[:500],
        status=status,
        fail_reason=fail_reason
    ))


@login_manager.unauthorized_handler
def unauthorized():
    if wants_json_error_response():
        return jsonify({'status': 'error', 'msg': '未登录或登录已过期'}), 401
    flash('请先登录后再继续', 'warning')
    next_target = get_next_target()
    return redirect(url_for('login', next=next_target))

# ==================== Permission ====================
def get_bearer_user():
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return None
    token_value = auth.split(' ', 1)[1].strip()
    if not token_value:
        return None
    token = ApiToken.query.filter_by(token=token_value, revoked=False).first()
    if not token or token.expires_at < datetime.now():
        return None
    return token.user if token.user and token.user.is_active else None


def api_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        user = get_bearer_user()
        if not user:
            return jsonify({'status': 'error', 'msg': 'Bearer Token 无效或已过期'}), 401
        return f(user, *args, **kwargs)
    return decorated_function


def api_role_required(*roles):
    """Require a bearer token user with one of the allowed business roles."""
    allowed = set(roles or ())

    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            user = get_bearer_user()
            if not user:
                return jsonify({'status': 'error', 'msg': 'Bearer Token 无效或已过期'}), 401
            if user.role != 'admin' and user.role not in allowed:
                return jsonify({'status': 'error', 'msg': '当前账号没有权限执行该操作'}), 403
            return f(user, *args, **kwargs)
        return decorated_function
    return decorator


def web_or_api_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if current_user.is_authenticated:
            return f(*args, **kwargs)
        if get_bearer_user():
            return f(*args, **kwargs)
        return jsonify({'status': 'error', 'success': False, 'msg': '未登录或 Bearer Token 无效'}), 401
    return decorated_function


def role_required(*roles):
    """Require one of the given roles for page access."""
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            if not current_user.is_authenticated:
                flash('请先登录后再继续', 'warning')
                return redirect(url_for('login', next=get_next_target()))
            if current_user.role not in roles:
                flash('当前账号没有权限访问该页面', 'danger')
                return redirect(url_for('index'))
            return f(*args, **kwargs)
        return decorated_function
    return decorator

# ==================== Operation ====================
def log_operation(operation_type, operation_content, target_type=None, target_id=None):
    """Write an operation log record."""
    try:
        if not current_user or not current_user.is_authenticated:
            return

        log = OperationLog(
            user_id=current_user.id,
            operation_type=operation_type or '其他操作',
            operation_content=operation_content or '',
            target_type=target_type,
            target_id=target_id,
            ip_address=request.remote_addr if request else None
        )
        db.session.add(log)
        try:
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            app.logger.error(f'数据库操作失败: {e}')
    except Exception as e:
        db.session.rollback()
        app.logger.error(f'log_operation failed: {e}')


def api_material_payload(material):
    warehouse_code = getattr(material, 'warehouse', '') or ''
    location_code = ''
    if location_management_enabled():
        location_row = LocationInventory.query.filter_by(material_id=material.id).order_by(
            LocationInventory.quantity.desc(),
            LocationInventory.location.asc()
        ).first()
        location_code = location_row.location if location_row else ''
    return {
        'id': material.id,
        'code': material.code or '',
        'name': material.name or '',
        'spec': material.spec or '',
        'unit': material.unit.name if material.unit else '',
        'stock': material.stock or 0,
        'warehouse_code': warehouse_code,
        'location_code': location_code,
    }


def api_json_error(message, status_code=400):
    return jsonify({'status': 'error', 'success': False, 'msg': message, 'message': message}), status_code


def api_json_success(data=None, message='操作成功'):
    return jsonify({'status': 'success', 'success': True, 'msg': message, 'message': message, 'data': data or {}})


def parse_api_lines(payload):
    lines = payload.get('lines') if isinstance(payload, dict) else None
    if not isinstance(lines, list) or not lines:
        return None, '明细不能为空'

    parsed = []
    for index, line in enumerate(lines, start=1):
        if not isinstance(line, dict):
            return None, f'第 {index} 行格式错误'
        code = (line.get('material_code') or line.get('code') or '').strip()
        if not code:
            return None, f'第 {index} 行缺少物料编码'
        quantity = parse_float_value(line.get('quantity'), 0)
        if quantity <= 0:
            return None, f'第 {index} 行数量必须大于 0'
        material = Material.query.filter_by(code=code).first()
        if not material:
            return None, f'物料不存在：{code}'
        parsed.append((material, quantity, line))
    return parsed, None


@app.route('/api/login', methods=['POST'])
@csrf.exempt
def native_api_login():
    payload = request.get_json(silent=True) or {}
    username = (payload.get('username') or '').strip()
    password = payload.get('password') or ''
    if not username or not password:
        return api_json_error('请输入账号和密码', 400)

    user = User.query.filter_by(username=username).first()
    if not user or not check_password_hash(user.password_hash, password):
        if user and user.is_active:
            user.increment_failed_count()
        add_login_log(status='failed', username=username, user=user, fail_reason='api_failed')
        try:
            db.session.commit()
        except Exception:
            db.session.rollback()
        return api_json_error('账号或密码错误', 401)
    if not user.is_active:
        return api_json_error('账号已被禁用', 403)
    if user.is_locked:
        return api_json_error('账号已锁定，请稍后再试', 423)

    token = ApiToken(
        token=secrets.token_urlsafe(48),
        user_id=user.id,
        expires_at=datetime.now() + timedelta(days=7),
    )
    user.last_login_at = datetime.now()
    user.last_login_ip = get_request_ip()
    user.reset_failed_count()
    add_login_log(status='success', username=username, user=user)
    db.session.add(token)
    db.session.commit()
    return api_json_success({
        'token': token.token,
        'expires_in': 7 * 24 * 60 * 60,
        'user': {
            'id': user.id,
            'username': user.username,
            'name': user.username,
            'role': user.role,
        }
    }, '登录成功')


@app.route('/api/inbound', methods=['POST'])
@csrf.exempt
@api_role_required('warehouse')
def native_api_inbound(user):
    payload = request.get_json(silent=True) or {}
    parsed, error = parse_api_lines(payload)
    if error:
        return api_json_error(error)
    business_type = (payload.get('business_type') or payload.get('type') or '').strip()
    if business_type in ('product', '产品', '产品入库'):
        business_type = '产品入库'
    elif business_type in ('purchase', '采购', '采购入库', ''):
        business_type = '采购入库'
    else:
        business_type = business_type[:50]
    if business_type == '采购入库' and purchase_in_order_requires_order():
        return api_json_error('系统要求采购入库必须关联采购订单，请从采购订单下推或选单生成入库单', 403)
    if location_management_enabled() and location_required_on_save():
        order_warehouse = (payload.get('warehouse_code') or payload.get('warehouse') or '').strip()
        for _material, _quantity, line in parsed:
            location = (line.get('warehouse_code') or line.get('location_code') or order_warehouse or '').strip()
            if not location:
                return api_json_error('启用库位管理后，入库必须填写仓库/库位')

    try:
        order = InOrder(
            order_no=generate_order_no('IN'),
            date=date.today(),
            warehouse=(payload.get('warehouse_code') or payload.get('warehouse') or '').strip() or None,
            business_type=business_type,
            purpose='Android扫码入库',
            remark='Android原生端提交',
            status='completed',
            operator_id=user.id,
            total_amount=0,
        )
        db.session.add(order)
        db.session.flush()
        total_amount = 0
        for material, quantity, line in parsed:
            price = parse_float_value(line.get('price'), material.price or 0)
            amount = round_to_2_decimals(quantity * price)
            total_amount += amount
            db.session.add(InOrderItem(
                in_order_id=order.id,
                material_id=material.id,
                quantity=quantity,
                price=price,
                amount=amount,
            ))
            ok, msg = add_stock(material, quantity, 'in', 'in_order', order.id, f'Android入库 {order.order_no}')
            if not ok:
                db.session.rollback()
                return api_json_error(msg or '库存增加失败', 500)
            location = (line.get('warehouse_code') or line.get('location_code') or order.warehouse or '').strip()
            loc_ok, loc_msg = update_location_inventory(material, location, quantity)
            if not loc_ok:
                db.session.rollback()
                return api_json_error(loc_msg or '库位库存更新失败', 500)
        order.total_amount = round_to_2_decimals(total_amount)
        db.session.commit()
        return api_json_success({'order_no': order.order_no}, '入库提交成功')
    except Exception as e:
        db.session.rollback()
        app.logger.exception('Android inbound failed')
        return api_json_error('入库提交失败', 500)


