@app.route('/material/add', methods=['GET', 'POST'])
@require_role('warehouse')
@login_required
def add_material():
    if request.method == 'GET':
        # Add new
        categories = MaterialCategory.query.all()
        units = Unit.query.all()
        suppliers = Supplier.query.all()
        return render_template('material_add.html',
                             categories=categories,
                             units=[serialize_unit(unit) for unit in units],
                             suppliers=[serialize_supplier(supplier) for supplier in suppliers])

    # POST
    code = request.form.get('code', '').strip()
    if not code:
        return jsonify({'status': 'error', 'msg': '请输入物料编码'})

    name = request.form.get('name', '').strip()
    if not name:
        return jsonify({'status': 'error', 'msg': '请输入物料名称'})

    if Material.query.filter_by(code=code).first():
        return jsonify({'status': 'error', 'msg': '物料编码已存在'})

    spec = (request.form.get('spec') or '').strip()
    if material_name_spec_exists(name, spec):
        return jsonify({'status': 'error', 'msg': '物料名称和规格不能同时重复'})

    image_file = request.files.get('image')
    image_path = None
    if image_file and image_file.filename:
        image_path, image_error = save_upload_image(image_file)
        if image_error:
            return jsonify({'status': 'error', 'msg': image_error}), 400

    expiry_date = request.form.get('expiry_date')
    try:
        expiry_date_parsed = datetime.strptime(expiry_date, '%Y-%m-%d').date() if expiry_date else None
    except ValueError:
        expiry_date_parsed = None

    material = Material(
        code=code,
        name=name,
        category_id=request.form.get('category_id') or None,
        unit_id=request.form.get('unit_id') or None,
        supplier_id=request.form.get('supplier_id') or None,
        spec=spec,
        purpose=request.form.get('purpose'),
        min_stock=float(request.form.get('min_stock', 0) or 0),
        max_stock=float(request.form.get('max_stock', 0) or 0),
        reorder_point=float((request.form.get('reorder_point') or request.form.get('safety_stock') or 0) or 0),
        expiry_date=expiry_date_parsed,
        alert_days=int(request.form.get('alert_days', 30) or 30),
        price=float(request.form.get('price', 0) or 0),
        remark=((request.form.get('remark') or '').strip() or None),
        image=image_path
    )
    db.session.add(material)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f'物料创建失败: {e}')
        return jsonify({'status': 'error', 'msg': '物料创建失败，编码可能已存在'}), 500
    app.logger.info(f'物料创建成功：{material.code}')
    return jsonify({'status': 'success', 'msg': '物料新增成功'})

def _opening_stock_payload_from_request():
    material_id = request.form.get('material_id', type=int)
    try:
        quantity = float(request.form.get('quantity') or '')
    except (TypeError, ValueError):
        quantity = None
    price = parse_float_value(request.form.get('price'), 0)
    remark = (request.form.get('remark') or '').strip()
    if not material_id:
        return None, '请选择物料'
    material = Material.query.filter_by(id=material_id).with_for_update().first()
    if not material:
        return None, '物料不存在'
    if quantity is None:
        return None, '请输入数量'
    if quantity < 0:
        return None, '期初数量不能小于 0'
    if price < 0:
        return None, '单价不能小于 0'
    return {
        'material': material,
        'quantity': normalize_stock_quantity(quantity),
        'price': round_to_2_decimals(price),
        'amount': round_to_2_decimals(quantity * price),
        'remark': remark or None,
    }, None


def _apply_opening_stock_balance(opening, material, new_quantity, new_price, new_amount, remark):
    old_quantity = normalize_stock_quantity(opening.quantity or 0) if opening else 0
    quantity_delta = normalize_stock_quantity(new_quantity - old_quantity)

    if opening is None:
        opening = OpeningStock(
            material_id=material.id,
            quantity=new_quantity,
            price=new_price,
            amount=new_amount,
            remark=remark,
            operator_id=current_user.id if current_user.is_authenticated else None,
        )
        db.session.add(opening)
        db.session.flush()
    else:
        opening.quantity = new_quantity
        opening.price = new_price
        opening.amount = new_amount
        opening.remark = remark
        opening.operator_id = current_user.id if current_user.is_authenticated else None
        opening.updated_at = datetime.now()
        db.session.flush()

    if abs(quantity_delta) > STOCK_COMPARE_EPSILON:
        db.session.execute(
            sa_update(Material)
            .where(Material.id == material.id)
            .values(stock=Material.stock + quantity_delta)
        )
        db.session.expire(material, ['stock'])
        db.session.add(StockTransaction(
            material_id=material.id,
            transaction_type='opening',
            quantity=quantity_delta,
            reference_type='opening_stock',
            reference_id=opening.id,
            operator_id=current_user.id if current_user.is_authenticated else None,
            remark=remark or '期初库存调整'
        ))
    return opening, quantity_delta


