@app.route('/material/edit/<int:id>', methods=['POST'])
@require_role('warehouse')
@login_required
def edit_material(id):
    """Update a material record."""
    material = db.session.get(Material, id)
    if not material:
        return jsonify({'status': 'error', 'msg': '物料不存在'})

    new_code = (request.form.get('code') or '').strip()
    new_name = (request.form.get('name') or '').strip()
    if not new_code:
        return jsonify({'status': 'error', 'msg': '请输入物料编码'})
    if not new_name:
        return jsonify({'status': 'error', 'msg': '请输入物料名称'})

    existing = Material.query.filter_by(code=new_code).first()
    if existing and existing.id != id:
        return jsonify({'status': 'error', 'msg': '物料编码已存在'})

    new_spec = (request.form.get('spec') or '').strip()
    if material_name_spec_exists(new_name, new_spec, exclude_id=id):
        return jsonify({'status': 'error', 'msg': '物料名称和规格不能同时重复'})

    image_file = request.files.get('image')
    image_path = material.image
    if image_file and image_file.filename:
        image_path, image_error = save_upload_image(image_file)
        if image_error:
            return jsonify({'status': 'error', 'msg': image_error}), 400

    expiry_date = request.form.get('expiry_date')

    old_code = material.code
    old_name = material.name
    code_changed = (old_code != new_code)
    name_changed = (old_name != new_name)
    if code_changed and not material_code_editable():
        return jsonify({'status': 'error', 'msg': '系统参数已禁止修改物料编码'})

    material.code = new_code
    material.name = new_name
    material.category_id = request.form.get('category_id') or None
    material.unit_id = request.form.get('unit_id') or None
    material.supplier_id = request.form.get('supplier_id') or None
    material.spec = new_spec
    material.purpose = request.form.get('purpose')
    material.max_stock = parse_float_value(request.form.get('max_stock'), 0)
    if inventory_alert_enabled():
        material.min_stock = parse_float_value(request.form.get('min_stock'), 0)
        material.reorder_point = parse_float_value(request.form.get('reorder_point'), 0)
        material.alert_days = int(request.form.get('alert_days') or 30)
    material.expiry_date = parse_date_value(expiry_date)
    material.price = parse_float_value(request.form.get('price'), 0)
    material.remark = (request.form.get('remark') or '').strip() or None
    material.image = image_path

    # 级联更新所有关联单据
    cascade_info = []
    spec_changed = (material.spec != new_spec)

    if code_changed or name_changed or spec_changed:
        # 1. 更新采购申请明细
        pr_items = PurchaseRequestItem.query.filter_by(material_id=id).all()
        for item in pr_items:
            if code_changed:
                item.material_code = new_code
            if name_changed:
                item.material_name = new_name
        if pr_items:
            cascade_info.append(f'采购申请 {len(pr_items)} 条')

        # 2. 更新BOM
        bom_records = BOM.query.filter_by(product_code=old_code if code_changed else new_code).all()
        for bom in bom_records:
            if code_changed:
                bom.product_code = new_code
            if name_changed:
                bom.product_name = new_name
        if bom_records:
            cascade_info.append(f'BOM {len(bom_records)} 条')

        # 3. 更新入库单明细
        in_items = InOrderItem.query.filter_by(material_id=id).all()
        for item in in_items:
            if code_changed:
                item.material_code = new_code
            if name_changed:
                item.material_name = new_name
            if spec_changed:
                item.spec = new_spec
        if in_items:
            cascade_info.append(f'入库单 {len(in_items)} 条')

        # 4. 更新领料单明细
        out_items = OutOrderItem.query.filter_by(material_id=id).all()
        for item in out_items:
            if code_changed:
                item.material_code = new_code
            if name_changed:
                item.material_name = new_name
            if spec_changed:
                item.spec = new_spec
        if out_items:
            cascade_info.append(f'领料单 {len(out_items)} 条')

        # 5. 更新盘点单明细
        check_items = InventoryCheckItem.query.filter_by(material_id=id).all()
        for item in check_items:
            if code_changed:
                item.material_code = new_code
            if name_changed:
                item.material_name = new_name
        if check_items:
            cascade_info.append(f'盘点单 {len(check_items)} 条')

        # 6. 更新委外加工明细
        subcontract_items = SubcontractItem.query.filter_by(material_id=id).all()
        for item in subcontract_items:
            if code_changed:
                item.material_code = new_code
            if name_changed:
                item.material_name = new_name
        if subcontract_items:
            cascade_info.append(f'委外单 {len(subcontract_items)} 条')

        # 7. 更新BOM子项明细
        bom_items = BOMItem.query.filter_by(material_id=id).all()
        for item in bom_items:
            if code_changed:
                item.material_code = new_code
            if name_changed:
                item.material_name = new_name
        if bom_items:
            cascade_info.append(f'BOM子项 {len(bom_items)} 条')

    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f'物料更新失败: {e}')
        return jsonify({'status': 'error', 'msg': '物料更新失败'}), 500

    msg = '物料更新成功'
    if cascade_info:
        msg += f'，已同步更新：{"、".join(cascade_info)}'
    return jsonify({'status': 'success', 'msg': msg})

