@app.route('/material/delete', methods=['POST'])
@require_role('warehouse')
@login_required
def delete_material():
    import json
    # equest.json ?form data
    if request.is_json:
        ids = request.json.get('ids', [])
    else:
        #  form data
        ids_str = request.form.get('ids', '[]')
        try:
            ids = json.loads(ids_str)
        except (json.JSONDecodeError, TypeError):
            return jsonify({'status': 'error', 'msg': '删除参数格式错误'})

    if not ids:
        return jsonify({'status': 'error', 'msg': '请选择要删除的物料'})

    success_count = 0
    fail_count = 0

    for id in ids:
        material = db.session.get(Material, id)
        if material:
            # 引用完整性校验：被已完成单据或库存流水引用的物料不允许删除，
            # 避免历史单据变空壳、审计流水丢失。仅允许删除无业务引用的物料。
            if (
                InOrderItem.query.filter_by(material_id=id).first()
                or OutOrderItem.query.filter_by(material_id=id).first()
                or StockTransaction.query.filter_by(material_id=id).first()
                or ProductionRequisitionItem.query.filter_by(material_id=id).first()
                or SubcontractItem.query.filter_by(material_id=id).first()
                or SubcontractIssueItem.query.filter_by(material_id=id).first()
                or SubcontractReceiveItem.query.filter_by(material_id=id).first()
                or BOMItem.query.filter_by(material_id=id).first()
                or InventoryCheckItem.query.filter_by(material_id=id).first()
                or AfterSaleOutOrderItem.query.filter_by(material_id=id).first()
                or PurchaseRequestItem.query.filter_by(material_id=id).first()
                or TransferOrderItem.query.filter_by(material_id=id).first()
                or AdjustmentOrderItem.query.filter_by(material_id=id).first()
                or InventoryCheckScanItem.query.filter_by(material_id=id).first()
                or OpeningStock.query.filter_by(material_id=id).first()
            ):
                fail_count += 1
                app.logger.info(f"跳过删除物料 {id}({material.code})：存在业务引用，建议改为停用")
                continue
            try:
                # 无业务引用时，只清理物料的库位辅助记录后删除物料主数据。
                LocationInventory.query.filter_by(material_id=id).delete()
                db.session.delete(material)
                success_count += 1
            except Exception as e:
                # 单条删除失败必须 rollback，否则 session 进入 PendingRollback 状态，
                # 后续所有迭代都会持续失败，且最终 commit 也会失败
                db.session.rollback()
                app.logger.error(f"删除物料 {id} 失败: {str(e)}")
                fail_count += 1
        else:
            fail_count += 1

    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f'数据库操作失败: {e}')
        return jsonify({'status': 'error', 'msg': f'数据库操作失败: {str(e)}'})

    # 记录操作日志
    log_operation('删除物料', f'批量删除物料，成功 {success_count} 条，失败 {fail_count} 条', 'material')

    if success_count == 0:
        return jsonify({'status': 'error', 'msg': '删除失败，没有物料被删除'})

    return jsonify({
        'status': 'success',
        'msg': f'物料删除完成，成功 {success_count} 条' + (f'，失败 {fail_count} 条' if fail_count > 0 else '')
    })

# ==================== Category management ====================

def build_category_tree_rows(categories):
    category_list = list(categories)
    by_parent = {}
    by_id = {cat.id: cat for cat in category_list}
    for cat in category_list:
        parent_id = cat.parent_id if cat.parent_id in by_id and cat.parent_id != cat.id else None
        by_parent.setdefault(parent_id, []).append(cat)

    for siblings in by_parent.values():
        siblings.sort(key=lambda item: ((item.code or '').lower(), (item.name or '').lower(), item.id))

    rows = []
    visited = set()

    def walk(parent_id, level, path):
        children = by_parent.get(parent_id, [])
        for index, cat in enumerate(children):
            if cat.id in visited:
                continue
            visited.add(cat.id)
            is_last = index == len(children) - 1
            branch_parts = []
            for ancestor_last in path:
                branch_parts.append('    ' if ancestor_last else '│   ')
            branch_parts.append('└─ ' if is_last else '├─ ')
            rows.append({
                'category': cat,
                'level': level,
                'branch': ''.join(branch_parts) if level > 0 else '',
                'has_children': bool(by_parent.get(cat.id)),
            })
            walk(cat.id, level + 1, path + [is_last])

    walk(None, 0, [])
    for cat in category_list:
        if cat.id not in visited:
            rows.append({'category': cat, 'level': 0, 'branch': '', 'has_children': bool(by_parent.get(cat.id))})
    return rows


def build_category_parent_options(categories, exclude_id=None):
    rows = build_category_tree_rows(categories)
    options = []
    for row in rows:
        cat = row['category']
        if exclude_id and cat.id == exclude_id:
            continue
        options.append({
            'id': cat.id,
            'label': f"{row['branch']}{cat.code} {cat.name}",
            'level': row['level'],
        })
    return options


def ensure_material_category_tree_defaults():
    """Create practical root categories and attach existing flat categories once."""
    if startup_db_upgrade_disabled():
        return

    roots = [
        ('100', '配件/耗材'),
        ('200', '组件配件'),
        ('300', '整机设备'),
        ('400', '用品工具'),
    ]
    root_by_code = {}
    changed = False
    for code, name in roots:
        root = MaterialCategory.query.filter_by(code=code).first()
        if not root:
            root = MaterialCategory.query.filter_by(name=name).first()
            if root:
                root.code = code
                root.parent_id = None
                changed = True
            else:
                root = MaterialCategory(code=code, name=name)
                db.session.add(root)
                db.session.flush()
                changed = True
        root_by_code[code] = root

    mapping = {
        '1': root_by_code['100'].id,
        '2': root_by_code['200'].id,
        '3': root_by_code['300'].id,
        '4': root_by_code['400'].id,
    }
    for cat in MaterialCategory.query.order_by(MaterialCategory.code.asc()).all():
        if cat.code in root_by_code or cat.parent_id:
            continue
        parent_id = mapping.get((cat.code or '')[:1])
        if parent_id and parent_id != cat.id:
            cat.parent_id = parent_id
            changed = True

    if changed:
        db.session.commit()

