def _ai_order_payload(label, order, endpoint):
    order_no = getattr(order, 'order_no', '') or getattr(order, 'request_no', '') or getattr(order, 'transfer_no', '') or getattr(order, 'adjustment_no', '') or getattr(order, 'check_no', '') or getattr(order, 'bom_no', '') or getattr(order, 'req_no', '') or getattr(order, 'issue_no', '') or getattr(order, 'receive_no', '')
    order_date = getattr(order, 'date', None)
    date_text = order_date.strftime('%Y-%m-%d') if hasattr(order_date, 'strftime') else (str(order_date) if order_date else '')
    return {
        'type': label,
        'order_no': order_no,
        'status': getattr(order, 'status', '') or '',
        'date': date_text,
        'url': url_for(endpoint, id=order.id),
    }


def _ai_find_orders(message, limit=8):
    text = (message or '').strip()
    tokens = re.findall(r'[A-Za-z]{1,8}\d{2,}|[\u4e00-\u9fffA-Za-z0-9_-]{4,}', text)
    stop_words = {'查询单据', '查单据', '打开单据', '单号', '今天有哪些', '有哪些异常', '待处理单据'}
    keywords = [token for token in tokens if token not in stop_words]
    if not keywords:
        return []
    keyword = keywords[0]
    like = f'%{keyword}%'
    configs = [
        ('入库单', InOrder, InOrder.order_no, 'in_order_detail'),
        ('领料单', OutOrder, OutOrder.order_no, 'out_order_detail'),
        ('售后出库单', AfterSaleOutOrder, AfterSaleOutOrder.order_no, 'after_sale_out_detail'),
        ('采购申请单', PurchaseRequest, PurchaseRequest.request_no, 'purchase_request_detail'),
        ('采购订单', PurchaseOrder, PurchaseOrder.order_no, 'purchase_order_detail'),
        ('调拨单', TransferOrder, TransferOrder.transfer_no, 'transfer_detail'),
        ('调整单', AdjustmentOrder, AdjustmentOrder.adjustment_no, 'adjustment_detail'),
        ('盘点单', InventoryCheck, InventoryCheck.check_no, 'check_detail'),
        ('工单领料', ProductionRequisition, ProductionRequisition.req_no, 'requisition_detail'),
        ('委外加工单', SubcontractOrder, SubcontractOrder.order_no, 'subcontract_detail'),
        ('委外发料单', SubcontractIssue, SubcontractIssue.issue_no, 'subcontract_issue_list'),
        ('委外入库单', SubcontractReceive, SubcontractReceive.receive_no, 'subcontract_receive_list'),
    ]
    results = []
    for label, model, field, endpoint in configs:
        for order in model.query.filter(field.ilike(like)).order_by(model.id.desc()).limit(limit).all():
            payload = _ai_order_payload(label, order, endpoint) if endpoint not in {'subcontract_issue_list', 'subcontract_receive_list'} else {
                'type': label,
                'order_no': getattr(order, 'issue_no', '') or getattr(order, 'receive_no', ''),
                'status': getattr(order, 'status', '') or '',
                'url': url_for(endpoint),
            }
            results.append(payload)
            if len(results) >= limit:
                return results
    return results


def _ai_pending_documents(limit=12):
    rows = []
    configs = [
        ('入库单', InOrder, 'in_order_detail'),
        ('领料单', OutOrder, 'out_order_detail'),
        ('售后出库单', AfterSaleOutOrder, 'after_sale_out_detail'),
        ('采购申请单', PurchaseRequest, 'purchase_request_detail'),
        ('采购订单', PurchaseOrder, 'purchase_order_detail'),
        ('调拨单', TransferOrder, 'transfer_detail'),
        ('调整单', AdjustmentOrder, 'adjustment_detail'),
        ('盘点单', InventoryCheck, 'check_detail'),
        ('工单领料', ProductionRequisition, 'requisition_detail'),
        ('委外加工单', SubcontractOrder, 'subcontract_detail'),
    ]
    for label, model, endpoint in configs:
        for order in model.query.filter(model.status.in_(('pending', 'approved', 'processing'))).order_by(model.id.desc()).limit(3).all():
            rows.append(_ai_order_payload(label, order, endpoint))
    return rows[:limit]


# ==================== AI 数据分析能力 ====================

def _ai_analysis_inventory_turnover(top_n=10, days=90, warehouse=None, category=None):
    """库存周转分析：按出库金额排序，识别动销/滞销品。
    可选参数：
      days: 统计窗口天数（默认 90）
      warehouse: 仓库名/库位关键字，过滤 StockTransaction.location
      category: 物料分类名，过滤 MaterialCategory.name
    """
    from sqlalchemy import func
    days = max(1, int(days or 90))
    cutoff = datetime.now() - timedelta(days=days)
    # 近 N 天出库数量 TOP
    txn_filters = [
        StockTransaction.material_id == Material.id,
        StockTransaction.transaction_type.in_(['out', 'transfer_out', 'adjustment_out']),
        StockTransaction.created_at >= cutoff,
    ]
    if warehouse:
        txn_filters.append(StockTransaction.location.like(f'%{warehouse}%'))
    material_filters = []
    if category:
        material_filters.append(MaterialCategory.name.like(f'%{category}%'))

    base_query = (
        db.session.query(
            Material.id, Material.code, Material.name, Material.spec, Material.stock,
            func.coalesce(func.sum(StockTransaction.quantity), 0).label('out_qty'),
        )
        .outerjoin(StockTransaction, db.and_(*txn_filters))
    )
    if category:
        base_query = base_query.outerjoin(MaterialCategory, MaterialCategory.id == Material.category_id)
        base_query = base_query.filter(*material_filters)
    out_rows = (
        base_query
        .group_by(Material.id)
        .order_by(func.coalesce(func.sum(StockTransaction.quantity), 0).desc())
        .limit(top_n)
        .all()
    )
    scope = []
    if warehouse:
        scope.append(f'仓库={warehouse}')
    if category:
        scope.append(f'分类={category}')
    scope_text = f'（{"，".join(scope)}）' if scope else ''
    if not out_rows:
        return f'近{days}天{scope_text}没有出库流水，无法计算周转。'
    lines = [f'**近{days}天{scope_text}出库量 TOP10（动销品）**：\n']
    lines.append('| 排名 | 物料编码 | 名称 | 规格 | 当前库存 | 出库量 |')
    lines.append('|------|---------|------|------|---------|---------|')
    for idx, row in enumerate(out_rows, 1):
        name = (row.name or '')[:12]
        spec = (row.spec or '')[:10]
        lines.append(f'| {idx} | {row.code} | {name} | {spec} | {row.stock:.0f} | {abs(row.out_qty):.0f} |')
    # 滞销品：库存>0 但 N 天无出库
    slow_query = (
        Material.query
        .filter(Material.stock > 0)
        .filter(~Material.id.in_([r.id for r in out_rows if r.out_qty > 0]))
    )
    if category:
        slow_query = slow_query.join(MaterialCategory, MaterialCategory.id == Material.category_id).filter(MaterialCategory.name.like(f'%{category}%'))
    slow_rows = slow_query.order_by(Material.stock.desc()).limit(5).all()
    if slow_rows:
        lines.append(f'\n**滞销品（有库存但近{days}天未出库）**：')
        for m in slow_rows:
            lines.append(f'- {m.code} {(m.name or "")[:12]}（库存 {m.stock:.0f}）')
    reply = '\n'.join(lines)
    reply += _ai_data_source_footer(
        '实时数据库查询',
        f'最近{days}天' + (f'；仓库/库位包含 {warehouse}' if warehouse else '') + (f'；分类包含 {category}' if category else ''),
        ['material', 'stock_transaction', 'material_category'],
    )
    return reply


def _ai_analysis_stock_value(category=None):
    """库存金额分布分析。
    可选参数：
      category: 物料分类名，过滤 MaterialCategory.name
    """
    from sqlalchemy import func
    query = Material.query
    if category:
        query = query.join(MaterialCategory, MaterialCategory.id == Material.category_id).filter(MaterialCategory.name.like(f'%{category}%'))
    total_value = db.session.query(func.coalesce(func.sum(Material.stock * Material.price), 0))
    if category:
        total_value = total_value.join(MaterialCategory, MaterialCategory.id == Material.category_id).filter(MaterialCategory.name.like(f'%{category}%'))
    total_value = total_value.scalar() or 0
    rows = (
        query
        .filter(Material.stock > 0)
        .order_by((Material.stock * Material.price).desc())
        .limit(10)
        .all()
    )
    scope_text = f'（分类={category}）' if category else ''
    lines = [f'**库存金额分析{scope_text}**：当前库存总价值约 **¥{total_value:,.2f}**\n']
    if rows:
        lines.append('**金额占用 TOP10**：')
        lines.append('| 排名 | 物料编码 | 名称 | 库存 | 单价 | 金额 |')
        lines.append('|------|---------|------|------|------|------|')
        for idx, m in enumerate(rows, 1):
            value = m.stock * m.price
            lines.append(f'| {idx} | {m.code} | {(m.name or "")[:12]} | {m.stock:.0f} | ¥{m.price:.2f} | ¥{value:,.2f} |')
    return '\n'.join(lines)


def _ai_analysis_supplier(days=90, warehouse=None):
    """供应商分析：采购金额、单据数。
    可选参数：
      days: 统计窗口天数（默认 90）
      warehouse: 仓库名关键字，过滤 InOrder.warehouse
    """
    from sqlalchemy import func
    days = max(1, int(days or 90))
    cutoff = datetime.now() - timedelta(days=days)
    query = (
        db.session.query(
            Supplier.id, Supplier.name,
            func.count(InOrder.id).label('order_count'),
            func.coalesce(func.sum(InOrder.total_amount), 0).label('total_amount'),
        )
        .join(InOrder, InOrder.supplier_id == Supplier.id)
        .filter(InOrder.date >= cutoff.date())
    )
    if warehouse:
        query = query.filter(InOrder.warehouse.like(f'%{warehouse}%'))
    rows = (
        query
        .group_by(Supplier.id)
        .order_by(func.coalesce(func.sum(InOrder.total_amount), 0).desc())
        .limit(10)
        .all()
    )
    scope_text = f'（仓库={warehouse}）' if warehouse else ''
    if not rows:
        return f'近{days}天{scope_text}没有采购入库记录，无法做供应商分析。'
    lines = [f'**近{days}天{scope_text}供应商采购分析**：\n']
    lines.append('| 排名 | 供应商 | 入库单数 | 采购金额 |')
    lines.append('|------|--------|---------|---------|')
    for idx, row in enumerate(rows, 1):
        lines.append(f'| {idx} | {(row.name or "")[:16]} | {row.order_count} | ¥{row.total_amount:,.2f} |')
    return '\n'.join(lines)


def _ai_analysis_consumption_trend(keyword, days=30, warehouse=None):
    """物料消耗趋势：返回近N天每日出库量。
    可选参数：
      days: 统计窗口天数（默认 30）
      warehouse: 仓库名/库位关键字，过滤 StockTransaction.location
    """
    from sqlalchemy import func
    days = max(1, int(days or 30))
    materials = _ai_material_query(keyword, limit=1)
    if not materials:
        return f'没有找到物料 "{keyword}"，请确认编码或名称。'
    material = materials[0]
    cutoff = datetime.now() - timedelta(days=days)
    query = (
        db.session.query(
            func.date(StockTransaction.created_at).label('day'),
            func.coalesce(func.sum(func.abs(StockTransaction.quantity)), 0).label('qty'),
        )
        .filter(StockTransaction.material_id == material.id)
        .filter(StockTransaction.transaction_type.in_(['out', 'transfer_out', 'adjustment_out']))
        .filter(StockTransaction.created_at >= cutoff)
    )
    if warehouse:
        query = query.filter(StockTransaction.location.like(f'%{warehouse}%'))
    rows = (
        query
        .group_by(func.date(StockTransaction.created_at))
        .order_by(func.date(StockTransaction.created_at))
        .all()
    )
    scope_text = f'（仓库={warehouse}）' if warehouse else ''
    if not rows:
        return f'物料 {material.code} 近{days}天{scope_text}没有出库记录。'
    total = sum(r.qty for r in rows)
    avg = total / days
    lines = [f'**物料 {material.code} {material.name} 近{days}天{scope_text}消耗趋势**：']
    lines.append(f'- 总出库量：**{total:.1f}**')
    lines.append(f'- 日均消耗：**{avg:.1f}**')
    if avg > 0:
        days_of_supply = material.stock / avg if avg > 0 else 999
        lines.append(f'- 当前库存：**{material.stock:.1f}**，按当前消耗速率可支撑约 **{days_of_supply:.0f} 天**')
    # 简易趋势判断
    if len(rows) >= 7:
        recent = sum(r.qty for r in rows[-7:]) / 7
        earlier = sum(r.qty for r in rows[:7]) / 7
        if earlier > 0:
            change = (recent - earlier) / earlier * 100
            arrow = '↑' if change > 0 else '↓'
            lines.append(f'- 近7天日均 {recent:.1f}，较前期{arrow}{abs(change):.0f}%')
    return '\n'.join(lines)


def _ai_analysis_category_summary(category=None):
    """按物料分类汇总库存：分类名、物料数、库存数量、库存金额。
    可选参数：
      category: 指定分类名（模糊匹配），不传则汇总所有分类
    """
    from sqlalchemy import func
    query = (
        db.session.query(
            MaterialCategory.id, MaterialCategory.name,
            func.count(Material.id).label('material_count'),
            func.coalesce(func.sum(Material.stock), 0).label('total_stock'),
            func.coalesce(func.sum(Material.stock * Material.price), 0).label('total_value'),
        )
        .outerjoin(Material, Material.category_id == MaterialCategory.id)
    )
    if category:
        query = query.filter(MaterialCategory.name.like(f'%{category}%'))
    rows = (
        query
        .group_by(MaterialCategory.id)
        .order_by(func.coalesce(func.sum(Material.stock * Material.price), 0).desc())
        .limit(15)
        .all()
    )
    if not rows:
        return '没有找到物料分类数据。请先在物料档案里维护分类。'
    scope_text = f'（分类包含"{category}"）' if category else ''
    lines = [f'**按物料分类汇总{scope_text}**：\n']
    lines.append('| 排名 | 分类 | 物料数 | 库存数量 | 库存金额 |')
    lines.append('|------|------|--------|---------|---------|')
    for idx, row in enumerate(rows, 1):
        lines.append(f'| {idx} | {(row.name or "-")[:16]} | {row.material_count} | {row.total_stock:.0f} | ¥{row.total_value:,.2f} |')
    return '\n'.join(lines)


def _ai_analysis_low_stock_report():
    """低库存补货建议报告"""
    if not inventory_alert_enabled():
        return '库存预警未启用，无法生成低库存报告。请到系统设置开启库存预警。'
    rows = (
        Material.query
        .filter(_material_low_stock_filter())
        .order_by((Material.min_stock - Material.stock).desc())
        .limit(20)
        .all()
    )
    if not rows:
        return '当前没有低库存物料，库存状态良好。'
    lines = [f'**低库存预警报告（共 {len(rows)} 项）**：\n']
    lines.append('| 物料编码 | 名称 | 当前库存 | 最低库存 | 建议补货 |')
    lines.append('|---------|------|---------|---------|---------|')
    for m in rows:
        reorder = max(0, (m.max_stock or m.min_stock or 0) - m.stock)
        lines.append(f'| {m.code} | {(m.name or "")[:12]} | {m.stock:.0f} | {m.min_stock:.0f} | {reorder:.0f} |')
    return '\n'.join(lines)


def _ai_inventory_health_report(days=30, limit=200, risk_filter='all'):
    """库存健康度评分报告。
    计算每个物料的健康分数、风险类型和优化建议。
    """
    days = max(int(days or 30), 1)
    limit = max(min(int(limit or 200), 500), 1)
    
    # 查询所有物料
    materials = Material.query.options(
        joinedload(Material.unit),
        joinedload(Material.supplier),
        joinedload(Material.category),
    ).order_by(Material.code.asc()).all()
    
    if not materials:
        return {
            'rows': [],
            'summary': {
                'total': 0,
                'healthy': 0,
                'warning': 0,
                'critical': 0,
                'avg_health_score': 0,
                'total_stock_value': 0,
                'overstock_value': 0,
                'stagnant_value': 0,
                'days': days,
                'generated_at': datetime.now(),
            }
        }
    
    material_ids = [m.id for m in materials]
    
    # 计算近N天出库量
    cutoff = datetime.now() - timedelta(days=days)
    out_qty_rows = db.session.query(
        StockTransaction.material_id,
        func.coalesce(func.sum(func.abs(StockTransaction.quantity)), 0),
    ).filter(
        StockTransaction.created_at >= cutoff,
        StockTransaction.quantity < 0,
    ).group_by(StockTransaction.material_id).all()
    out_qty_map = {mid: round_to_2_decimals(qty or 0) for mid, qty in out_qty_rows}
    
    # 计算近90天出库量（用于呆滞判断）
    cutoff_90 = datetime.now() - timedelta(days=90)
    out_qty_90_rows = db.session.query(
        StockTransaction.material_id,
        func.coalesce(func.sum(func.abs(StockTransaction.quantity)), 0),
    ).filter(
        StockTransaction.created_at >= cutoff_90,
        StockTransaction.quantity < 0,
    ).group_by(StockTransaction.material_id).all()
    out_qty_90_map = {mid: round_to_2_decimals(qty or 0) for mid, qty in out_qty_90_rows}
    
    # 计算近60天出库量
    cutoff_60 = datetime.now() - timedelta(days=60)
    out_qty_60_rows = db.session.query(
        StockTransaction.material_id,
        func.coalesce(func.sum(func.abs(StockTransaction.quantity)), 0),
    ).filter(
        StockTransaction.created_at >= cutoff_60,
        StockTransaction.quantity < 0,
    ).group_by(StockTransaction.material_id).all()
    out_qty_60_map = {mid: round_to_2_decimals(qty or 0) for mid, qty in out_qty_60_rows}
    
    rows = []
    total_stock_value = 0
    overstock_value = 0
    stagnant_value = 0
    healthy_count = 0
    warning_count = 0
    critical_count = 0
    total_health_score = 0
    
    for material in materials:
        current_stock = round_to_2_decimals(material.stock or 0)
        min_stock = round_to_2_decimals(material.min_stock or 0)
        max_stock = round_to_2_decimals(material.max_stock or 0)
        reorder_point = round_to_2_decimals(material.reorder_point or 0)
        price = float(material.price or 0)
        
        outbound_qty = out_qty_map.get(material.id, 0)
        outbound_90 = out_qty_90_map.get(material.id, 0)
        outbound_60 = out_qty_60_map.get(material.id, 0)
        
        avg_daily = round_to_2_decimals(outbound_qty / days) if outbound_qty > 0 else 0
        
        # 计算可用天数
        days_of_supply = None
        if avg_daily > STOCK_COMPARE_EPSILON:
            days_of_supply = round_to_2_decimals(current_stock / avg_daily)
        
        # 计算健康分数
        health_score = 100
        
        # 可用天数扣分
        if days_of_supply is not None:
            if days_of_supply < 7:
                health_score -= 40
            elif days_of_supply < 14:
                health_score -= 20
        
        # 超储扣分
        if max_stock > 0:
            if current_stock > max_stock * 2:
                health_score -= 30
            elif current_stock > max_stock * 1.5:
                health_score -= 15
        
        # 呆滞扣分
        if outbound_90 <= STOCK_COMPARE_EPSILON and current_stock > STOCK_COMPARE_EPSILON:
            health_score -= 25
        elif outbound_60 <= STOCK_COMPARE_EPSILON and current_stock > STOCK_COMPARE_EPSILON:
            health_score -= 15
        
        # 低于最低库存扣分
        if current_stock < min_stock and min_stock > 0:
            health_score -= 20
        
        # 限制在0-100
        health_score = max(0, min(100, health_score))
        
        # 确定风险类型（优先级顺序）
        risk_type = 'normal'
        if days_of_supply is not None and days_of_supply <= 7:
            risk_type = 'shortage'
        elif max_stock > 0 and current_stock > max_stock * 2:
            risk_type = 'overstock'
        elif outbound_90 <= STOCK_COMPARE_EPSILON and current_stock > STOCK_COMPARE_EPSILON:
            risk_type = 'stagnant'
        
        # 生成AI建议
        ai_suggestion = ''
        if risk_type == 'shortage':
            ai_suggestion = f'库存紧张，建议立即补货至安全库存{min_stock}以上'
        elif risk_type == 'overstock':
            ai_suggestion = f'库存超储，建议控制采购节奏，消耗至最大库存{max_stock}以下'
        elif risk_type == 'stagnant':
            ai_suggestion = '近90天无出库记录，建议评估是否呆滞，考虑促销或调拨'
        elif health_score < 60:
            ai_suggestion = '库存状态不佳，建议关注并及时调整'
        elif health_score < 80:
            ai_suggestion = '库存基本健康，建议持续监控'
        else:
            ai_suggestion = '库存状态良好'
        
        # 统计
        stock_value = round_to_2_decimals(current_stock * price)
        total_stock_value += stock_value
        
        if risk_type == 'overstock':
            overstock_value += stock_value
        if risk_type == 'stagnant':
            stagnant_value += stock_value
        
        if health_score >= 80:
            healthy_count += 1
        elif health_score >= 60:
            warning_count += 1
        else:
            critical_count += 1
        
        total_health_score += health_score
        
        # 根据筛选条件过滤
        if risk_filter == 'critical' and health_score >= 60:
            continue
        if risk_filter == 'warning' and not (60 <= health_score < 80):
            continue
        if risk_filter == 'healthy' and health_score < 80:
            continue
        
        rows.append({
            'material': material,
            'code': material.code,
            'name': material.name,
            'spec': material.spec or '',
            'unit': material.unit.name if material.unit else '',
            'category': material.category.name if material.category else '',
            'supplier': material.supplier.name if material.supplier else '',
            'current_stock': current_stock,
            'min_stock': min_stock,
            'max_stock': max_stock,
            'reorder_point': reorder_point,
            'price': price,
            'outbound_qty': outbound_qty,
            'avg_daily': avg_daily,
            'days_of_supply': days_of_supply,
            'health_score': health_score,
            'risk_type': risk_type,
            'ai_suggestion': ai_suggestion,
            'stock_value': stock_value,
        })
    
    # 按健康分升序排序（风险高的在前）
    rows.sort(key=lambda row: (row['health_score'], row['code'] or ''))
    rows = rows[:limit]
    
    total_materials = len(rows)
    avg_health_score = round_to_2_decimals(total_health_score / total_materials) if total_materials > 0 else 0
    
    summary = {
        'total': total_materials,
        'healthy': healthy_count,
        'warning': warning_count,
        'critical': critical_count,
        'avg_health_score': avg_health_score,
        'total_stock_value': round_to_2_decimals(total_stock_value),
        'overstock_value': round_to_2_decimals(overstock_value),
        'stagnant_value': round_to_2_decimals(stagnant_value),
        'days': days,
        'generated_at': datetime.now(),
    }
    
    return {'rows': rows, 'summary': summary}


def _ai_analyze_out_order_anomalies(order_id):
    """出库单异常AI分析：检查出库单中每个物料的异常情况。
    返回 dict: {order: {...}, anomalies: [...], summary: "..."}
    """
    from sqlalchemy import func
    order = OutOrder.query.options(
        joinedload(OutOrder.items).joinedload(OutOrderItem.material).joinedload(Material.unit),
        joinedload(OutOrder.department),
        joinedload(OutOrder.operator),
    ).get(order_id)
    if not order:
        return {'order': None, 'anomalies': [], 'summary': '未找到该出库单。'}

    # 计算近30天每个物料的日均出库量
    cutoff = datetime.now() - timedelta(days=30)
    avg_rows = db.session.query(
        StockTransaction.material_id,
        func.coalesce(func.sum(func.abs(StockTransaction.quantity)), 0),
    ).filter(
        StockTransaction.transaction_type == 'out',
        StockTransaction.created_at >= cutoff,
    ).group_by(StockTransaction.material_id).all()
    avg_daily = {mid: float(qty or 0) / 30.0 for mid, qty in avg_rows}

    anomalies = []
    for item in order.items:
        m = item.material
        if not m:
            continue
        current_stock = float(m.stock or 0)
        min_stock = float(m.min_stock or 0)
        item_qty = float(item.quantity or 0)
        item_price = float(item.price or 0)
        std_price = float(m.price or 0)
        avg_out = avg_daily.get(m.id, 0.0)

        # 1. 出库数量超过当前库存（潜在缺库）
        if item_qty > current_stock and current_stock >= 0:
            anomalies.append({
                'material_code': m.code,
                'material_name': m.name,
                'anomaly_type': '超库存出库',
                'description': f'出库数量 {item_qty:.2f} 超过当前库存 {current_stock:.2f}，缺口 {item_qty - current_stock:.2f}',
                'severity': 'danger',
            })

        # 2. 出库数量异常偏大（超过30天日均的3倍且日均>0）
        if avg_out > 0 and item_qty > avg_out * 3 * 30:
            anomalies.append({
                'material_code': m.code,
                'material_name': m.name,
                'anomaly_type': '数量异常偏大',
                'description': f'出库数量 {item_qty:.2f} 远超近30天日均 {avg_out:.2f}（超过日均3倍）',
                'severity': 'warning',
            })

        # 3. 物料已处于低库存状态
        if min_stock > 0 and current_stock <= min_stock:
            anomalies.append({
                'material_code': m.code,
                'material_name': m.name,
                'anomaly_type': '低库存物料',
                'description': f'当前库存 {current_stock:.2f} 已低于最低库存 {min_stock:.2f}，继续出库将加剧短缺',
                'severity': 'warning',
            })

        # 4. 单价与标准价偏差超过20%
        if std_price > 0 and abs(item_price - std_price) / std_price > 0.2:
            deviation = (item_price - std_price) / std_price * 100
            anomalies.append({
                'material_code': m.code,
                'material_name': m.name,
                'anomaly_type': '单价偏差过大',
                'description': f'出库单价 ¥{item_price:.2f} 与标准价 ¥{std_price:.2f} 偏差 {deviation:+.1f}%',
                'severity': 'info' if abs(deviation) < 50 else 'warning',
            })

    # 生成AI摘要
    if not anomalies:
        summary = f'出库单 {order.order_no} 共 {len(order.items)} 项物料，AI分析未发现明显异常。'
    else:
        danger_count = sum(1 for a in anomalies if a['severity'] == 'danger')
        warning_count = sum(1 for a in anomalies if a['severity'] == 'warning')
        info_count = sum(1 for a in anomalies if a['severity'] == 'info')
        parts = []
        if danger_count:
            parts.append(f'{danger_count} 项严重异常（超库存出库）')
        if warning_count:
            parts.append(f'{warning_count} 项警告（数量偏大或低库存）')
        if info_count:
            parts.append(f'{info_count} 项提示（单价偏差）')
        summary = f'出库单 {order.order_no} 共 {len(order.items)} 项物料，AI发现 {"，".join(parts)}。建议核实后再提交。'

    return {
        'order': {
            'id': order.id,
            'order_no': order.order_no,
            'date': str(order.date) if order.date else '',
            'status': order.status,
            'department': order.department.name if order.department else (order.customer or ''),
            'operator': order.operator.username if order.operator else '',
            'item_count': len(order.items),
        },
        'anomalies': anomalies,
        'summary': summary,
    }


def _ai_report_mom_insights():
    """报表仪表盘环比分析洞察"""
    today = date.today()
    month_start = today.replace(day=1)
    last_month_start = _shift_month_start(month_start, -1)
    next_month_start = _shift_month_start(month_start, 1)

    # 本月数据
    month_in_amount = db.session.query(func.coalesce(func.sum(InOrder.total_amount), 0)).filter(
        InOrder.date >= month_start,
        InOrder.date < next_month_start
    ).scalar() or 0
    month_out_amount = db.session.query(func.coalesce(func.sum(OutOrder.total_amount), 0)).filter(
        OutOrder.date >= month_start,
        OutOrder.date < next_month_start
    ).scalar() or 0
    month_in_count = db.session.query(func.count(InOrder.id)).filter(
        InOrder.date >= month_start,
        InOrder.date < next_month_start
    ).scalar() or 0
    month_out_count = db.session.query(func.count(OutOrder.id)).filter(
        OutOrder.date >= month_start,
        OutOrder.date < next_month_start
    ).scalar() or 0

    # 上月数据
    last_month_in_amount = db.session.query(func.coalesce(func.sum(InOrder.total_amount), 0)).filter(
        InOrder.date >= last_month_start,
        InOrder.date < month_start
    ).scalar() or 0
    last_month_out_amount = db.session.query(func.coalesce(func.sum(OutOrder.total_amount), 0)).filter(
        OutOrder.date >= last_month_start,
        OutOrder.date < month_start
    ).scalar() or 0
    last_month_in_count = db.session.query(func.count(InOrder.id)).filter(
        InOrder.date >= last_month_start,
        InOrder.date < month_start
    ).scalar() or 0
    last_month_out_count = db.session.query(func.count(OutOrder.id)).filter(
        OutOrder.date >= last_month_start,
        OutOrder.date < month_start
    ).scalar() or 0

    def _calc_rate(current, last):
        if last and last > 0:
            return ((current - last) / last) * 100
        return None

    def _format_rate(rate):
        if rate is None:
            return '无上月数据'
        return f'{rate:+.1f}%'

    def _highlight_rate(rate):
        if rate is None:
            return ''
        if rate > 20:
            return ' ⚠️ 显著增长'
        if rate < -20:
            return ' ⚠️ 显著下降'
        return ''

    in_amount_rate = _calc_rate(float(month_in_amount), float(last_month_in_amount))
    out_amount_rate = _calc_rate(float(month_out_amount), float(last_month_out_amount))
    in_count_rate = _calc_rate(int(month_in_count), int(last_month_in_count))
    out_count_rate = _calc_rate(int(month_out_count), int(last_month_out_count))

    lines = [
        f'**本月 vs 上月环比分析**\n',
        f'| 指标 | 本月 | 上月 | 环比增长率 |',
        f'|------|------|------|-----------|',
        f'| 入库金额 | ¥{float(month_in_amount):,.2f} | ¥{float(last_month_in_amount):,.2f} | {_format_rate(in_amount_rate)}{_highlight_rate(in_amount_rate)} |',
        f'| 领料金额 | ¥{float(month_out_amount):,.2f} | ¥{float(last_month_out_amount):,.2f} | {_format_rate(out_amount_rate)}{_highlight_rate(out_amount_rate)} |',
        f'| 入库单数 | {int(month_in_count)} | {int(last_month_in_count)} | {_format_rate(in_count_rate)}{_highlight_rate(in_count_rate)} |',
        f'| 领料单数 | {int(month_out_count)} | {int(last_month_out_count)} | {_format_rate(out_count_rate)}{_highlight_rate(out_count_rate)} |',
    ]

    # 添加关键洞察
    insights = []
    if in_amount_rate is not None and abs(in_amount_rate) > 20:
        direction = '增长' if in_amount_rate > 0 else '下降'
        insights.append(f'入库金额环比{direction} {abs(in_amount_rate):.1f}%，变化显著')
    if out_amount_rate is not None and abs(out_amount_rate) > 20:
        direction = '增长' if out_amount_rate > 0 else '下降'
        insights.append(f'领料金额环比{direction} {abs(out_amount_rate):.1f}%，变化显著')

    if insights:
        lines.append('\n**关键洞察：**')
        for insight in insights:
            lines.append(f'- {insight}')
    else:
        lines.append('\n整体出入库指标环比变化平稳，无显著波动。')

    return '\n'.join(lines)


def _ai_is_stage4_deep_analysis_question(message):
    compact = (message or '').replace(' ', '').lower()
    if not compact:
        return False
    return any(word in compact for word in (
        '可用天数', '预计可用', '还能用几天', '库存覆盖', '库存覆盖天数',
        '滞销', '呆滞', '慢动销', '长期未出库',
        '缺料', '缺货', '短缺', '补货缺口',
        '供应商履约', '供应商交付', '供应商到货', '采购履约',
        '盘点差异', '盘盈盘亏', '差异分析',
        '深度分析', '分析深度',
        'stage4', 'deep analysis', 'supply_days', 'days_of_supply', 'slow_moving',
        'shortage', 'supplier_performance', 'stocktake_variance',
    ))


def _ai_stage4_out_qty_by_material(days=30):
    cutoff = datetime.now() - timedelta(days=max(1, int(days or 30)))
    rows = db.session.query(
        StockTransaction.material_id,
        func.coalesce(func.sum(func.abs(StockTransaction.quantity)), 0),
    ).filter(
        StockTransaction.transaction_type.in_(('out', 'transfer_out', 'adjustment_out')),
        StockTransaction.created_at >= cutoff,
    ).group_by(StockTransaction.material_id).all()
    return {material_id: float(qty or 0) for material_id, qty in rows}


def _ai_stage4_days_of_supply_report(days=30, limit=12):
    out_qty = _ai_stage4_out_qty_by_material(days)
    material_ids = list(out_qty)
    if not material_ids:
        return '最近没有出库类库存流水，暂时无法计算预计可用天数。'
    materials = Material.query.options(joinedload(Material.unit)).filter(Material.id.in_(material_ids)).all()
    rows = []
    for material in materials:
        total_out = out_qty.get(material.id, 0)
        if total_out <= 0:
            continue
        avg_daily = total_out / max(1, int(days or 30))
        available_days = (material.stock or 0) / avg_daily if avg_daily > 0 else 999999
        rows.append((available_days, avg_daily, material))
    rows.sort(key=lambda row: row[0])
    lines = [f'**预计可用天数分析（最近{days}天消耗）**']
    lines.append('| 物料 | 当前库存 | 日均消耗 | 预计可用天数 | 判断 |')
    lines.append('|---|---:|---:|---:|---|')
    for available_days, avg_daily, material in rows[:limit]:
        unit_name = material.unit.name if material.unit else ''
        status = '紧急' if available_days <= 7 else ('关注' if available_days <= 30 else '正常')
        lines.append(
            f'| {material.code} {material.name} | {normalize_stock_quantity(material.stock or 0)}{unit_name} | '
            f'{normalize_stock_quantity(avg_daily)}{unit_name}/天 | {available_days:.1f} | {status} |'
        )
    return '\n'.join(lines)


def _ai_stage4_slow_moving_report(days=90, limit=12):
    cutoff = datetime.now() - timedelta(days=max(1, int(days or 90)))
    recent_out_material_ids = db.session.query(StockTransaction.material_id).filter(
        StockTransaction.transaction_type.in_(('out', 'transfer_out', 'adjustment_out')),
        StockTransaction.created_at >= cutoff,
    ).distinct()
    rows = Material.query.options(joinedload(Material.unit)).filter(
        Material.stock > 0,
        ~Material.id.in_(recent_out_material_ids),
    ).order_by((Material.stock * Material.price).desc(), Material.stock.desc()).limit(limit).all()
    if not rows:
        return f'最近{days}天没有发现有库存且无出库的滞销物料。'
    lines = [f'**滞销/呆滞库存分析（最近{days}天无出库）**']
    lines.append('| 物料 | 当前库存 | 库存金额 | 建议动作 |')
    lines.append('|---|---:|---:|---|')
    for material in rows:
        unit_name = material.unit.name if material.unit else ''
        value = round_to_2_decimals((material.stock or 0) * (material.price or 0))
        lines.append(
            f'| {material.code} {material.name} | {normalize_stock_quantity(material.stock or 0)}{unit_name} | '
            f'{value:,.2f} | 复核需求、替代料、报废或降库存上限 |'
        )
    return '\n'.join(lines)


def _ai_stage4_shortage_report(limit=12):
    if not inventory_alert_enabled():
        return '库存预警未启用，缺料分析只能参考负库存；建议先启用库存预警并维护最低/安全/最高库存。'
    materials = Material.query.options(joinedload(Material.unit), joinedload(Material.supplier)).filter(_material_low_stock_filter()).limit(200).all()
    material_ids = [material.id for material in materials]
    on_order = {material_id: 0 for material_id in material_ids}
    if material_ids:
        po_rows = db.session.query(
            PurchaseOrderItem.material_id,
            func.coalesce(func.sum(PurchaseOrderItem.quantity - PurchaseOrderItem.received_quantity), 0),
        ).join(PurchaseOrder, PurchaseOrderItem.purchase_order_id == PurchaseOrder.id).filter(
            PurchaseOrderItem.material_id.in_(material_ids),
            PurchaseOrder.status.in_(('pending', 'partial')),
        ).group_by(PurchaseOrderItem.material_id).all()
        for material_id, qty in po_rows:
            on_order[material_id] = max(float(qty or 0), 0)
    rows = []
    for material in materials:
        target = material.max_stock or material.min_stock or material.reorder_point or 0
        shortage = max((target or 0) - (material.stock or 0) - on_order.get(material.id, 0), 0)
        severity = max((material.min_stock or 0) - (material.stock or 0), 0)
        rows.append((severity, shortage, material))
    rows.sort(key=lambda row: (row[0], row[1]), reverse=True)
    if not rows:
        return '当前没有低库存缺料项。'
    lines = ['**缺料/补货缺口分析**']
    lines.append('| 物料 | 当前库存 | 在途未到 | 建议补货缺口 | 默认供应商 |')
    lines.append('|---|---:|---:|---:|---|')
    for _severity, shortage, material in rows[:limit]:
        unit_name = material.unit.name if material.unit else ''
        lines.append(
            f'| {material.code} {material.name} | {normalize_stock_quantity(material.stock or 0)}{unit_name} | '
            f'{normalize_stock_quantity(on_order.get(material.id, 0))}{unit_name} | {normalize_stock_quantity(shortage)}{unit_name} | '
            f'{material.supplier.name if material.supplier else "-"} |'
        )
    return '\n'.join(lines)


def _ai_stage4_supplier_performance_report(days=90, limit=12):
    today_value = date.today()
    cutoff = today_value - timedelta(days=max(1, int(days or 90)))
    rows = db.session.query(
        Supplier.id,
        Supplier.name,
        func.count(PurchaseOrder.id).label('order_count'),
        func.coalesce(func.sum(PurchaseOrder.total_amount), 0).label('total_amount'),
    ).join(PurchaseOrder, PurchaseOrder.supplier_id == Supplier.id).filter(
        PurchaseOrder.date >= cutoff,
    ).group_by(Supplier.id).order_by(func.count(PurchaseOrder.id).desc()).limit(limit).all()
    if not rows:
        return f'最近{days}天没有采购订单，暂时无法计算供应商履约。'
    lines = [f'**供应商履约分析（最近{days}天采购订单）**']
    lines.append('| 供应商 | 订单数 | 逾期未完 | 未到货数量 | 采购金额 | 履约判断 |')
    lines.append('|---|---:|---:|---:|---:|---|')
    for row in rows:
        orders = PurchaseOrder.query.options(selectinload(PurchaseOrder.items)).filter(
            PurchaseOrder.supplier_id == row.id,
            PurchaseOrder.date >= cutoff,
        ).all()
        overdue = 0
        remaining_qty = 0
        for order in orders:
            remaining = sum(max((item.quantity or 0) - (item.received_quantity or 0), 0) for item in order.items or [])
            remaining_qty += remaining
            if order.expected_date and order.expected_date < today_value and remaining > STOCK_COMPARE_EPSILON and order.status not in ('completed', 'closed'):
                overdue += 1
        status = '风险' if overdue else ('跟进' if remaining_qty > 0 else '正常')
        lines.append(f'| {row.name or "-"} | {row.order_count} | {overdue} | {normalize_stock_quantity(remaining_qty)} | {float(row.total_amount or 0):,.2f} | {status} |')
    return '\n'.join(lines)


def _ai_stage4_stocktake_variance_report(days=90, limit=12):
    cutoff = date.today() - timedelta(days=max(1, int(days or 90)))
    rows = InventoryCheckItem.query.options(
        joinedload(InventoryCheckItem.material),
        joinedload(InventoryCheckItem.inventory_check),
    ).join(InventoryCheck, InventoryCheckItem.inventory_check_id == InventoryCheck.id).filter(
        InventoryCheck.date >= cutoff,
        InventoryCheckItem.difference != 0,
    ).order_by(func.abs(InventoryCheckItem.difference).desc()).limit(limit).all()
    if not rows:
        return f'最近{days}天没有盘点差异记录。'
    lines = [f'**盘点差异分析（最近{days}天）**']
    lines.append('| 盘点单 | 物料 | 系统数 | 实盘数 | 差异 | 原因 |')
    lines.append('|---|---|---:|---:|---:|---|')
    for item in rows:
        material = item.material
        check = item.inventory_check
        lines.append(
            f'| {check.check_no if check else "-"} | {material.code if material else item.material_id} {material.name if material else ""} | '
            f'{normalize_stock_quantity(item.system_stock or 0)} | {normalize_stock_quantity(item.actual_stock or 0)} | '
            f'{normalize_stock_quantity(item.difference or 0)} | {item.reason or "-"} |'
        )
    return '\n'.join(lines)


def _ai_stage4_deep_analysis_response(message, context=None, force=False):
    if not force and not _ai_is_stage4_deep_analysis_question(message):
        return None
    compact = (message or '').replace(' ', '').lower()
    reports = []
    actions = []
    tables = set()
    source_scope = []

    if any(word in compact for word in ('供应商履约', '供应商交付', '供应商到货', '采购履约', 'supplier_performance')):
        if not _ai_capability_allowed('purchase_insights'):
            return _ai_permission_denied_response('purchase_insights')
        reports.append(_ai_stage4_supplier_performance_report(days=90))
        actions.append({'label': '采购订单', 'url': url_for('purchase_order_list')})
        tables.update(('supplier', 'purchase_order', 'purchase_order_item'))
        source_scope.append('最近90天采购履约')
    else:
        if not _ai_capability_allowed('warehouse_insights'):
            return _ai_permission_denied_response('warehouse_insights')
        if any(word in compact for word in ('可用天数', '预计可用', '还能用几天', '库存覆盖', 'supply_days', 'days_of_supply')):
            reports.append(_ai_stage4_days_of_supply_report(days=30))
            source_scope.append('最近30天消耗和当前库存')
        if any(word in compact for word in ('滞销', '呆滞', '慢动销', '长期未出库', 'slow_moving')):
            reports.append(_ai_stage4_slow_moving_report(days=90))
            source_scope.append('最近90天出库流水和当前库存')
        if any(word in compact for word in ('缺料', '缺货', '短缺', '补货缺口', 'shortage')):
            reports.append(_ai_stage4_shortage_report())
            source_scope.append('当前低库存、在途采购和补货缺口')
        if any(word in compact for word in ('盘点差异', '盘盈盘亏', '差异分析', 'stocktake_variance')):
            reports.append(_ai_stage4_stocktake_variance_report(days=90))
            actions.append({'label': '盘点单', 'url': url_for('check_list')})
            source_scope.append('最近90天盘点差异')
        if not reports:
            reports.extend([
                _ai_stage4_days_of_supply_report(days=30),
                _ai_stage4_slow_moving_report(days=90),
                _ai_stage4_shortage_report(),
                _ai_stage4_stocktake_variance_report(days=90),
            ])
            source_scope.append('阶段4库存深度分析组合')
        actions.append({'label': '库存查询', 'url': url_for('stock_query')})
        actions.append({'label': '物料档案', 'url': url_for('material_list')})
        tables.update(('material', 'stock_transaction', 'purchase_order', 'purchase_order_item', 'inventory_check', 'inventory_check_item'))

    reply = '\n\n'.join(reports)
    reply += '\n\nAI只做只读分析和入口定位，不自动提交、审核、完成、调整库存或修改主数据。'
    reply = _ai_append_data_source(
        reply,
        '实时数据库查询',
        '；'.join(source_scope) if source_scope else '阶段4深度分析',
        sorted(tables),
    )
    return _ai_json_response(reply, [], actions[:4])


def _ai_today_summary():
    today = date.today()
    in_count = InOrder.query.filter_by(date=today).count()
    out_count = OutOrder.query.filter_by(date=today).count()
    after_sale_count = AfterSaleOutOrder.query.filter_by(date=today).count()
    transfer_count = TransferOrder.query.filter_by(date=today).count()
    check_count = InventoryCheck.query.filter_by(date=today).count()
    pending_count = (
        InOrder.query.filter_by(status='pending').count()
        + OutOrder.query.filter_by(status='pending').count()
        + AfterSaleOutOrder.query.filter_by(status='pending').count()
        + TransferOrder.query.filter_by(status='pending').count()
        + AdjustmentOrder.query.filter_by(status='pending').count()
        + InventoryCheck.query.filter_by(status='pending').count()
    )
    negative_count = Material.query.filter(Material.stock < 0).count()
    low_count = Material.query.filter(_material_low_stock_filter()).count() if inventory_alert_enabled() else 0
    cards = [
        _ai_card('今日入库单', f'{in_count} 张', url_for('in_order_list')),
        _ai_card('今日领料单', f'{out_count} 张', url_for('out_order_list')),
        _ai_card('今日售后出库', f'{after_sale_count} 张', url_for('after_sale_out_list')),
        _ai_card('今日调拨/盘点', f'调拨 {transfer_count} 张，盘点 {check_count} 张', url_for('transfer_list')),
        _ai_card('待处理单据', f'{pending_count} 张', url_for('pending_documents')),
        _ai_card('库存异常', f'负库存 {negative_count} 项，低库存 {low_count} 项', url_for('material_list', stock_filter='low')),
    ]
    reply = f'今天业务概况：入库 {in_count} 张，领料 {out_count} 张，售后出库 {after_sale_count} 张；待处理 {pending_count} 张；负库存 {negative_count} 项，低库存 {low_count} 项。'
    return reply, cards


def _ai_today_received_materials(limit=12):
    today = date.today()
    rows = (
        InOrderItem.query
        .options(joinedload(InOrderItem.material).joinedload(Material.unit), joinedload(InOrderItem.in_order))
        .join(InOrder, InOrderItem.in_order_id == InOrder.id)
        .join(Material, InOrderItem.material_id == Material.id)
        .filter(InOrder.date == today)
        .order_by(InOrder.id.desc(), InOrderItem.id.asc())
        .limit(limit)
        .all()
    )
    cards = []
    for item in rows:
        material = item.material
        order = item.in_order
        cards.append({
            'title': f'{material.code if material else ""} {material.name if material else ""}'.strip(),
            'meta': f'入库 {normalize_stock_quantity(item.quantity or 0)} {material.unit.name if material and material.unit else ""}，单据 {order.order_no if order else ""}',
            'url': url_for('in_order_detail', id=order.id) if order else '',
        })
    total_orders = InOrder.query.filter_by(date=today).count()
    reply = f'今天共有 {total_orders} 张入库单，下面列出前 {len(cards)} 条入库物料。' if cards else '今天还没有入库物料记录。'
    return reply, cards


