def _ai_stock_transactions(material, limit=8):
    rows = StockTransaction.query.filter_by(material_id=material.id).order_by(StockTransaction.created_at.desc()).limit(limit).all()
    cards = []
    for row in rows:
        when = row.created_at.strftime('%m-%d %H:%M') if row.created_at else ''
        cards.append(_ai_card(
            f'{row.transaction_type or "库存流水"} {normalize_stock_quantity(row.quantity or 0)}',
            f'{when} {row.remark or ""}',
            url_for('material_list', search=material.code or material.name or '')
        ))
    return cards


def _ai_guess_keyword(message):
    text = (message or '').strip()
    for word in ('库存', '物料', '查询', '查一下', '查', '现在', '还有多少', '多少', '低库存', '负库存', '异常'):
        text = text.replace(word, ' ')
    tokens = re.findall(r'[\w\-\u4e00-\u9fff]+', text)
    stop_words = {'帮我', '一下', '今天', '本月', '哪些', '有没有', '还有', '当前'}
    tokens = [token for token in tokens if token not in stop_words]
    return tokens[0] if tokens else ''


def _ai_extract_material_candidates(message):
    text = (message or '').strip()
    candidates = []
    seen = set()
    for token in re.findall(r'[A-Za-z0-9][A-Za-z0-9_\-./*]{1,}', text):
        normalized = token.strip('.,;:!?，。；：！？、')
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        candidates.append(normalized)
    return candidates


def _ai_find_materials_from_message(message, limit=8):
    candidates = _ai_extract_material_candidates(message)
    for keyword in candidates:
        exact = Material.query.options(joinedload(Material.unit), joinedload(Material.category), joinedload(Material.supplier)).filter(
            db.func.lower(Material.code) == keyword.lower()
        ).first()
        if exact:
            return [exact]

    found = []
    seen_ids = set()
    for keyword in candidates:
        for material in _ai_material_query(keyword, limit=limit):
            if material.id in seen_ids:
                continue
            seen_ids.add(material.id)
            found.append(material)
            if len(found) >= limit:
                return found
    return found


def _ai_alert_status_label(status):
    return {
        'disabled': '未启用预警',
        'low': '低于最低库存',
        'danger': '低于安全库存',
        'normal': '正常',
    }.get(status or '', status or '未知')


def _ai_context_value(context, key):
    if isinstance(context, dict):
        return str(context.get(key) or '').strip()
    return ''


def _ai_material_from_context(context):
    """从当前页面上下文推断用户正在查看的物料。
    支持 URL 形如 /material/<id>、/material/edit/<id>、/material_detail/<id>。
    """
    page_url = _ai_context_value(context, 'page_url') or _ai_context_value(context, 'url')
    if not page_url:
        return None
    match = re.search(r'/material(?:_detail|/edit)?/(\d+)(?:\D|$)', page_url)
    if not match:
        return None
    try:
        material_id = int(match.group(1))
    except (ValueError, TypeError):
        return None
    return Material.query.get(material_id)


def _ai_is_purchase_order_receive_request(message, context=None):
    compact = (message or '').strip().replace(' ', '')
    if not compact:
        return False
    compact_lower = compact.lower()
    page_url = _ai_context_value(context, 'page_url') or _ai_context_value(context, 'url')
    on_purchase_order_page = bool(re.search(r'/purchase_order/\d+(?:\D|$)', page_url or ''))
    purchase_words = ('采购单', '采购订单', 'po')
    receive_words = ('入库单', '采购入库', '入库', '下推', '生成入库', '生成采购入库')
    action_words = ('生成', '创建', '下推', '转', '做', '开')
    context_words = ('这张', '这个', '当前', '本单', '该单')
    has_purchase = any(word in compact_lower for word in purchase_words)
    has_receive = any(word in compact for word in receive_words)
    has_action = any(word in compact for word in action_words) or any(word in compact for word in context_words)
    return has_receive and has_action and (has_purchase or on_purchase_order_page)


def _ai_purchase_order_from_context_or_message(message, context=None):
    page_url = _ai_context_value(context, 'page_url') or _ai_context_value(context, 'url')
    candidates = []
    if page_url:
        match = re.search(r'/purchase_order/(\d+)(?:\D|$)', page_url)
        if match:
            try:
                candidates.append(('id', int(match.group(1))))
            except ValueError:
                pass
    for order_no in re.findall(r'\bPO\d{4,}\b', message or '', flags=re.IGNORECASE):
        candidates.append(('order_no', order_no.upper()))

    for kind, value in candidates:
        query = PurchaseOrder.query.options(
            joinedload(PurchaseOrder.items).joinedload(PurchaseOrderItem.material).joinedload(Material.unit),
            joinedload(PurchaseOrder.supplier),
        )
        if kind == 'id':
            order = query.get(value)
        else:
            order = query.filter(db.func.upper(PurchaseOrder.order_no) == value).first()
        if order:
            return order
    return None


def _create_in_order_from_purchase_order_core(order, warehouse='', remark='', submitted_qty_by_id=None):
    if not purchase_order_to_in_order_enabled():
        return None, '系统已关闭采购订单下推入库单'
    if order.status == 'completed':
        return None, '该采购单已全部入库'
    if order.status == 'closed':
        return None, '该采购单已关闭，不能继续入库'

    submitted_qty_by_id = submitted_qty_by_id if isinstance(submitted_qty_by_id, dict) else {}
    receivable_items = []
    for item in order.items:
        remain_qty = round_to_2_decimals((item.quantity or 0) - (item.received_quantity or 0))
        if remain_qty <= 0:
            continue
        if submitted_qty_by_id:
            if item.id not in submitted_qty_by_id:
                continue
            receive_qty = round_to_2_decimals(submitted_qty_by_id.get(item.id) or 0)
            if receive_qty <= 0:
                continue
        else:
            receive_qty = remain_qty
        valid_qty, qty_msg = validate_purchase_receive_quantity(
            item,
            receive_qty,
            item.material.code if item.material else item.material_id,
        )
        if not valid_qty:
            return None, qty_msg
        receivable_items.append((item, receive_qty))
    if not receivable_items:
        update_purchase_order_status(order)
        db.session.commit()
        return None, '该采购单没有可入库数量'

    in_order = InOrder(
        order_no=generate_order_no('IN'),
        date=date.today(),
        supplier_id=order.supplier_id,
        business_type='采购入库',
        purpose=f'采购单 {order.order_no} 入库',
        warehouse=warehouse,
        source_purchase_order_id=order.id,
        remark=remark or f'由采购单 {order.order_no} 下推生成',
        status='pending',
        operator_id=current_user.id,
    )
    db.session.add(in_order)
    db.session.flush()

    for item, receive_qty in receivable_items:
        price = round_to_2_decimals(item.price or (item.material.price if item.material else 0) or 0)
        db.session.add(InOrderItem(
            in_order_id=in_order.id,
            material_id=item.material_id,
            source_purchase_order_item_id=item.id,
            quantity=receive_qty,
            price=price,
            amount=round_to_2_decimals(receive_qty * price),
        ))
        item.received_quantity = round_to_2_decimals((item.received_quantity or 0) + receive_qty)

    recalculate_order_total(in_order)
    update_purchase_order_status(order)
    db.session.commit()
    log_operation('采购单下推采购入库单', f'{order.order_no} -> {in_order.order_no}', 'in_order', in_order.id)
    return in_order, None


def _ai_parse_material_lines(message):
    text = (message or '').strip()
    text = re.sub(r'[，,；;、\n]+', ' ', text)
    parsed = []
    seen = set()
    pattern = re.compile(r'([A-Za-z0-9_\-\u4e00-\u9fff]{2,})\s*(?:数量|qty|x|X|\\*)?\s*([0-9]+(?:\.[0-9]+)?)')
    for code, qty_text in pattern.findall(text):
        if code in {'生成', '创建', '新增', '入库', '出库', '领用', '领料', '给', '采购', '做一张', '开一张'}:
            continue
        material = Material.query.filter(db.func.lower(Material.code) == code.lower()).first()
        if not material:
            material = Material.query.filter(Material.name == code).first()
        if not material:
            like = f'%{code}%'
            matches = Material.query.filter(db.or_(Material.code.ilike(like), Material.name.ilike(like), Material.spec.ilike(like))).limit(2).all()
            material = matches[0] if len(matches) == 1 else None
        if not material or material.id in seen:
            continue
        quantity = round_to_2_decimals(parse_float_value(qty_text, 0))
        if quantity <= 0:
            continue
        parsed.append((material, quantity))
        seen.add(material.id)
    return parsed


