def _ai_extract_transfer_locations(message):
    """从自然语言中提取调拨的源仓库和目标仓库。
    支持的表达式：
        从A仓库转到B仓库 / 从A到B / A调拨到B / 把A仓库的...转到B仓库
    """
    text = (message or '').strip()
    # 统一分隔符，便于正则匹配
    text_norm = re.sub(r'[，,；;、\n]+', ' ', text)
    patterns = [
        # 从X[仓库](转到|调到|到|->)Y[仓库]
        r'从\s*([\u4e00-\u9fffA-Za-z0-9]{1,20})\s*仓库?\s*(?:转到|调拨到|调到|移到|到|->|→)\s*([\u4e00-\u9fffA-Za-z0-9]{1,20})\s*仓库?',
        # X[仓库](转到|调拨到|调到)Y[仓库]
        r'([\u4e00-\u9fffA-Za-z0-9]{1,20})\s*仓库?\s*(?:转到|调拨到|调到|移到|->|→)\s*([\u4e00-\u9fffA-Za-z0-9]{1,20})\s*仓库?',
    ]
    for pattern in patterns:
        m = re.search(pattern, text_norm)
        if m:
            from_loc = m.group(1).strip()
            to_loc = m.group(2).strip()
            # 排除误匹配的关键词
            skip_words = {'生成', '创建', '新增', '调拨', '转移', '物料', '数量'}
            if from_loc in skip_words or to_loc in skip_words:
                continue
            if from_loc and to_loc and from_loc != to_loc:
                return from_loc, to_loc
    return None, None


def _ai_create_transfer_draft(message, manual_confirmation=False, confirmation_token=None, document_job_id=None, source='text'):
    """AI 助手生成库存调拨单草稿。
    示例：从A仓库转到B仓库 M001 100 M002 20
    """
    allowed, error = _ai_draft_execution_allowed('transfer_draft', manual_confirmation)
    if not allowed:
        return None, error
    # AI_TASK: AI-R08-F01 服务端门禁校验
    gate_allowed, gate_reasons = _ai_check_draft_creation_gate(document_job_id)
    if not gate_allowed:
        error_msg = '门禁校验失败，禁止创建草稿：' + '; '.join(gate_reasons)
        app.logger.warning(f'文档任务 {document_job_id} 门禁校验失败: {gate_reasons}')
        return None, error_msg

    from_loc, to_loc = _ai_extract_transfer_locations(message)
    if not from_loc or not to_loc:
        return None, '没有识别到调出/调入仓库。可以这样说：从A仓库转到B仓库 M001 100 M002 20'

    items = _ai_parse_material_lines(message)
    if not items:
        return None, '没有识别到物料和数量。可以这样说：从A仓库转到B仓库 M001 100 M002 20'

    business_key = _ai_draft_business_key_from_items(
        items,
        extra={'from': from_loc, 'to': to_loc, 'message': (message or '')[:200]},
    )
    slot = _ai_draft_idempotency().acquire(
        capability='transfer_draft',
        source=source,
        business_fields=business_key,
        draft_type='transfer',
        request_snapshot={'message': (message or '')[:500]},
        confirmation_token=confirmation_token,
        document_job_id=document_job_id,
    )
    if slot.is_replay and slot.replay:
        return slot.replay, None
    if not slot.acquired:
        return None, slot.conflict_reason

    order = TransferOrder(
        transfer_no=generate_order_no('TF'),
        date=date.today(),
        from_location=from_loc,
        to_location=to_loc,
        remark=(message or '')[:200],
        status='pending',
        operator_id=current_user.id,
    )
    db.session.add(order)
    db.session.flush()
    for material, quantity in items:
        price = round_to_2_decimals(material.price or 0)
        db.session.add(TransferOrderItem(
            transfer_order_id=order.id,
            material_id=material.id,
            quantity=quantity,
            unit_id=material.unit_id,
            price=price,
            amount=round_to_2_decimals(quantity * price),
        ))
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f'AI生成调拨单草稿失败: {e}')
        _ai_draft_idempotency().fail(slot.record, f'创建调拨单草稿失败: {e}')
        return None, '创建调拨单草稿失败，请稍后重试'
    log_operation('AI生成调拨单草稿', f'调拨单：{order.transfer_no}', 'transfer', order.id)
    response = {
        'order_no': order.transfer_no,
        'url': url_for('transfer_detail', id=order.id),
        'items': [{'code': m.code, 'name': m.name, 'quantity': q} for m, q in items],
        'from_location': from_loc,
        'to_location': to_loc,
    }
    _ai_draft_idempotency().complete(
        slot.record,
        draft_type='transfer',
        draft_id=order.id,
        draft_no=order.transfer_no,
        response=response,
    )
    return response, None


def _ai_create_check_draft(message, manual_confirmation=False, confirmation_token=None, document_job_id=None, source='text'):
    """AI 助手生成盘点单草稿。
    示例：盘点 M001 M002 M003  /  生成盘点单 A001 A002
    物料行的 system_stock 自动填入当前库存，actual_stock 等待用户盘点录入。
    """
    allowed, error = _ai_draft_execution_allowed('check_draft', manual_confirmation)
    if not allowed:
        return None, error
    # AI_TASK: AI-R08-F01 服务端门禁校验
    gate_allowed, gate_reasons = _ai_check_draft_creation_gate(document_job_id)
    if not gate_allowed:
        error_msg = '门禁校验失败，禁止创建草稿：' + '; '.join(gate_reasons)
        app.logger.warning(f'文档任务 {document_job_id} 门禁校验失败: {gate_reasons}')
        return None, error_msg

    items = _ai_parse_material_lines(message)
    # 盘点单允许只指定物料不指定数量（数量用于辅助识别，实际以系统库存为准）
    if not items:
        # 尝试仅按物料名称/编码匹配（不要求带数量）
        candidates = _ai_find_materials_from_message(message, limit=20)
        items = [(m, normalize_stock_quantity(m.stock or 0)) for m in candidates]
    if not items:
        return None, '没有识别到要盘点的物料。可以这样说：盘点 M001 M002 M003'

    business_key = _ai_draft_business_key_from_items(items, extra={'message': (message or '')[:200]})
    slot = _ai_draft_idempotency().acquire(
        capability='check_draft',
        source=source,
        business_fields=business_key,
        draft_type='check',
        request_snapshot={'message': (message or '')[:500]},
        confirmation_token=confirmation_token,
        document_job_id=document_job_id,
    )
    if slot.is_replay and slot.replay:
        return slot.replay, None
    if not slot.acquired:
        return None, slot.conflict_reason

    order = InventoryCheck(
        check_no=generate_order_no('CK'),
        date=date.today(),
        remark=(message or '')[:200],
        status='pending',
        operator_id=current_user.id,
    )
    db.session.add(order)
    db.session.flush()
    for material, _ in items:
        sys_stock = normalize_stock_quantity(material.stock or 0)
        db.session.add(InventoryCheckItem(
            inventory_check_id=order.id,
            material_id=material.id,
            system_stock=sys_stock,
            actual_stock=sys_stock,  # 默认等于系统库存，用户盘点时修改
            difference=0,
        ))
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f'AI生成盘点单草稿失败: {e}')
        _ai_draft_idempotency().fail(slot.record, f'创建盘点单草稿失败: {e}')
        return None, '创建盘点单草稿失败，请稍后重试'
    log_operation('AI生成盘点单草稿', f'盘点单：{order.check_no}', 'check', order.id)
    response = {
        'order_no': order.check_no,
        'url': url_for('check_detail', id=order.id),
        'items': [{'code': m.code, 'name': m.name, 'system_stock': normalize_stock_quantity(m.stock or 0)} for m, _ in items],
    }
    _ai_draft_idempotency().complete(
        slot.record,
        draft_type='check',
        draft_id=order.id,
        draft_no=order.check_no,
        response=response,
    )
    return response, None


def _ai_create_adjustment_draft(message, manual_confirmation=False, confirmation_token=None, document_job_id=None, source='text'):
    """AI 助手生成库存调整单草稿。
    示例：报废 M001 5  /  盘亏 A002 3  /  盘盈 B001 10
    调整类型识别：
      loss（盘亏）：报废、损坏、盘亏、损耗、丢失、少了
      surplus（盘盈）：盘盈、多出、溢余、多了
    """
    allowed, error = _ai_draft_execution_allowed('adjustment_draft', manual_confirmation)
    if not allowed:
        return None, error
    # AI_TASK: AI-R08-F01 服务端门禁校验
    gate_allowed, gate_reasons = _ai_check_draft_creation_gate(document_job_id)
    if not gate_allowed:
        error_msg = '门禁校验失败，禁止创建草稿：' + '; '.join(gate_reasons)
        app.logger.warning(f'文档任务 {document_job_id} 门禁校验失败: {gate_reasons}')
        return None, error_msg

    text = (message or '')
    loss_keywords = ('报废', '损坏', '盘亏', '损耗', '丢失', '少了', '坏')
    surplus_keywords = ('盘盈', '多出', '溢余', '多了')
    if any(k in text for k in loss_keywords):
        adjustment_type = 'loss'
        type_label = '盘亏/报废'
    elif any(k in text for k in surplus_keywords):
        adjustment_type = 'surplus'
        type_label = '盘盈'
    else:
        # 默认按盘亏处理（调整单最常见场景是处理差异/报废）
        adjustment_type = 'loss'
        type_label = '盘亏（默认）'

    items = _ai_parse_material_lines(message)
    if not items:
        return None, '没有识别到物料和数量。可以这样说：报废 M001 5  /  盘盈 A002 10'

    business_key = _ai_draft_business_key_from_items(
        items,
        extra={'adjustment_type': adjustment_type, 'message': (message or '')[:200]},
    )
    slot = _ai_draft_idempotency().acquire(
        capability='adjustment_draft',
        source=source,
        business_fields=business_key,
        draft_type='adjustment',
        request_snapshot={'message': (message or '')[:500], 'adjustment_type': adjustment_type},
        confirmation_token=confirmation_token,
        document_job_id=document_job_id,
    )
    if slot.is_replay and slot.replay:
        return slot.replay, None
    if not slot.acquired:
        return None, slot.conflict_reason

    order = AdjustmentOrder(
        adjustment_no=generate_order_no('ADJ'),
        date=date.today(),
        adjustment_type=adjustment_type,
        source_type='manual',
        remark=(message or '')[:200],
        status='pending',
        operator_id=current_user.id,
    )
    db.session.add(order)
    db.session.flush()
    for material, quantity in items:
        # 盘亏数量为负，盘盈为正
        signed_qty = -abs(quantity) if adjustment_type == 'loss' else abs(quantity)
        db.session.add(AdjustmentOrderItem(
            adjustment_order_id=order.id,
            material_id=material.id,
            location=material.spec or '',
            quantity=signed_qty,
            unit_id=material.unit_id,
            reason=(message or '')[:200],
        ))
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f'AI生成调整单草稿失败: {e}')
        _ai_draft_idempotency().fail(slot.record, f'创建调整单草稿失败: {e}')
        return None, '创建调整单草稿失败，请稍后重试'
    log_operation('AI生成调整单草稿', f'调整单：{order.adjustment_no}（{type_label}）', 'adjustment', order.id)
    response = {
        'order_no': order.adjustment_no,
        'url': url_for('adjustment_detail', id=order.id),
        'items': [{'code': m.code, 'name': m.name, 'quantity': q} for m, q in items],
        'adjustment_type': type_label,
    }
    _ai_draft_idempotency().complete(
        slot.record,
        draft_type='adjustment',
        draft_id=order.id,
        draft_no=order.adjustment_no,
        response=response,
    )
    return response, None


