def _ai_stock_shortage_help_response(message):
    compact = (message or '').strip().replace(' ', '')
    shortage_words = (
        '库存不足', '库存不够', '不够库存', '低库存', '负库存', '缺料', '缺货',
        '欠料', '没库存', '没有库存', '库存没了', '库存不够用', '不够用了',
        '没有了', '没了', '没货', '无货', '断货', '用完了', '没有料',
    )
    if not compact or not any(word in compact for word in shortage_words):
        return None

    mentioned_materials = _ai_find_materials_from_message(message, limit=5)
    negative_query = Material.query.options(joinedload(Material.unit)).filter(Material.stock < 0)
    low_query = Material.query.options(joinedload(Material.unit)).filter(_material_low_stock_filter())
    negatives = negative_query.order_by(Material.stock.asc()).limit(8).all()
    lows = low_query.order_by(Material.stock.asc()).limit(8).all() if inventory_alert_enabled() else []

    cards = []
    seen_ids = set()
    for material in mentioned_materials + negatives + lows:
        if material.id in seen_ids:
            continue
        seen_ids.add(material.id)
        cards.append(_ai_material_payload(material))
        if len(cards) >= 8:
            break

    if mentioned_materials:
        first = mentioned_materials[0]
        stock, min_stock, safety_stock, alert_status = _material_alert_status_values(first)
        unit = first.unit.name if first.unit else ''
        reply = (
            f'已识别到物料 {first.code or ""} {first.name or ""} {first.spec or ""}，当前库存 {normalize_stock_quantity(stock)}{unit}，库存状态：{_ai_alert_status_label(alert_status)}。'
            '这种情况不要只问“怎么办”，按缺料处理：'
            '1. 先点库存查询确认该物料是否在其他仓库/库位还有可用库存；'
            '2. 查该物料流水，看是否有未完成入库、误出库或盘点差异；'
            '3. 如果只是实物已到但没入账，补做入库或盘点调整；'
            '4. 如果确实没有货，立即发起采购申请，并把物料编码、规格和需求数量写清楚；'
            '5. 采购到货后从采购订单下推入库，再安排领料。'
        )
    else:
        alert_status = (
            f'当前系统发现负库存 {len(negatives)} 项、低库存 {len(lows)} 项。'
            if inventory_alert_enabled()
            else f'当前系统发现负库存 {len(negatives)} 项；库存预警未启用，低库存按最低库存规则暂不统计。'
        )
        reply = (
            f'{alert_status}库存不足不要直接强行出库，建议按顺序处理：'
            '1. 先查库存确认物料编码、仓库/库位和实际可用数；'
            '2. 查最近入库、出库、盘点流水，排除单据未完成或账实差异；'
            '3. 有实物没入账就补做入库或盘点调整；'
            '4. 确实缺料就发起采购申请或采购订单，到货后再入库；'
            '5. 已经负库存的物料优先处理，避免继续领料扩大差异。'
        )

    material_search = (mentioned_materials[0].code or mentioned_materials[0].name or '') if mentioned_materials else ''
    stock_query_url = url_for('stock_query', search=material_search) if material_search else url_for('stock_query')
    material_list_url = url_for('material_list', search=material_search) if material_search else url_for('material_list', stock_filter='low')
    return _ai_json_response(
        reply,
        cards,
        [
            {'label': '库存查询', 'url': stock_query_url},
            {'label': '物料档案', 'url': material_list_url},
            {'label': '采购申请', 'url': url_for('purchase_request_add_page')},
            {'label': '新建入库单', 'url': url_for('in_order_add_page')},
        ],
    )


def _ai_purchase_order_receive_response(message, context=None):
    if not _ai_is_purchase_order_receive_request(message, context):
        return None
    if not _ai_capability_allowed('purchase_receive_draft'):
        return _ai_permission_denied_response('purchase_receive_draft')
    if current_user.role not in ('admin', 'warehouse', 'purchase'):
        return _ai_json_response('你当前账号没有生成采购入库单权限，请让仓库或采购权限账号操作。')

    order = _ai_purchase_order_from_context_or_message(message, context)
    if not order:
        return _ai_json_response(
            '我需要知道是哪一张采购单。请在采购单详情页直接说“把这张采购单生成入库单”，或带上采购单号，例如“把 PO26050001 生成采购入库单”。',
            actions=[{'label': '采购订单', 'url': url_for('purchase_order_list')}],
        )
    items = []
    for item in order.items:
        remaining = round_to_2_decimals((item.quantity or 0) - (item.received_quantity or 0))
        if remaining <= 0 or not item.material:
            continue
        items.append({
            'code': item.material.code or '',
            'name': item.material.name or '',
            'spec': item.material.spec or '',
            'quantity': remaining,
        })
    if not items:
        return _ai_json_response(
            f'采购单 {order.order_no} 没有可下推的剩余数量。',
            actions=[{'label': '打开采购单', 'url': url_for('purchase_order_detail', id=order.id)}],
        )
    extracted = {
        'document_type': 'in_order',
        'source_text': f'人工确认后从采购订单 {order.order_no} 下推采购入库草稿',
        'supplier': order.supplier.name if order.supplier else '',
        'items': items,
    }
    return _ai_create_draft_from_extracted(
        extracted,
        source='purchase_order',
        context={'page_url': f'/purchase_order/{order.id}', 'page_title': order.order_no},
    )


def _ai_usage_help_response(message):
    compact = (message or '').strip().replace(' ', '')
    if not compact:
        return None

    asks_help = any(word in compact for word in ('怎么', '如何', '不会用', '使用', '操作', '流程', '教程', '教我', '怎么做', '帮我'))
    if not asks_help:
        return None

    general_help = any(word in compact for word in ('不会用', '怎么用', '如何用', '使用系统', '用这个系统', '用这个软件', '管理软件', '教我'))

    stock_shortage_help = _ai_stock_shortage_help_response(message)
    if stock_shortage_help:
        return stock_shortage_help

    if any(word in compact for word in ('入库', '到货', '收货', '来料')):
        return _ai_json_response(
            '入库常用流程：1. 先维护物料和供应商；2. 如果是采购到货，先从采购订单下推入库；3. 录入入库明细、数量、仓库/库位；4. 保存后检查单据；5. 确认无误再完成入库，系统才会增加库存。',
            actions=[
                {'label': '新建入库单', 'url': url_for('in_order_add_page')},
                {'label': '打开入库列表', 'url': url_for('in_order_list')},
                {'label': '打开采购订单', 'url': url_for('purchase_order_list')},
            ],
        )

    if any(word in compact for word in ('领料', '出库', '发料', '销售发货')):
        return _ai_json_response(
            '领料/出库流程：1. 打开新建领料单；2. 选择领用部门、用途和仓库；3. 添加物料编码和数量；4. 保存后核对库存；5. 完成单据后系统扣减库存。也可以直接说“生成领料单 A001 20”，我会先生成草稿。',
            actions=[
                {'label': '新建领料单', 'url': url_for('out_order_add_page')},
                {'label': '打开领料列表', 'url': url_for('out_order_list')},
                {'label': '查询库存', 'url': url_for('stock_query')},
            ],
        )

    if any(word in compact for word in ('采购', '采购申请', '采购单', '采购订单')):
        return _ai_json_response(
            '采购流程：1. 先做采购申请；2. 审核后生成采购订单；3. 供应商到货后从采购订单下推入库；4. 入库完成后库存增加。这样可以追踪申请、订单、入库之间的来源关系。',
            actions=[
                {'label': '采购申请', 'url': url_for('purchase_request_list')},
                {'label': '新建采购申请', 'url': url_for('purchase_request_add_page')},
                {'label': '采购订单', 'url': url_for('purchase_order_list')},
            ],
        )

    if any(word in compact for word in ('扫码', '手机', 'app', 'APP', '条码')):
        return _ai_json_response(
            '手机扫码流程：1. 先下载手机扫码 APP；2. 手机和电脑/服务器在同一网络；3. 在 APP 里配置服务器地址；4. 选择入库、出库、盘点或查询模式；5. 扫码后核对数量再提交。',
            actions=[
                {'label': '下载扫码APP', 'url': url_for('mobile_app_download')},
                {'label': '手工入库', 'url': url_for('mobile_scan', mode='in')},
                {'label': '手工出库', 'url': url_for('mobile_scan', mode='out')},
                {'label': '库存查询', 'url': url_for('mobile_scan', mode='query')},
            ],
        )

    if any(word in compact for word in ('盘点', '盘库')):
        return _ai_json_response(
            '盘点流程：1. 新建盘点单；2. 添加需要盘点的物料；3. 填写实盘数量；4. 核对账面数和差异；5. 完成盘点后生成库存调整草稿，审核提交调整单后才更新库存。盘点前建议先导出当前库存备查。',
            actions=[
                {'label': '盘点列表', 'url': url_for('check_list')},
                {'label': '新建盘点单', 'url': url_for('check_legacy_page')},
                {'label': '查询库存', 'url': url_for('stock_query')},
            ],
        )

    if general_help and not any(word in compact for word in ('入库', '到货', '收货', '来料', '领料', '出库', '发料', '采购', '扫码', '手机', 'app', 'APP', '条码', '盘点', '盘库', '物料', '基础资料', '供应商', '客户')):
        return _ai_json_response(
            '这个系统可以按“先建资料、再做单据、最后查报表”的顺序用：1. 先维护仓库、物料、供应商/客户；2. 采购先做采购申请和采购订单；3. 到货后做入库单；4. 生产或销售领用时做领料单；5. 每天看首页待处理、库存异常和库存查询。',
            actions=[
                {'label': '物料档案', 'url': url_for('material_list')},
                {'label': '采购申请', 'url': url_for('purchase_request_list')},
                {'label': '新建入库单', 'url': url_for('in_order_add_page')},
                {'label': '新建领料单', 'url': url_for('out_order_add_page')},
                {'label': '待处理中心', 'url': url_for('pending_documents')},
            ],
        )

    if any(word in compact for word in ('物料', '基础资料', '供应商', '客户', '仓库')):
        return _ai_json_response(
            '基础资料建议先按这个顺序维护：1. 仓库；2. 物料分类和单位；3. 供应商/客户；4. 物料档案。物料编码建议保持唯一、稳定，后续出入库和扫码都依赖它。',
            actions=[
                {'label': '物料档案', 'url': url_for('material_list')},
                {'label': '仓库资料', 'url': url_for('warehouse_list')},
                {'label': '供应商', 'url': url_for('supplier_list')},
                {'label': '客户', 'url': url_for('customer_list')},
            ],
        )

    return _ai_json_response(
        '你可以先按这条主线使用：先维护基础资料，再做采购申请和采购订单，到货后入库；生产或销售领用时做领料单；每天看首页待处理和库存异常。你也可以直接问我“怎么入库”“怎么领料”“怎么采购”“怎么扫码”。',
        actions=[
            {'label': '物料档案', 'url': url_for('material_list')},
            {'label': '采购申请', 'url': url_for('purchase_request_list')},
            {'label': '入库列表', 'url': url_for('in_order_list')},
            {'label': '领料列表', 'url': url_for('out_order_list')},
            {'label': '待处理中心', 'url': url_for('pending_documents')},
        ],
    )


def _ai_skill_catalog_response(message):
    compact = (message or '').strip().replace(' ', '').lower()
    if not compact:
        return None
    skill_words = ('技能', '能力', '会什么', '能做什么', '可以做什么', '你会干什么', '功能清单', '能力清单')
    if not any(word in compact for word in skill_words):
        return None

    cards = [
        {'title': skill['title'], 'meta': skill['description']}
        for skill in AI_LOCAL_SKILLS
        if skill['name'] != 'skill_catalog'
    ]
    return _ai_json_response(
        '我现在先按本地技能表处理确定性仓库问题，命中不了再交给大模型理解。已接入的本地技能如下，后续可以继续按业务场景扩展。',
        cards,
        [
            {'label': '库存查询', 'url': url_for('stock_query')},
            {'label': '待处理中心', 'url': url_for('pending_documents')},
            {'label': '系统设置', 'url': url_for('system_settings_page')},
        ],
    )


