def _ai_try_local_skills(message, context=None):
    for skill in AI_LOCAL_SKILLS:
        try:
            response = skill['handler'](message, context)
        except TypeError:
            response = skill['handler'](message)
        if response:
            return response, skill['name']
    return None, ''


def _ai_rule_based_response(message):
    stage4_response = _ai_stage4_deep_analysis_response(message)
    if stage4_response:
        return stage4_response
    local_response, _skill_name = _ai_try_local_skills(message)
    if local_response:
        return local_response

    compact = message.replace(' ', '')
    if any(word in compact for word in ('今天', '今日')) and any(word in compact for word in ('出库', '领料', '发出', '领用', '用了')):
        reply, cards = _ai_today_issued_materials()
        return _ai_json_response(reply, cards, [{'label': '打开出库列表', 'url': url_for('out_order_list')}])

    if any(word in compact for word in ('今天', '今日')) and any(word in compact for word in ('到货', '到了', '入库', '到料', '来料', '收货')):
        reply, cards = _ai_today_received_materials()
        return _ai_json_response(reply, cards, [{'label': '打开入库列表', 'url': url_for('in_order_list')}])

    if any(word in compact for word in ('今天', '今日', '概况', '汇总', '看板')) and not any(word in compact for word in ('生成', '创建', '新增')):
        reply, cards = _ai_today_summary()
        return _ai_json_response(reply, cards, [
            {'label': '打开首页看板', 'url': url_for('index')},
            {'label': '查看待处理', 'url': url_for('pending_documents')},
        ])

    if any(word in compact for word in ('生成', '创建', '新增', '开一张', '做一张')):
        if any(word in compact for word in ('领料', '出库')):
            draft, error = _ai_create_out_order_draft(message)
            if error:
                return _ai_json_response(error)
            return _ai_json_response(
                f'已生成领料单草稿 {draft["order_no"]}，请打开检查后再提交。',
                draft['items'],
                [{'label': '打开草稿', 'url': draft['url']}],
            )
        if '入库' in compact:
            draft, error = _ai_create_in_order_draft(message)
            if error:
                return _ai_json_response(error)
            return _ai_json_response(
                f'已生成入库单草稿 {draft["order_no"]}，请打开检查后再提交。',
                draft['items'],
                [{'label': '打开草稿', 'url': draft['url']}],
            )
        if any(word in compact for word in ('调拨', '转移', '转库', '调转')):
            draft, error = _ai_create_transfer_draft(message)
            if error:
                return _ai_json_response(error)
            return _ai_json_response(
                f'已生成调拨单草稿 {draft["order_no"]}（{draft["from_location"]} → {draft["to_location"]}），请打开检查后再提交。',
                draft['items'],
                [{'label': '打开草稿', 'url': draft['url']}],
            )
        if any(word in compact for word in ('盘点', '盘库')):
            draft, error = _ai_create_check_draft(message)
            if error:
                return _ai_json_response(error)
            return _ai_json_response(
                f'已生成盘点单草稿 {draft["order_no"]}，系统库存已自动填入，请盘点后录入实际数量。',
                draft['items'],
                [{'label': '打开草稿', 'url': draft['url']}],
            )
        if any(word in compact for word in ('调整', '报废', '盘亏', '盘盈', '损坏', '损耗')):
            draft, error = _ai_create_adjustment_draft(message)
            if error:
                return _ai_json_response(error)
            return _ai_json_response(
                f'已生成调整单草稿 {draft["order_no"]}（{draft["adjustment_type"]}），请打开检查后再提交。',
                draft['items'],
                [{'label': '打开草稿', 'url': draft['url']}],
            )

    # 盘点支持无"生成"关键词直接触发：盘点 M001 M002
    if any(word in compact for word in ('盘点', '盘库')) and not any(
        word in compact for word in ('查', '查看', '打开', '单号')
    ):
        draft, error = _ai_create_check_draft(message)
        if error:
            return _ai_json_response(error)
        return _ai_json_response(
            f'已生成盘点单草稿 {draft["order_no"]}，系统库存已自动填入，请盘点后录入实际数量。',
            draft['items'],
            [{'label': '打开草稿', 'url': draft['url']}],
        )

    # 报废/盘亏/盘盈 支持无"生成"关键词直接触发
    if any(word in compact for word in ('报废', '盘亏', '盘盈', '损坏')) and not any(
        word in compact for word in ('查', '查看', '打开', '单号')
    ):
        draft, error = _ai_create_adjustment_draft(message)
        if error:
            return _ai_json_response(error)
        return _ai_json_response(
            f'已生成调整单草稿 {draft["order_no"]}（{draft["adjustment_type"]}），请打开检查后再提交。',
            draft['items'],
            [{'label': '打开草稿', 'url': draft['url']}],
        )

    found_orders = _ai_find_orders(message)
    if found_orders and any(word in compact for word in ('单号', '单据', '打开', '查')):
        return _ai_json_response(
            f'找到 {len(found_orders)} 张相关单据，下面可以直接打开。',
            found_orders,
            [{'label': '全部待处理', 'url': url_for('pending_documents')}],
        )

    if any(word in compact for word in ('异常', '预警', '低库存', '负库存', '超储', '库存不足')):
        low_query = Material.query.options(joinedload(Material.unit)).filter(_material_low_stock_filter())
        negative_query = Material.query.options(joinedload(Material.unit)).filter(Material.stock < 0)
        lows = low_query.order_by(Material.stock.asc()).limit(8).all() if inventory_alert_enabled() else []
        negatives = negative_query.order_by(Material.stock.asc()).limit(8).all()
        cards = [_ai_material_payload(item) for item in negatives + lows]
        return _ai_json_response(
            f'发现负库存 {len(negatives)} 项，低库存 {len(lows)} 项。下面显示前 {len(cards)} 项。',
            cards,
            [{'label': '查看库存预警', 'url': url_for('material_list', stock_filter='low')}],
        )

    if any(word in compact for word in ('待办', '待处理', '待入库', '待出库', '未完成', '待审核', '未审核')):
        cards = _ai_pending_documents(limit=12)
        return _ai_json_response(
            f'当前找到 {len(cards)} 张待处理/待审核单据，已按最新单据优先显示。',
            cards,
            [{'label': '打开待处理中心', 'url': url_for('pending_documents')}],
        )

    # 数据分析关键词：即使LLM未配置也能用本地规则触发
    if any(word in compact for word in ('周转', '动销', '滞销', '销量排行', '销量排名', '出货排行')):
        return _ai_json_response(_ai_analysis_inventory_turnover())
    if any(word in compact for word in ('库存金额', '库存价值', '资金占用', '库存总值')):
        return _ai_json_response(_ai_analysis_stock_value())
    if any(word in compact for word in ('供应商分析', '供应商排行', '采购排行', '采购排名', '供应商排名')):
        return _ai_json_response(_ai_analysis_supplier())
    if any(word in compact for word in ('补货建议', '缺货清单', '补货清单', '低库存报告', '低库存报表')):
        return _ai_json_response(_ai_analysis_low_stock_report())
    if any(word in compact for word in ('消耗趋势', '消耗多少', '能用多久', '够用几天', '还够用', '消耗分析')):
        kw = _ai_guess_keyword(message)
        if not kw:
            return _ai_json_response('请告诉我物料编码或名称，例如：查 M001 消耗趋势。')
        return _ai_json_response(_ai_analysis_consumption_trend(kw))

    keyword = _ai_guess_keyword(message)
    materials = _ai_material_query(keyword, limit=8)
    if materials:
        cards = [_ai_material_payload(material) for material in materials]
        actions = [{'label': '打开物料列表', 'url': url_for('material_list', search=keyword)}]
        if len(materials) == 1 and any(word in compact for word in ('流水', '明细', '变化', '记录', '最近')):
            cards = _ai_stock_transactions(materials[0]) or cards
            actions.append({'label': '查看物料', 'url': url_for('material_list', search=materials[0].code or materials[0].name or '')})
        return _ai_json_response(
            f'找到 {len(materials)} 个相关物料。可以继续问“查 {materials[0].code} 流水”或“生成领料单 {materials[0].code} 10”。',
            cards,
            actions,
        )

    return _ai_json_response(
        '我可以查库存、查单号、查今日概况、查待处理、查库存异常、查物料流水，也可以生成各类单据草稿。示例：查 A001 库存；查 IN26050001；今天概况；查 A001 流水；生成领料单 A001 20；从A仓库转到B仓库 M001 100；盘点 M001 M002；报废 M001 5；盘盈 A002 10。'
    )


def _ai_feature_enabled(key, default=True):
    return get_system_setting_bool(key, bool(default))


def _ai_global_enabled():
    return _ai_feature_enabled('ai_feature_global_enabled', True)


def _ai_degrade_local_only():
    return _ai_feature_enabled('ai_degrade_local_only', False)


def _ai_rollout_mode():
    """AI-R17-F01：返回归一化后的灰度模式（off/allowlist/role/all，默认 off）。

    旧值 admin_only/read_only/read_draft 通过 rollout_control.normalize_mode 自动映射：
    admin_only→off，read_only/read_draft→role，all→all。
    """
    # AI_TASK: AI-R17-F01
    from ai.ops.rollout_control import normalize_mode, DEFAULT_MODE
    raw_mode = get_system_setting('ai_feature_rollout_mode', DEFAULT_MODE)
    return normalize_mode(raw_mode)


def _ai_allowed_user_ids():
    """AI-R17-F01：从系统设置读取灰度白名单用户 ID 列表。"""
    # AI_TASK: AI-R17-F01
    from ai.ops.rollout_control import parse_allowed_user_ids
    raw = get_system_setting('ai_feature_allowed_user_ids', '')
    return parse_allowed_user_ids(raw)


def _ai_force_fallback():
    """AI-R17-F01：Provider 紧急回滚（降级为人工流程）是否开启。"""
    # AI_TASK: AI-R17-F01
    return _ai_feature_enabled('ai_force_fallback', False)


def _ai_capability_allowed_by_rollout(capability, role, user_id=None, risk_level=None, source='api'):
    """AI-R17-F01：按固定权限判定顺序进行灰度判定。

    权限判定顺序固定为：全局开关 → 功能开关 → 角色权限 → 用户白名单 → 风险级别 → 人工确认边界。

    Args:
        capability: AI 能力名。
        role: 用户角色（admin 直通）。
        user_id: 用户 ID（allowlist 模式必填，None 视为未登录）。
        risk_level: 风险级别（None 时从工具规范读取）。
        source: 请求来源（api/page/agent/background），用于审计。

    Returns:
        bool：是否允许。
    """
    # AI_TASK: AI-R17-F01
    from ai.ops.rollout_control import evaluate_rollout_access
    if risk_level is None:
        spec = get_ai_tool_spec(capability)
        risk_level = spec.risk_level if spec else 'read'
    decision = evaluate_rollout_access(
        capability=capability,
        role=role,
        user_id=user_id,
        risk_level=risk_level,
        mode=_ai_rollout_mode(),
        allowed_user_ids=_ai_allowed_user_ids(),
        global_enabled=_ai_global_enabled(),
    )
    # 被拒绝时写灰度拒绝审计（不阻塞主流程，仅记录）
    if not decision.allowed and has_request_context():
        try:
            _ai_record_rollout_denied_audit(decision, source)
        except Exception as exc:  # noqa: BLE001
            app.logger.warning(f'AI-R17-F01 写灰度拒绝审计失败: {exc}')
    return decision.allowed


def _ai_llm_configured(overrides=None):
    return bool(
        _ai_llm_enabled(overrides)
        and _ai_llm_api_key(overrides)
    )


def _ai_override_value(overrides, key):
    if isinstance(overrides, dict) and key in overrides:
        return str(overrides.get(key) or '').strip()
    return None


def _ai_llm_enabled(overrides=None):
    if _ai_degrade_local_only():
        return False
    override = _ai_override_value(overrides, 'ai_llm_enabled')
    if override is not None:
        return override == '1'
    return get_system_setting_bool('ai_llm_enabled', bool(app.config.get('WMS_LLM_ENABLED', True)))


def _ai_llm_api_key(overrides=None):
    override = _ai_override_value(overrides, 'ai_llm_api_key')
    if override:
        return override
    return (get_system_setting('ai_llm_api_key', '') or str(app.config.get('WMS_LLM_API_KEY') or '')).strip()


def _ai_llm_model(overrides=None):
    override = _ai_override_value(overrides, 'ai_llm_model')
    if override:
        return override
    return (get_system_setting('ai_llm_model', app.config.get('WMS_LLM_MODEL', 'gpt-4.1-mini')) or 'gpt-4.1-mini').strip()


def _ai_llm_vision_enabled(overrides=None):
    if not _ai_feature_enabled('ai_feature_vision_enabled', True):
        return False
    override = _ai_override_value(overrides, 'ai_llm_vision_enabled')
    if override is not None:
        return override == '1'
    return get_system_setting_bool('ai_llm_vision_enabled', True)


def _ai_llm_timeout_seconds(overrides=None):
    override = _ai_override_value(overrides, 'ai_llm_timeout_seconds')
    if override:
        try:
            return max(1.0, min(60.0, float(override)))
        except ValueError:
            return 8.0
    return get_system_setting_float('ai_llm_timeout_seconds', float(app.config.get('WMS_LLM_TIMEOUT_SECONDS') or 8))


def _ai_llm_max_tokens(overrides=None):
    override = _ai_override_value(overrides, 'ai_llm_max_tokens')
    if override:
        try:
            return max(50, min(2000, int(override)))
        except ValueError:
            return 300
    return get_system_setting_int('ai_llm_max_tokens', int(app.config.get('WMS_LLM_MAX_TOKENS') or 300))


def _ai_llm_endpoint(overrides=None):
    override = _ai_override_value(overrides, 'ai_llm_base_url')
    base_url = override or get_system_setting(
        'ai_llm_base_url',
        app.config.get('WMS_LLM_BASE_URL') or 'https://api.openai.com/v1/chat/completions',
    ).strip()
    normalized = base_url.rstrip('/')
    if normalized.endswith('/chat/completions'):
        return normalized
    return normalized + '/chat/completions'


def _ai_llm_headers(overrides=None):
    return {
        'Authorization': f'Bearer {_ai_llm_api_key(overrides)}',
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) WMS-AI-Assistant/1.0',
    }


def _ai_extract_json_object(text):
    text = (text or '').strip()
    if not text:
        return None
    if text.startswith('```'):
        text = re.sub(r'^```(?:json)?\s*', '', text, flags=re.IGNORECASE)
        text = re.sub(r'\s*```$', '', text)
    try:
        return json.loads(text)
    except ValueError:
        start = text.find('{')
        end = text.rfind('}')
        if start >= 0 and end > start:
            try:
                return json.loads(text[start:end + 1])
            except ValueError:
                return None
    return None


def _ai_normalize_image_attachments(raw_attachments):
    if not isinstance(raw_attachments, list):
        return [], ''
    if len(raw_attachments) > 3:
        return [], '一次最多上传 3 张图片。'
    images = []
    allowed_types = {'image/png', 'image/jpeg', 'image/webp', 'image/gif'}
    for item in raw_attachments:
        if not isinstance(item, dict):
            continue
        data_url = str(item.get('data_url') or '').strip()
        mime_type = str(item.get('mime_type') or '').strip().lower()
        name = str(item.get('name') or '图片').strip()[:80]
        if not data_url.startswith('data:image/') or ';base64,' not in data_url:
            return [], '图片格式不正确，请上传 PNG、JPG、WEBP 或 GIF 图片。'
        header, b64_data = data_url.split(',', 1)
        header_type = header[5:].split(';', 1)[0].lower()
        mime_type = mime_type or header_type
        if mime_type not in allowed_types or header_type not in allowed_types:
            return [], '只支持 PNG、JPG、WEBP 或 GIF 图片。'
        if len(b64_data) > 14 * 1024 * 1024:
            return [], '图片太大，请上传 10MB 以内的清晰原图。'
        data_url, mime_type, compress_error = _ai_prepare_vision_image(data_url, mime_type)
        if compress_error:
            return [], compress_error
        images.append({'name': name, 'mime_type': mime_type, 'data_url': data_url})
    return images, ''


def _ai_prepare_vision_image(data_url, mime_type):
    try:
        _header, b64_data = data_url.split(',', 1)
        image_bytes = base64.b64decode(b64_data, validate=True)
    except Exception:
        return data_url, mime_type, '图片 base64 数据不正确，请重新上传。'

    if len(image_bytes) <= 350 * 1024 and mime_type in {'image/jpeg', 'image/png', 'image/webp'}:
        return data_url, mime_type, ''

    try:
        from PIL import Image, ImageOps

        with Image.open(io.BytesIO(image_bytes)) as image:
            image = ImageOps.exif_transpose(image)
            if image.mode not in ('RGB', 'L'):
                background = Image.new('RGB', image.size, 'white')
                if image.mode in ('RGBA', 'LA'):
                    background.paste(image.convert('RGBA'), mask=image.convert('RGBA').split()[-1])
                    image = background
                else:
                    image = image.convert('RGB')
            elif image.mode == 'L':
                image = image.convert('RGB')

            max_side = 1800
            if max(image.size) > max_side:
                image.thumbnail((max_side, max_side), Image.Resampling.LANCZOS)

            output = io.BytesIO()
            image.save(output, format='JPEG', quality=86, optimize=True)
            compressed = output.getvalue()
            if len(compressed) > 2 * 1024 * 1024:
                if max(image.size) > 1600:
                    image.thumbnail((1600, 1600), Image.Resampling.LANCZOS)
                output = io.BytesIO()
                image.save(output, format='JPEG', quality=80, optimize=True)
                compressed = output.getvalue()
    except Exception as exc:
        app.logger.warning('AI image compression failed: %s', exc)
        return data_url, mime_type, ''

    compressed_url = 'data:image/jpeg;base64,' + base64.b64encode(compressed).decode('ascii')
    return compressed_url, 'image/jpeg', ''


def _ai_normalize_intent(raw):
    if not isinstance(raw, dict):
        return None
    intent = str(raw.get('intent') or '').strip()
    if intent not in AI_ASSISTANT_INTENTS:
        return None
    params = raw.get('params') if isinstance(raw.get('params'), dict) else {}
    return {'intent': intent, 'params': params}


def _ai_call_llm_intent(message, overrides=None):
    if not _ai_llm_configured(overrides):
        return None

    system_prompt = (
        '你是仓库管理系统的意图解析器，只输出 JSON，不要输出解释。'
        '可用 intent：greeting, model_status, current_time, general_chat, inventory_discrepancy, today_issued_materials, today_received_materials, today_summary, '
        'create_out_order_draft, create_in_order_draft, create_transfer_draft, create_check_draft, create_adjustment_draft, '
        'find_orders, stock_alerts, pending_documents, query_material, stock_transactions, '
        'analysis_turnover, analysis_stock_value, analysis_supplier, analysis_consumption_trend, analysis_low_stock, analysis_category, exception_workbench, agent_patrol, delivery_note_inbound, help。'
        'params 允许包含：keyword、warehouse（仓库名/库位，字符串）、days（天数，整数）、category（物料分类名，字符串）。'
        '只有用户明确提到时才填相应字段，未提到就省略。'
        '新增、生成、开单只能选择草稿 intent；不要选择提交、审核、完成等高风险动作。'
        '如果用户问库存、物料、还有多少，选择 query_material；问流水/最近变化选择 stock_transactions；'
        '问库存账物不一致/账实不符/账实不一致/系统库存和实物不一致/库存盘点差异/库存不准怎么办，选择 inventory_discrepancy；'
        '问单号/单据选择 find_orders；问待办/待审核选择 pending_documents；问异常工作台/风险总览/今天优先处理什么选择 exception_workbench；问agent巡检/自动巡检/帮我巡检仓库选择 agent_patrol；问上传送货单/送货单入库/识别送货单生成采购入库选择 delivery_note_inbound；问异常/预警/负库存/低库存选择 stock_alerts；'
        '问你好/您好/在吗选择 greeting；问你是谁/哪个模型/是否接入大模型选择 model_status；'
        '问现在几点/当前时间/今天日期选择 current_time；完全不属于仓库业务或系统操作的问题选择 general_chat；'
        '问今天概况选择 today_summary；问今天入库/到货选择 today_received_materials；问今天出库/领料选择 today_issued_materials。'
        '生成领料单/出库单选择 create_out_order_draft；生成入库单/产品入库选择 create_in_order_draft；'
        '调拨/转移/转库（从一个仓库转到另一个仓库）选择 create_transfer_draft；'
        '盘点/盘库/清点库存选择 create_check_draft；'
        '报废/盘亏/盘盈/损坏/调整数量选择 create_adjustment_draft。'
        '问周转/动销/滞销/销量排行选择 analysis_turnover；近N天/最近一段时间的周转记得在 params.days 填数字（默认90）。'
        '问库存金额/库存价值/资金占用选择 analysis_stock_value；按分类/类别分析时在 params.category 填分类名。'
        '问供应商分析/采购排行选择 analysis_supplier；'
        '问某物料消耗趋势/消耗多少/能用多久/还够用几天选择 analysis_consumption_trend（keyword 填物料编码或名称，days 可选默认30）。'
        '问补货建议/低库存报告/缺货清单选择 analysis_low_stock。'
        '问按分类汇总/各分类库存/分类占比选择 analysis_category。'
        '输出格式示例：{"intent":"query_material","params":{"keyword":"A001"}}'
    )
    payload = {
        'model': _ai_llm_model(overrides),
        'messages': [
            {'role': 'system', 'content': system_prompt},
            {'role': 'user', 'content': message[:1000]},
        ],
        'temperature': 0,
        'max_tokens': _ai_llm_max_tokens(overrides),
    }
    request_payload = dict(payload, response_format={'type': 'json_object'})
    headers = _ai_llm_headers(overrides)
    try:
        response = requests.post(
            _ai_llm_endpoint(overrides),
            headers=headers,
            json=request_payload,
            timeout=min(max(_ai_llm_timeout_seconds(overrides), 2), 6),
        )
        if response.status_code == 400:
            response = requests.post(
                _ai_llm_endpoint(overrides),
                headers=headers,
                json=payload,
                timeout=min(max(_ai_llm_timeout_seconds(overrides), 2), 6),
            )
        response.raise_for_status()
        data = response.json()
        content = (((data.get('choices') or [{}])[0].get('message') or {}).get('content') or '').strip()
        return _ai_normalize_intent(_ai_extract_json_object(content))
    except Exception as exc:
        app.logger.warning('AI intent model unavailable, falling back to rules: %s', exc)
        return None


def _ai_call_llm_chat(message):
    if not _ai_llm_configured():
        return None

    system_prompt = (
        '你是仓库管理系统里的AI业务顾问，不是通用闲聊机器人。'
        '系统模块包括：物料档案、仓库/库位、供应商/客户、采购申请、采购订单、采购入库、领料/出库、盘点、调拨、调整、BOM、委外、库存查询、库存预警、报表、打印模板、手机扫码。'
        '回答任何仓库问题时，先判断业务场景，再给可执行步骤；要尽量引用系统里的页面入口名称，例如库存查询、物料档案、采购申请、采购订单、入库列表、领料列表、待处理中心。'
        '如果用户提到物料编码、规格、单号、客户、供应商、数量，必须围绕这些信息回答，不要说“我没看懂”。'
        '涉及真实库存、单据、金额、客户、供应商、审核状态等系统数据时，不要编造；应建议用户用系统查询，或说明需要通过后台工具查询真实数据。'
        '库存不足/没货/缺料：建议先查库存和库位，再查流水，排除未完成单据或盘点差异；确实缺料则发起采购申请/采购订单，到货后入库。'
        '入库后库存没变：检查单据是否只是草稿/未完成、是否关联采购订单、仓库库位是否正确、是否被反提交。'
        '出库失败或库存不足：检查物料编码、仓库库位、可用库存、是否允许负库存，再改数量或补货。'
        '如果用户要求提交、审核、删除、清库、改库存等高风险动作，说明只能协助生成草稿或引导到页面由用户确认。'
        '回答要简洁、直接、像仓库主管给操作建议；优先控制在 200 字以内。不要写营销话术，不要泛泛讲“先维护基础资料”除非问题确实是基础资料维护。'
    )
    payload = {
        'model': _ai_llm_model(),
        'messages': [
            {'role': 'system', 'content': system_prompt},
            {'role': 'user', 'content': message[:1000]},
        ],
        'temperature': 0.4,
        'max_tokens': min(max(_ai_llm_max_tokens(), 120), 420),
    }
    headers = _ai_llm_headers()
    try:
        response = requests.post(
            _ai_llm_endpoint(),
            headers=headers,
            json=payload,
            timeout=_ai_llm_timeout_seconds(),
        )
        response.raise_for_status()
        data = response.json()
        content = (((data.get('choices') or [{}])[0].get('message') or {}).get('content') or '').strip()
        return content[:1200] if content else None
    except Exception as exc:
        app.logger.warning('AI chat model unavailable, falling back to rules: %s', exc)
        return None


def _ai_call_llm_vision(message, images, context=None):
    """调用视觉大模型识别图片，返回 (reply, extracted, error)。
    extracted 为结构化提取结果（dict 或 None），包含 document_type / items 等。
    """
    if not _ai_llm_configured():
        return None, None, '请先启用大模型并保存 API Key'
    if not _ai_llm_vision_enabled():
        return None, None, '系统设置里没有启用图片识别'
    if not images:
        return None, None, '没有收到图片附件'

    page_title = _ai_context_value(context, 'page_title')
    page_url = _ai_context_value(context, 'page_url')
    system_prompt = (
        '你是仓库管理系统里的AI视觉业务助手。用户会上传仓库系统截图、单据图片、物料照片、标签或异常现场图片。'
        '请结合图片和用户文字判断业务场景，优先识别：物料编码、单号、数量、状态、错误提示、页面位置、需要用户点击的系统入口。'
        '如果图片是系统页面截图，要指出当前页面可能是什么模块，并给下一步操作建议。'
        '涉及真实库存、金额、审批状态时，不要凭图片编造最终结果；应建议到系统对应页面查询或通过已接入工具查询。'
        '回答要简洁直接，像仓库主管指导操作。\n\n'
        '【结构化提取】如果图片包含物料清单、送货单、领料单、出库单、入库单、盘点表、库存调整单或物料标签，'
        '请在回答末尾追加一个 JSON 代码块（用 ```json 包裹），格式如下：\n'
        '```json\n'
        '{"document_type": "in_order", "items": [{"code": "A001", "name": "物料名称", "quantity": 10}], '
        '"order_no": "单号(如有)", "remarks": "备注(如有)", "adjustment_type": "loss"}\n'
        '```\n'
        'document_type 只能选：in_order（入库/送货/采购到货）、out_order（出库/领料/发料）、'
        'transfer（调拨）、check（盘点表）、adjustment（库存调整/盘盈盘亏/报损报废）、label（单个物料标签）、other（其他）。\n'
        '当 document_type 为 adjustment 时，必须输出 adjustment_type 字段，取值：loss（盘亏/报废/损耗）或 surplus（盘盈/溢余）。\n'
        'quantity 必须是数字（正数表示实际数量，系统会按 adjustment_type 自动加正负号）。无法识别的字段留空或省略。items 为空数组时也要输出。'
    )
    user_content = [{'type': 'text', 'text': (message or '请分析这张图片，指出和仓库业务相关的问题及下一步操作。')[:1200]}]
    if page_title or page_url:
        user_content.append({'type': 'text', 'text': f'当前系统页面：{page_title or "-"} {page_url or ""}'.strip()})
    for image in images:
        user_content.append({'type': 'image_url', 'image_url': {'url': image['data_url']}})

    payload = {
        'model': _ai_llm_model(),
        'messages': [
            {'role': 'system', 'content': system_prompt},
            {'role': 'user', 'content': user_content},
        ],
        'temperature': 0.2,
        'max_tokens': min(max(_ai_llm_max_tokens(), 200), 1200),
    }
    headers = _ai_llm_headers()
    try:
        response = requests.post(
            _ai_llm_endpoint(),
            headers=headers,
            json=payload,
            timeout=max(_ai_llm_timeout_seconds(), 60),
        )
        if not response.ok:
            return None, None, _ai_llm_error_message(response)
        response.raise_for_status()
        data = response.json()
        content = (((data.get('choices') or [{}])[0].get('message') or {}).get('content') or '').strip()
        if not content:
            return None, None, '供应商接口返回成功，但 choices[0].message.content 为空'
        reply, extracted = _ai_vision_parse_extracted(content)
        return reply[:1400], extracted, ''
    except Exception as exc:
        app.logger.warning('AI vision model unavailable: %s', exc)
        return None, None, str(exc)


def _ai_vision_parse_extracted(content):
    """从视觉模型回复中解析末尾的 JSON 代码块，返回 (clean_reply, extracted_or_none)"""
    if not content:
        return '', None
    # 兼容 ```json\n...```、```json...```、```...``` 等多种写法，不强求换行符
    match = re.search(r'```(?:json)?\s*([\s\S]*?)\s*```', content)
    if not match:
        return content.strip(), None
    json_str = match.group(1).strip()
    try:
        extracted = json.loads(json_str)
        if isinstance(extracted, dict):
            clean = content[:match.start()].rstrip()
            return clean, extracted
    except (ValueError, TypeError):
        pass
    return content.strip(), None


def _ai_vision_try_create_draft(extracted, message):
    """根据视觉模型提取的结构化数据尝试创建单据草稿。
    返回 (reply, cards, actions) 或 None。
    """
    if not extracted or not isinstance(extracted, dict):
        return None
    doc_type = str(extracted.get('document_type') or '').strip().lower()
    items_raw = extracted.get('items') or []
    if not items_raw or not isinstance(items_raw, list):
        return None
    # 只对明确的单据类型自动建单
    if doc_type not in ('in_order', 'out_order', 'transfer', 'check', 'adjustment'):
        return None

    matched = []
    unmatched = []
    for item in items_raw:
        if not isinstance(item, dict):
            continue
        code = str(item.get('code') or '').strip()
        name = str(item.get('name') or '').strip()
        qty = item.get('quantity')
        try:
            qty = float(qty) if qty is not None else None
        except (ValueError, TypeError):
            qty = None
        if not code and not name:
            continue
        material = _ai_material_query(code or name, limit=1)
        if not material and name and name != code:
            material = _ai_material_query(name, limit=1)
        if material and qty is not None and qty > 0:
            matched.append({'material': material[0], 'quantity': qty})
        else:
            # 物料未匹配或数量无效（None/0/负数）→ 归入未匹配，提示用户手工补录
            unmatched.append({'code': code, 'name': name, 'quantity': qty})

    if not matched:
        return None
    return None

    # 构建草稿创建消息（复用现有建单逻辑）
    lines = []
    for m in matched:
        code = m['material'].code or m['material'].name
        qty = m['quantity']
        qty_str = str(int(qty)) if qty == int(qty) else str(qty)
        lines.append(f'{code} {qty_str}')
    draft_message = ' '.join(lines)

    if doc_type == 'in_order':
        draft, error = _ai_create_in_order_draft(draft_message, manual_confirmation=True)
        type_label = '入库单'
    elif doc_type == 'out_order':
        draft, error = _ai_create_out_order_draft(draft_message, manual_confirmation=True)
        type_label = '领料单'
    elif doc_type == 'transfer':
        draft, error = _ai_create_transfer_draft(draft_message)
        type_label = '调拨单'
    elif doc_type == 'adjustment':
        # 调整单需要 loss/surplus 关键词；从提取的 adjustment_type 推断
        adj_type = str(extracted.get('adjustment_type') or '').strip().lower()
        if adj_type == 'surplus':
            draft_message = '盘盈 ' + draft_message
        else:
            # 默认按盘亏/报废处理
            draft_message = '报废 ' + draft_message
        draft, error = _ai_create_adjustment_draft(draft_message)
        type_label = '调整单'
    else:
        draft, error = _ai_create_check_draft(draft_message)
        type_label = '盘点单'

    if error:
        return None

    reply_parts = [f'从图片识别到 {len(matched)} 个物料，已生成{type_label}草稿 {draft["order_no"]}，请核对数量后再提交。']
    if unmatched:
        names = '、'.join([u['code'] or u['name'] or '?' for u in unmatched[:5]])
        reply_parts.append(f'另有 {len(unmatched)} 个物料未匹配或数量无效，需手工补录：{names}')
    return '\n'.join(reply_parts), draft['items'], [{'label': '打开草稿', 'url': draft['url']}]


AI_DOC_TYPE_LABELS = {
    'in_order': '采购入库草稿',
    'out_order': '领料单草稿',
    'sales_out_order': '销售出库草稿',
    'transfer': '调拨草稿',
    'check': '盘点草稿',
    'adjustment': '调整草稿',
    'purchase_request': '采购申请草稿',
}


def _ai_material_alias_key(value):
    value = (value or '').strip().lower()
    value = re.sub(r'[\s\-_/#:：，,;；]+', '', value)
    return value[:120]


def _ai_learn_material_alias(alias, material_id, source='confirm'):
    alias = (alias or '').strip()
    material_id = _clean_int(material_id)
    alias_key = _ai_material_alias_key(alias)
    if not alias_key or not material_id:
        return None
    material = db.session.get(Material, material_id)
    if not material:
        return None
    normalized_material_terms = {
        _ai_material_alias_key(material.code),
        _ai_material_alias_key(material.name),
    }
    if material.spec:
        normalized_material_terms.add(_ai_material_alias_key(material.spec))
    if alias_key in normalized_material_terms:
        return None
    row = AIMaterialAlias.query.filter_by(alias_key=alias_key).first()
    if not row:
        row = AIMaterialAlias(
            alias=alias[:100],
            alias_key=alias_key,
            material_id=material.id,
            source=source,
            use_count=1,
            created_by=current_user.id if current_user.is_authenticated else None,
        )
        db.session.add(row)
    else:
        row.alias = alias[:100]
        row.material_id = material.id
        row.source = source or row.source
        row.use_count = (row.use_count or 0) + 1
        row.updated_at = datetime.now()
    return row


def _ai_material_match_one(code='', name='', spec='', barcode=''):
    """Match extracted item to a Material record.

    Priority order:
    1. Exact material code match (case-insensitive)
    2. Exact name + spec match
    3. Learned alias match (for supplier nicknames, old part numbers, barcodes)
    4. Single fuzzy candidate (only when exactly one result)
    """
    code = (code or '').strip()
    name = (name or '').strip()
    spec = (spec or '').strip()
    barcode = (barcode or '').strip()

    # Priority 1: exact code match
    if code:
        material = Material.query.options(joinedload(Material.unit)).filter(db.func.lower(Material.code) == code.lower()).first()
        if material:
            return material, 'exact_code'

    # Priority 2: exact name + spec match
    if name:
        exact_query = Material.query.options(joinedload(Material.unit)).filter(Material.name == name)
        if spec:
            exact_query = exact_query.filter(db.func.coalesce(Material.spec, '') == spec)
        material = exact_query.first()
        if material:
            return material, 'exact_name'

    # Priority 3: learned alias match (covers supplier nicknames, barcodes stored as aliases)
    alias_candidates = [name, spec, barcode, ' '.join(part for part in (name, spec) if part)]
    if code and code not in alias_candidates:
        alias_candidates.insert(0, code)
    for alias in alias_candidates:
        alias_key = _ai_material_alias_key(alias)
        if not alias_key:
            continue
        learned = AIMaterialAlias.query.options(joinedload(AIMaterialAlias.material).joinedload(Material.unit)).filter_by(alias_key=alias_key, disabled=False).first()
        if learned and learned.material:
            learned.use_count = (learned.use_count or 0) + 1
            learned.updated_at = datetime.now()
            db.session.flush()
            return learned.material, 'learned_alias'

    # Priority 4: single fuzzy candidate
    keywords = [part for part in (code, name, spec, barcode) if part]
    if keywords:
        filters = []
        for keyword in keywords:
            like = f'%{keyword}%'
            filters.append(db.or_(
                Material.code.ilike(like),
                Material.name.ilike(like),
                Material.spec.ilike(like),
            ))
        matches = Material.query.options(joinedload(Material.unit)).filter(*filters).limit(3).all()
        if len(matches) == 1:
            return matches[0], 'single_fuzzy'
        if matches:
            return None, 'multiple'
    return None, 'none'


def _ai_guess_doc_type_from_text(text):
    compact = (text or '').replace(' ', '').lower()
    if _ai_is_wechat_delivery_notice(text):
        return 'in_order'
    if any(word in compact for word in ('送货单', '到货', '采购入库', '供应商发货', '来货', '收货')):
        return 'in_order'
    if any(word in compact for word in ('销售出库', '客户发货', '发给客户', '发货给客户', '客户要货')):
        return 'sales_out_order'
    if any(word in compact for word in ('领料', '发料', '生产出库', '材料出库')):
        return 'out_order'
    if any(word in compact for word in ('调拨', '移库', '转库')):
        return 'transfer'
    if any(word in compact for word in ('盘点', '盘库')):
        return 'check'
    if any(word in compact for word in ('报废', '损坏', '盘亏', '盘盈', '调整')):
        return 'adjustment'
    return None


def _ai_is_wechat_delivery_notice(text):
    """Detect short WeChat-style supplier shipment notices.

    Example: 明天发鑫达 6204轴承 100套，M8螺母 500个
    In this WMS, that means supplier delivery/arrival notice, so create an inbound draft.
    """
    compact = (text or '').strip()
    if not compact:
        return False
    if not re.search(r'(今天|明天|后天|上午|下午|晚上|到货|送货|发货|出货|发)\S{0,20}', compact):
        return False
    if not _ai_parse_wechat_material_segments(compact):
        return False
    # Exclude explicit customer outbound wording; those should become sales/outbound documents.
    if any(word in compact for word in ('发给客户', '发往客户', '客户要货', '销售出库')):
        return False
    return True


def _ai_parse_wechat_material_segments(text):
    text = (text or '').strip()
    if not text:
        return []
    normalized = re.sub(r'[\r\n,\uff0c;\uff1b\u3001]+', ' ', text)
    segments = []
    unit_pattern = r'(?:\u4e2a|\u53ea|\u5957|\u4ef6|\u7bb1|\u5305|PCS|pcs|kg|KG|\u7c73|\u652f|\u6761)'
    for match in re.finditer(r'([A-Za-z0-9_\-\*/\u4e00-\u9fff]{2,40}?)\s*([0-9]+(?:\.[0-9]+)?)\s*(' + unit_pattern + r')?(?=\s|$)', normalized):
        name = (match.group(1) or '').strip()
        qty = round_to_2_decimals(parse_float_value(match.group(2), 0))
        unit = (match.group(3) or '').strip()
        if not name or qty <= 0:
            continue
        if re.fullmatch(r'\d+(?:\.\d+)?', name):
            continue
        segments.append({'name': name, 'quantity': qty, 'unit': unit})
    return segments


def _ai_extract_supplier_from_wechat_delivery_notice(text):
    text = (text or '').strip()
    if not text:
        return ''
    patterns = (
        r'(?:今天|明天|后天|上午|下午|晚上)?\s*(?:发|送|出货|发货)\s*([\u4e00-\u9fffA-Za-z0-9_\-]{2,30})',
        r'(?:供应商|厂家)\s*[:：]?\s*([\u4e00-\u9fffA-Za-z0-9_\-]{2,30})',
    )
    stop_words = ('货', '货单', '送货单', '出货通知', '通知', '一下')
    for pattern in patterns:
        match = re.search(pattern, text)
        if not match:
            continue
        value = (match.group(1) or '').strip()
        value = re.split(r'\s|,|，|;|；', value, 1)[0].strip()
        if not value or value in stop_words:
            continue
        return value[:100]
    return ''


def _ai_extract_customer_from_text(text):
    text = (text or '').strip()
    if not text:
        return ''
    patterns = (
        r'(?:\u5ba2\u6237|\u5ba2\u6237\u540d\u79f0|\u6536\u8d27\u5ba2\u6237)\s*[:\uff1a]?\s*([\u4e00-\u9fffA-Za-z0-9_\-]{2,40})',
        r'(?:\u53d1\u7ed9|\u53d1\u8d27\u7ed9|\u9001\u5230|\u53d1\u5f80)\s*([\u4e00-\u9fffA-Za-z0-9_\-]{2,40})',
    )
    bad_prefixes = ('\u53d1\u8d27', '\u8981\u8d27', '\u51fa\u5e93', '\u9886\u6599')
    for pattern in patterns:
        match = re.search(pattern, text)
        if not match:
            continue
        value = (match.group(1) or '').strip()
        if not value or any(value.startswith(prefix) for prefix in bad_prefixes):
            continue
        return value[:100]
    return ''


def _ai_extract_document_from_text(message):
    text = (message or '').strip()
    if not text:
        return None
    doc_type = _ai_guess_doc_type_from_text(text)
    if not doc_type:
        return None
    normalized = re.sub(r'[\r\n,\uff0c;\uff1b\u3001]+', ' ', text)
    normalized = re.sub(r'(?:\u6570\u91cf|qty|Qty|QTY|\uff1a|:|=|\u00d7)', ' ', normalized)
    skip = {
        '生成', '创建', '新增', '做一张', '开一张', '送货单', '采购入库', '领料单', '领料', '销售出库',
        '出库', '入库', '文本', '微信', '客户', '供应商', '发货', '到货', '数量', '草稿', '检查',
    }
    items = []
    seen_tokens = set()
    parsed_segments = _ai_parse_wechat_material_segments(normalized) if _ai_is_wechat_delivery_notice(text) else []
    if parsed_segments:
        raw_rows = [(row['name'], row['quantity'], row.get('unit') or '') for row in parsed_segments]
    else:
        pattern = re.compile(r'([A-Za-z0-9_\-\*/\u4e00-\u9fff]{2,40}?)\s*(?:x|X|\*)?\s*([0-9]+(?:\.[0-9]+)?)(?:\s*(\u4e2a|\u53ea|\u5957|\u4ef6|\u7bb1|\u5305|PCS|pcs|kg|KG|\u7c73|\u652f|\u6761))?')
        raw_rows = [(token, round_to_2_decimals(parse_float_value(qty_text, 0)), unit_text or '') for token, qty_text, unit_text in pattern.findall(normalized)]
    for token, quantity, unit_text in raw_rows:
        token = token.strip()
        if token in skip or token.lower() in skip:
            continue
        if re.fullmatch(r'\d+(?:\.\d+)?', token):
            continue
        key = token.lower()
        if key in seen_tokens:
            continue
        if quantity <= 0:
            continue
        items.append({'code': token, 'name': '', 'quantity': quantity, 'unit': unit_text or '', 'raw': token})
        seen_tokens.add(key)
    if not items:
        return None
    extracted = {'document_type': doc_type, 'items': items, 'source_text': text}
    if doc_type == 'in_order':
        supplier = _ai_extract_supplier_from_wechat_delivery_notice(text)
        if supplier:
            extracted['supplier'] = supplier
            extracted['source_text'] = f'{text}\n供应商：{supplier}'
    if doc_type in ('sales_out_order', 'out_order'):
        extracted['customer'] = _ai_extract_customer_from_text(text)
    return extracted


def _ai_is_excel_table_document_question(message):
    compact = (message or '').replace(' ', '').lower()
    if not compact:
        return False
    return any(word in compact for word in (
        'excel转单据', 'Excel转单据', '表格转单据', '表格生成单据', '复制表格生成',
        'excel生成领料', 'excel生成入库', 'excel生成出库', 'excel生成采购入库',
        '表格生成领料', '表格生成入库', '表格生成出库', '粘贴表格',
        '剪贴板表格', 'excel表格',
    ))


def _ai_table_columns(line):
    line = (line or '').strip()
    if not line:
        return []
    if '\t' in line:
        return [part.strip() for part in line.split('\t')]
    if '|' in line:
        return [part.strip() for part in line.strip('|').split('|')]
    if ',' in line:
        return [part.strip() for part in line.split(',')]
    return [part.strip() for part in re.split(r'\s{2,}', line) if part.strip()]


def _ai_header_index(headers, aliases):
    lowered = [str(header or '').strip().lower() for header in headers]
    for alias in aliases:
        alias_key = alias.lower()
        for idx, header in enumerate(lowered):
            if header == alias_key or alias_key in header:
                return idx
    return None


def _ai_table_header_score(cols):
    if not cols:
        return 0
    score = 0
    if _ai_header_index(cols, ('物料编码', '编码', '料号', '品号', '货号', 'sku', 'code', 'material code')) is not None:
        score += 3
    if _ai_header_index(cols, ('物料名称', '品名', '名称', '产品名称', '商品名称', 'name', 'material name')) is not None:
        score += 2
    if _ai_header_index(cols, ('数量', '出库数量', '入库数量', '实发数量', '实收数量', '采购数量', 'qty', 'quantity')) is not None:
        score += 3
    if _ai_header_index(cols, ('单位', 'unit', 'uom')) is not None:
        score += 1
    return score


def _ai_table_header_value(text, aliases):
    text = (text or '').strip()
    if not text:
        return ''
    alias_keys = [str(alias or '').strip().lower() for alias in aliases if str(alias or '').strip()]
    for line in text.splitlines():
        raw_line = (line or '').strip()
        if not raw_line:
            continue
        normalized = raw_line.lower()
        for alias in alias_keys:
            if not normalized.startswith(alias):
                continue
            rest = raw_line[len(alias):].strip()
            if rest.startswith((':', '：', '=', '-')):
                rest = rest[1:].strip()
            if not rest:
                continue
            value = re.split(r'[，,；;|]', rest, maxsplit=1)[0].strip()
            if value:
                return value[:100]
    return ''


def _ai_extract_document_table_from_text(message):
    text = (message or '').strip()
    if not text:
        return None
    lines_raw = [line.strip() for line in text.splitlines() if line.strip()]
    table_rows = []
    for line in lines_raw:
        cols = _ai_table_columns(line)
        if len(cols) >= 2:
            table_rows.append(cols)
    if len(table_rows) < 2:
        return None

    doc_type = _ai_guess_doc_type_from_text(text)
    header_values = {
        'customer': _ai_table_header_value(text, ('客户', '客户名称', '收货客户', 'customer')),
        'supplier': _ai_table_header_value(text, ('供应商', '供应商名称', '供方', 'supplier')),
        'warehouse': _ai_table_header_value(text, ('仓库', '入库仓库', '出库仓库', '库位', 'warehouse')),
        'from_location': _ai_table_header_value(text, ('调出仓库', '调出库位', '源仓库', 'from', 'from warehouse')),
        'to_location': _ai_table_header_value(text, ('调入仓库', '调入库位', '目标仓库', 'to', 'to warehouse')),
        'remarks': _ai_table_header_value(text, ('备注', '说明', 'remark', 'remarks')),
    }
    header_idx = 0
    best_score = -1
    for idx, cols in enumerate(table_rows[:8]):
        score = _ai_table_header_score(cols)
        if score > best_score:
            best_score = score
            header_idx = idx
    header = table_rows[header_idx]
    code_idx = _ai_header_index(header, ('物料编码', '编码', '料号', '品号', '货号', 'sku', 'code', 'material code'))
    name_idx = _ai_header_index(header, ('物料名称', '品名', '名称', '产品名称', '商品名称', 'name', 'material name'))
    spec_idx = _ai_header_index(header, ('规格', '规格型号', '型号', 'spec', 'model'))
    qty_idx = _ai_header_index(header, ('数量', '出库数量', '入库数量', '实发数量', '实收数量', '采购数量', 'qty', 'quantity'))
    unit_idx = _ai_header_index(header, ('单位', 'unit', 'uom'))
    remark_idx = _ai_header_index(header, ('备注', '说明', 'remark', 'note'))

    data_rows = table_rows[header_idx + 1:]
    if qty_idx is None:
        # No clear header: treat the first row as data when it looks like code/name/qty.
        data_rows = table_rows
        code_idx, name_idx, spec_idx, qty_idx, unit_idx, remark_idx = 0, None, None, 1, None, None
        if len(data_rows[0]) >= 3 and not _ai_ocr_number(data_rows[0][1], 0):
            name_idx, qty_idx = 1, 2

    items = []
    for cols in data_rows[:100]:
        def col(idx):
            return cols[idx].strip() if idx is not None and idx < len(cols) else ''

        code = col(code_idx)
        name = col(name_idx)
        spec = col(spec_idx)
        quantity = _ai_ocr_number(col(qty_idx), 0)
        unit = col(unit_idx)
        remark = col(remark_idx)
        if not code and not name:
            continue
        if quantity <= 0:
            continue
        items.append({
            'code': code,
            'name': name,
            'spec': spec,
            'quantity': quantity,
            'unit': unit,
            'remark': remark,
            'raw_text': ' | '.join(cols)[:200],
            'confidence': 0.92,
        })

    if not items:
        return None
    if not doc_type:
        return {
            'needs_doc_type': True,
            'items': items,
            'source_text': text,
            **header_values,
        }
    source_parts = [text]
    if header_values.get('customer'):
        source_parts.append(f'客户：{header_values["customer"]}')
    if header_values.get('supplier'):
        source_parts.append(f'供应商：{header_values["supplier"]}')
    if header_values.get('warehouse'):
        source_parts.append(f'仓库：{header_values["warehouse"]}')
    if header_values.get('from_location') or header_values.get('to_location'):
        source_parts.append(f'从{header_values.get("from_location") or ""}转到{header_values.get("to_location") or ""}')
    extracted = {
        'document_type': doc_type,
        'items': items,
        'source_text': '\n'.join(part for part in source_parts if part),
        **header_values,
    }
    if doc_type in ('sales_out_order', 'out_order'):
        extracted['customer'] = header_values.get('customer') or _ai_extract_customer_from_text(text)
    return extracted


def _ai_excel_table_document_response(message, context=None, force=False):
    if not force and not _ai_is_excel_table_document_question(message):
        return None
    extracted = _ai_extract_document_table_from_text(message)
    if not extracted:
        return _ai_json_response(
            '请把Excel里的表头和明细一起复制给我，并说明要生成什么单据，例如“表格生成领料单”或“Excel生成采购入库”。表头可带客户、供应商、仓库、调出仓库、调入仓库；明细建议列：物料编码、物料名称、规格、数量、单位、备注。',
            [],
            [
                {'label': '领料示例', 'url': '#', 'prompt': '表格生成领料单\n仓库：A仓\n物料编码\t物料名称\t规格\t数量\t单位\nA001\t示例物料\t规格A\t10\t个'},
                {'label': '销售出库示例', 'url': '#', 'prompt': '表格生成销售出库\n客户：华南客户\n仓库：成品仓\n物料编码\t物料名称\t规格\t数量\t单位\nA001\t示例物料\t规格A\t10\t个'},
                {'label': '调拨示例', 'url': '#', 'prompt': '表格生成调拨单\n调出仓库：A仓\n调入仓库：B仓\n物料编码\t物料名称\t规格\t数量\t单位\nA001\t示例物料\t规格A\t10\t个'},
            ],
        )
    if extracted.get('needs_doc_type'):
        cards = []
        for item in extracted.get('items', [])[:8]:
            cards.append({
                'title': f'{item.get("code") or item.get("name")} {item.get("name") or ""}'.strip(),
                'meta': f'数量 {normalize_stock_quantity(item.get("quantity") or 0)} {item.get("unit") or ""}；请补充单据类型',
            })
        return _ai_json_response(
            f'已识别到 {len(extracted.get("items") or [])} 行表格明细，但还不知道要生成哪类单据。请说明“生成领料单/销售出库/采购入库/调拨/盘点/调整”。',
            cards,
            [
                {'label': '生成领料单', 'url': '#', 'prompt': '表格生成领料单\n' + (message or '')[:1200]},
                {'label': '生成采购入库', 'url': '#', 'prompt': 'Excel生成采购入库\n' + (message or '')[:1200]},
            ],
        )
    return _ai_create_draft_from_extracted(extracted, source='excel', context=context)


def _ai_call_llm_document_extract(message):
    if not _ai_llm_configured():
        return None
    text = (message or '').strip()
    if not text:
        return None
    system_prompt = (
        'You are a WMS document extraction engine. Extract warehouse document data from Chinese or mixed-language text. '
        'Return JSON only. Do not explain. Schema: '
        '{"document_type":"in_order|out_order|sales_out_order|transfer|check|adjustment|other",'
        '"customer":"","supplier":"","warehouse":"","from_location":"","to_location":"","remarks":"",'
        '"adjustment_type":"loss|surplus","items":[{"code":"","name":"","spec":"","quantity":0,"unit":"","remark":""}]}. '
        'Rules: delivery note, arrival, supplier shipment, purchase receipt => in_order. '
        'customer shipment, sales outbound, send to customer => sales_out_order. '
        'material picking, production issue => out_order. Transfer/move warehouse => transfer. '
        'Inventory count => check. Scrap, damage, surplus, loss => adjustment. '
        'Convert Chinese numerals and package phrases to numeric quantity when possible. '
        'If material code is absent, put the external material name in name. Keep all uncertain text in remarks.'
    )
    payload = {
        'model': _ai_llm_model(),
        'messages': [
            {'role': 'system', 'content': system_prompt},
            {'role': 'user', 'content': text[:2000]},
        ],
        'temperature': 0,
        'max_tokens': min(max(_ai_llm_max_tokens(), 300), 1200),
    }
    request_payload = dict(payload, response_format={'type': 'json_object'})
    headers = _ai_llm_headers()
    try:
        response = requests.post(
            _ai_llm_endpoint(),
            headers=headers,
            json=request_payload,
            timeout=max(_ai_llm_timeout_seconds(), 20),
        )
        if response.status_code == 400:
            response = requests.post(
                _ai_llm_endpoint(),
                headers=headers,
                json=payload,
                timeout=max(_ai_llm_timeout_seconds(), 20),
            )
        if not response.ok:
            app.logger.warning('AI document extraction failed: %s', _ai_llm_error_message(response))
            return None
        data = response.json()
        content = (((data.get('choices') or [{}])[0].get('message') or {}).get('content') or '').strip()
        extracted = _ai_extract_json_object(content)
        if not isinstance(extracted, dict):
            return None
        normalized = _ai_normalize_document_extraction(extracted, source_text=text)
        if not normalized:
            return None
        normalized['extracted_by'] = 'llm'
        if not normalized.get('customer') and normalized.get('document_type') in ('sales_out_order', 'out_order'):
            normalized['customer'] = _ai_extract_customer_from_text(text)
        return normalized
    except Exception as exc:
        app.logger.warning('AI document extraction unavailable: %s', exc)
        return None


def _ai_try_llm_document_response(message, context=None):
    extracted = _ai_call_llm_document_extract(message)
    if not extracted:
        return None
    return _ai_create_draft_from_extracted(extracted, source='gpt', context=context)


def _ai_should_try_llm_document(message):
    compact = (message or '').replace(' ', '').lower()
    return any(marker in compact for marker in ('gpt识别', 'ai识别', '大模型识别', '智能识别'))


_AI_ITEM_FIELD_ALIASES = {
    'code': ('code', 'material_code', 'materialCode', 'item_code', 'sku', 'part_no', 'partNo', 'product_code', 'productCode', '\u7269\u6599\u7f16\u7801', '\u7f16\u7801', '\u6599\u53f7', '\u54c1\u53f7', '\u8d27\u53f7', '\u4ea7\u54c1\u7f16\u7801', '\u578b\u53f7\u7f16\u7801'),
    'name': ('name', 'material_name', 'materialName', 'item_name', 'product_name', 'productName', 'description', '\u7269\u6599\u540d\u79f0', '\u54c1\u540d', '\u540d\u79f0', '\u4ea7\u54c1\u540d\u79f0', '\u8d27\u54c1\u540d\u79f0', '\u63cf\u8ff0'),
    'spec': ('spec', 'specification', 'model', 'model_no', 'modelNo', 'size', '\u89c4\u683c', '\u89c4\u683c\u578b\u53f7', '\u578b\u53f7', '\u5c3a\u5bf8'),
    'quantity': ('quantity', 'qty', 'count', 'amount_qty', 'actual_qty', 'total_qty', 'totalQuantity', '\u6570\u91cf', '\u9001\u8d27\u6570\u91cf', '\u5b9e\u9001\u6570\u91cf', '\u5165\u5e93\u6570\u91cf', '\u5408\u8ba1\u6570\u91cf', '\u603b\u6570\u91cf'),
    'unit': ('unit', 'uom', '\u5355\u4f4d', '\u8ba1\u91cf\u5355\u4f4d'),
    'remark': ('remark', 'remarks', 'note', 'memo', '\u5907\u6ce8', '\u8bf4\u660e'),
    'raw_text': ('raw_text', 'rawText', 'ocr_text', 'line_text', 'source_line', '\u539f\u59cb\u884c', '\u8bc6\u522b\u539f\u6587'),
    'barcode': ('barcode', 'bar_code', 'ean', '\u6761\u7801'),
    'batch_no': ('batch_no', 'batchNo', 'lot_no', 'lotNo', '\u6279\u53f7', '\u6279\u6b21', '\u7089\u6279\u53f7'),
    'box_count': ('box_count', 'boxCount', 'cartons', 'package_count', '\u7bb1\u6570', '\u4ef6\u6570', '\u5305\u6570'),
    'pcs_per_box': ('pcs_per_box', 'pcsPerBox', 'per_box', 'perPackageQty', '\u6bcf\u7bb1\u6570', '\u6bcf\u4ef6\u6570', '\u5305\u88c5\u6570', '\u5355\u7bb1\u6570'),
    'confidence': ('confidence', 'score', '\u7f6e\u4fe1\u5ea6'),
}


def _ai_item_value(item, field, default=''):
    for key in _AI_ITEM_FIELD_ALIASES.get(field, (field,)):
        if key in item and item.get(key) not in (None, ''):
            return item.get(key)
    return default


def _ai_ocr_text(value):
    table = str.maketrans('０１２３４５６７８９．，,＊×Xx', '0123456789.,,****')
    return str(value or '').translate(table).strip()


def _ai_ocr_number(value, default=0):
    text = _ai_ocr_text(value)
    text = re.sub(r'(?<=\d),(?=\d{3}(?:\D|$))', '', text)
    match = re.search(r'\d+(?:\.\d+)?', text)
    if not match:
        return round_to_2_decimals(parse_float_value(value, default))
    return round_to_2_decimals(parse_float_value(match.group(0), default))


def _ai_ocr_confidence(value):
    confidence = _ai_ocr_number(value, 0)
    if confidence > 1 and confidence <= 100:
        confidence = round_to_2_decimals(confidence / 100)
    return confidence if 0 <= confidence <= 1 else 0


def _ai_normalize_document_extraction(raw, source_text=''):
    if not isinstance(raw, dict):
        return None
    doc_type = str(raw.get('document_type') or '').strip().lower()
    if doc_type == 'sales_out':
        doc_type = 'sales_out_order'
    if doc_type not in AI_DOC_TYPE_LABELS:
        return None
    items = raw.get('items') or []
    if not isinstance(items, list):
        return None
    normalized_items = []
    for item in items:
        if not isinstance(item, dict):
            continue
        quantity = _ai_ocr_number(_ai_item_value(item, 'quantity'), 0)
        box_count = _ai_ocr_number(_ai_item_value(item, 'box_count'), 0)
        pcs_per_box = _ai_ocr_number(_ai_item_value(item, 'pcs_per_box'), 0)
        if quantity <= 0 and box_count > 0 and pcs_per_box > 0:
            quantity = round_to_2_decimals(box_count * pcs_per_box)
        code = str(_ai_item_value(item, 'code') or '').strip()
        name = str(_ai_item_value(item, 'name') or '').strip()
        spec = str(_ai_item_value(item, 'spec') or '').strip()
        barcode = str(_ai_item_value(item, 'barcode') or '').strip()
        batch_no = str(_ai_item_value(item, 'batch_no') or '').strip()
        raw_text = str(_ai_item_value(item, 'raw_text') or '').strip()
        if not code and not name and spec:
            name = spec
        if not code and barcode:
            code = barcode
        if not code and not name:
            continue
        remark_parts = [str(_ai_item_value(item, 'remark') or '').strip()]
        if batch_no:
            remark_parts.append(f'batch:{batch_no}')
        if box_count > 0 and pcs_per_box > 0:
            remark_parts.append(f'package:{box_count}*{pcs_per_box}')
        if raw_text:
            remark_parts.append(f'raw:{raw_text[:120]}')
        normalized_items.append({
            'code': code,
            'name': name,
            'spec': spec,
            'quantity': round_to_2_decimals(quantity),
            'unit': str(_ai_item_value(item, 'unit') or '').strip()[:20],
            'remark': '; '.join(part for part in remark_parts if part)[:300],
            'raw_text': raw_text[:200],
            'barcode': barcode[:80],
            'batch_no': batch_no[:80],
            'box_count': box_count,
            'pcs_per_box': pcs_per_box,
            'confidence': _ai_ocr_confidence(_ai_item_value(item, 'confidence')),
        })
    if not normalized_items:
        return None
    result = {
        'document_type': doc_type,
        'items': normalized_items,
        'source_text': source_text or str(raw.get('source_text') or raw.get('remarks') or '').strip(),
        'customer': str(raw.get('customer') or '').strip()[:100],
        'supplier': str(raw.get('supplier') or '').strip()[:100],
        'warehouse': str(raw.get('warehouse') or '').strip()[:100],
        'from_location': str(raw.get('from_location') or '').strip()[:100],
        'to_location': str(raw.get('to_location') or '').strip()[:100],
        'order_no': str(raw.get('order_no') or raw.get('delivery_no') or '').strip()[:100],
        'remarks': str(raw.get('remarks') or '').strip()[:300],
        'adjustment_type': str(raw.get('adjustment_type') or '').strip().lower(),
        'extracted_by': str(raw.get('extracted_by') or 'llm').strip()[:30],
    }
    if not result['customer'] and doc_type in ('sales_out_order', 'out_order'):
        result['customer'] = _ai_extract_customer_from_text(source_text)
    return result


def _ai_collect_vision_ocr_text(raw, message=''):
    parts = []
    if message:
        parts.append(str(message).strip())
    if isinstance(raw, dict):
        for key in ('source_text', 'ocr_text', 'raw_text', 'text', 'message_text', 'chat_text', 'remarks'):
            value = str(raw.get(key) or '').strip()
            if value:
                parts.append(value)
        for item in raw.get('items') or []:
            if not isinstance(item, dict):
                continue
            line_parts = []
            for field in ('raw_text', 'name', 'spec', 'code', 'quantity', 'unit', 'remark'):
                value = str(_ai_item_value(item, field) or '').strip()
                if value:
                    line_parts.append(value)
            if line_parts:
                parts.append(' '.join(line_parts))
    seen = set()
    clean_parts = []
    for part in parts:
        key = part.lower()
        if key and key not in seen:
            clean_parts.append(part)
            seen.add(key)
    return '\n'.join(clean_parts).strip()


def _ai_try_wechat_document_from_vision_json(raw, message=''):
    ocr_text = _ai_collect_vision_ocr_text(raw, message)
    if not ocr_text or not _ai_is_wechat_delivery_notice(ocr_text):
        return None
    extracted = _ai_extract_document_from_text(ocr_text)
    if not extracted:
        return None
    extracted['extracted_by'] = 'vision_ocr_text'
    return extracted


def _ai_call_llm_document_vision_extract(message, images, context=None):
    if not _ai_llm_configured():
        return None, '请先配置AI模型 API Key'
    if not _ai_llm_vision_enabled():
        return None, '系统未启用图片识别'
    if not images:
        return None, '没有收到图片'
    system_prompt = (
        'You are a high-accuracy WMS OCR and document extraction engine for Chinese delivery notes, purchase receipts, sales shipments and warehouse documents. '
        'Read the whole image, including WeChat chat screenshots, stamps, handwritten notes, table headers, merged cells, rotated photos, low contrast scans and mixed Chinese/English text. '
        'Return JSON only. No markdown. No explanation. Schema: '
        '{"document_type":"in_order|sales_out_order|out_order|transfer|check|adjustment|other",'
        '"order_no":"","delivery_no":"","supplier":"","customer":"","warehouse":"","from_location":"","to_location":"",'
        '"remarks":"","source_text":"","ocr_text":"","adjustment_type":"loss|surplus",'
        '"items":[{"code":"","name":"","spec":"","quantity":0,"unit":"","barcode":"","batch_no":"",'
        '"box_count":0,"pcs_per_box":0,"confidence":0,"raw_text":"","remark":""}]}. '
        'Classify delivery note, supplier shipment, arrival notice, purchase receipt as in_order. '
        'For a WeChat screenshot or chat message such as "明天发鑫达 6204轴承 100套，M8螺母 500个", classify it as in_order: supplier is 鑫达, items are 6204轴承 quantity 100 unit 套 and M8螺母 quantity 500 unit 个. '
        'When the image is a WeChat shipment notice, extract the visible chat text into source_text or ocr_text even if the layout is not a formal document table. '
        'Classify customer shipment, sales outbound as sales_out_order. '
        'Classify material picking or production issue as out_order. '
        'Recognize common table columns: serial no, material code, item no, sku, product name, material name, spec/model, unit, quantity, delivered quantity, cartons, packages, pcs per carton, batch/lot no, barcode and remarks. '
        'Extract material code when visible; otherwise put visible material name/spec in name/spec. Never use row serial numbers as material code. '
        'Quantity must be numeric. If both package count and per-package quantity are clear, compute quantity as package_count * pcs_per_box, keep box_count and pcs_per_box, and mention the formula in remark. '
        'Keep raw_text as the original OCR text for each detail row. Set confidence from 0 to 1 for each line; use lower confidence for handwriting, blur, crossed-out text or uncertain split rows. '
        'Do not invent missing material codes, quantities, suppliers or order numbers. Keep uncertain header fields blank. If the image is not a warehouse document, use document_type other and empty items.'
    )
    user_content = [{'type': 'text', 'text': (message or 'Extract this warehouse document into WMS draft data.')[:1200]}]
    page_title = _ai_context_value(context or {}, 'page_title')
    page_url = _ai_context_value(context or {}, 'page_url')
    if page_title or page_url:
        user_content.append({'type': 'text', 'text': f'Current WMS page: {page_title or "-"} {page_url or ""}'.strip()})
    for image in images:
        user_content.append({'type': 'image_url', 'image_url': {'url': image['data_url']}})
    payload = {
        'model': _ai_llm_model(),
        'messages': [
            {'role': 'system', 'content': system_prompt},
            {'role': 'user', 'content': user_content},
        ],
        'temperature': 0,
        'max_tokens': min(max(_ai_llm_max_tokens(), 500), 1500),
    }
    request_payload = dict(payload, response_format={'type': 'json_object'})
    headers = _ai_llm_headers()
    try:
        response = requests.post(
            _ai_llm_endpoint(),
            headers=headers,
            json=request_payload,
            timeout=max(_ai_llm_timeout_seconds(), 60),
        )
        if response.status_code == 400:
            response = requests.post(
                _ai_llm_endpoint(),
                headers=headers,
                json=payload,
                timeout=max(_ai_llm_timeout_seconds(), 60),
            )
        if not response.ok:
            return None, _ai_llm_error_message(response)
        data = response.json()
        content = (((data.get('choices') or [{}])[0].get('message') or {}).get('content') or '').strip()
        extracted = _ai_extract_json_object(content)
        wechat_extracted = _ai_try_wechat_document_from_vision_json(extracted, message)
        if wechat_extracted:
            return wechat_extracted, ''
        source_text = _ai_collect_vision_ocr_text(extracted, message) or message or '图片识别'
        normalized = _ai_normalize_document_extraction(extracted, source_text=source_text)
        if not normalized:
            return None, '图片没有识别到可生成草稿的单据明细'
        normalized['extracted_by'] = 'vision'
        return normalized, ''
    except Exception as exc:
        app.logger.warning('AI document vision extraction unavailable: %s', exc)
        return None, str(exc)


def _ai_match_extracted_items(items_raw, purchase_order_id=None):
    """Match extracted document items to materials.

    Args:
        items_raw: List of extracted item dicts from OCR/vision
        purchase_order_id: Optional purchase order ID for over-purchase blocking

    Returns:
        (matched, unmatched) tuple
    """
    matched = []
    unmatched = []
    seen_materials = set()

    # Pre-load purchase order remaining quantities if needed
    po_remaining = {}
    if purchase_order_id:
        po_items = PurchaseOrderItem.query.filter_by(purchase_order_id=purchase_order_id).all()
        for po_item in po_items:
            remaining = po_item.quantity - (po_item.received_quantity or 0)
            po_remaining[po_item.material_id] = max(0, remaining)

    for item in items_raw or []:
        if not isinstance(item, dict):
            continue
        code = str(_ai_item_value(item, 'code') or '').strip()
        name = str(_ai_item_value(item, 'name') or '').strip()
        spec = str(_ai_item_value(item, 'spec') or '').strip()
        barcode = str(_ai_item_value(item, 'barcode') or '').strip()
        raw_text = str(_ai_item_value(item, 'raw_text') or '').strip()
        quantity = _ai_ocr_number(_ai_item_value(item, 'quantity'), 0)
        if not code and not name and not barcode:
            continue
        material, match_type = _ai_material_match_one(code, name, spec, barcode)
        raw_label = raw_text or ' '.join(part for part in (code, name, spec, barcode) if part)
        if material and quantity > 0:
            # Over-purchase blocking: check against purchase order remaining quantity
            if purchase_order_id and material.id in po_remaining:
                remaining = po_remaining[material.id]
                if quantity > remaining:
                    unmatched.append({
                        'title': raw_label or code or name,
                        'meta': f'超采购数量（识别{quantity}，剩余{remaining}），需要人工确认',
                        'quantity': quantity,
                        'item': item,
                        'spec': spec,
                        'material': material,
                        'match_type': match_type,
                    })
                    continue

            if material.id in seen_materials:
                unmatched.append({
                    'title': raw_label or code or name,
                    'meta': f'重复物料，需要人工合并数量：{quantity}',
                    'quantity': quantity,
                    'item': item,
                    'spec': spec,
                })
                continue
            matched.append({
                'material': material,
                'quantity': quantity,
                'match_type': match_type,
                'raw': raw_label or code or name,
                'item': item,
                'spec': spec,
            })
            seen_materials.add(material.id)
        else:
            reason = '数量无效' if quantity <= 0 else ('匹配到多个物料，请手工选择' if match_type == 'multiple' else '未找到物料档案')
            unmatched.append({
                'title': raw_label or code or name,
                'meta': f'{reason}，识别数量：{quantity or "-"}',
                'quantity': quantity,
                'item': item,
                'spec': spec,
            })
    return matched, unmatched


def _ai_document_summary_text(extracted):
    text = str((extracted or {}).get('source_text') or (extracted or {}).get('ocr_text') or '').strip()
    if not text:
        parts = []
        for item in (extracted or {}).get('items') or []:
            if isinstance(item, dict):
                parts.append(str(item.get('raw_text') or item.get('name') or item.get('code') or '').strip())
        text = '\n'.join(part for part in parts if part)
    return text[:500]


def _ai_document_generated_type(doc_type):
    if doc_type == 'in_order':
        return 'in_order'
    if doc_type in ('out_order', 'sales_out_order'):
        return 'out_order'
    if doc_type == 'transfer':
        return 'transfer'
    if doc_type == 'adjustment':
        return 'adjustment'
    if doc_type == 'check':
        return 'check'
    if doc_type == 'purchase_request':
        return 'purchase_request'
    return doc_type or ''


def _ai_record_document_job(extracted, source, status, context=None, matched=None, unmatched=None, error_message='', image_path=None):
    if not has_request_context() or not current_user.is_authenticated:
        return None
    extracted = extracted or {}
    doc_type = str(extracted.get('document_type') or '').strip().lower()
    if doc_type == 'sales_out':
        doc_type = 'sales_out_order'
    job = AIDocumentJob(
        ai_run_id=getattr(g, 'ai_run_id', None),
        user_id=current_user.id,
        source=(source or 'unknown')[:30],
        document_type=doc_type[:40],
        status=(status or 'recognized')[:30],
        supplier=str(extracted.get('supplier') or '')[:100],
        customer=str(extracted.get('customer') or '')[:100],
        order_no=str(extracted.get('order_no') or '')[:100],
        source_text_summary=_ai_document_summary_text(extracted),
        source_purchase_order_id=_ai_context_purchase_order_id(context),
        error_message=(error_message or '')[:500] or None,
        image_path=(image_path or '')[:500] or None,
    )
    db.session.add(job)
    db.session.flush()
    matched_count = len(matched or [])
    unmatched_count = len(unmatched or [])
    db.session.add(AIDocumentAttempt(
        job_id=job.id,
        attempt_no=1,
        source=(source or 'unknown')[:30],
        model=_ai_llm_model()[:100] if _ai_llm_configured() else 'local-rules',
        prompt_version='legacy-v1',
        status=(status or 'recognized')[:30],
        item_count=matched_count + unmatched_count,
        matched_count=matched_count,
        unmatched_count=unmatched_count,
        error_message=(error_message or '')[:500] or None,
        completed_at=datetime.now(),
    ))

    line_no = 1
    for row in matched or []:
        material = row.get('material')
        item = row.get('item') or {}
        db.session.add(AIDocumentItem(
            job_id=job.id,
            line_no=line_no,
            material_id=material.id if material else None,
            raw_text=str(item.get('raw_text') or row.get('raw') or '')[:500],
            code=str(item.get('code') or (material.code if material else ''))[:100],
            name=str(item.get('name') or (material.name if material else ''))[:200],
            spec=str(item.get('spec') or row.get('spec') or '')[:200],
            unit=str(item.get('unit') or (material.unit.name if material and material.unit else ''))[:50],
            quantity=row.get('quantity') or 0,
            confidence=_ai_ocr_confidence(item.get('confidence')),
            match_status='matched',
            match_reason=str(row.get('match_type') or '')[:300],
        ))
        line_no += 1
    for row in unmatched or []:
        item = row.get('item') or {}
        db.session.add(AIDocumentItem(
            job_id=job.id,
            line_no=line_no,
            raw_text=str(item.get('raw_text') or row.get('title') or '')[:500],
            code=str(item.get('code') or '')[:100],
            name=str(item.get('name') or '')[:200],
            spec=str(item.get('spec') or row.get('spec') or '')[:200],
            unit=str(item.get('unit') or '')[:50],
            quantity=row.get('quantity') or 0,
            confidence=_ai_ocr_confidence(item.get('confidence')),
            match_status='unmatched',
            match_reason=str(row.get('meta') or '')[:300],
        ))
        line_no += 1
    db.session.commit()
    return job


def _ai_record_document_attempt(job, source, status, matched=None, unmatched=None, error_message=''):
    if not job:
        return None
    attempt_no = (len(job.attempts or []) + 1) if job.id else 1
    matched_count = len(matched or [])
    unmatched_count = len(unmatched or [])
    attempt = AIDocumentAttempt(
        job_id=job.id,
        attempt_no=attempt_no,
        source=(source or job.source or 'unknown')[:30],
        model=_ai_llm_model()[:100] if _ai_llm_configured() else 'local-rules',
        prompt_version='legacy-v1',
        status=(status or 'recognized')[:30],
        item_count=matched_count + unmatched_count,
        matched_count=matched_count,
        unmatched_count=unmatched_count,
        error_message=(error_message or '')[:500] or None,
        completed_at=datetime.now(),
    )
    db.session.add(attempt)
    db.session.commit()
    return attempt


def _ai_update_document_job(job_id, status, **values):
    if not job_id:
        return
    job = db.session.get(AIDocumentJob, job_id)
    if not job:
        return
    job.status = (status or job.status)[:30]
    job.updated_at = datetime.now()
    if status in ('draft_created', 'failed', 'cancelled'):
        job.completed_at = datetime.now()
    for field in (
        'confirmation_token',
        'generated_document_type',
        'generated_document_id',
        'generated_document_no',
        'error_message',
    ):
        if field in values:
            value = values.get(field)
            if isinstance(value, str):
                value = value[:500] if field == 'error_message' else value[:100]
            setattr(job, field, value)
    db.session.commit()


def _ai_generated_document_ref(doc_type, draft):
    if not draft:
        return '', None, ''
    order_no = draft.get('order_no') or ''
    generated_type = _ai_document_generated_type(doc_type)
    model = {
        'in_order': InOrder,
        'out_order': OutOrder,
        'transfer': TransferOrder,
        'adjustment': AdjustmentOrder,
        'check': InventoryCheck,
        'purchase_request': PurchaseRequest,
    }.get(generated_type)
    number_field = 'request_no' if generated_type == 'purchase_request' else 'order_no'
    row = model.query.filter_by(**{number_field: order_no}).first() if model and order_no else None
    return generated_type, row.id if row else None, order_no


def _ai_mark_document_job_draft_created(job_id, doc_type, draft):
    generated_type, generated_id, generated_no = _ai_generated_document_ref(doc_type, draft)
    _ai_update_document_job(
        job_id,
        'draft_created',
        generated_document_type=generated_type,
        generated_document_id=generated_id,
        generated_document_no=generated_no,
    )


def _ai_draft_message_from_matches(matched):
    parts = []
    for row in matched:
        material = row['material']
        qty = row['quantity']
        qty_text = str(int(qty)) if float(qty).is_integer() else str(qty)
        parts.append(f'{material.code or material.name} {qty_text}')
    return ' '.join(parts)


def _ai_match_cards(matched, unmatched):
    cards = []
    for row in matched:
        material = row['material']
        unit_name = material.unit.name if material.unit else ''
        cards.append({
            'title': f'已匹配 {material.code} {material.name}',
            'meta': f'数量：{row["quantity"]}{unit_name}，库存：{normalize_stock_quantity(material.stock or 0)}{unit_name}',
            'url': url_for('material_list', search=material.code or material.name or ''),
        })
    for row in unmatched:
        cards.append({'title': f'未匹配 {row.get("title") or "-"}', 'meta': row.get('meta') or '需要人工补录物料'})
    return cards


def _ai_vision_low_confidence_items(items, threshold=0.75):
    low_items = []
    for item in items or []:
        if not isinstance(item, dict):
            continue
        confidence = _ai_ocr_confidence(_ai_item_value(item, 'confidence'))
        if confidence and confidence < threshold:
            label = str(_ai_item_value(item, 'raw_text') or _ai_item_value(item, 'code') or _ai_item_value(item, 'name') or '').strip()
            low_items.append({'label': label[:80] or '未命名行', 'confidence': confidence})
    return low_items


def _ai_context_purchase_order_id(context=None):
    page_url = (context or {}).get('page_url') or ''
    po_match = re.search(r'/purchase_order/(\d+)(?:\D|$)', page_url)
    if not po_match:
        return None
    try:
        return int(po_match.group(1))
    except ValueError:
        return None


AI_MATCH_TYPE_LABELS = {
    'exact_code': '精确编码',
    'exact_name': '精确名称',
    'learned_alias': '别名匹配',
    'single_fuzzy': '模糊匹配',
    'multiple': '多个候选',
    'none': '未找到',
}


def _ai_confirmation_payload(extracted, context=None, document_job_id=None):
    doc_type = str((extracted or {}).get('document_type') or '').strip().lower()
    if doc_type == 'sales_out':
        doc_type = 'sales_out_order'
    rows = []
    po_id = _ai_context_purchase_order_id(context)
    matched, unmatched = _ai_match_extracted_items((extracted or {}).get('items') or [], purchase_order_id=po_id)
    for row in matched:
        material = row['material']
        item = row.get('item') or {}
        match_type = row.get('match_type') or ''
        rows.append({
            'raw': row.get('raw') or material.code or material.name or '',
            'code': material.code or '',
            'name': material.name or '',
            'spec': item.get('spec') or row.get('spec') or material.spec or '',
            'unit': item.get('unit') or (material.unit.name if material.unit else ''),
            'raw_text': item.get('raw_text') or row.get('raw') or '',
            'batch_no': item.get('batch_no') or '',
            'barcode': item.get('barcode') or '',
            'box_count': item.get('box_count') or '',
            'pcs_per_box': item.get('pcs_per_box') or '',
            'confidence': item.get('confidence') or '',
            'remark': item.get('remark') or '',
            'quantity': row.get('quantity') or 0,
            'material_id': material.id,
            'match_status': 'matched',
            'match_type': match_type,
            'match_type_label': AI_MATCH_TYPE_LABELS.get(match_type, match_type),
        })
    for row in unmatched:
        item = row.get('item') or {}
        rows.append({
            'raw': row.get('title') or '',
            'code': item.get('code') or row.get('title') or '',
            'name': item.get('name') or '',
            'spec': item.get('spec') or row.get('spec') or '',
            'unit': item.get('unit') or '',
            'raw_text': item.get('raw_text') or row.get('title') or '',
            'batch_no': item.get('batch_no') or '',
            'barcode': item.get('barcode') or '',
            'box_count': item.get('box_count') or '',
            'pcs_per_box': item.get('pcs_per_box') or '',
            'confidence': item.get('confidence') or '',
            'remark': item.get('remark') or '',
            'quantity': row.get('quantity') or 0,
            'material_id': None,
            'match_status': 'unmatched',
            'reason': row.get('meta') or '',
        })
    source_purchase_order_id = _ai_context_purchase_order_id(context)
    source_purchase_order_no = ''
    if source_purchase_order_id:
        source_po = db.session.get(PurchaseOrder, source_purchase_order_id)
        source_purchase_order_no = source_po.order_no if source_po else ''
    return {
        'document_type': doc_type,
        'source_text': (extracted or {}).get('source_text') or '',
        'customer': (extracted or {}).get('customer') or '',
        'adjustment_type': (extracted or {}).get('adjustment_type') or '',
        'source_purchase_order_id': source_purchase_order_id,
        'source_purchase_order_no': source_purchase_order_no,
        'document_job_id': document_job_id,
        'rows': rows,
    }


def _ai_store_document_confirmation(extracted, context=None, document_job_id=None):
    payload = _ai_confirmation_payload(extracted, context, document_job_id)
    token = secrets.token_urlsafe(12)
    pending = session.get('_ai_document_confirmations') or {}
    pending[token] = payload
    # Keep the session small and bounded.
    for key in list(pending.keys())[:-8]:
        pending.pop(key, None)
    session['_ai_document_confirmations'] = pending
    session.modified = True
    _ai_update_document_job(document_job_id, 'pending_confirmation', confirmation_token=token)
    return token, payload


def _ai_confirmation_action(extracted, context=None, document_job_id=None):
    token, payload = _ai_store_document_confirmation(extracted, context, document_job_id)
    return {
        'label': '确认识别结果',
        'url': url_for('ai_document_confirm', token=token),
        'payload': payload,
    }


def _ai_document_job_confirmation_payload(job):
    rows = []
    for item in sorted(job.items or [], key=lambda row: (row.line_no or 0, row.id or 0)):
        match_type = item.match_reason or ''
        rows.append({
            'raw': item.raw_text or item.code or item.name or '',
            'code': item.code or '',
            'name': item.name or '',
            'spec': item.spec or '',
            'unit': item.unit or (item.material.unit.name if item.material and item.material.unit else ''),
            'raw_text': item.raw_text or '',
            'batch_no': '',
            'barcode': '',
            'box_count': '',
            'pcs_per_box': '',
            'confidence': item.confidence if item.confidence is not None else '',
            'remark': item.match_reason or '',
            'quantity': item.quantity or 0,
            'material_id': item.material_id,
            'match_status': item.match_status or 'unmatched',
            'reason': item.match_reason or '',
            'match_type': match_type,
            'match_type_label': AI_MATCH_TYPE_LABELS.get(match_type, match_type) if match_type else '',
        })
    return {
        'document_type': job.document_type,
        'source_text': job.source_text_summary or '',
        'customer': job.customer or '',
        'supplier': job.supplier or '',
        'adjustment_type': '',
        'source_purchase_order_id': job.source_purchase_order_id,
        'source_purchase_order_no': job.source_purchase_order.order_no if job.source_purchase_order else '',
        'document_job_id': job.id,
        'rows': rows,
    }


def _ai_save_field_confirmations_from_form(document_job_id, payload, form):
    """AI-R08-F01 从确认台表单保存字段确认状态。

    遍历表单中的每一行，根据用户是否选择该行以及是否修改了物料/数量，
    构造 FieldConfirmationRecord 并持久化到 AIDocumentFieldConfirmation 表。
    表头字段（supplier/order_no/date）也保存确认状态。

    Args:
        document_job_id: 文档任务 ID。
        payload: 确认台 payload（含 rows 等）。
        form: Flask request.form。

    Returns:
        bool: 是否成功保存。
    """
    try:
        from ai.documents.document_confirmation_status import (
            STATUS_CONFIRMED_ORIGINAL,
            STATUS_CORRECTED,
            STATUS_PENDING,
            build_field_confirmation_record,
        )
        from datetime import datetime

        job = AIDocumentJob.query.get(document_job_id)
        if not job:
            return False

        user_id = current_user.id if current_user.is_authenticated else None
        if not user_id:
            return False

        now = datetime.now()
        records = []

        # 表头字段：supplier/order_no/date 默认 confirmed_original（用户未修改则视为确认原值）
        header_fields = [
            ('supplier', job.supplier or ''),
            ('order_no', job.order_no or ''),
            ('date', ''),
        ]
        for field_name, original_value in header_fields:
            form_value = form.get(f'header_{field_name}')
            if form_value is not None and form_value != original_value:
                status = STATUS_CORRECTED
                confirmed_value = form_value
                correction_reason = f'用户修正：{original_value} -> {form_value}'
            else:
                status = STATUS_CONFIRMED_ORIGINAL
                confirmed_value = original_value
                correction_reason = None
            record = build_field_confirmation_record(
                field_id=0,  # 表头字段无 field_id，用 0 占位
                task_id=document_job_id,
                line_id=None,
                field_name=field_name,
                confirmation_status=status,
                original_value=original_value,
                confirmed_value=confirmed_value,
                correction_reason=correction_reason,
                evidence_source='ocr',
                model='local-rules',
                prompt_version='',
                schema_version='document-extraction-v1',
                confirmed_by=user_id,
                confirmed_at=now,
            )
            records.append(record)

        # 行级字段：每一行的 material_id/quantity
        payload_rows = payload.get('rows') or []
        row_count = _clean_int(form.get('row_count')) or 0
        for idx in range(row_count):
            use_row = form.get(f'use_row_{idx}') == '1'
            if not use_row:
                continue
            original_row = payload_rows[idx] if idx < len(payload_rows) else {}
            material_id = _clean_int(form.get(f'material_id_{idx}'))
            quantity = parse_float_value(form.get(f'quantity_{idx}'), 0)
            original_material_id = original_row.get('material_id')
            original_quantity = original_row.get('quantity') or 0

            # 物料字段确认
            if material_id and material_id != original_material_id:
                mat_status = STATUS_CORRECTED
                mat_confirmed = material_id
                mat_reason = f'用户修正物料：{original_material_id} -> {material_id}'
            else:
                mat_status = STATUS_CONFIRMED_ORIGINAL
                mat_confirmed = material_id or original_material_id
                mat_reason = None
            mat_record = build_field_confirmation_record(
                field_id=0,
                task_id=document_job_id,
                line_id=idx,
                field_name='material_id',
                confirmation_status=mat_status,
                original_value=original_material_id,
                confirmed_value=mat_confirmed,
                correction_reason=mat_reason,
                evidence_source='ocr',
                model='local-rules',
                prompt_version='',
                schema_version='document-extraction-v1',
                confirmed_by=user_id,
                confirmed_at=now,
            )
            records.append(mat_record)

            # 数量字段确认
            if quantity and quantity != original_quantity:
                qty_status = STATUS_CORRECTED
                qty_confirmed = quantity
                qty_reason = f'用户修正数量：{original_quantity} -> {quantity}'
            else:
                qty_status = STATUS_CONFIRMED_ORIGINAL
                qty_confirmed = quantity or original_quantity
                qty_reason = None
            qty_record = build_field_confirmation_record(
                field_id=0,
                task_id=document_job_id,
                line_id=idx,
                field_name='quantity',
                confirmation_status=qty_status,
                original_value=original_quantity,
                confirmed_value=qty_confirmed,
                correction_reason=qty_reason,
                evidence_source='ocr',
                model='local-rules',
                prompt_version='',
                schema_version='document-extraction-v1',
                confirmed_by=user_id,
                confirmed_at=now,
            )
            records.append(qty_record)

        # 持久化到 AIDocumentFieldConfirmation 表
        for record in records:
            db_row = AIDocumentFieldConfirmation(
                job_id=document_job_id,
                item_id=None,  # 行级字段用 line_id 映射，不直接关联 AIDocumentItem.id
                field_name=record.field_name,
                confirmation_status=record.confirmation_status,
                original_value=str(record.original_value or '')[:500],
                confirmed_value=str(record.confirmed_value or '')[:500],
                correction_reason=(record.correction_reason or '')[:500],
                evidence_source=record.evidence_source,
                model=record.model[:100] if record.model else '',
                prompt_version=record.prompt_version[:50] if record.prompt_version else '',
                schema_version=record.schema_version[:50] if record.schema_version else '',
                confirmed_by=record.confirmed_by,
                confirmed_at=record.confirmed_at,
            )
            db.session.add(db_row)

        # 更新 job 的确认状态
        job.confirmation_status = 'confirmed'
        job.confirmed_by = user_id
        job.confirmed_at = now

        db.session.commit()
        return True
    except Exception as e:
        db.session.rollback()
        app.logger.error(f'保存字段确认状态失败: {e}')
        return False


def _ai_check_draft_creation_gate(document_job_id):
    """AI-R08-F01 服务端门禁校验。

    在创建草稿前调用，查询 AIDocumentFieldConfirmation 表，
    构造 FieldConfirmationRecord 列表，调用 validate_draft_creation_allowed
    校验是否允许创建草稿。

    Args:
        document_job_id: 文档任务 ID。

    Returns:
        (is_allowed, reasons): 是否允许创建草稿，以及拒绝原因列表。
    """
    try:
        from ai.documents.document_confirmation_status import (
            FieldConfirmationRecord,
            validate_draft_creation_allowed,
        )

        if not document_job_id:
            return True, []

        # 查询该 job 的所有字段确认记录
        confirmations = AIDocumentFieldConfirmation.query.filter_by(
            job_id=document_job_id
        ).all()

        if not confirmations:
            # 没有确认记录，允许创建（兼容旧流程）
            return True, []

        # 构造 FieldConfirmationRecord 列表
        field_records = []
        for conf in confirmations:
            record = FieldConfirmationRecord(
                field_id=conf.id,
                task_id=conf.job_id,
                line_id=None,  # 行级字段用 field_name 区分
                field_name=conf.field_name,
                confirmation_status=conf.confirmation_status,
                original_value=conf.original_value,
                confirmed_value=conf.confirmed_value,
                correction_reason=conf.correction_reason,
                evidence_source=conf.evidence_source,
                model=conf.model or '',
                prompt_version=conf.prompt_version or '',
                schema_version=conf.schema_version or '',
                confirmed_by=conf.confirmed_by or 0,
                confirmed_at=conf.confirmed_at,
                created_at=conf.created_at,
            )
            field_records.append(record)

        # 查询 job 的风险标记（从 AIDocumentJob 的 status 或额外字段推断）
        job = AIDocumentJob.query.get(document_job_id)
        if not job:
            return True, []

        # AI-R08-F01: 直接从 job 风险标记字段读取
        import json as _json
        duplicate_risk = bool(getattr(job, 'duplicate_risk', False))
        low_confidence_fields_raw = getattr(job, 'low_confidence_fields', None) or '[]'
        try:
            low_confidence_fields = _json.loads(low_confidence_fields_raw) if isinstance(low_confidence_fields_raw, str) else []
        except Exception:
            low_confidence_fields = []
        material_ambiguity = bool(getattr(job, 'material_ambiguity', False))
        specification_conflict = bool(getattr(job, 'specification_conflict', False))
        high_risk_material = bool(getattr(job, 'high_risk_material', False))

        # 调用纯逻辑校验
        is_allowed, reasons = validate_draft_creation_allowed(
            field_records=field_records,
            duplicate_risk=duplicate_risk,
            low_confidence_fields=low_confidence_fields,
            material_ambiguity=material_ambiguity,
            specification_conflict=specification_conflict,
            high_risk_material=high_risk_material,
        )
        return is_allowed, reasons
    except Exception as e:
        app.logger.error(f'门禁校验失败: {e}')
        return True, []  # 校验失败时降级允许创建


def _ai_create_confirmed_document_draft(doc_type, rows, source_text='', adjustment_type='', customer='', source_purchase_order_id=None, confirmation_token=None, document_job_id=None):
    doc_type = (doc_type or '').strip()
    if doc_type == 'sales_out':
        doc_type = 'sales_out_order'
    if doc_type not in AI_DOC_TYPE_LABELS:
        return None, '单据类型无效'

    # AI_TASK: AI-R08-F01 服务端门禁校验
    gate_allowed, gate_reasons = _ai_check_draft_creation_gate(document_job_id)
    if not gate_allowed:
        error_msg = '门禁校验失败，禁止创建草稿：' + '; '.join(gate_reasons)
        app.logger.warning(f'文档任务 {document_job_id} 门禁校验失败: {gate_reasons}')
        return None, error_msg

    matched = []
    for row in rows or []:
        material_id = _clean_int(row.get('material_id'))
        quantity = round_to_2_decimals(parse_float_value(row.get('quantity'), 0))
        if not material_id or quantity <= 0:
            continue
        material = Material.query.options(joinedload(Material.unit)).get(material_id)
        if not material:
            continue
        _ai_learn_material_alias(row.get('raw') or '', material.id, source='ai_confirm')
        matched.append({'material': material, 'quantity': quantity, 'raw': material.code or material.name})
    if not matched:
        return None, '没有可生成草稿的有效物料行'

    draft_message = _ai_draft_message_from_matches(matched)
    if doc_type == 'purchase_request':
        business_items = sorted(
            ((int(row['material'].id), round(float(row['quantity'] or 0), 6)) for row in matched),
            key=lambda entry: (entry[0], entry[1]),
        )
        business_key = {
            'items': business_items,
            'confirmation_token': confirmation_token or '',
        }
        slot = _ai_draft_idempotency().acquire(
            capability='purchase_request_draft',
            source='confirmation',
            business_fields=business_key,
            draft_type='purchase_request',
            request_snapshot={'source_text': (source_text or '')[:200], 'rows': len(matched)},
            confirmation_token=confirmation_token,
            document_job_id=document_job_id,
        )
        if slot.is_replay and slot.replay:
            return slot.replay, None
        if not slot.acquired:
            return None, slot.conflict_reason
        try:
            request_order = PurchaseRequest(
                request_no=generate_order_no('PR'),
                date=date.today(),
                applicant=current_user.username if current_user.is_authenticated else '',
                department='采购',
                urgency='urgent' if len(matched) >= 5 else 'normal',
                expected_date=date.today() + timedelta(days=7),
                reason='AI 建议经人工确认后生成采购申请草稿',
                remark=(source_text or 'AI 仅生成草稿，供应商、数量和价格需采购人员复核。')[:500],
                status='pending',
                operator_id=current_user.id if current_user.is_authenticated else None,
                total_amount=0,
            )
            db.session.add(request_order)
            db.session.flush()
            total_amount = 0
            for row in matched:
                material = row['material']
                quantity = row['quantity']
                estimated_price = round_to_2_decimals(material.price or 0)
                estimated_amount = round_to_2_decimals(quantity * estimated_price)
                total_amount += estimated_amount
                db.session.add(PurchaseRequestItem(
                    purchase_request_id=request_order.id,
                    material_id=material.id,
                    material_name=material.name,
                    material_code=material.code,
                    spec=material.spec or '',
                    quantity=quantity,
                    unit_id=material.unit_id,
                    estimated_price=estimated_price,
                    estimated_amount=estimated_amount,
                    supplier_id=material.supplier_id,
                    supplier_name=material.supplier.name if material.supplier else None,
                    remark='AI 补货建议，已由当前登录人员在确认页确认。',
                ))
            request_order.total_amount = round_to_2_decimals(total_amount)
            db.session.commit()
            log_operation(
                'AI人工确认生成采购申请草稿',
                f'采购申请单：{request_order.request_no}',
                'purchase_request',
                request_order.id,
            )
            response = {
                'order_no': request_order.request_no,
                'url': url_for('purchase_request_detail', id=request_order.id),
                'items': [
                    {'code': row['material'].code, 'name': row['material'].name, 'quantity': row['quantity']}
                    for row in matched
                ],
            }
            _ai_draft_idempotency().complete(
                slot.record,
                draft_type='purchase_request',
                draft_id=request_order.id,
                draft_no=request_order.request_no,
                response=response,
            )
            return response, None
        except Exception as exc:
            db.session.rollback()
            _ai_draft_idempotency().fail(slot.record, str(exc))
            raise
    if doc_type == 'in_order':
        if source_purchase_order_id:
            context_po_result = _ai_try_create_in_order_from_context_purchase_order(
                matched,
                {'page_url': f'/purchase_order/{source_purchase_order_id}'},
                source_text or 'AI识别结果确认',
                confirmation_token=confirmation_token,
                document_job_id=document_job_id,
            )
            if context_po_result:
                return context_po_result
        po_result = _ai_try_create_in_order_from_purchase_order_matches(
            matched,
            source_text or 'AI识别结果确认',
            confirmation_token=confirmation_token,
            document_job_id=document_job_id,
        )
        if po_result:
            return po_result
        if purchase_in_order_requires_order():
            return None, '采购入库要求关联采购订单。没有找到可下推的采购订单，请先维护或选择采购订单后再入库。'
        draft, error = _ai_create_in_order_draft(
            draft_message,
            manual_confirmation=True,
            confirmation_token=confirmation_token,
            document_job_id=document_job_id,
            source='confirmation',
        )
        if draft:
            order = InOrder.query.filter_by(order_no=draft.get('order_no')).first()
            if order:
                order.business_type = '采购入库'
                order.remark = (source_text or order.remark or '')[:200]
                db.session.commit()
    elif doc_type in ('out_order', 'sales_out_order'):
        draft, error = _ai_create_out_order_draft(
            draft_message,
            manual_confirmation=True,
            confirmation_token=confirmation_token,
            document_job_id=document_job_id,
            source='confirmation',
        )
        if draft:
            order = OutOrder.query.filter_by(order_no=draft.get('order_no')).first()
            if order:
                if doc_type == 'sales_out_order':
                    order.business_type = '销售出库'
                if customer:
                    order.customer = customer[:100]
                order.remark = (source_text or order.remark or '')[:200]
                db.session.commit()
    elif doc_type == 'transfer':
        draft, error = _ai_create_transfer_draft(
            (source_text or '') + ' ' + draft_message,
            manual_confirmation=True,
            confirmation_token=confirmation_token,
            document_job_id=document_job_id,
            source='confirmation',
        )
    elif doc_type == 'adjustment':
        prefix = '盘盈 ' if str(adjustment_type or '').lower() == 'surplus' else '报废 '
        draft, error = _ai_create_adjustment_draft(
            prefix + draft_message,
            manual_confirmation=True,
            confirmation_token=confirmation_token,
            document_job_id=document_job_id,
            source='confirmation',
        )
    else:
        draft, error = _ai_create_check_draft(
            draft_message,
            manual_confirmation=True,
            confirmation_token=confirmation_token,
            document_job_id=document_job_id,
            source='confirmation',
        )
    if error:
        return None, error
    return draft, None


def _ai_purchase_match_qty_map(matched):
    qty_by_material = {}
    for row in matched or []:
        material = row.get('material')
        if not material:
            continue
        qty_by_material[material.id] = round_to_2_decimals(qty_by_material.get(material.id, 0) + (row.get('quantity') or 0))
    return {mid: qty for mid, qty in qty_by_material.items() if qty > 0}


def _ai_find_purchase_order_candidates_for_matches(matched, limit=5):
    qty_by_material = _ai_purchase_match_qty_map(matched)
    if not qty_by_material:
        return []
    material_ids = set(qty_by_material.keys())
    orders = PurchaseOrder.query.options(
        joinedload(PurchaseOrder.supplier),
        selectinload(PurchaseOrder.items).joinedload(PurchaseOrderItem.material),
    ).join(PurchaseOrderItem).filter(
        PurchaseOrder.status.in_(('pending', 'partial', 'open')),
        PurchaseOrderItem.material_id.in_(material_ids),
    ).order_by(PurchaseOrder.expected_date.asc().nullslast(), PurchaseOrder.date.asc(), PurchaseOrder.id.asc()).limit(50).all()
    candidates = []
    for order in orders:
        submitted = {}
        score = 0
        for material_id, need_qty in qty_by_material.items():
            remaining = []
            for item in order.items or []:
                if item.material_id != material_id:
                    continue
                remain_qty = round_to_2_decimals((item.quantity or 0) - (item.received_quantity or 0))
                if remain_qty > 0:
                    remaining.append((item, remain_qty))
            if not remaining:
                submitted = None
                break
            exact = next(((item, remain) for item, remain in remaining if abs(remain - need_qty) <= STOCK_COMPARE_EPSILON), None)
            item, remain_qty = exact or remaining[0]
            receive_qty = need_qty
            if receive_qty - remain_qty > STOCK_COMPARE_EPSILON:
                submitted = None
                break
            submitted[item.id] = receive_qty
            score += 3 if exact else 1
        if submitted:
            candidates.append({'order': order, 'submitted_qty_by_id': submitted, 'score': score})
    candidates.sort(key=lambda row: (-row['score'], row['order'].expected_date or date.max, row['order'].date or date.max, row['order'].id))
    return candidates[:limit]


# AI_TASK: AI-R06
# ORM adapter：把 PurchaseOrder ORM 查询结果转成 delivery_matcher 的纯数据结构
def _ai_purchase_order_to_info(order):
    """把 PurchaseOrder ORM 对象转成 PurchaseOrderInfo 纯数据结构。"""
    from ai.documents.delivery_matcher import PurchaseOrderInfo, PurchaseOrderLineInfo
    supplier_name = ''
    try:
        if order.supplier:
            supplier_name = order.supplier.name or ''
    except Exception:  # noqa: BLE001
        pass
    lines = tuple(
        PurchaseOrderLineInfo(
            line_id=item.id,
            material_id=item.material_id or 0,
            material_code=(item.material.code if item.material else '') or '',
            material_name=(item.material.name if item.material else '') or '',
            material_spec=(item.material.spec if item.material else '') or '',
            quantity=float(item.quantity or 0),
            received_quantity=float(item.received_quantity or 0),
        )
        for item in (order.items or [])
    )
    expected_date_str = ''
    try:
        if order.expected_date:
            expected_date_str = order.expected_date.strftime('%Y-%m-%d') if hasattr(order.expected_date, 'strftime') else str(order.expected_date)[:10]
    except Exception:  # noqa: BLE001
        pass
    return PurchaseOrderInfo(
        order_id=order.id,
        order_no=order.order_no or '',
        supplier_id=(order.supplier_id or 0),
        supplier_name=supplier_name,
        status=order.status or 'pending',
        expected_date=expected_date_str,
        lines=lines,
    )


def _ai_query_open_purchase_orders_for_delivery(supplier_name, material_codes):
    """联合匹配注入回调：按供应商名称 + 物料编码/名称查开放采购订单。

    Args:
        supplier_name: 送货通知提取的供应商名称
        material_codes: 物料编码与名称的合并列表
    """
    try:
        # 先按物料编码查 Material.id 集合
        material_ids = set()
        code_or_name_list = [c for c in material_codes if c]
        if not code_or_name_list:
            return []
        materials = Material.query.filter(
            or_(
                Material.code.in_(code_or_name_list),
                Material.name.in_(code_or_name_list),
            )
        ).all()
        for m in materials:
            material_ids.add(m.id)
        if not material_ids:
            return []

        query = PurchaseOrder.query.options(
            joinedload(PurchaseOrder.supplier),
            selectinload(PurchaseOrder.items).joinedload(PurchaseOrderItem.material),
        ).join(PurchaseOrderItem).filter(
            PurchaseOrder.status.in_(('pending', 'partial', 'open')),
            PurchaseOrderItem.material_id.in_(material_ids),
        )
        # 供应商名称过滤（如果有）
        if supplier_name:
            try:
                query = query.join(Supplier, PurchaseOrder.supplier_id == Supplier.id).filter(
                    or_(
                        Supplier.name.like(f'%{supplier_name}%'),
                        Supplier.name.ilike(f'%{supplier_name}%'),
                    )
                )
            except Exception:  # noqa: BLE001 - 供应商关联查询失败不阻塞
                pass
        orders = query.order_by(
            PurchaseOrder.expected_date.asc().nullslast(),
            PurchaseOrder.date.asc(),
            PurchaseOrder.id.asc(),
        ).limit(20).all()
        return [_ai_purchase_order_to_info(o) for o in orders]
    except Exception as exc:  # noqa: BLE001 - 查询失败返回空，不阻塞主流程
        app.logger.warning(f'查询开放采购订单异常: {exc}')
        return []


def _ai_query_purchase_order_by_no(order_no):
    """联合匹配注入回调：按订单号精确查采购订单（含关闭订单，用于差异展示）。"""
    if not order_no:
        return None
    try:
        order = PurchaseOrder.query.options(
            joinedload(PurchaseOrder.supplier),
            selectinload(PurchaseOrder.items).joinedload(PurchaseOrderItem.material),
        ).filter(PurchaseOrder.order_no == order_no).first()
        if not order:
            return None
        return _ai_purchase_order_to_info(order)
    except Exception as exc:  # noqa: BLE001
        app.logger.warning(f'按订单号查询采购订单异常: {exc}')
        return None


# AI_TASK: AI-R07
# 物料治理 ORM adapter：把 Material/AIMaterialAlias ORM 对象转成 MaterialInfo
# 纯数据结构，注入到 match_material_governance 供纯逻辑层调用。
def _ai_material_to_info(material):
    """Material ORM 对象转 MaterialInfo（含别名键列表）。"""
    from ai.documents.material_governance import MaterialInfo as _MG_MaterialInfo
    if material is None:
        return None
    aliases = tuple(
        a.alias_key for a in (material.ai_aliases or []) if not a.disabled
    )
    unit_code = material.unit.code if material.unit else ''
    return _MG_MaterialInfo(
        material_id=int(material.id),
        code=str(material.code or ''),
        name=str(material.name or ''),
        spec=str(material.spec or ''),
        unit_code=str(unit_code or ''),
        aliases=aliases,
    )


def _ai_mg_query_materials_by_codes(codes):
    """物料治理注入回调：按编码列表查物料。"""
    if not codes:
        return []
    try:
        # 归一化后去重，大小写不敏感查询
        unique_codes = list({c.strip() for c in codes if c and c.strip()})
        if not unique_codes:
            return []
        # 用 OR 条件查多个编码
        or_filters = [db.func.lower(Material.code) == c.lower() for c in unique_codes]
        materials = Material.query.options(joinedload(Material.unit)).filter(or_(*or_filters)).limit(20).all()
        return [m for m in (_ai_material_to_info(mat) for mat in materials) if m]
    except Exception as exc:  # noqa: BLE001
        app.logger.warning(f'按编码查询物料异常: {exc}')
        return []


def _ai_mg_query_materials_by_name(name, limit=3):
    """物料治理注入回调：按名称模糊查物料（limit 上限 3）。"""
    if not name:
        return []
    try:
        like = f'%{name}%'
        materials = Material.query.options(joinedload(Material.unit)).filter(
            or_(Material.name.ilike(like), Material.spec.ilike(like))
        ).limit(min(int(limit), 20)).all()
        return [m for m in (_ai_material_to_info(mat) for mat in materials) if m]
    except Exception as exc:  # noqa: BLE001
        app.logger.warning(f'按名称查询物料异常: {exc}')
        return []


def _ai_mg_query_aliases(alias_keys):
    """物料治理注入回调：按别名键列表查物料（一物多码）。"""
    if not alias_keys:
        return []
    try:
        unique_keys = list({k.strip() for k in alias_keys if k and k.strip()})
        if not unique_keys:
            return []
        # 通过别名关联物料，过滤已禁用别名
        rows = AIMaterialAlias.query.options(
            joinedload(AIMaterialAlias.material).joinedload(Material.unit),
        ).filter(
            AIMaterialAlias.alias_key.in_(unique_keys),
            AIMaterialAlias.disabled == False,  # noqa: E712
        ).limit(20).all()
        seen_ids = set()
        result = []
        for r in rows:
            if r.material and r.material.id not in seen_ids:
                seen_ids.add(r.material.id)
                info = _ai_material_to_info(r.material)
                if info:
                    result.append(info)
        return result
    except Exception as exc:  # noqa: BLE001
        app.logger.warning(f'按别名查询物料异常: {exc}')
        return []


def _ai_dc_query_existing_drafts(source_hash, business_key):
    """AI-R08 文档确认台注入回调：按 source_hash/business_key 查已存在的草稿。

    用于重复风险检测（验收：重复风险可阻止建单）。
    返回字典列表：[{draft_type, draft_id, draft_no, status, created_at,
                    match_reason, similarity}, ...]
    """
    if not source_hash and not business_key:
        return []
    try:
        # 查 AIDraftIdempotency 表，按 source_hash 或 business_key（idempotency_key）匹配
        from sqlalchemy import or_ as sa_or
        query = AIDraftIdempotency.query
        conditions = []
        if source_hash:
            # source_hash 是 idempotency_key 前 32 位，用 like 匹配
            conditions.append(AIDraftIdempotency.source_hash.ilike(f'{source_hash}%'))
        if business_key:
            conditions.append(AIDraftIdempotency.idempotency_key == business_key)
        if not conditions:
            return []
        records = query.filter(sa_or(*conditions)).order_by(
            AIDraftIdempotency.created_at.desc()
        ).limit(10).all()

        result = []
        for r in records:
            # 相似度判定：idempotency_key 完全匹配=1.0，source_hash 前缀匹配=0.90
            similarity = 0.90
            match_reason = 'source_hash'
            if business_key and r.idempotency_key == business_key:
                similarity = 1.0
                match_reason = 'business_key'
            elif source_hash and business_key and (
                r.idempotency_key == business_key
                and (r.source_hash or '').startswith(source_hash)
            ):
                similarity = 1.0
                match_reason = 'both'
            result.append({
                'draft_type': r.draft_type or '',
                'draft_id': int(r.draft_id or 0),
                'draft_no': r.draft_no or '',
                'status': r.status or '',
                'created_at': r.created_at.isoformat() if r.created_at else '',
                'match_reason': match_reason,
                'similarity': similarity,
            })
        return result
    except Exception as exc:  # noqa: BLE001
        app.logger.warning(f'查询已存在草稿异常: {exc}')
        return []


def _ai_ff_save_feedback_record(record):
    """AI-R09 字段反馈注入回调：持久化单条 FieldCorrectionRecord 到 AIFieldFeedback 表。

    用于按来源与版本聚合准确率和修正率，定位质量下降的字段和版本。
    敏感原文已在 build_field_correction_records 中脱敏，此处直接存储。
    """
    try:
        from flask import g as _g_ff
        _ff_user_id = current_user.id if current_user.is_authenticated else None
        _ff_run_id = getattr(_g_ff, 'ai_run_id', None)
        row = AIFieldFeedback(
            user_id=_ff_user_id,
            ai_run_id=_ff_run_id,
            field_name=(record.field_name or '')[:40],
            line_index=int(record.line_index or -1),
            original_value=(record.original_value or '')[:500],
            corrected_value=(record.corrected_value or '')[:500],
            correction_reason=(record.correction_reason or '')[:60],
            adopted=bool(record.adopted),
            model=(record.model or '')[:100],
            prompt_hash=(record.prompt_hash or '')[:20],
            schema_version=(record.schema_version or '')[:40],
            source=(record.source or 'ocr_upload')[:30],
        )
        db.session.add(row)
        db.session.commit()
    except Exception as exc:  # noqa: BLE001 - 反馈记录持久化失败不阻塞业务
        db.session.rollback()
        app.logger.warning(f'字段反馈记录持久化异常: {exc}')


def _ai_ff_query_feedback_records(source='', model='', schema_version='', field_name='', limit=500):
    """AI-R09 查询字段反馈记录（供聚合质量指标用）。"""
    try:
        query = AIFieldFeedback.query
        if source:
            query = query.filter_by(source=source)
        if model:
            query = query.filter_by(model=model)
        if schema_version:
            query = query.filter_by(schema_version=schema_version)
        if field_name:
            query = query.filter_by(field_name=field_name)
        records = query.order_by(AIFieldFeedback.created_at.desc()).limit(limit).all()
        result = []
        for r in records:
            result.append({
                'field_name': r.field_name or '',
                'line_index': int(r.line_index or -1),
                'original_value': r.original_value or '',
                'corrected_value': r.corrected_value or '',
                'correction_reason': r.correction_reason or '',
                'adopted': bool(r.adopted),
                'model': r.model or '',
                'prompt_hash': r.prompt_hash or '',
                'schema_version': r.schema_version or '',
                'source': r.source or '',
                'created_at': r.created_at.isoformat() if r.created_at else '',
            })
        return result
    except Exception as exc:  # noqa: BLE001
        app.logger.warning(f'查询字段反馈记录异常: {exc}')
        return []


