        ('操作审计', '系统管理', 'operation_audit_page', {}, ('操作审计', '日志审计', '操作日志', '审计', '日志')),
        ('风险操作审计', '系统管理', 'operation_audit_page', {'risk': '1'}, ('风险日志', '风险操作', '删除记录', '反审记录')),
