def _ai_create_agent_task(agent_type, objective):
    task = AIAgentTask(
        ai_run_id=getattr(g, 'ai_run_id', None),
        user_id=current_user.id,
        agent_type=agent_type,
        objective=objective[:300],
        status='running',
    )
