def _ai_confirmation_material_candidates(payload, limit=300):
    payload = payload or {}
    rows = payload.get('rows') or []
    material_ids = {
        _clean_int(row.get('material_id'))
        for row in rows
        if isinstance(row, dict) and _clean_int(row.get('material_id'))
    }
    candidates = []
    seen = set()
    if material_ids:
        for material in Material.query.options(joinedload(Material.unit)).filter(Material.id.in_(material_ids)).all():
            candidates.append(material)
            seen.add(material.id)

    keywords = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        for key in ('code', 'name', 'spec', 'raw_text', 'raw'):
            value = str(row.get(key) or '').strip()
            if value and value not in keywords:
                keywords.append(value)
    for keyword in keywords[:20]:
        if len(candidates) >= limit:
            break
        like = f'%{keyword[:80]}%'
        matches = (
            Material.query.options(joinedload(Material.unit))
            .filter(db.or_(Material.code.ilike(like), Material.name.ilike(like), Material.spec.ilike(like)))
            .order_by(Material.code.asc())
            .limit(20)
            .all()
        )
        for material in matches:
            if material.id in seen:
                continue
            candidates.append(material)
            seen.add(material.id)
            if len(candidates) >= limit:
                break

    if len(candidates) < min(limit, 50):
        for material in Material.query.options(joinedload(Material.unit)).order_by(Material.code.asc()).limit(50).all():
            if material.id in seen:
                continue
            candidates.append(material)
            seen.add(material.id)
            if len(candidates) >= limit:
                break
    return candidates


def _ai_document_confirm_allowed(doc_type):
    doc_type = (doc_type or '').strip()
    if doc_type == 'sales_out':
        doc_type = 'sales_out_order'
    capability = {
        'in_order': 'purchase_receive_draft',
        'out_order': 'out_order_draft',
        'sales_out_order': 'sales_out_draft',
        'transfer': 'transfer_draft',
        'check': 'check_draft',
        'adjustment': 'adjustment_draft',
        'purchase_request': 'purchase_request_draft',
    }.get(doc_type)
    return bool(capability and _ai_capability_allowed(capability))


@app.route('/ai/document_confirm/<token>', methods=['GET', 'POST'])
@require_role('warehouse', 'purchase', 'production')
@login_required
def ai_document_confirm(token):
    pending = session.get('_ai_document_confirmations') or {}
    payload = pending.get(token)
    if not payload:
        flash('AI识别结果已过期，请重新识别。', 'warning')
        return redirect(url_for('index'))

    materials = _ai_confirmation_material_candidates(payload)
    material_count = Material.query.count()
    if request.method == 'POST':
        if not _ai_document_confirm_allowed(payload.get('document_type')):
            flash('当前账号没有权限生成该类型单据草稿。', 'danger')
            return redirect(url_for('index'))
        
        # AI_TASK: AI-R08-F01 保存字段确认状态并执行门禁校验
        document_job_id = payload.get('document_job_id')
        if document_job_id:
            field_confirmation_saved = _ai_save_field_confirmations_from_form(
                document_job_id=document_job_id,
                payload=payload,
                form=request.form,
            )
            if not field_confirmation_saved:
                app.logger.warning(f'文档任务 {document_job_id} 字段确认状态保存失败')
        
        row_count = _clean_int(request.form.get('row_count')) or 0
        rows = []
        for idx in range(row_count):
            if request.form.get(f'use_row_{idx}') != '1':
                continue
            original_row = (payload.get('rows') or [{}])[idx] if idx < len(payload.get('rows') or []) else {}
            rows.append({
                'material_id': request.form.get(f'material_id_{idx}'),
                'quantity': request.form.get(f'quantity_{idx}'),
                'raw': original_row.get('raw') or original_row.get('code') or '',
            })
        draft, error = _ai_create_confirmed_document_draft(
            payload.get('document_type'),
            rows,
            source_text=payload.get('source_text') or '',
            adjustment_type=payload.get('adjustment_type') or '',
            customer=(request.form.get('customer') or payload.get('customer') or '').strip(),
            source_purchase_order_id=payload.get('source_purchase_order_id'),
            confirmation_token=token,
            document_job_id=payload.get('document_job_id'),
        )
        if error:
            db.session.rollback()
            _ai_update_document_job(payload.get('document_job_id'), 'failed', error_message=error)
            flash(error, 'danger')
            return render_template('ai_document_confirm.html', token=token, payload=payload, materials=materials, material_count=material_count)
        pending.pop(token, None)
        session['_ai_document_confirmations'] = pending
        session.modified = True
        _ai_mark_document_job_draft_created(
            payload.get('document_job_id'),
            payload.get('document_type'),
            draft,
        )
        flash(f'已生成草稿 {draft["order_no"]}，请核对后再提交。', 'success')
        return redirect(draft['url'])

    return render_template('ai_document_confirm.html', token=token, payload=payload, materials=materials, material_count=material_count)


def _ai_test_llm_vision(overrides=None):
    if not _ai_llm_configured(overrides):
        return None, '请先启用大模型并保存 API Key'
    if not _ai_llm_vision_enabled(overrides):
        return None, '系统设置里没有启用图片识别'

    payload = {
        'model': _ai_llm_model(overrides),
        'messages': [
            {'role': 'system', 'content': '你是图片识别连通性测试助手。只用一句中文回答图片的主要颜色。'},
            {
                'role': 'user',
                'content': [
                    {'type': 'text', 'text': '请判断这张测试图片的主要颜色。'},
                    {
                        'type': 'image_url',
                        'image_url': {
                            'url': 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAIAAAD8GO2jAAAAJ0lEQVR42u3NsQkAAAjAsP7/tF7hIASyp6lTCQQCgUAgEAgEgi/BAjLD/C5w/SM9AAAAAElFTkSuQmCC'
                        },
                    },
                ],
            },
        ],
        'temperature': 0,
        'max_tokens': min(max(_ai_llm_max_tokens(overrides), 50), 200),
    }
    headers = _ai_llm_headers(overrides)
    try:
        response = requests.post(
            _ai_llm_endpoint(overrides),
            headers=headers,
            json=payload,
            timeout=max(_ai_llm_timeout_seconds(overrides), 60),
        )
        if not response.ok:
            return None, _ai_llm_error_message(response)
        response.raise_for_status()
        data = response.json()
        content = (((data.get('choices') or [{}])[0].get('message') or {}).get('content') or '').strip()
        if not content:
            return None, '供应商接口返回成功，但 choices[0].message.content 为空'
        return content[:300], ''
    except Exception as exc:
        app.logger.warning('AI vision test unavailable: %s', exc)
        return None, str(exc)


def _ai_llm_error_message(response):
    try:
        data = response.json()
    except ValueError:
        text = (response.text or '').strip()
        return f'HTTP {response.status_code}: {text[:300]}' if text else f'HTTP {response.status_code}'
    error = data.get('error') if isinstance(data, dict) else None
    if isinstance(error, dict):
        message = str(error.get('message') or '').strip()
        err_type = str(error.get('type') or '').strip()
        code = str(error.get('code') or '').strip()
        detail = message or json.dumps(error, ensure_ascii=False)
        suffix = '，'.join(part for part in [err_type, code] if part)
        return f'HTTP {response.status_code}: {detail}' + (f'（{suffix}）' if suffix else '')
    return f'HTTP {response.status_code}: {json.dumps(data, ensure_ascii=False)[:300]}'


def _ai_execute_intent(message, intent_payload, context=None):
    if not intent_payload:
        return None

    intent = intent_payload.get('intent')
    params = intent_payload.get('params') or {}
    keyword = str(params.get('keyword') or '').strip() or _ai_guess_keyword(message)
    context = context or {}

    supplier_profile_response = _ai_supplier_profile_response(message, context)
    if supplier_profile_response:
        return supplier_profile_response

    if intent == 'greeting':
        return _ai_json_response('你好，我是AI助手。你可以问我库存、单据、今日概况、待处理事项，也可以让我生成入库单、领料单、调拨单、盘点单、调整单草稿。')

    if intent == 'model_status':
        return _ai_json_response(_ai_model_status_text())

    if intent == 'current_time':
        now = datetime.now()
        return _ai_json_response(f'现在是 {now.strftime("%Y-%m-%d %H:%M:%S")}。')

    if intent == 'general_chat':
        return None

    if intent == 'inventory_discrepancy':
        return _ai_inventory_discrepancy_response(message, context)

    if intent == 'today_issued_materials':
        reply, cards = _ai_today_issued_materials()
        return _ai_json_response(reply, cards, [{'label': '打开出库列表', 'url': url_for('out_order_list')}])

    if intent == 'today_received_materials':
        reply, cards = _ai_today_received_materials()
        return _ai_json_response(reply, cards, [{'label': '打开入库列表', 'url': url_for('in_order_list')}])

    if intent == 'today_summary':
        reply, cards = _ai_today_summary()
        return _ai_json_response(reply, cards, [
            {'label': '打开首页看板', 'url': url_for('index')},
            {'label': '查看待处理', 'url': url_for('pending_documents')},
        ])

    if intent == 'create_out_order_draft':
        draft, error = _ai_create_out_order_draft(message)
        if error:
            return _ai_json_response(error)
        return _ai_json_response(
            f'已生成领料单草稿 {draft["order_no"]}，请打开检查后再提交。',
            draft['items'],
            [{'label': '打开草稿', 'url': draft['url']}],
        )

    if intent == 'create_in_order_draft':
        draft, error = _ai_create_in_order_draft(message)
        if error:
            return _ai_json_response(error)
        return _ai_json_response(
            f'已生成入库单草稿 {draft["order_no"]}，请打开检查后再提交。',
            draft['items'],
            [{'label': '打开草稿', 'url': draft['url']}],
        )

    if intent == 'create_transfer_draft':
        draft, error = _ai_create_transfer_draft(message)
        if error:
            return _ai_json_response(error)
        return _ai_json_response(
            f'已生成调拨单草稿 {draft["order_no"]}（{draft["from_location"]} → {draft["to_location"]}），请打开检查后再提交。',
            draft['items'],
            [{'label': '打开草稿', 'url': draft['url']}],
        )

    if intent == 'create_check_draft':
        draft, error = _ai_create_check_draft(message)
        if error:
            return _ai_json_response(error)
        return _ai_json_response(
            f'已生成盘点单草稿 {draft["order_no"]}，系统库存已自动填入，请盘点后录入实际数量。',
            draft['items'],
            [{'label': '打开草稿', 'url': draft['url']}],
        )

    if intent == 'create_adjustment_draft':
        draft, error = _ai_create_adjustment_draft(message)
        if error:
            return _ai_json_response(error)
        return _ai_json_response(
            f'已生成调整单草稿 {draft["order_no"]}（{draft["adjustment_type"]}），请打开检查后再提交。',
            draft['items'],
            [{'label': '打开草稿', 'url': draft['url']}],
        )

    if intent == 'find_orders':
        found_orders = _ai_find_orders(keyword or message)
        if not found_orders and keyword and keyword != message:
            found_orders = _ai_find_orders(message)
        return _ai_json_response(
            f'找到 {len(found_orders)} 张相关单据，下面可以直接打开。' if found_orders else '没有找到相关单据，可以换完整单号再查一次。',
            found_orders,
            [{'label': '全部待处理', 'url': url_for('pending_documents')}],
        )

    if intent == 'stock_alerts':
        low_query = Material.query.options(joinedload(Material.unit)).filter(_material_low_stock_filter())
        negative_query = Material.query.options(joinedload(Material.unit)).filter(Material.stock < 0)
        lows = low_query.order_by(Material.stock.asc()).limit(8).all() if inventory_alert_enabled() else []
        negatives = negative_query.order_by(Material.stock.asc()).limit(8).all()
        cards = [_ai_material_payload(item) for item in negatives + lows]
        return _ai_json_response(
            f'发现负库存 {len(negatives)} 项，低库存 {len(lows)} 项。下面显示前 {len(cards)} 项。',
            cards,
            [{'label': '查看库存预警', 'url': url_for('material_list', stock_filter='low')}],
        )

    if intent == 'pending_documents':
        cards = _ai_pending_documents(limit=12)
        return _ai_json_response(
            f'当前找到 {len(cards)} 张待处理/待审核单据，已按最新单据优先显示。',
            cards,
            [{'label': '打开待处理中心', 'url': url_for('pending_documents')}],
        )

    if intent in {'query_material', 'stock_transactions'}:
        materials = _ai_material_query(keyword, limit=8)
        if not materials and keyword:
            materials = _ai_material_query(_ai_guess_keyword(message), limit=8)
        # 上下文感知：用户在物料详情页或列表选中行问"这个库存"时，从 page_url 提取物料 id
        if not materials:
            ctx_material = _ai_material_from_context(context)
            if ctx_material:
                materials = [ctx_material]
        if not materials:
            return _ai_json_response('没有找到相关物料，可以换物料编码、名称或规格再查一次。')
        cards = [_ai_material_payload(material) for material in materials]
        actions = [{'label': '打开物料列表', 'url': url_for('material_list', search=keyword)}]
        if intent == 'stock_transactions' and len(materials) == 1:
            cards = _ai_stock_transactions(materials[0]) or cards
            actions.append({'label': '查看物料', 'url': url_for('material_list', search=materials[0].code or materials[0].name or '')})
        return _ai_json_response(
            f'找到 {len(materials)} 个相关物料。可以继续问“查 {materials[0].code} 流水”或“生成领料单 {materials[0].code} 10”。',
            cards,
            actions,
        )

    if intent == 'analysis_turnover':
        days = params.get('days')
        warehouse = str(params.get('warehouse') or '').strip() or None
        category = str(params.get('category') or '').strip() or None
        return _ai_json_response(_ai_analysis_inventory_turnover(days=days, warehouse=warehouse, category=category))

    if intent == 'analysis_stock_value':
        category = str(params.get('category') or '').strip() or None
        reply = _ai_append_data_source(
            _ai_analysis_stock_value(category=category),
            '实时数据库查询',
            '当前库存' + (f'；分类包含 {category}' if category else ''),
            ['material', 'material_category'],
        )
        return _ai_json_response(reply)

    if intent == 'analysis_supplier':
        days = params.get('days')
        warehouse = str(params.get('warehouse') or '').strip() or None
        scope_days = max(1, int(days or 90))
        reply = _ai_append_data_source(
            _ai_analysis_supplier(days=days, warehouse=warehouse),
            '实时数据库查询',
            f'最近{scope_days}天' + (f'；仓库包含 {warehouse}' if warehouse else ''),
            ['supplier', 'in_order'],
        )
        return _ai_json_response(reply)

    if intent == 'analysis_consumption_trend':
        kw = keyword or _ai_guess_keyword(message)
        if not kw:
            return _ai_json_response('请告诉我物料编码或名称，例如：查 M001 消耗趋势。')
        days = params.get('days')
        warehouse = str(params.get('warehouse') or '').strip() or None
        scope_days = max(1, int(days or 30))
        reply = _ai_append_data_source(
            _ai_analysis_consumption_trend(kw, days=days, warehouse=warehouse),
            '实时数据库查询',
            f'物料 {kw}；最近{scope_days}天' + (f'；仓库/库位包含 {warehouse}' if warehouse else ''),
            ['material', 'stock_transaction'],
        )
        return _ai_json_response(reply)

    if intent == 'analysis_low_stock':
        reply = _ai_append_data_source(
            _ai_analysis_low_stock_report(),
            '实时数据库查询',
            '当前库存预警启用范围',
            ['material', 'system_setting'],
        )
        return _ai_json_response(reply)

    if intent == 'analysis_category':
        category = str(params.get('category') or '').strip() or None
        reply = _ai_append_data_source(
            _ai_analysis_category_summary(category=category),
            '实时数据库查询',
            ('分类包含 ' + category) if category else '全部物料分类',
            ['material_category', 'material'],
        )
        return _ai_json_response(reply)

    if intent == 'exception_workbench':
        return _ai_exception_workbench_response(message, context, force=True)

    if intent == 'agent_patrol':
        return _ai_agent_patrol_response(message, context, force=True)

    if intent == 'delivery_note_inbound':
        return _ai_delivery_note_inbound_response(message, context, force=True)

    if intent == 'help':
        return _ai_json_response(
            '我可以查库存、查单号、查今日概况、查待处理、查库存异常、查物料流水，也可以生成各类单据草稿，还支持周转分析、库存金额分析、供应商分析、消耗趋势、补货建议、按分类汇总等数据洞察。示例：\n'
            '- 查库存/查单号：查 A001 库存；查 IN26050001\n'
            '- 今日概况：今天概况\n'
            '- 查流水：查 A001 流水\n'
            '- 生成单据：生成领料单 A001 20；从A仓转到B仓 M001 100；盘点 M001 M002；报废 M001 5\n'
            '- 数据分析（支持多仓库/分类/日期范围）：\n'
            '  · 周转分析（默认90天，可指定：近30天周转）\n'
            '  · 库存金额（可按分类：原料分类库存金额）\n'
            '  · 供应商排行（可指定仓库和天数：A仓近30天供应商）\n'
            '  · 查 M001 消耗趋势（可指定天数和仓库：M001近60天消耗 材料仓）\n'
            '  · 补货建议\n'
            '  · 按分类汇总（各分类库存金额）'
        )

    return None


def _ai_should_try_general_chat(message):
    compact = (message or '').strip().replace(' ', '').lower()
    if not compact:
        return False
    if _ai_is_stage4_deep_analysis_question(message):
        return False
    business_words = (
        '库存', '物料', '单号', '单据', '入库', '出库', '领料', '采购', '盘点', '调拨', '待办', '待处理',
        '异常', '预警', '流水', '生成', '创建', '新增', '审核', '客户', '供应商', '仓库', '库位',
        '扫码', '手机', 'app', '条码',
        '缺料', '缺货', '没货', '没有了', '没了', '断货', '用完了', '没有库存',
    )
    if any(word in compact for word in business_words):
        return False
    return True


def _ai_should_try_business_chat(message):
    compact = (message or '').strip().replace(' ', '').lower()
    if not compact or not _ai_llm_configured():
        return False

    action_words = (
        '生成', '创建', '新增', '开一张', '做一张', '提交', '审核', '删除', '作废', '完成',
        '查库存', '查询库存', '查物料', '查单号', '查单据', '找单据', '待办', '待处理',
        '今天', '今日', '报表', '清单', '排行', '金额', '价值', '导出',
    )
    if any(word in compact for word in action_words):
        return False

    advice_words = (
        '怎么办', '怎么处理', '如何处理', '怎么解决', '如何解决', '怎么查', '如何查',
        '为什么', '原因', '分析', '建议', '流程', '规范', '应该', '能不能', '可不可以',
        '风险', '注意事项', '最佳', '优化',
    )
    business_words = (
        '库存', '物料', '入库', '出库', '领料', '采购', '盘点', '调拨', '调整',
        '仓库', '库位', '供应商', '客户', '扫码', '条码', '单据', '审核',
    )
    return any(word in compact for word in advice_words) and any(word in compact for word in business_words)


def _ai_strip_general_chat_marker(message):
    text = (message or '').strip()
    for marker in ('问大模型', '问GPT', '问gpt', 'GPT回答', 'gpt回答', 'GPT聊', 'gpt聊', 'AI聊天', 'ai聊天', '大模型回答', '通用聊天'):
        if text.startswith(marker):
            return text[len(marker):].lstrip('：: ，,')
    return text


def _ai_handle_warehouse_assistant_request(payload):
    payload = payload or {}
    message = (payload.get('message') or '').strip()
    context = {
        'page_url': (payload.get('page_url') or '').strip(),
        'page_title': (payload.get('page_title') or '').strip(),
    }
    images, image_error = _ai_normalize_image_attachments(payload.get('attachments'))
    if image_error:
        return jsonify({'status': 'error', 'msg': image_error}), 400
    if not message and not images:
        return jsonify({'status': 'error', 'msg': '请输入要查询或处理的内容'}), 400

    if not _ai_global_enabled():
        return _ai_json_response('AI功能当前已由管理员关闭。WMS主业务不受影响，请使用对应业务页面手工查询或处理。')
    high_risk_response = _ai_high_risk_denied_response(message)
    if high_risk_response:
        return high_risk_response

    user_id = current_user.id if current_user.is_authenticated else 0
    # 拼接最近一轮用户消息到当前 message 前面，让意图识别和草稿解析能感知多轮上下文。
    # 仅取最近 1 条 user 历史，避免污染；不拼接 assistant 回复（含摘要文本会干扰正则）。
    augmented_message = message

    try:
        if images:
            if not _ai_feature_enabled('ai_feature_vision_enabled', True):
                return _ai_json_response(
                    'AI视觉识别当前处于灰度关闭状态。请改用文字描述、Excel粘贴，或进入对应业务页面手工录入。',
                    actions=[{'label': 'AI助手参数', 'url': url_for('system_settings_page')}],
                )
            extracted_doc, doc_vision_error = _ai_call_llm_document_vision_extract(message, images, context)
            if extracted_doc:
                structured_response = _ai_create_draft_from_extracted(extracted_doc, source='vision', context=context)
                if structured_response:
                    body = structured_response.get_json(silent=True) or {}
                    reply_text = str(body.get('reply') or '')
                    if extracted_doc.get('supplier') or extracted_doc.get('order_no'):
                        header_bits = []
                        if extracted_doc.get('supplier'):
                            header_bits.append(f'供应商：{extracted_doc.get("supplier")}')
                        if extracted_doc.get('order_no'):
                            header_bits.append(f'单号：{extracted_doc.get("order_no")}')
                        reply_text = '图片识别到' + '，'.join(header_bits) + '。\n' + reply_text
                    _ai_append_history(user_id, 'user', message or '(上传图片)')
                    _ai_append_history(user_id, 'assistant', reply_text)
                    return _ai_json_response(reply_text, body.get('cards') or [], body.get('actions') or [])

            vision_reply, extracted, vision_error = _ai_call_llm_vision(message, images, context)
            if vision_reply:
                # 尝试根据提取的结构化数据自动建单
                structured_response = _ai_create_draft_from_extracted(extracted, source='vision', context=context)
                if structured_response:
                    body = structured_response.get_json(silent=True) or {}
                    full_reply = vision_reply + '\n\n' + str(body.get('reply') or '')
                    _ai_append_history(user_id, 'user', message or '(上传图片)')
                    _ai_append_history(user_id, 'assistant', full_reply)
                    return _ai_json_response(full_reply, body.get('cards') or [], body.get('actions') or [])
                draft_result = _ai_vision_try_create_draft(extracted, message)
                if draft_result:
                    draft_reply, draft_cards, draft_actions = draft_result
                    full_reply = vision_reply + '\n\n' + draft_reply
                    _ai_append_history(user_id, 'user', message or '(上传图片)')
                    _ai_append_history(user_id, 'assistant', full_reply)
                    return _ai_json_response(full_reply, draft_cards, draft_actions)
                _ai_append_history(user_id, 'user', message or '(上传图片)')
                _ai_append_history(user_id, 'assistant', vision_reply)
                return _ai_json_response(vision_reply)
            if not _ai_llm_vision_enabled():
                return _ai_json_response(
                    '图片已收到，但系统设置里没有启用图片识别。请到“系统管理 - 系统设置 - AI助手参数”打开“启用图片识别”，并填写支持视觉/图片理解的模型后再测试。'
                )
            detail = f'供应商返回：{vision_error}' if vision_error else '没有返回具体错误。'
            return _ai_json_response(
                '图片已收到，但当前大模型没有成功返回图片分析结果。'
                + detail
                + ' 请确认这张图片格式有效、图片内容清晰，并到“系统管理 - 系统设置 - AI助手参数”点击“测试图片识别”确认通道可用。'
            )

        text_doc_response = _ai_try_text_document_response(augmented_message, context)
        if text_doc_response:
            body = text_doc_response.get_json(silent=True) or {}
            reply_text = str(body.get('reply') or '')
            if reply_text:
                _ai_append_history(user_id, 'user', message)
                _ai_append_history(user_id, 'assistant', reply_text)
            return text_doc_response

        intent_payload = _ai_call_llm_intent(augmented_message)
        if (
            intent_payload
            and intent_payload.get('intent') == 'general_chat'
            and not _ai_is_inventory_discrepancy_question(augmented_message)
        ):
            chat_reply = _ai_call_llm_chat(_ai_strip_general_chat_marker(augmented_message))
            if chat_reply:
                _ai_append_history(user_id, 'user', message)
                _ai_append_history(user_id, 'assistant', chat_reply)
                return _ai_json_response(chat_reply)
        elif intent_payload:
            llm_response = _ai_execute_intent(augmented_message, intent_payload, context)
            if llm_response:
                body = llm_response.get_json(silent=True) or {}
                reply_text = str(body.get('reply') or '')
                if reply_text:
                    _ai_append_history(user_id, 'user', message)
                    _ai_append_history(user_id, 'assistant', reply_text)
                return llm_response

        check_response = _ai_draft_check_response(augmented_message, context)
        if check_response:
            return check_response

        vision_status_response = _ai_vision_status_response(augmented_message, context)
        if vision_status_response:
            return vision_status_response

        delivery_response = _ai_delivery_note_inbound_response(augmented_message, context)
        if delivery_response:
            return delivery_response

        excel_table_response = _ai_excel_table_document_response(augmented_message, context)
        if excel_table_response:
            return excel_table_response

        purchase_draft_response = _ai_create_purchase_request_draft_response(augmented_message, context)
        if purchase_draft_response:
            return purchase_draft_response

        product_suggestion_response = _ai_product_suggestion_response(augmented_message, context)
        if product_suggestion_response:
            return product_suggestion_response

        benchmark_roadmap_response = _ai_benchmark_roadmap_response(augmented_message, context)
        if benchmark_roadmap_response:
            return benchmark_roadmap_response

        warehouse_insights_response = _ai_dispatch_registered_tool('warehouse_insights', augmented_message, context)
        if warehouse_insights_response:
            return warehouse_insights_response

        purchase_insights_response = _ai_dispatch_registered_tool('purchase_insights', augmented_message, context)
        if purchase_insights_response:
            return purchase_insights_response

        master_data_insights_response = _ai_dispatch_registered_tool('master_data_insights', augmented_message, context)
        if master_data_insights_response:
            return master_data_insights_response

        admin_insights_response = _ai_dispatch_registered_tool('admin_insights', augmented_message, context)
        if admin_insights_response:
            return admin_insights_response

        alias_response = _ai_alias_management_response(augmented_message)
        if alias_response:
            return alias_response

        if _ai_should_try_business_chat(augmented_message):
            chat_reply = _ai_call_llm_chat(_ai_strip_general_chat_marker(augmented_message))
            if chat_reply:
                _ai_append_history(user_id, 'user', message)
                _ai_append_history(user_id, 'assistant', chat_reply)
                return _ai_json_response(chat_reply)

        local_response, _skill_name = _ai_try_local_skills(augmented_message, context)
        if local_response:
            return local_response

        if _ai_should_try_llm_document(augmented_message):
            llm_doc_response = _ai_try_llm_document_response(augmented_message, context)
            if llm_doc_response:
                return llm_doc_response

        if _ai_should_try_general_chat(augmented_message):
            basic_response = _ai_basic_conversation_response(message)
            if basic_response:
                return basic_response
            chat_reply = _ai_call_llm_chat(_ai_strip_general_chat_marker(augmented_message))
            if chat_reply:
                _ai_append_history(user_id, 'user', message)
                _ai_append_history(user_id, 'assistant', chat_reply)
                return _ai_json_response(chat_reply)
            return _ai_json_response('当前大模型聊天没有连通。请到“系统管理 - 系统设置 - AI助手参数”点击“测试连接”，确认接口地址、模型名称和 API Key 可用。')

        rule_response = _ai_rule_based_response(augmented_message)
        if rule_response:
            return rule_response

        return _ai_rule_based_response(message)
    except Exception as exc:
        db.session.rollback()
        app.logger.exception('AI warehouse assistant failed: %s', exc)
        return jsonify({'status': 'error', 'msg': 'AI助手处理失败，请稍后重试'}), 500


# ==================== AI 流式响应 + 多轮对话 ====================

def _ai_get_history(user_id):
    """Return the current user AI chat history."""
    return get_history(user_id)


def _ai_append_history(user_id, role, content):
    """Append a message to the current user AI chat history."""
    append_history(user_id, role, content)


def _ai_handle_chat_stream_request(payload):
    """流式返回 AI 回答（SSE），支持多轮对话上下文。
    统一通道：闲聊问题走 LLM 流式；业务关键词命中时不再 redirect 回退，
    而是在 SSE 内直接执行业务意图，把 reply 文本按字符拆分流式输出，
    最后追加 cards/actions 事件，避免"流式光标闪一下→清空→重新 loading"的割裂体验。
    """
    payload = payload or {}
    message = (payload.get('message') or '').strip()
    history_payload = payload.get('history') or []
    page_url = (payload.get('page_url') or '').strip()
    page_title = (payload.get('page_title') or '').strip()
    user_id = current_user.id if current_user.is_authenticated else 0

    if not message:
        return jsonify({'status': 'error', 'msg': '请输入要查询或处理的内容'}), 400

    if not _ai_global_enabled():
        return jsonify({'status': 'error', 'msg': 'AI功能当前已由管理员关闭。WMS主业务不受影响。'}), 503
    high_risk_response = _ai_high_risk_denied_response(message)
    if high_risk_response:
        def denied_generate():
            body = high_risk_response.get_json(silent=True) or {}
            yield from stream_response_payload(body.get('reply'), body.get('cards'), body.get('actions'))

        return Response(
            stream_with_context(denied_generate()),
            content_type='text/event-stream; charset=utf-8',
            headers={'Cache-Control': 'no-cache', 'X-Accel-Buffering': 'no'},
        )

    context = {'page_url': page_url, 'page_title': page_title}
    intent_payload = _ai_call_llm_intent(message)
    force_general_chat = bool(
        intent_payload
        and intent_payload.get('intent') == 'general_chat'
        and not _ai_is_inventory_discrepancy_question(message)
    )
    priority_response = None
    if intent_payload and not force_general_chat:
        priority_response = _ai_execute_intent(message, intent_payload, context)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_basic_conversation_response(message)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_draft_check_response(message, context)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_vision_status_response(message, context)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_delivery_note_inbound_response(message, context)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_excel_table_document_response(message, context)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_create_purchase_request_draft_response(message, context)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_product_suggestion_response(message, context)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_benchmark_roadmap_response(message, context)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_dispatch_registered_tool('warehouse_insights', message, context)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_dispatch_registered_tool('purchase_insights', message, context)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_dispatch_registered_tool('master_data_insights', message, context)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_dispatch_registered_tool('admin_insights', message, context)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_alias_management_response(message)
    if priority_response is None and not force_general_chat:
        priority_response = _ai_try_text_document_response(message, context)
    if priority_response is None and not force_general_chat and _ai_should_try_llm_document(message):
        priority_response = _ai_try_llm_document_response(message, context)
    if priority_response is not None:
        def priority_generate():
            body = priority_response.get_json(silent=True) or {}
            reply_text = str(body.get('reply') or '')
            yield from stream_response_payload(reply_text, body.get('cards'), body.get('actions'))
            if reply_text:
                _ai_append_history(user_id, 'user', message)
                _ai_append_history(user_id, 'assistant', reply_text)

        return Response(stream_with_context(priority_generate()), content_type='text/event-stream; charset=utf-8',
                        headers={'Cache-Control': 'no-cache', 'X-Accel-Buffering': 'no'})

    if (
        not force_general_chat
        and not _ai_should_try_general_chat(message)
        and not _ai_should_try_business_chat(message)
    ):
        context = {'page_url': page_url, 'page_title': page_title}
        augmented_message = message

        def business_generate():
            try:
                local_response = _ai_draft_check_response(augmented_message, context)
                if local_response is None:
                    local_response = _ai_vision_status_response(augmented_message, context)
                if local_response is None:
                    local_response = _ai_delivery_note_inbound_response(augmented_message, context)
                if local_response is None:
                    local_response = _ai_excel_table_document_response(augmented_message, context)
                if local_response is None:
                    local_response = _ai_create_purchase_request_draft_response(augmented_message, context)
                if local_response is None:
                    local_response = _ai_product_suggestion_response(augmented_message, context)
                if local_response is None:
                    local_response = _ai_benchmark_roadmap_response(augmented_message, context)
                if local_response is None:
                    local_response = _ai_dispatch_registered_tool('warehouse_insights', message, context)
                if local_response is None:
                    local_response = _ai_dispatch_registered_tool('purchase_insights', message, context)
                if local_response is None:
                    local_response = _ai_dispatch_registered_tool('master_data_insights', message, context)
                if local_response is None:
                    local_response = _ai_dispatch_registered_tool('admin_insights', message, context)
                if local_response is None:
                    local_response = _ai_alias_management_response(augmented_message)
                if local_response is None:
                    local_response = _ai_try_text_document_response(augmented_message, context)
                if local_response is None:
                    local_response, _skill_name = _ai_try_local_skills(augmented_message, context)
                if local_response is None:
                    local_response = _ai_rule_based_response(augmented_message)
                if local_response is None and _ai_should_try_llm_document(augmented_message):
                    local_response = _ai_try_llm_document_response(augmented_message, context)
                if local_response is None:
                    llm_response = _ai_rule_based_response(message)
                else:
                    llm_response = local_response

                if llm_response is None:
                    yield sse_event('error', '未能处理该问题，请换种说法或到系统设置确认 AI 已配置')
                    return

                # llm_response 是 Flask Response 对象，需要提取 json 数据
                body = llm_response.get_json(silent=True) or {}
                reply_text = str(body.get('reply') or '')
                cards = body.get('cards') or []
                actions = body.get('actions') or []

                yield from stream_response_payload(reply_text, cards, actions)

                # 写入对话历史，业务回复也能被多轮引用
                if reply_text:
                    _ai_append_history(user_id, 'user', message)
                    _ai_append_history(user_id, 'assistant', reply_text)

            except Exception as exc:
                db.session.rollback()
                app.logger.exception('AI stream business intent failed: %s', exc)
                yield sse_event('error', 'AI助手处理失败，请稍后重试')

        return Response(stream_with_context(business_generate()), content_type='text/event-stream; charset=utf-8',
                        headers={'Cache-Control': 'no-cache', 'X-Accel-Buffering': 'no'})

    # 闲聊和非确定性业务咨询走 LLM 流式；确定性的查询/建单/查待办仍优先走本地工具。
    if not _ai_llm_configured():
        return jsonify({'status': 'error', 'msg': 'AI大模型未配置，请到系统设置配置接口地址、模型和API Key'}), 503

    # 构建多轮上下文：系统提示 + 历史 + 当前问题
    system_prompt = (
        '你是仓库管理系统里的AI业务顾问，不是通用闲聊机器人。'
        '系统模块包括：物料档案、仓库/库位、供应商/客户、采购申请、采购订单、采购入库、领料/出库、盘点、调拨、调整、BOM、委外、库存查询、库存预警、报表、手机扫码。'
        '回答仓库相关问题时，先判断具体业务场景，再给可执行步骤；尽量引用系统里的页面入口名称，例如库存查询、物料档案、采购申请、采购订单、入库列表、领料列表、盘点列表、库存调整、待处理中心。'
        '涉及真实库存、单据、金额、客户、供应商、审核状态等系统数据时，不要编造；应建议用户到系统查询，或说明需要通过后台工具查询真实数据。'
        '不要泛泛回答“先维护基础资料、再做采购申请”，除非用户明确问基础资料或系统总体使用流程。'
        '如果用户问异常处理，要先给排查顺序，再给按原因处理的分支；如果用户问操作流程，要指出保存/完成/审核哪个步骤才影响库存。'
        '回答要简洁直接，像仓库主管给操作建议，优先控制在 200 字以内。支持 Markdown 格式输出，可以使用列表、表格、加粗等。'
    )
    messages = [{'role': 'system', 'content': system_prompt}]
    # 合并前端传来的历史（优先）+ 后端内存历史（兜底）
    seen_history = history_payload if isinstance(history_payload, list) else _ai_get_history(user_id)
    for item in seen_history[-AI_CHAT_HISTORY_MAX_TURNS * 2:]:
        if isinstance(item, dict) and item.get('role') in ('user', 'assistant') and item.get('content'):
            messages.append({'role': item['role'], 'content': str(item['content'])[:1000]})
    chat_message = _ai_strip_general_chat_marker(message)
    messages.append({'role': 'user', 'content': chat_message[:1000]})

    payload_body = {
        'model': _ai_llm_model(),
        'messages': messages,
        'temperature': 0.4,
        'max_tokens': min(max(_ai_llm_max_tokens(), 160), 420),
        'stream': True,
    }
    headers = _ai_llm_headers()

    def generate():
        full_reply = []
        try:
            with requests.post(
                _ai_llm_endpoint(),
                headers=headers,
                json=payload_body,
                stream=True,
                timeout=min(max(_ai_llm_timeout_seconds(), 8), 15),
            ) as resp:
                if not resp.ok:
                    err_msg = f'大模型请求失败: HTTP {resp.status_code}'
                    yield sse_event('error', err_msg)
                    return
                resp.encoding = 'utf-8'
                for line in resp.iter_lines(decode_unicode=True):
                    if not line:
                        continue
                    if line.startswith('data: '):
                        chunk = line[6:]
                        if chunk.strip() == '[DONE]':
                            break
                        try:
                            data = json.loads(chunk)
                            delta = ((data.get('choices') or [{}])[0].get('delta') or {}).get('content') or ''
                            if delta:
                                full_reply.append(delta)
                                yield sse_event('token', delta)
                        except (ValueError, IndexError):
                            continue
        except requests.exceptions.Timeout:
            yield sse_event('error', '大模型响应超时，请稍后重试或调高超时设置')
            return
        except Exception as exc:
            app.logger.warning('AI stream chat failed: %s', exc)
            yield sse_event('error', f'流式响应异常: {exc}')
            return

        reply_text = ''.join(full_reply).strip()
        if reply_text:
            _ai_append_history(user_id, 'user', chat_message)
            _ai_append_history(user_id, 'assistant', reply_text)
        yield sse_event('done', reply_text)

    return Response(stream_with_context(generate()), content_type='text/event-stream; charset=utf-8',
                    headers={'Cache-Control': 'no-cache', 'X-Accel-Buffering': 'no'})


def _ai_handle_chat_clear_request():
    """清空当前用户的对话历史"""
    user_id = current_user.id if current_user.is_authenticated else 0
    clear_history(user_id)
    return jsonify({'status': 'success', 'msg': '已清空对话历史'})


def _document_nav_related(obj, relation_name, field_name='name'):
    related = getattr(obj, relation_name, None)
    return getattr(related, field_name, '') if related else ''


