def _pending_action_label(config, item):
    action = config.get('action') or ''
    return action(item) if callable(action) else action


def _pending_status_label(config, item):
    status = str(getattr(item, 'status', '') or '')
    if status == 'pending':
        if config.get('key') in {'in_order', 'out_order'}:
            return '未审核/待完成'
        if config.get('key') == 'purchase_request':
            return '待审批'
        return '草稿/待处理'
    if status == 'approved':
        return '已审批'
    if status == 'processing':
        return '处理中'
    return _share_pdf_status_label(status)


def _pending_document_search_text(config, item):
    parts = [
        config.get('label'),
        _document_nav_value(item, config.get('number')),
        _format_document_nav_date(_document_nav_value(item, config.get('date'))),
        getattr(item, 'status', ''),
        _pending_action_label(config, item),
        config.get('title')(item) if callable(config.get('title')) else '',
    ]
    parts.extend(_document_status_terms(getattr(item, 'status', '')))
    for getter in config.get('search', []):
        parts.append(_document_nav_value(item, getter))
    parts.extend(_document_nav_material_terms(item))
    return ' '.join(str(part or '') for part in parts).lower()


def _build_pending_document_rows(module_filter='', status_filter='', search=''):
    rows = []
    search_lower = search.lower()
    for config in PENDING_DOCUMENT_MODULES:
        if module_filter and config['key'] != module_filter:
            continue
        model = config['model']
        query = model.query.filter(model.status.in_(config['status']))
        if status_filter:
            query = query.filter(model.status == status_filter)
        query = query.order_by(model.created_at.desc(), model.id.desc())
        for item in query.all():
            if search_lower and search_lower not in _pending_document_search_text(config, item):
                continue
            item_date = _document_nav_value(item, config.get('date'))
            rows.append({
                'id': item.id,
                'module_key': config['key'],
                'module_label': config['label'],
                'icon': config.get('icon') or 'bi-file-earmark-text',
                'number': _document_nav_value(item, config.get('number')),
                'date': item_date,
                'date_text': _format_document_nav_date(item_date),
                'title': config.get('title')(item) if callable(config.get('title')) else '',
                'status': item.status,
                'status_label': _pending_status_label(config, item),
                'action_label': _pending_action_label(config, item),
                'created_at': item.created_at,
                'detail_url': url_for(config['detail_endpoint'], id=item.id),
            })
    rows.sort(key=lambda row: (row['created_at'] or datetime.min, row['id']), reverse=True)
    return rows


def _format_document_nav_date(value):
    if isinstance(value, datetime):
        return value.strftime('%Y-%m-%d')
    if isinstance(value, date):
        return value.strftime('%Y-%m-%d')
    return str(value or '')


def _document_status_terms(status):
    status = str(status or '').strip()
    status_map = {
        'pending': ['pending', '未审核', '待审核', '待完成', '待处理', '草稿', '待审批'],
        'completed': ['completed', '已完成', '已审核', '已处理'],
        'approved': ['approved', '已审批', '已审核', '已批准'],
        'rejected': ['rejected', '已驳回', '驳回'],
        'processing': ['processing', '处理中', '加工中'],
        'cancelled': ['cancelled', '已取消', '取消'],
    }
    terms = status_map.get(status, [status])
    return [term for term in terms if term]


def _status_from_search_keyword(keyword, allowed_statuses):
    keyword = str(keyword or '').strip().lower()
    if not keyword:
        return None
    for status in allowed_statuses:
        terms = {str(term).strip().lower() for term in _document_status_terms(status)}
        if any(keyword == term or (len(term) > 1 and term in keyword) or (len(keyword) > 1 and keyword in term) for term in terms):
            return status
    return None


def _get_order_list_filters(allowed_statuses, default_sort='created_at'):
    status_filter = (request.args.get('status') or '').strip()
    search = (request.args.get('search') or '').strip()
    date_start = parse_date_value(request.args.get('date_start'))
    date_end = parse_date_value(request.args.get('date_end'))
    sort_by = request.args.get('sort', default_sort)
    sort_order = request.args.get('order', 'desc')
    if status_filter not in allowed_statuses:
        status_filter = ''
    if sort_order not in ('asc', 'desc'):
        sort_order = 'desc'
    return status_filter, search, date_start, date_end, sort_by, sort_order


def _apply_status_date_filters(query, model, status_filter, date_start, date_end):
    if status_filter:
        query = query.filter(model.status == status_filter)
    if date_start:
        query = query.filter(model.date >= date_start)
    if date_end:
        query = query.filter(model.date <= date_end)
    return query


def _apply_in_order_search(query, search):
    if not search:
        return query
    search_like = f'%{search}%'
    status_from_search = _status_from_search_keyword(search, ('pending', 'completed'))
    conditions = [
        InOrder.order_no.like(search_like),
        InOrder.business_type.like(search_like),
        InOrder.purpose.like(search_like),
        Supplier.name.like(search_like),
        Material.code.like(search_like),
        Material.name.like(search_like),
        Material.spec.like(search_like),
        PurchaseOrder.order_no.like(search_like),
    ]
    if status_from_search:
        conditions.append(InOrder.status == status_from_search)
    return (
        query.outerjoin(Material, InOrderItem.material_id == Material.id)
        .outerjoin(Supplier, InOrder.supplier_id == Supplier.id)
        .outerjoin(PurchaseOrderItem, InOrderItem.source_purchase_order_item_id == PurchaseOrderItem.id)
        .outerjoin(PurchaseOrder, db.or_(
            InOrder.source_purchase_order_id == PurchaseOrder.id,
            PurchaseOrderItem.purchase_order_id == PurchaseOrder.id,
        ))
        .filter(db.or_(*conditions))
    )


