def _status_from_master_keyword(keyword):
    keyword = str(keyword or '').strip().lower()
    active_terms = {'active', '启用', '正常', '激活'}
    inactive_terms = {'inactive', '停用', '禁用', '停用中'}
    if keyword in active_terms:
        return 'active'
    if keyword in inactive_terms:
        return 'inactive'
    return None


def _share_pdf_font_name():
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.cidfonts import UnicodeCIDFont

    font_name = 'STSong-Light'
    if font_name not in pdfmetrics.getRegisteredFontNames():
        pdfmetrics.registerFont(UnicodeCIDFont(font_name))
    return font_name


def _share_pdf_text(value, default='-'):
    if value is None:
        return default
    if isinstance(value, datetime):
        return value.strftime('%Y-%m-%d %H:%M')
    if isinstance(value, date):
        return value.strftime('%Y-%m-%d')
    text = str(value).strip()
    return text if text else default


def _share_pdf_money(value):
    try:
        return f'¥{float(value or 0):.2f}'
    except (TypeError, ValueError):
        return '¥0.00'


def _share_pdf_qty(value):
    try:
        return f'{float(value or 0):.2f}'
    except (TypeError, ValueError):
        return '0.00'


