def _get_master_list_filters(default_sort='created_at'):
    search = (request.args.get('search') or '').strip()
    status_filter = (request.args.get('status') or '').strip()
    sort_by = request.args.get('sort', default_sort)
    sort_order = request.args.get('order', 'desc')
    if sort_order not in ('asc', 'desc'):
        sort_order = 'desc'
    return search, status_filter, sort_by, sort_order


def _apply_simple_search(query, model, search, fields):
    if not search:
        return query
    search_like = f'%{search}%'
    return query.filter(db.or_(*(getattr(model, field).like(search_like) for field in fields)))


def _apply_master_order(query, model, sort_by, sort_order, allowed_sorts, default_sort='created_at'):
    if sort_by not in allowed_sorts:
        sort_by = default_sort
    sort_col = getattr(model, sort_by, getattr(model, default_sort))
    return query.order_by(sort_col.asc() if sort_order == 'asc' else sort_col.desc()), sort_by


def _warehouse_query_from_args():
    search, status_filter, sort_by, sort_order = _get_master_list_filters()
    query = Warehouse.query
    if search:
        status_from_search = _status_from_master_keyword(search)
        conditions = [
            Warehouse.code.like(f'%{search}%'),
            Warehouse.name.like(f'%{search}%'),
            Warehouse.type.like(f'%{search}%'),
            Warehouse.location.like(f'%{search}%'),
            Warehouse.remark.like(f'%{search}%'),
        ]
        if status_from_search:
            conditions.append(Warehouse.status == status_from_search)
        query = query.filter(db.or_(*conditions))
    if status_filter in ('active', 'inactive'):
        query = query.filter(Warehouse.status == status_filter)
    query, sort_by = _apply_master_order(query, Warehouse, sort_by, sort_order, {'code', 'name', 'type', 'location', 'status', 'created_at'})
    return query, {'search': search, 'status': status_filter}, sort_by, sort_order


def _department_query_from_args():
    search, status_filter, sort_by, sort_order = _get_master_list_filters()
    query = Department.query
    if search:
        status_from_search = _status_from_master_keyword(search)
        conditions = [
            Department.code.like(f'%{search}%'),
            Department.name.like(f'%{search}%'),
            Department.remark.like(f'%{search}%'),
        ]
        if status_from_search:
            conditions.append(Department.status == status_from_search)
        query = query.filter(db.or_(*conditions))
    if status_filter in ('active', 'inactive'):
        query = query.filter(Department.status == status_filter)
    query, sort_by = _apply_master_order(query, Department, sort_by, sort_order, {'code', 'name', 'status', 'created_at'})
    return query, {'search': search, 'status': status_filter}, sort_by, sort_order


def _bom_query_from_args():
    search, status_filter, sort_by, sort_order = _get_master_list_filters()
    allowed_sorts = {'bom_no', 'product_code', 'product_name', 'version', 'level', 'status', 'total_cost', 'created_at'}
    if sort_by not in allowed_sorts:
        sort_by = 'created_at'
    query = BOM.query.options(selectinload(BOM.items).joinedload(BOMItem.material))
    if search:
        search_like = f'%{search}%'
        status_from_search = _status_from_master_keyword(search)
        conditions = [
            BOM.bom_no.like(search_like),
            BOM.product_code.like(search_like),
            BOM.product_name.like(search_like),
            BOM.version.like(search_like),
            BOM.remark.like(search_like),
            Material.code.like(search_like),
            Material.name.like(search_like),
            Material.spec.like(search_like),
        ]
        if status_from_search:
            conditions.append(BOM.status == status_from_search)
        query = query.outerjoin(BOMItem, BOMItem.bom_id == BOM.id).outerjoin(Material, BOMItem.material_id == Material.id).filter(db.or_(*conditions)).distinct()
    if status_filter in ('active', 'inactive'):
        query = query.filter(BOM.status == status_filter)
    sort_col = getattr(BOM, sort_by, BOM.created_at)
    query = query.order_by(sort_col.asc() if sort_order == 'asc' else sort_col.desc())
    return query, {'search': search, 'status': status_filter}, sort_by, sort_order


def _print_template_query_from_args(model):
    search, status_filter, sort_by, sort_order = _get_master_list_filters('created_at')
    type_filter = (request.args.get('type') or '').strip()
    if status_filter not in ('default', 'normal'):
        status_filter = ''
    if type_filter not in ('excel', 'html'):
        type_filter = ''
    allowed_sorts = {'name', 'template_type', 'is_default', 'created_at', 'updated_at'}
    query = model.query
    if search:
        search_like = f'%{search}%'
        search_lower = search.lower()
        conditions = [
            model.name.like(search_like),
            model.template_type.like(search_like),
        ]
        if search_lower in {'默认', 'default'}:
            conditions.append(model.is_default.is_(True))
        if search_lower in {'普通', 'normal', '非默认'}:
            conditions.append(model.is_default.is_(False))
        if search_lower in {'excel', '表格', '电子表格'}:
            conditions.append(model.template_type == 'excel')
        if search_lower in {'html', '网页'}:
            conditions.append(model.template_type == 'html')
        query = query.filter(db.or_(*conditions))
    if status_filter == 'default':
        query = query.filter(model.is_default.is_(True))
    elif status_filter == 'normal':
        query = query.filter(model.is_default.is_(False))
    if type_filter:
        query = query.filter(model.template_type == type_filter)
    query, sort_by = _apply_master_order(query, model, sort_by, sort_order, allowed_sorts, 'created_at')
    if sort_by != 'is_default':
        query = query.order_by(model.is_default.desc())
    return query, {'search': search, 'status': status_filter, 'type': type_filter}, sort_by, sort_order


def _serialize_document_nav_item(item, config):
    item_id = item.id
    number = str(_document_nav_value(item, config['number']) or '')
    item_date = _format_document_nav_date(_document_nav_value(item, config.get('date')))
    title = str(_document_nav_value(item, config.get('title')) or '')
    status = str(getattr(item, 'status', '') or '')
    detail_url = config.get('detail_url', '').format(id=item_id)
    return {
        'id': item_id,
        'no': number,
        'date': item_date,
        'title': title,
        'status': status,
        'url': detail_url,
    }


def _document_nav_matches(item, row, config, keyword):
    if not keyword:
        return True
    parts = [row.get('no'), row.get('date'), row.get('title'), row.get('status'), str(row.get('id'))]
    parts.extend(_document_status_terms(row.get('status')))
    for getter in config.get('search', []):
        parts.append(_document_nav_value(item, getter))
    parts.extend(_document_nav_material_terms(item))
    return keyword in ' '.join(str(part or '') for part in parts).lower()


@app.route('/api/document_navigation/<module_key>')
@login_required
def api_document_navigation(module_key):
    config = DOCUMENT_NAVIGATION_MODULES.get(module_key)
    if not config:
        return jsonify({'status': 'error', 'msg': '暂不支持该单据导航'}), 404

    current_id = request.args.get('current_id', type=int)
    keyword = (request.args.get('q') or '').strip().lower()
    items = config['model'].query.order_by(config['model'].id.asc()).all()
    rows = []
    for item in items:
        row = _serialize_document_nav_item(item, config)
        if _document_nav_matches(item, row, config, keyword):
            rows.append(row)

    ids = [row['id'] for row in rows]
    current_index = ids.index(current_id) if current_id in ids else -1
    return jsonify({
        'status': 'success',
        'current_id': current_id if current_index >= 0 else None,
        'first_id': ids[0] if ids else None,
        'prev_id': ids[current_index - 1] if current_index > 0 else None,
        'next_id': ids[current_index + 1] if 0 <= current_index < len(ids) - 1 else None,
        'last_id': ids[-1] if ids else None,
        'list': rows[:80],
        'total': len(rows),
    })

