@app.route('/in_order/item/update', methods=['POST'])
@require_role('warehouse')
@login_required
def update_in_order_item():
    """Update an inbound order item."""
    item_id = request.form.get('id', type=int)
    if not item_id:
        return jsonify({'status': 'error', 'msg': '缺少明细ID'})
    item = InOrderItem.query.get_or_404(item_id)
    if item.in_order.status != 'pending':
        return jsonify({'status': 'error', 'msg': '只有待处理的入库单可以修改明细'})
    old_quantity = item.quantity or 0
    new_quantity = round_to_2_decimals(request.form.get('quantity', item.quantity))
    if is_purchase_in_order(item.in_order) and purchase_in_order_requires_order() and not item.source_purchase_order_item:
        return jsonify({'status': 'error', 'msg': '采购入库必须关联采购订单，请从采购订单下推或选单生成入库单'})
    if item.source_purchase_order_item and should_block_purchase_over_receive():
        source_item = item.source_purchase_order_item
        available_qty = round_to_2_decimals((source_item.quantity or 0) - ((source_item.received_quantity or 0) - old_quantity))
        if new_quantity - available_qty > STOCK_COMPARE_EPSILON:
            material_code = item.material.code if item.material else item.material_id
            return jsonify({'status': 'error', 'msg': f'物料 {material_code} 入库数量不能大于采购单未入库数量'})
        source_item.received_quantity = round_to_2_decimals((source_item.received_quantity or 0) - old_quantity + new_quantity)
        update_purchase_order_status(source_item.purchase_order)
    item.quantity = new_quantity
    item.price = round_to_2_decimals(request.form.get('price', item.price))
    item.amount = round_to_2_decimals(item.quantity * item.price)
    if 'remark' in request.form:
        item.remark = (request.form.get('remark') or '').strip() or None
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f"数据库操作失败: {e}")
        return jsonify({"status": "error", "msg": "操作失败"}), 500
    return jsonify({'status': 'success', 'msg': '保存成功'})

@app.route('/in_order/<int:id>/copy_to_out', methods=['POST'])
@require_role('warehouse')
@login_required
def copy_in_order_to_out(id):
    """Copy an inbound order into a draft outbound order."""
    in_order = InOrder.query.get_or_404(id)
    order_no = generate_order_no('OU')
    out_order = OutOrder(
        order_no=order_no,
        date=date.today(),
        customer=in_order.supplier.name if in_order.supplier else '',
        purpose=in_order.purpose or '',
        business_type='领料单',
        warehouse=in_order.warehouse or '',
        status='pending'
    )
    db.session.add(out_order)
    db.session.flush()
    for item in in_order.items:
        out_item = OutOrderItem(
            out_order_id=out_order.id,
            material_id=item.material_id,
            quantity=item.quantity,
            price=item.price,
            amount=item.amount,
            remark=item.remark
        )
        db.session.add(out_item)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f"数据库操作失败: {e}")
        return jsonify({"status": "error", "msg": "操作失败"}), 500
    return jsonify({'status': 'success', 'msg': '操作完成', 'out_order_id': out_order.id})

@app.route('/in_order/<int:id>/copy', methods=['POST'])
@require_role('warehouse')
@login_required
def copy_in_order(id):
    """Copy an inbound order into a new draft inbound order."""
    source = InOrder.query.options(
        joinedload(InOrder.items).joinedload(InOrderItem.material),
        joinedload(InOrder.items).joinedload(InOrderItem.source_purchase_order_item).joinedload(PurchaseOrderItem.purchase_order),
    ).get_or_404(id)
    if not source.items:
        return jsonify({'status': 'error', 'msg': '原入库单没有明细，不能复制'})

    business_type = source.business_type or '采购入库'
    source_item_updates = []
    affected_purchase_orders = set()
    try:
        for item in source.items:
            quantity = round_to_2_decimals(item.quantity or 0)
            if quantity <= 0:
                continue
            if item.source_purchase_order_item_id:
                source_item = item.source_purchase_order_item
                source_order = source_item.purchase_order if source_item else None
                if not source_item or not source_order or source_order.status not in ('pending', 'partial'):
                    return jsonify({'status': 'error', 'msg': '原入库单的采购来源已完成或关闭，请从采购订单重新下推生成入库单'})
                valid_qty, qty_msg = validate_purchase_receive_quantity(
                    source_item,
                    quantity,
                    item.material.code if item.material else item.material_id,
                )
                if not valid_qty:
                    return jsonify({'status': 'error', 'msg': f'{qty_msg}。请从采购订单按剩余未入库数量重新下推。'})
                source_item_updates.append((source_item, quantity))
                affected_purchase_orders.add(source_order)
        prefix = 'PI' if business_type == '产品入库' else 'IN'
        new_order = InOrder(
            order_no=generate_order_no(prefix),
            date=date.today(),
            supplier_id=source.supplier_id,
            business_type=business_type,
            purpose=source.purpose or business_type,
            warehouse=source.warehouse or '',
            source_purchase_order_id=source.source_purchase_order_id if source_item_updates else None,
            remark=f'由入库单 {source.order_no} 复制生成' + (f'；原备注：{source.remark}' if source.remark else ''),
            status='pending',
            operator_id=current_user.id,
            total_amount=0,
        )
        db.session.add(new_order)
        db.session.flush()

        copied_count = 0
        for item in source.items:
            quantity = round_to_2_decimals(item.quantity or 0)
            if quantity <= 0:
                continue
            price = round_to_2_decimals(item.price or 0)
            db.session.add(InOrderItem(
                in_order_id=new_order.id,
                material_id=item.material_id,
                source_purchase_order_item_id=item.source_purchase_order_item_id,
                quantity=quantity,
                price=price,
                amount=round_to_2_decimals(quantity * price),
                remark=item.remark,
            ))
            copied_count += 1

        if copied_count <= 0:
            db.session.rollback()
            return jsonify({'status': 'error', 'msg': '原入库单没有有效数量，不能复制'})

        for source_item, quantity in source_item_updates:
            source_item.received_quantity = round_to_2_decimals((source_item.received_quantity or 0) + quantity)
        for purchase_order in affected_purchase_orders:
            update_purchase_order_status(purchase_order)
        recalculate_order_total(new_order)
        db.session.commit()
        log_operation('复制入库单', f'{source.order_no} -> {new_order.order_no}', 'in_order', new_order.id)
        return jsonify({
            'status': 'success',
            'msg': '复制成功，已生成新的入库草稿',
            'id': new_order.id,
            'order_no': new_order.order_no,
            'redirect_url': url_for('in_order_detail', id=new_order.id),
        })
    except Exception as e:
        db.session.rollback()
        app.logger.error(f'复制入库单失败: {e}')
        return jsonify({'status': 'error', 'msg': '复制失败，请稍后重试'})


def _calc_smart_threshold(values, base_threshold=0.5, min_threshold=0.2, max_threshold=1.0):
    """基于历史数据计算智能异常阈值。
    数据稳定（变异系数小）→ 阈值收紧；数据波动大 → 阈值放宽。
    返回 (threshold, mean, std)。
    """
    if not values or len(values) < 2:
        return base_threshold, (sum(values) / len(values) if values else 0), 0
    
    n = len(values)
    mean = sum(values) / n
    if mean <= 0:
        return base_threshold, mean, 0
    
    variance = sum((v - mean) ** 2 for v in values) / (n - 1)
    std = variance ** 0.5
    cv = std / mean  # 变异系数
    
    # 变异系数映射到阈值系数：cv=0 → 0.6倍基础阈值，cv=1 → 1.5倍基础阈值
    scale = 0.6 + cv * 0.9
    scale = max(0.6, min(scale, 2.0))
    threshold = base_threshold * scale
    threshold = max(min_threshold, min(threshold, max_threshold))
    
    return threshold, mean, std


def _check_in_order_anomalies(order):
    """检测入库单异常：数量异常、价格异常、重复单据。返回异常列表。"""
    anomalies = []
    if not order.items:
        return anomalies
    
    today = date.today()
    thirty_days_ago = today - timedelta(days=30)
    
    # 收集所有物料ID
    material_ids = [item.material_id for item in order.items if item.material_id]
    if not material_ids:
        return anomalies
    
    # 一次性查询近30天所有相关物料的入库明细（性能优化）
    recent_items = InOrderItem.query.join(InOrder).filter(
        InOrder.status == 'completed',
        InOrder.date >= thirty_days_ago,
        InOrder.date < today,
        InOrder.id != order.id,
        InOrderItem.material_id.in_(material_ids)
    ).all()
    
    # 按物料ID分组数据
    qty_by_material = {}
    price_by_material = {}
    for ri in recent_items:
        mid = ri.material_id
        if ri.quantity:
            qty_by_material.setdefault(mid, []).append(ri.quantity)
        if ri.price and ri.price > 0:
            price_by_material.setdefault(mid, []).append(ri.price)
    
    for item in order.items:
        if not item.material:
            continue
        
        material_name = item.material.name or item.material.code or '未知物料'
        
        # 1. 数量异常检测：与近30天平均入库量对比（智能阈值）
        recent_quantities = qty_by_material.get(item.material_id, [])
        if recent_quantities:
            qty_threshold, avg_qty, _ = _calc_smart_threshold(recent_quantities, base_threshold=0.5)
            if avg_qty > 0 and item.quantity:
                deviation = abs(item.quantity - avg_qty) / avg_qty
                if deviation > qty_threshold:
                    anomalies.append({
                        'type': 'quantity_deviation',
                        'material': material_name,
                        'current': item.quantity,
                        'average': round(avg_qty, 2),
                        'deviation': f'{deviation*100:.0f}%',
                        'threshold': f'{qty_threshold*100:.0f}%',
                        'msg': f'物料 {material_name} 本次入库量 {item.quantity} 偏离近30天均值 {round(avg_qty, 2)} 达 {deviation*100:.0f}%（动态阈值 {qty_threshold*100:.0f}%），请确认是否正确'
                    })
        
        # 2. 价格异常检测：与近3次采购价对比（智能阈值）
        if item.price and item.price > 0:
            recent_prices = price_by_material.get(item.material_id, [])
            if recent_prices:
                recent_prices_sorted = sorted(recent_prices, reverse=True)[:3]  # 取最近3次
                price_threshold, avg_price, _ = _calc_smart_threshold(recent_prices_sorted, base_threshold=0.3)
                if avg_price > 0:
                    price_deviation = abs(item.price - avg_price) / avg_price
                    if price_deviation > price_threshold:
                        anomalies.append({
                            'type': 'price_deviation',
                            'material': material_name,
                            'current': item.price,
                            'average': round(avg_price, 2),
                            'deviation': f'{price_deviation*100:.0f}%',
                            'threshold': f'{price_threshold*100:.0f}%',
                            'msg': f'物料 {material_name} 本次单价 {item.price} 偏离近期均价 {round(avg_price, 2)} 达 {price_deviation*100:.0f}%（动态阈值 {price_threshold*100:.0f}%），请确认'
                        })
    
    # 3. 重复单据检测：同一天同物料同供应商
    if order.supplier_id and order.date == today:
        today_orders = InOrder.query.filter(
            InOrder.date == today,
            InOrder.supplier_id == order.supplier_id,
            InOrder.id != order.id
        ).all()
        
        for to in today_orders:
            for ti in to.items:
                for oi in order.items:
                    if ti.material_id == oi.material_id:
                        material_name = oi.material.name or oi.material.code
                        anomalies.append({
                            'type': 'duplicate_order',
                            'material': material_name,
                            'existing_order': to.order_no,
                            'msg': f'物料 {material_name} 今天已在单据 {to.order_no} 中入库，请确认是否为重复操作'
                        })
    
    return anomalies


@app.route('/in_order/<int:id>/check_anomalies', methods=['POST'])
@require_role('warehouse')
@login_required
def check_in_order_anomalies(id):
    """检查入库单异常，返回异常列表供前端确认。"""
    order = InOrder.query.get_or_404(id)
    if order.status != 'pending':
        return jsonify({'status': 'error', 'msg': '该入库单已提交，不能检查异常'})
    
    anomalies = _check_in_order_anomalies(order)
    
    # 如果有异常且启用了AI，添加AI原因分析
    if anomalies and _ai_llm_configured():
        for anomaly in anomalies:
            # 生成AI分析提示
            prompt = f"作为仓库管理专家，请分析以下异常情况并给出简短建议（50字内）：\n"
            prompt += f"异常类型：{anomaly['type']}\n"
            prompt += f"物料：{anomaly['material']}\n"
            prompt += f"当前值：{anomaly['current']}\n"
            prompt += f"历史均值：{anomaly['average']}\n"
            prompt += f"偏离度：{anomaly['deviation']}\n"
            prompt += f"可能原因和建议："
            
            try:
                ai_suggestion = _ai_call_llm_chat(prompt)
                if ai_suggestion:
                    anomaly['ai_suggestion'] = ai_suggestion.strip()
            except Exception as e:
                app.logger.warning(f'AI异常分析失败: {e}')
    
    return jsonify({
        'status': 'success',
        'anomalies': anomalies,
        'has_anomalies': len(anomalies) > 0
    })


@app.route('/in_order/<int:id>/complete', methods=['POST'])
@require_role('warehouse')
@login_required
def complete_in_order(id):
    """Complete an inbound order and add stock."""
    order = InOrder.query.get_or_404(id)
    if order.status != 'pending':
        return jsonify({'status': 'error', 'msg': '该入库单已提交，不能重复操作'})

    if not order.items:
        return jsonify({'status': 'error', 'msg': '请至少添加一条入库明细'})
    if location_management_enabled() and location_required_on_save() and not order.warehouse:
        return jsonify({'status': 'error', 'msg': '启用库位管理后，入库单必须填写仓库/库位'})
    valid_source, source_msg = validate_purchase_in_order_source(order)
    if not valid_source:
        return jsonify({'status': 'error', 'msg': source_msg})

    force_submit = request.args.get('force', '').lower() in ('true', '1', 'yes')
    if not force_submit:
        anomalies = _check_in_order_anomalies(order)
        if anomalies:
            return jsonify({
                'status': 'warning',
                'msg': '检测到异常，请确认是否继续提交',
                'anomalies': anomalies
            })

    try:
        is_recompleted = StockTransaction.query.filter_by(
            reference_type='in_order',
            reference_id=order.id,
            transaction_type='revert_in'
        ).first() is not None
        affected_purchase_order_ids = set()
        for item in order.items:
            if item.material:
                ok, err = add_stock(item.material, item.quantity,
                                    transaction_type='in',
                                    reference_type='in_order',
                                    reference_id=order.id)
                if not ok:
                    db.session.rollback()
                    return jsonify({'status': 'error', 'msg': err or '库存增加失败'})
                if location_management_enabled() and order.warehouse:
                    loc_ok, loc_err = update_location_inventory(item.material, order.warehouse, item.quantity or 0)
                    if not loc_ok:
                        db.session.rollback()
                        return jsonify({'status': 'error', 'msg': loc_err or '库位库存更新失败'})
            if is_recompleted and item.source_purchase_order_item:
                source_item = item.source_purchase_order_item
                source_item.received_quantity = round_to_2_decimals((source_item.received_quantity or 0) + (item.quantity or 0))
                if source_item.purchase_order:
                    affected_purchase_order_ids.add(source_item.purchase_order.id)

        order.status = 'completed'
        order.total_amount = sum((item.amount or 0) for item in order.items)
        for purchase_order in PurchaseOrder.query.filter(PurchaseOrder.id.in_(affected_purchase_order_ids)).all():
            update_purchase_order_status(purchase_order)
        try:
            db.session.commit()
            share_now_config = WechatShareConfig.query.filter_by(enabled=True, immediate_on_complete=True, share_in_order=True).first()
            if share_now_config:
                try:
                    _wechat_share_order(share_now_config, order, trigger_type='completed', force=False)
                    db.session.commit()
                except Exception:
                    db.session.rollback()
                    app.logger.exception('入库单完成后微信分享失败: %s', order.order_no)
        except Exception as e:
            db.session.rollback()
            app.logger.error(f'数据库操作失败: {e}')
            return jsonify({'status': 'error', 'msg': '操作失败'}), 500

        log_operation('入库', f'入库单：{order.order_no}', 'in_order', id)
        app.logger.info(f'入库单完成：{order.order_no}')
        return jsonify({'status': 'success', 'msg': '提交成功'})
    except Exception as e:
        db.session.rollback()
        return jsonify({'status': 'error', 'msg': '提交失败，请稍后重试'})


@app.route('/in_order/<int:id>/update_completed', methods=['POST'])
@require_role('warehouse')
@login_required
def update_completed_in_order(id):
    """Update a completed inbound order and adjust stock differences."""
    order = InOrder.query.get_or_404(id)
    if order.status != 'completed':
        return jsonify({'status': 'error', 'msg': '只有已完成的入库单可以修改已入库明细'})

    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'status': 'error', 'msg': '请求数据格式不正确，请刷新后重试'})
    items_data = data.get('items', [])
    deleted_items = data.get('deleted_items', [])

    try:
        affected_purchase_order_ids = set()
        # 1. Delete detail rows and reverse their stock changes
        for item_id in deleted_items:
            item = db.session.get(InOrderItem, item_id)
            if item and item.in_order_id == id:
                if not allow_negative_stock():
                    sufficient, current_stock, error_msg = check_stock_sufficient(item.material, item.quantity)
                    if not sufficient:
                        return jsonify({'status': 'error', 'msg': error_msg})
                # 使用 deduct_stock 写流水+归一化+库位还原，避免直接改 stock
                ok, err = deduct_stock(item.material, item.quantity or 0,
                                       transaction_type='delete_in_item',
                                       reference_type='in_order',
                                       reference_id=order.id,
                                       remark=f'删除已完成入库单 {order.order_no} 明细回退库存')
                if not ok:
                    return jsonify({'status': 'error', 'msg': err or '库存回退失败'})
                if location_management_enabled() and order.warehouse:
                    update_location_inventory(item.material, order.warehouse, -(item.quantity or 0))
                if item.source_purchase_order_item:
                    source_item = item.source_purchase_order_item
                    source_item.received_quantity = max(
                        0,
                        round_to_2_decimals((source_item.received_quantity or 0) - (item.quantity or 0))
                    )
                    if source_item.purchase_order:
                        affected_purchase_order_ids.add(source_item.purchase_order.id)
                db.session.delete(item)

        # 2. Modify detail rows
        for item_data in items_data:
            item_id = item_data.get('id')
            is_new = item_data.get('is_new', False)

            if is_new:
                # Add new detail row and apply stock change
                material_code = (item_data.get('code') or item_data.get('material_code') or '').strip()
                if not material_code:
                    return jsonify({'status': 'error', 'msg': '请选择物料后再添加'})
                material = Material.query.filter_by(code=material_code).first()
                if not material:
                    return jsonify({'status': 'error', 'msg': f'物料 {material_code} 不存在'})

                quantity = float(item_data['quantity'])
                if quantity <= 0:
                    return jsonify({'status': 'error', 'msg': f'物料 {material_code} 的数量必须大于0'})
                price = float(item_data.get('price', 0))
                amount = round_to_2_decimals(quantity * price)
                source_purchase_order_item_id = None
                source_item_id = item_data.get('source_purchase_order_item_id')
                if source_item_id:
                    try:
                        source_item_id = int(source_item_id)
                    except (TypeError, ValueError):
                        return jsonify({'status': 'error', 'msg': '来源采购单明细格式不正确'})
                    source_item = db.session.get(PurchaseOrderItem, source_item_id)
                    if not source_item or source_item.material_id != material.id:
                        return jsonify({'status': 'error', 'msg': '来源采购单明细与物料不匹配'})
                    remain_qty = round_to_2_decimals((source_item.quantity or 0) - (source_item.received_quantity or 0))
                    if quantity - remain_qty > STOCK_COMPARE_EPSILON:
                        return jsonify({'status': 'error', 'msg': '新增明细数量不能大于来源采购单未下推数量'})
                    source_item.received_quantity = round_to_2_decimals((source_item.received_quantity or 0) + quantity)
                    source_purchase_order_item_id = source_item.id
                    if source_item.purchase_order:
                        affected_purchase_order_ids.add(source_item.purchase_order.id)

                new_item = InOrderItem(
                    in_order_id=id,
                    material_id=material.id,
                    quantity=quantity,
                    price=price,
                    amount=amount,
                    source_purchase_order_item_id=source_purchase_order_item_id,
                    remark=(item_data.get('remark') or '').strip() or None
                )
                db.session.add(new_item)
                # 使用 add_stock 写流水+归一化+库位同步，避免直接改 stock
                ok, err = add_stock(material, quantity,
                                    transaction_type='add_in_item',
                                    reference_type='in_order',
                                    reference_id=order.id,
                                    remark=f'已完成入库单 {order.order_no} 新增明细')
                if not ok:
                    db.session.rollback()
                    return jsonify({'status': 'error', 'msg': err or '库存增加失败'})
                if location_management_enabled() and order.warehouse:
                    loc_ok, loc_err = update_location_inventory(material, order.warehouse, quantity)
                    if not loc_ok:
                        db.session.rollback()
                        return jsonify({'status': 'error', 'msg': loc_err or '库位库存更新失败'})

            elif item_id:
                item = db.session.get(InOrderItem, item_id)
                if item and item.in_order_id == id:
                    old_qty = item.quantity
                    new_qty = float(item_data['quantity'])
                    if new_qty <= 0:
                        material_code = item.material.code if item.material else ''
                        return jsonify({'status': 'error', 'msg': f'物料 {material_code} 的数量必须大于0'})
                    new_price = float(item_data.get('price', 0))

                    qty_diff = new_qty - old_qty
                    if qty_diff < 0:
                        deduct_qty = abs(qty_diff)
                        if not allow_negative_stock():
                            sufficient, current_stock, error_msg = check_stock_sufficient(item.material, deduct_qty)
                            if not sufficient:
                                return jsonify({'status': 'error', 'msg': error_msg})
                    if item.source_purchase_order_item and abs(qty_diff) > STOCK_COMPARE_EPSILON:
                        source_item = item.source_purchase_order_item
                        effective_received_before = round_to_2_decimals((source_item.received_quantity or 0) - (old_qty or 0))
                        allowed_qty = round_to_2_decimals(max((source_item.quantity or 0) - effective_received_before, 0))
                        if new_qty - allowed_qty > STOCK_COMPARE_EPSILON:
                            return jsonify({'status': 'error', 'msg': '明细数量不能大于来源采购单未下推数量'})
                        source_item.received_quantity = max(
                            0,
                            round_to_2_decimals((source_item.received_quantity or 0) + qty_diff)
                        )
                        if source_item.purchase_order:
                            affected_purchase_order_ids.add(source_item.purchase_order.id)
                    # 使用 add_stock/deduct_stock 写流水+归一化+库位同步，避免直接改 stock
                    if qty_diff > 0:
                        ok, err = add_stock(item.material, qty_diff,
                                            transaction_type='adjust_in_item',
                                            reference_type='in_order',
                                            reference_id=order.id,
                                            remark=f'修改已完成入库单 {order.order_no} 明细数量增加')
                        if not ok:
                            db.session.rollback()
                            return jsonify({'status': 'error', 'msg': err or '库存增加失败'})
                    elif qty_diff < 0:
                        ok, err = deduct_stock(item.material, abs(qty_diff),
                                               transaction_type='adjust_in_item',
                                               reference_type='in_order',
                                               reference_id=order.id,
                                               remark=f'修改已完成入库单 {order.order_no} 明细数量减少')
                        if not ok:
                            return jsonify({'status': 'error', 'msg': err or '库存回退失败'})
                    if location_management_enabled() and order.warehouse and qty_diff != 0:
                        loc_ok, loc_err = update_location_inventory(item.material, order.warehouse, qty_diff)
                        if not loc_ok:
                            db.session.rollback()
                            return jsonify({'status': 'error', 'msg': loc_err or '库位库存更新失败'})

                    item.quantity = new_qty
                    item.price = new_price
                    item.amount = round_to_2_decimals(new_qty * new_price)
                    if 'remark' in item_data:
                        item.remark = (item_data.get('remark') or '').strip() or None

        recalculate_order_total(order)
        for purchase_order in PurchaseOrder.query.filter(PurchaseOrder.id.in_(affected_purchase_order_ids)).all():
            update_purchase_order_status(purchase_order)
        try:
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            app.logger.error(f'数据库操作失败: {e}')
            return jsonify({'status': 'error', 'msg': '操作失败'}), 500
        return jsonify({'status': 'success', 'msg': '保存成功'})

    except Exception as e:
        db.session.rollback()
        return jsonify({'status': 'error', 'msg': '保存失败，请稍后重试'})


@app.route('/api/material/all', methods=['GET', 'POST'])
@web_or_api_required
def material_all_api():
    materials = Material.query.order_by(Material.code.asc()).limit(1000).all()
    return jsonify({
        'status': 'success',
        'success': True,
        'data': [api_material_payload(material) for material in materials]
    })


@app.route('/api/material/search', methods=['GET', 'POST'])
@web_or_api_required
def material_search_api():
    keyword = (request.values.get('kw') or request.values.get('keyword') or '').strip()
    query = Material.query
    if keyword:
        query = query.filter(
            db.or_(
                Material.code.like(f'%{keyword}%'),
                Material.name.like(f'%{keyword}%'),
                Material.spec.like(f'%{keyword}%')
            )
        )
    materials = query.order_by(Material.code.asc()).limit(100).all()
    return jsonify({
        'status': 'success',
        'success': True,
        'data': [api_material_payload(material) for material in materials]
    })


@app.route('/api/material/info', methods=['GET', 'POST'])
@web_or_api_required
def material_info_api():
    code = (request.values.get('code') or '').strip()
    material_id = request.values.get('id', type=int)

    material = None
    if code:
        material = Material.query.filter_by(code=code).first()
    elif material_id:
        material = db.session.get(Material, material_id)

    if not material:
        return jsonify({'status': 'error', 'success': False, 'msg': '物料不存在'})

    return jsonify({
        'status': 'success',
        'success': True,
        'data': api_material_payload(material)
    })


