@login_required
def export_bom():
    from openpyxl import Workbook
    wb = Workbook()
    ws = wb.active
    ws.title = 'BOM'
    ws.append(['BOM编号', '产品编码', '产品名称', '版本', '状态', '层级', '物料数', '总成本', '创建时间', '备注'])
