@app.route('/check/import', methods=['POST'])
@require_role('warehouse')
@login_required
def import_check():
    file = request.files.get('file')
    if not file:
        return jsonify({'status': 'error', 'msg': '请选择要导入的库存盘点文件'})
    aliases = {
        'order_no': ['单据编号', '盘点单号', '订单编号'],
        'date': ['日期'],
        'material_code': ['物料编码', '材料编码'],
        'material_name': ['物料名称', '材料名称'],
        'spec': ['规格'],
        'unit': ['单位'],
        'system_stock': ['系统库存', '账面库存'],
        'actual_stock': ['实际库存', '盘点库存'],
        'reason': ['差异原因', '原因'],
        'remark': ['备注'],
    }
    try:
        ws, col_map, header_row = _read_import_sheet(file, aliases)
        required = {'material_code', 'actual_stock'}
        if not required.issubset(col_map):
            return jsonify({'status': 'error', 'msg': f'Excel表头缺少必要列（物料编码、实际库存）。检测到的表头：{", ".join(header_row)}'})
        checks_by_no = {}
        order_count = 0
        item_count = 0
        skip = 0
        skip_details = []
        for row_idx, row in enumerate(ws.iter_rows(min_row=2, values_only=True), start=2):
            material_code = _get_excel_cell(row, col_map, 'material_code')
            if not material_code:
                skip += 1
                skip_details.append(f'第{row_idx}行：物料编码为空')
                continue
            order_no = _order_no_from_row(row, col_map, 'order_no', 'CK')
            check = checks_by_no.get(order_no)
            if not check:
                if InventoryCheck.query.filter_by(check_no=order_no).first():
                    skip += 1
                    skip_details.append(f'第{row_idx}行：盘点单号 {order_no} 已存在')
                    continue
                check = InventoryCheck(
                    check_no=order_no,
                    date=_parse_excel_date(_get_excel_cell(row, col_map, 'date')),
                    remark=_get_excel_cell(row, col_map, 'remark'),
                    status='pending',
                    operator_id=current_user.id,
                )
                db.session.add(check)
                db.session.flush()
                checks_by_no[order_no] = check
                order_count += 1
            material = _find_or_create_material(
                material_code,
                _get_excel_cell(row, col_map, 'material_name'),
                _get_excel_cell(row, col_map, 'spec'),
                _get_excel_cell(row, col_map, 'unit'),
            )
            system_stock = _get_excel_number(row, col_map, 'system_stock', material.stock or 0)
            actual_stock = _get_excel_number(row, col_map, 'actual_stock', system_stock)
            db.session.add(InventoryCheckItem(
                inventory_check_id=check.id,
                material_id=material.id,
                system_stock=system_stock,
                actual_stock=actual_stock,
                difference=round_to_2_decimals(actual_stock - system_stock),
                reason=_get_excel_cell(row, col_map, 'reason'),
            ))
            item_count += 1
        db.session.commit()
        return _import_result('库存盘点单', order_count, item_count, skip, skip_details)
    except Exception as e:
        db.session.rollback()
        app.logger.error(f'库存盘点导入失败: {e}')
        return jsonify({'status': 'error', 'msg': f'库存盘点导入失败：{str(e)}'})


# ==================== Outbound order management ====================

@app.route('/out_order')
@login_required
def out_order_list():
    page = request.args.get('page', 1, type=int)
    per_page = request.args.get('per_page', 20, type=int)
    # per_page 必须有下限保护，传入 0 或负数会让 paginate 抛 ValueError 导致接口 500
    per_page = max(1, per_page)
    if per_page not in [20, 50, 100, 200]:
        per_page = 20
    status_filter, search, date_start, date_end, sort_by, sort_order = _get_order_list_filters(('pending', 'completed'))
    allowed_sorts = {'order_no', 'date', 'department_id', 'customer', 'business_type', 'purpose', 'status', 'created_at', 'total_amount'}
    if sort_by not in allowed_sorts:
        sort_by = 'created_at'
    sort_col = getattr(OutOrder, sort_by, OutOrder.created_at)
    # 按单据左连接明细展示，待完成但没有明细的单据也能查到。
    query = db.session.query(OutOrder, OutOrderItem).outerjoin(OutOrderItem, OutOrderItem.out_order_id == OutOrder.id).options(
        joinedload(OutOrder.department),
        joinedload(OutOrderItem.material).joinedload(Material.unit),
    )
    query = _apply_status_date_filters(query, OutOrder, status_filter, date_start, date_end)
    query = _apply_out_order_search(query, search)
    # 领料明细默认排除"销售出库"（销售出库归销售管理，见 /sales/outflow_report），
    # 避免销售单据混入仓库领料明细。显式传 business_type=销售出库 时仍可查看。
    explicit_bt = (request.args.get('business_type') or '').strip()
    if not explicit_bt:
        query = query.filter(OutOrder.business_type != '销售出库')
    if sort_order == 'asc':
        query = query.order_by(sort_col.asc())
    else:
        query = query.order_by(sort_col.desc())
    pagination = query.paginate(page=page, per_page=per_page, error_out=False)
    items = [
        type('OutOrderListRow', (), {
            'out_order': order,
            'material': item.material if item else None,
            'quantity': item.quantity if item else 0,
            'price': item.price if item else 0,
            'amount': item.amount if item else 0,
        })()
        for order, item in pagination.items
    ]
    filters = {
        'status': status_filter,
        'search': search,
        'date_start': date_start.strftime('%Y-%m-%d') if date_start else '',
        'date_end': date_end.strftime('%Y-%m-%d') if date_end else '',
    }
    return render_template('out_order.html', items=items, pagination=pagination, sort_by=sort_by, sort_order=sort_order, per_page=per_page, filters=filters)

