def _collect_ledger_rows(filters):
    query = StockTransaction.query.options(
        joinedload(StockTransaction.material),
        joinedload(StockTransaction.operator)
    )
    if filters.get('end_date'):
        query = query.filter(StockTransaction.created_at <= datetime.combine(filters['end_date'], time.max))
    material_clause = _material_filter_clause(filters.get('material_code'))
    if material_clause is not None:
        query = query.join(StockTransaction.material).filter(material_clause)

    transactions = query.order_by(StockTransaction.material_id.asc(), StockTransaction.created_at.asc(), StockTransaction.id.asc()).limit(5000).all()

    rows = []
    balances = {}
    start_date = filters.get('start_date')
    for transaction in transactions:
        material = transaction.material
        if not material:
            continue

        material_id = transaction.material_id
        quantity = _safe_float(transaction.quantity)
        before_balance = balances.get(material_id, 0.0)
        after_balance = before_balance + quantity
        balances[material_id] = after_balance

        txn_datetime = transaction.created_at or datetime.min
        txn_date = txn_datetime.date()
        if start_date and txn_date < start_date:
            continue

        is_opening = (transaction.transaction_type or '').lower() in {'opening', 'opening_stock'}
        reference_no, reference_url = _report_reference_info(
            transaction.reference_type,
            transaction.reference_id,
            f"{transaction.reference_type or 'txn'}-{transaction.reference_id or transaction.id}",
        )
        rows.append({
            'date': txn_date.isoformat() if txn_date else '',
            'reference_type': REFERENCE_TYPE_LABELS.get(transaction.reference_type, transaction.reference_type or '库存流水'),
            'reference_no': reference_no,
            'reference_url': reference_url,
            'opening_quantity': quantity if is_opening else 0.0,
            'in_quantity': quantity if quantity > 0 and not is_opening else 0.0,
            'out_quantity': abs(quantity) if quantity < 0 and not is_opening else 0.0,
            'balance_quantity': after_balance,
            'material_id': material_id,
            'material_code': material.code or '',
            'material_name': material.name or '',
            'spec': material.spec or '',
            'quantity': _safe_float(transaction.quantity),
            'amount': _safe_float(transaction.quantity) * _safe_float(material.price),
            'operator': transaction.operator.username if transaction.operator else '',
            'location': transaction.location or '',
            'remark': transaction.remark or '',
        })

    return sorted(rows, key=lambda row: (row['date'], row['material_code'], row['reference_no']))


def _purchase_order_item_query(filters):
    query = PurchaseOrderItem.query.join(PurchaseOrder).join(Material, PurchaseOrderItem.material_id == Material.id).options(
        joinedload(PurchaseOrderItem.purchase_order).joinedload(PurchaseOrder.supplier),
        joinedload(PurchaseOrderItem.purchase_order).joinedload(PurchaseOrder.purchase_request),
        joinedload(PurchaseOrderItem.material).joinedload(Material.unit),
    ).order_by(
        PurchaseOrder.date.desc(),
        PurchaseOrder.order_no.desc(),
        PurchaseOrderItem.id.desc(),
    )
    if filters.get('start_date'):
        query = query.filter(PurchaseOrder.date >= filters['start_date'])
    if filters.get('end_date'):
        query = query.filter(PurchaseOrder.date <= filters['end_date'])
    if filters.get('supplier_id'):
        query = query.filter(PurchaseOrder.supplier_id == filters['supplier_id'])
    supplier_clause = _supplier_filter_clause(filters.get('supplier'))
    if supplier_clause is not None:
        query = query.join(Supplier, PurchaseOrder.supplier_id == Supplier.id).filter(supplier_clause)
    if filters.get('status'):
        query = query.filter(PurchaseOrder.status == filters['status'])
    material_clause = _material_filter_clause(filters.get('material_code'))
    if material_clause is not None:
        query = query.filter(material_clause)
    return query


def _collect_purchase_order_execution_rows(filters):
    items = _purchase_order_item_query(filters).limit(5000).all()
    today_value = date.today()
    rows = []
    for item in items:
        order = item.purchase_order
        material = item.material
        if not order or not material:
            continue
        order_qty = _safe_float(item.quantity)
        received_qty = _safe_float(item.received_quantity)
        remaining_qty = max(round_to_2_decimals(order_qty - received_qty), 0)
        price = _safe_float(item.price)
        overdue_days = 0
        if order.expected_date and remaining_qty > STOCK_COMPARE_EPSILON and order.status not in ('completed', 'closed') and order.expected_date < today_value:
            overdue_days = (today_value - order.expected_date).days
        rows.append({
            'date': order.date.isoformat() if order.date else '',
            'order_no': order.order_no or '',
            'order_url': _report_detail_url('purchase_order_detail', order.id),
            'supplier': order.supplier.name if order.supplier else '',
            'material_code': material.code or '',
            'material_name': material.name or '',
            'spec': material.spec or '',
            'unit': material.unit.name if material.unit else '',
            'order_quantity': order_qty,
            'received_quantity': received_qty,
            'remaining_quantity': remaining_qty,
            'price': price,
            'amount': _safe_float(item.amount) or round_to_2_decimals(order_qty * price),
            'received_amount': round_to_2_decimals(received_qty * price),
            'remaining_amount': round_to_2_decimals(remaining_qty * price),
            'expected_date': order.expected_date.isoformat() if order.expected_date else '',
            'overdue_days': overdue_days,
            'status': order.status or '',
            'source_request_no': order.purchase_request.request_no if order.purchase_request else '',
            'remark': item.remark or order.remark or '',
        })
    return rows


def _build_purchase_summary_row(bucket):
    amount = bucket['amount']
    quantity = bucket['order_quantity']
    row = {
        key: value
        for key, value in bucket.items()
        if key not in ('order_ids', 'material_ids', 'supplier_ids')
    }
    return {
        **row,
        'order_count': len(bucket['order_ids']),
        'material_count': len(bucket.get('material_ids', set())),
        'supplier_count': len(bucket.get('supplier_ids', set())),
        'avg_price': round_to_2_decimals(amount / quantity) if quantity else 0,
        'last_purchase_date': bucket['last_purchase_date'].isoformat() if bucket.get('last_purchase_date') else '',
    }


def _build_supplier_purchase_summary_report(filters):
    rows_by_supplier = {}
    for row in _collect_purchase_order_execution_rows(filters):
        supplier_name = row['supplier'] or '未指定供应商'
        key = supplier_name
        bucket = rows_by_supplier.setdefault(key, {
            'supplier_code': '',
            'supplier': supplier_name,
            'order_ids': set(),
            'material_ids': set(),
            'order_quantity': 0.0,
            'received_quantity': 0.0,
            'remaining_quantity': 0.0,
            'amount': 0.0,
            'received_amount': 0.0,
            'remaining_amount': 0.0,
            'overdue_count': 0,
            'last_purchase_date': None,
        })
        if row['order_url']:
            bucket['order_ids'].add(row['order_url'])
        if row['material_code']:
            bucket['material_ids'].add(row['material_code'])
        bucket['order_quantity'] += _safe_float(row['order_quantity'])
        bucket['received_quantity'] += _safe_float(row['received_quantity'])
        bucket['remaining_quantity'] += _safe_float(row['remaining_quantity'])
        bucket['amount'] += _safe_float(row['amount'])
        bucket['received_amount'] += _safe_float(row['received_amount'])
        bucket['remaining_amount'] += _safe_float(row['remaining_amount'])
        if _safe_float(row['overdue_days']) > 0:
            bucket['overdue_count'] += 1
        row_date = parse_date_value(row['date'])
        if row_date and (bucket['last_purchase_date'] is None or row_date > bucket['last_purchase_date']):
            bucket['last_purchase_date'] = row_date

    supplier_by_name = {supplier.name: supplier for supplier in Supplier.query.all()}
    rows = []
    for bucket in rows_by_supplier.values():
        supplier = supplier_by_name.get(bucket['supplier'])
        if supplier:
            bucket['supplier_code'] = supplier.code or ''
        rows.append(_build_purchase_summary_row(bucket))
    return rows


def _build_material_purchase_summary_report(filters):
    rows_by_material = {}
    for row in _collect_purchase_order_execution_rows(filters):
        key = (row['material_code'], row['material_name'], row['spec'])
        bucket = rows_by_material.setdefault(key, {
            'material_code': row['material_code'],
            'material_name': row['material_name'],
            'spec': row['spec'],
            'unit': row['unit'],
            'order_ids': set(),
            'supplier_ids': set(),
            'order_quantity': 0.0,
            'received_quantity': 0.0,
            'remaining_quantity': 0.0,
            'amount': 0.0,
            'received_amount': 0.0,
            'remaining_amount': 0.0,
            'last_supplier': '',
            'last_purchase_date': None,
        })
        if row['order_url']:
            bucket['order_ids'].add(row['order_url'])
        if row['supplier']:
            bucket['supplier_ids'].add(row['supplier'])
        bucket['order_quantity'] += _safe_float(row['order_quantity'])
        bucket['received_quantity'] += _safe_float(row['received_quantity'])
        bucket['remaining_quantity'] += _safe_float(row['remaining_quantity'])
        bucket['amount'] += _safe_float(row['amount'])
        bucket['received_amount'] += _safe_float(row['received_amount'])
        bucket['remaining_amount'] += _safe_float(row['remaining_amount'])
        row_date = parse_date_value(row['date'])
        if row_date and (bucket['last_purchase_date'] is None or row_date > bucket['last_purchase_date']):
            bucket['last_purchase_date'] = row_date
            bucket['last_supplier'] = row['supplier']

    return [_build_purchase_summary_row(bucket) for bucket in rows_by_material.values()]


def _build_purchase_price_analysis_report(filters):
    rows_by_key = {}
    for row in _collect_purchase_order_execution_rows(filters):
        key = (row['material_code'], row['material_name'], row['spec'], row['supplier'])
        bucket = rows_by_key.setdefault(key, {
            'material_code': row['material_code'],
            'material_name': row['material_name'],
            'spec': row['spec'],
            'supplier': row['supplier'] or '未指定供应商',
            'purchase_times': 0,
            'quantity': 0.0,
            'amount': 0.0,
            'min_price': None,
            'max_price': None,
            'last_price': 0.0,
            'last_purchase_date': None,
            'last_order_no': '',
            'last_order_url': '',
        })
        price = _safe_float(row['price'])
        quantity = _safe_float(row['order_quantity'])
        bucket['purchase_times'] += 1
        bucket['quantity'] += quantity
        bucket['amount'] += _safe_float(row['amount'])
        bucket['min_price'] = price if bucket['min_price'] is None else min(bucket['min_price'], price)
        bucket['max_price'] = price if bucket['max_price'] is None else max(bucket['max_price'], price)
        row_date = parse_date_value(row['date'])
        if row_date and (bucket['last_purchase_date'] is None or row_date >= bucket['last_purchase_date']):
            bucket['last_purchase_date'] = row_date
            bucket['last_price'] = price
            bucket['last_order_no'] = row['order_no']
            bucket['last_order_url'] = row.get('order_url', '')

    rows = []
    for bucket in rows_by_key.values():
        min_price = _safe_float(bucket['min_price'])
        max_price = _safe_float(bucket['max_price'])
        rows.append({
            **bucket,
            'min_price': min_price,
            'max_price': max_price,
            'price_range': round_to_2_decimals(max_price - min_price),
            'avg_price': round_to_2_decimals(bucket['amount'] / bucket['quantity']) if bucket['quantity'] else 0,
            'last_purchase_date': bucket['last_purchase_date'].isoformat() if bucket.get('last_purchase_date') else '',
        })
    return rows


def _build_inventory_report(filters):
    rows = _collect_inventory_rows(filters)
    summary = {
        'count': len(rows),
        'quantity': sum(row['stock'] for row in rows),
        'amount': sum(row['stock_value'] for row in rows),
    }
    return _inventory_columns(), rows, summary


