@app.route('/report/dashboard/ai_insights', methods=['POST'])
@login_required
def report_dashboard_ai_insights():
    if not _ai_llm_configured():
        return jsonify({'status': 'error', 'msg': '请先在系统设置中配置大模型API'})
    stats, chart_data = build_report_dashboard_context()
    
    # 计算环比增长率
    in_amount_mom = ((stats['month_in_amount'] - stats['last_month_in_amount']) / stats['last_month_in_amount'] * 100) if stats['last_month_in_amount'] > 0 else 0
    out_amount_mom = ((stats['month_out_amount'] - stats['last_month_out_amount']) / stats['last_month_out_amount'] * 100) if stats['last_month_out_amount'] > 0 else 0
    
    prompt = f"""你是仓库管理系统的数据分析师，请基于以下仪表盘数据生成简洁的业务洞察：

【核心指标】
- 本月入库金额：{stats.month_in_amount:.2f} 元，共 {stats.month_in_count} 笔单据
- 本月领料金额：{stats.month_out_amount:.2f} 元，共 {stats.month_out_count} 笔单据
- 库存总量：{stats.total_stock:.2f}，共 {stats.material_count} 种物料
- 库存金额：{stats.stock_value:.2f} 元

【环比分析】
- 入库金额环比：{in_amount_mom:+.1f}%（上月 {stats.last_month_in_amount:.2f} 元）
- 领料金额环比：{out_amount_mom:+.1f}%（上月 {stats.last_month_out_amount:.2f} 元）

【趋势数据】近10天出入库数量趋势：{json.dumps(chart_data.get('trend', {}), ensure_ascii=False)[:500]}

请生成4-6条有价值的业务洞察，包括：
1. 环比分析（本月vs上月，增长/下降原因分析）
2. 出入库趋势分析（近10天波动情况及可能原因）
3. 库存健康度评估（是否有积压或缺货风险）
4. 可执行的改进建议
要求语言简洁专业，每条不超过80字，用换行分隔。"""
    try:
        insights = _ai_call_llm_chat(prompt)
        if not insights:
            return jsonify({'status': 'error', 'msg': 'AI生成失败，请稍后重试'})
        return jsonify({'status': 'success', 'insights': insights})
    except Exception as e:
        app.logger.error(f'报表AI解读失败: {e}')
        return jsonify({'status': 'error', 'msg': '生成失败，请稍后重试'}), 500

@app.route('/api/ai/replenishment_suggestions', methods=['POST'])
@login_required
def ai_replenishment_suggestions():
    """智能补货建议：分析库存低于补货点的物料，结合历史出库数据生成补货建议。"""
    if not _ai_llm_configured():
        return jsonify({'status': 'error', 'msg': '请先在系统设置中配置大模型API'})
    
    # 查询库存低于补货点的物料
    materials = Material.query.filter(
        Material.stock < Material.reorder_point,
        Material.reorder_point > 0
    ).all()
    
    if not materials:
        return jsonify({'status': 'success', 'suggestions': [], 'msg': '当前所有物料库存充足，无需补货'})
    
    # 收集物料信息和历史出库数据
    suggestions_data = []
    thirty_days_ago = date.today() - timedelta(days=30)
    
    for material in materials[:20]:  # 限制最多20个物料，避免数据过大
        # 查询近30天出库量
        recent_out = db.session.query(
            func.coalesce(func.sum(OutOrderItem.quantity), 0)
        ).join(OutOrder, OutOrderItem.out_order_id == OutOrder.id).filter(
            OutOrderItem.material_id == material.id,
            OutOrder.status == 'completed',
            OutOrder.date >= thirty_days_ago
        ).scalar() or 0
        
        # 计算日均出库量
        daily_avg = recent_out / 30 if recent_out > 0 else 0
        
        # 计算建议补货量（补到最大库存或满足30天需求）
        target_stock = max(material.max_stock, material.reorder_point + daily_avg * 30)
        suggested_qty = max(0, target_stock - material.stock)
        
        suggestions_data.append({
            'material_code': material.code,
            'material_name': material.name,
            'current_stock': material.stock,
            'reorder_point': material.reorder_point,
            'daily_avg_out': round(daily_avg, 2),
            'suggested_qty': round(suggested_qty, 2),
            'supplier': material.supplier.name if material.supplier else '未设置',
            'unit': material.unit.name if material.unit else '个',
            'price': material.price or 0
        })
    
    # 构建AI分析提示
    prompt = f"""作为仓库管理专家，请分析以下需要补货的物料，给出专业的补货建议：

【需要补货的物料】（共{len(suggestions_data)}种）
"""
    for i, s in enumerate(suggestions_data[:10], 1):  # 最多分析10个
        prompt += f"{i}. {s['material_name']}（{s['material_code']}）\n"
        prompt += f"   当前库存：{s['current_stock']} {s['unit']}，补货点：{s['reorder_point']}\n"
        prompt += f"   近30天日均出库：{s['daily_avg_out']}，建议补货量：{s['suggested_qty']}\n"
        prompt += f"   供应商：{s['supplier']}，单价：{s['price']}元\n\n"
    
    prompt += """请生成简洁的补货建议（200字内），包括：
1. 紧急程度排序（哪些物料最急需补货）
2. 补货策略建议（批量采购还是分批补货）
3. 风险提示（是否有供应商交期、季节性因素等需要注意）
要求语言简洁实用，可直接指导采购操作。"""
    
    try:
        ai_analysis = _ai_call_llm_chat(prompt)
        return jsonify({
            'status': 'success',
            'suggestions': suggestions_data,
            'ai_analysis': ai_analysis or 'AI分析暂不可用，请参考系统建议量进行补货。'
        })
    except Exception as e:
        app.logger.error(f'智能补货建议失败: {e}')
        return jsonify({'status': 'error', 'msg': '生成失败，请稍后重试'}), 500

@app.route('/api/ai/inventory_health', methods=['POST'])
@login_required
def ai_inventory_health():
    """库存健康度评分：AI评估每个物料的库存健康度（积压/缺货风险）。"""
    if not _ai_llm_configured():
        return jsonify({'status': 'error', 'msg': '请先在系统设置中配置大模型API'})
    
    # 查询所有有库存的物料
    materials = Material.query.filter(Material.stock > 0).all()
    
    if not materials:
        return jsonify({'status': 'success', 'health_scores': [], 'msg': '当前无库存数据'})
    
    # 收集物料健康度数据
    health_data = []
    thirty_days_ago = date.today() - timedelta(days=30)
    ninety_days_ago = date.today() - timedelta(days=90)
    
    for material in materials[:50]:  # 限制最多50个物料
        # 查询近30天出库量
        recent_out_30 = db.session.query(
            func.coalesce(func.sum(OutOrderItem.quantity), 0)
        ).join(OutOrder, OutOrderItem.out_order_id == OutOrder.id).filter(
            OutOrderItem.material_id == material.id,
            OutOrder.status == 'completed',
            OutOrder.date >= thirty_days_ago
        ).scalar() or 0
        
        # 查询近90天出库量
        recent_out_90 = db.session.query(
            func.coalesce(func.sum(OutOrderItem.quantity), 0)
        ).join(OutOrder, OutOrderItem.out_order_id == OutOrder.id).filter(
            OutOrderItem.material_id == material.id,
            OutOrder.status == 'completed',
            OutOrder.date >= ninety_days_ago
        ).scalar() or 0
        
        # 计算日均出库量
        daily_avg_30 = recent_out_30 / 30 if recent_out_30 > 0 else 0
        daily_avg_90 = recent_out_90 / 90 if recent_out_90 > 0 else 0
        
        # 计算库存可用天数
        days_of_supply = material.stock / daily_avg_30 if daily_avg_30 > 0 else 999
        
        # 判断健康状态
        health_status = 'healthy'
        risk_level = 'low'
        
        if material.stock < material.min_stock:
            health_status = 'critical'
            risk_level = 'high'
        elif material.stock < material.reorder_point:
            health_status = 'warning'
            risk_level = 'medium'
        elif days_of_supply > 90 and daily_avg_30 > 0:
            health_status = 'overstock'
            risk_level = 'medium'
        elif daily_avg_30 == 0 and daily_avg_90 == 0:
            health_status = 'dead_stock'
            risk_level = 'high'
        
        health_data.append({
            'material_code': material.code,
            'material_name': material.name,
            'current_stock': material.stock,
            'min_stock': material.min_stock,
            'reorder_point': material.reorder_point,
            'daily_avg_30': round(daily_avg_30, 2),
            'daily_avg_90': round(daily_avg_90, 2),
            'days_of_supply': round(days_of_supply, 1) if days_of_supply < 999 else '无出库',
            'health_status': health_status,
            'risk_level': risk_level,
            'unit': material.unit.name if material.unit else '个',
            'stock_value': round(material.stock * (material.price or 0), 2)
        })
    
    # 按风险等级排序
    health_data.sort(key=lambda x: {'high': 0, 'medium': 1, 'low': 2}.get(x['risk_level'], 3))
    
    # 构建AI分析提示
    critical_items = [h for h in health_data if h['risk_level'] == 'high'][:5]
    overstock_items = [h for h in health_data if h['health_status'] == 'overstock'][:5]
    
    prompt = f"""作为仓库管理专家，请分析以下库存健康度数据，给出专业的库存优化建议：

【库存概况】共{len(health_data)}种物料有库存

【高风险物料】（需立即关注）
"""
    for i, h in enumerate(critical_items, 1):
        prompt += f"{i}. {h['material_name']}（{h['material_code']}）：库存{h['current_stock']}，状态{h['health_status']}\n"
    
    if overstock_items:
        prompt += "\n【积压风险物料】（库存周转慢）\n"
        for i, h in enumerate(overstock_items, 1):
            prompt += f"{i}. {h['material_name']}：库存{h['current_stock']}，可用{h['days_of_supply']}天\n"
    
    prompt += """

请生成简洁的库存优化建议（200字内），包括：
1. 高风险物料处理建议（紧急补货或清理）
2. 积压物料处理建议（促销、调拨或暂停采购）
3. 整体库存健康度评估和改进方向
要求语言简洁实用，可直接指导库存管理决策。"""
    
    try:
        ai_analysis = _ai_call_llm_chat(prompt)
        return jsonify({
            'status': 'success',
            'health_scores': health_data,
            'ai_analysis': ai_analysis or 'AI分析暂不可用，请参考系统评分进行库存优化。',
            'summary': {
                'total': len(health_data),
                'critical': len([h for h in health_data if h['risk_level'] == 'high']),
                'warning': len([h for h in health_data if h['risk_level'] == 'medium']),
                'healthy': len([h for h in health_data if h['risk_level'] == 'low'])
            }
        })
    except Exception as e:
        app.logger.error(f'库存健康度分析失败: {e}')
        return jsonify({'status': 'error', 'msg': '生成失败，请稍后重试'}), 500

@app.route('/ai/document_ocr')
@login_required
@require_role('warehouse', 'purchase')
def document_ocr_page():
    """单据OCR识别页面"""
    return render_template('document_ocr.html')

@app.route('/api/ai/document_ocr', methods=['POST'])
@login_required
@require_role('warehouse', 'purchase')
def api_document_ocr():
    """单据OCR识别API：上传图片，AI识别单据内容并生成入库草稿。"""
    if not _ai_llm_configured() or not _ai_llm_vision_enabled():
        return jsonify({'status': 'error', 'msg': '请先在系统设置中启用大模型和图片识别'}), 400

    if 'image' not in request.files:
        return jsonify({'status': 'error', 'msg': '请上传图片'}), 400

    file = request.files['image']
    if not file.filename:
        return jsonify({'status': 'error', 'msg': '请选择图片文件'}), 400

    allowed_ext = {'png', 'jpg', 'jpeg', 'gif', 'bmp', 'webp'}
    ext = file.filename.rsplit('.', 1)[-1].lower() if '.' in file.filename else ''
    if ext not in allowed_ext:
        return jsonify({'status': 'error', 'msg': '不支持的图片格式'}), 400

    file.seek(0, 2)
    file_size = file.tell()
    file.seek(0)
    if file_size > 10 * 1024 * 1024:
        return jsonify({'status': 'error', 'msg': '图片大小不能超过10MB'}), 400

    # AI_TASK: AI-R17-F01 Provider 紧急回滚：降级为人工流程，保留文件证据不丢失
    if _ai_force_fallback():
        task_id = f'r17f01-fb-{uuid.uuid4().hex[:16]}'
        preserved_files = [{
            'filename': file.filename,
            'size': file_size,
            'ext': ext,
            'document_type': request.form.get('document_type', 'auto'),
            'remarks': (request.form.get('remarks', '') or '')[:200],
        }]
        fallback_task = AIManualFallbackTask(
            task_id=task_id,
            original_run_id=getattr(g, 'ai_run_id', None),
            reason='provider_fault',  # 紧急回滚统一归因为 provider_fault（人工处理）
            preserved_files=json.dumps(preserved_files, ensure_ascii=False),
            preserved_drafts='[]',
            status='pending',
        )
        db.session.add(fallback_task)
        try:
            db.session.commit()
        except Exception as exc:  # noqa: BLE001
            db.session.rollback()
            app.logger.warning(f'AI-R17-F01 写人工降级任务失败: {exc}')
        return jsonify({
            'status': 'fallback',
            'msg': 'AI 视觉识别已紧急回滚，已保留上传文件证据，请转人工处理',
            'fallback_task_id': task_id,
            'preserved_files': preserved_files,
        }), 200

    try:
        import base64
        # AI_TASK: AI-R04
        # 上传后先走图片预处理与质量门禁
        # 不可用图片提前给出中文提示，不破坏原文件（处理在副本上）
        original_bytes = file.read()
        try:
            from ai.documents.image_preprocessing import preprocess_image
            preprocess_result = preprocess_image(original_bytes, filename=file.filename)
        except Exception as preprocess_exc:  # noqa: BLE001 - 预处理失败降级走原图
            app.logger.warning(f'图片预处理异常，降级使用原图: {preprocess_exc}')
            preprocess_result = None

        if preprocess_result is not None and not preprocess_result.is_usable:
            # 致命质量问题：提前返回中文提示，不调用视觉模型
            return jsonify({
                'status': 'error',
                'msg': preprocess_result.blocked_reason or '图片质量不满足识别要求',
                'quality_issues': preprocess_result.errors,
            }), 400

        if preprocess_result is not None and preprocess_result.is_usable and preprocess_result.processed_bytes:
            # 使用处理后的图片（已校正方向/裁剪/压缩）
            img_data = base64.b64encode(preprocess_result.processed_bytes).decode('ascii')
            ext_normalized = preprocess_result.processed_mime.split('/')[-1]
            if ext_normalized == 'jpeg':
                ext_normalized = 'jpg'
            data_url = f'data:{preprocess_result.processed_mime};base64,{img_data}'
            # 保存预处理证据到 g 上下文，供审计追溯（不阻塞主流程）
            try:
                from flask import g as _g
                _g.ai_image_preprocess_evidence = preprocess_result.to_evidence_dict()
                if preprocess_result.warnings:
                    _g.ai_image_preprocess_warnings = list(preprocess_result.warnings)
            except Exception:  # noqa: BLE001
                pass
        else:
            # 降级：使用原图
            img_data = base64.b64encode(original_bytes).decode('ascii')
            data_url = f'data:image/{ext};base64,{img_data}'
        
        # 获取用户指定的单据类型和备注
        doc_type_hint = request.form.get('document_type', 'auto')
        remarks = request.form.get('remarks', '').strip()
        
        # 构建识别提示
        prompt = '''请仔细识别这张单据图片的内容。这可能是一张送货单、入库单、出库单、领料单、微信聊天截图或手写单据。

请提取以下信息：
1. 单据类型（入库/出库/调拨/盘点/微信通知）
2. 供应商/客户名称（如有）
3. 单据编号（如有）
4. 物料明细：编码、名称、规格、数量、单价、金额
5. 日期（如有）
6. 备注信息

请在回答末尾追加一个JSON代码块，格式如下：
```json
{
  "document_type": "in_order",
  "supplier": "供应商名称",
  "order_no": "单据编号",
  "date": "2024-01-15",
  "items": [
    {"code": "A001", "name": "物料名称", "spec": "规格", "quantity": 100, "price": 10.5}
  ],
  "remarks": "备注"
}
```
document_type可选：in_order（入库/送货）、out_order（出库/领料）、transfer（调拨）、check（盘点）、wechat（微信通知）。
无法识别的字段留空或省略。'''
        
        if doc_type_hint != 'auto':
            type_labels = {
                'in_order': '这是一张入库单/送货单',
                'out_order': '这是一张出库单/领料单',
                'wechat': '这是微信聊天截图，可能包含送货通知'
            }
            prompt = f'提示：{type_labels.get(doc_type_hint, "")}\n\n' + prompt
        
        if remarks:
            prompt += f'\n\n用户备注：{remarks}'
        
        # AI_TASK: AI-R09
        # 保存提取提示词到flask.g，供后续计算prompt_hash使用
        from flask import g as _g_prompt
        _g_prompt.ai_extraction_prompt = prompt
        
        # AI_TASK: AI-R05
        # 路由决策：可解释、可配置、可回滚
        try:
            from ai.documents.provider_router import route_document, call_with_evidence
            from flask import g as _g_router
            _blur_score = preprocess_result.metrics.blur_score if (preprocess_result and preprocess_result.metrics) else None
            _aspect = preprocess_result.metrics.aspect_ratio if (preprocess_result and preprocess_result.metrics) else None
            _routing_decision = route_document(
                source_type='image',
                has_image=True,
                image_blur_score=_blur_score,
                image_aspect_ratio=_aspect,
                vision_available=_ai_llm_configured() and _ai_llm_vision_enabled(),
            )
            _g_router.ai_routing_decision = _routing_decision.to_dict()
        except Exception as _route_exc:  # noqa: BLE001 - 路由决策失败不阻塞主流程
            app.logger.warning(f'路由决策异常，降级走默认视觉通道: {_route_exc}')
            _routing_decision = None

        # 调用视觉模型
        # AI_TASK: AI-R05
        # 重试证据保留：超时/错误JSON/不可用时可重试，即使全失败也不丢证据
        try:
            reply, extracted, error, _call_evidence = call_with_evidence(
                lambda: _ai_call_llm_vision(prompt, [{'data_url': data_url}]),
                max_retries=1,
            )
            try:
                from flask import g as _g_ev
                _g_ev.ai_vision_call_evidence = _call_evidence.to_dict()
            except Exception:  # noqa: BLE001
                pass
        except Exception as _ev_exc:  # noqa: BLE001 - 证据包裹异常降级直接调用
            app.logger.warning(f'证据包裹异常，降级直接调用: {_ev_exc}')
            reply, extracted, error = _ai_call_llm_vision(prompt, [{'data_url': data_url}])
            _call_evidence = None

        if error:
            # 不丢证据：返回降级提示 + 路由决策 + 调用证据
            _err_resp = {
                'status': 'error',
                'msg': f'视觉模型调用失败：{error}',
            }
            if _routing_decision is not None:
                _err_resp['routing_decision'] = _routing_decision.to_dict()
            if _call_evidence is not None:
                _err_resp['call_evidence'] = _call_evidence.to_dict()
            return jsonify(_err_resp), 500
        
        # 尝试创建草稿
        draft_info = None
        items_info = []
        delivery_match_info = None
        
        if extracted and isinstance(extracted, dict):
            items_raw = extracted.get('items', [])
            
            # 匹配物料并构建items_info
            for item in items_raw:
                if not isinstance(item, dict):
                    continue
                code = str(item.get('code') or '').strip()
                name = str(item.get('name') or '').strip()
                spec = str(item.get('spec') or '').strip()
                qty = item.get('quantity')
                try:
                    qty = float(qty) if qty is not None else None
                except (ValueError, TypeError):
                    qty = None
                
                # 尝试匹配物料
                matched = False
                if code or name:
                    material = _ai_material_query(code or name, limit=1)
                    if material and qty and qty > 0:
                        items_info.append({
                            'code': code,
                            'name': name,
                            'spec': spec,
                            'quantity': qty,
                            'matched': True
                        })
                        matched = True
                
                if not matched:
                    items_info.append({
                        'code': code,
                        'name': name,
                        'spec': spec,
                        'quantity': qty,
                        'matched': False
                    })
            
            # 尝试创建入库草稿
            doc_type = str(extracted.get('document_type') or '').strip().lower()
            if doc_type in ('in_order', 'wechat') and items_info:
                matched_items = [i for i in items_info if i['matched']]
                unmatched_items = [i for i in items_info if not i['matched']]

                # AI_TASK: AI-R06
                # 送货通知与采购订单联合匹配：误建采购申请防护、低置信度不自动选单、
                # 匹配依据和数量差异可见
                try:
                    from ai.documents.delivery_matcher import (
                        DeliveryMatchInput,
                        DeliveryMaterialLine,
                        match_delivery,
                    )
                    from flask import g as _g_dm
                    _dm_lines = tuple(
                        DeliveryMaterialLine(
                            code=str(i.get('code') or ''),
                            name=str(i.get('name') or ''),
                            spec=str(i.get('spec') or ''),
                            quantity=float(i.get('quantity') or 0),
                        )
                        for i in items_info
                    )
                    _dm_input = DeliveryMatchInput(
                        supplier_name=str(extracted.get('supplier') or ''),
                        purchase_order_no=str(extracted.get('order_no') or extracted.get('purchase_order_no') or ''),
                        expected_date=str(extracted.get('date') or ''),
                        lines=_dm_lines,
                        source_text=reply or '',
                        is_delivery_notice=(doc_type == 'wechat' or '送货' in (reply or '') or '发货' in (reply or '')),
                    )
                    _dm_result = match_delivery(
                        _dm_input,
                        query_open_purchase_orders=_ai_query_open_purchase_orders_for_delivery,
                        query_purchase_order_by_no=_ai_query_purchase_order_by_no,
                    )
                    _g_dm.ai_delivery_match = _dm_result.to_dict()
                    delivery_match_info = _dm_result.to_dict()
                except Exception as _dm_exc:  # noqa: BLE001 - 联合匹配失败不阻塞草稿创建
                    app.logger.warning(f'送货通知联合匹配异常，降级走原草稿流程: {_dm_exc}')
                    delivery_match_info = None

                # AI_TASK: AI-R07
                # 物料歧义/别名/单位换算/高风险规则旁路调用：
                # 对每条 OCR 提取的 item 执行加权评分匹配，结果存 flask.g 供
                # 前端展示候选清单和证据；不破坏现有 _ai_material_match_one 草稿路径。
                # 验收：歧义行 100% 人工确认；高风险物料错误自动确认数为 0；
                # 换算依据可追溯。
                material_governance_info = None
                try:
                    from ai.documents.material_governance import (
                        match_material_governance as _mg_match,
                    )
                    from flask import g as _g_mg
                    _mg_results = []
                    for _mg_item in items_info:
                        _mg_code = str(_mg_item.get('code') or '')
                        _mg_name = str(_mg_item.get('name') or '')
                        _mg_spec = str(_mg_item.get('spec') or '')
                        _mg_qty = float(_mg_item.get('quantity') or 0)
                        _mg_unit = str(_mg_item.get('unit') or '')
                        _mg_result = _mg_match(
                            _mg_code, _mg_name, _mg_spec,
                            query_materials_by_codes=_ai_mg_query_materials_by_codes,
                            query_materials_by_name=_ai_mg_query_materials_by_name,
                            query_aliases=_ai_mg_query_aliases,
                        )
                        _mg_dict = _mg_result.to_dict()
                        _mg_dict['input'] = {
                            'code': _mg_code, 'name': _mg_name,
                            'spec': _mg_spec, 'quantity': _mg_qty, 'unit': _mg_unit,
                        }
                        _mg_results.append(_mg_dict)
                    _g_mg.ai_material_governance = _mg_results
                    material_governance_info = _mg_results
                except Exception as _mg_exc:  # noqa: BLE001 - 物料治理失败不阻塞草稿创建
                    app.logger.warning(f'物料治理匹配异常，降级走原匹配: {_mg_exc}')
                    material_governance_info = None

                # AI_TASK: AI-R08
                # 文档确认台字段证据与重复风险聚合：
                # 汇总 OCR extracted/items + AI-R06 delivery_match + AI-R07
                # material_governance + AI-R01 idempotency 三方证据，产出统一的
                # DocumentConfirmationEvidence 结构供确认台前端渲染。
                # 验收：低置信度字段不能静默通过；重复风险可阻止建单；
                # 仓库人员可在浏览器完成整个流程。
                document_confirmation_info = None
                try:
                    from ai.documents.document_confirmation import (
                        build_confirmation_evidence as _dc_build,
                    )
                    from ai.draft_idempotency import compute_draft_idempotency_key
                    from flask import g as _g_dc

                    # 计算 source_hash 和 business_key（用于查 AIDraftIdempotency 重复草稿）
                    _dc_user_id = current_user.id if current_user.is_authenticated else 0
                    _dc_capability = 'in_order_draft'  # OCR 默认入库草稿能力
                    _dc_source = 'ocr_upload'
                    _dc_business = {
                        'supplier': str(extracted.get('supplier') or ''),
                        'order_no': str(extracted.get('order_no') or ''),
                        'items': [
                            {
                                'code': str(i.get('code') or ''),
                                'name': str(i.get('name') or ''),
                                'quantity': float(i.get('quantity') or 0),
                            }
                            for i in items_info
                        ],
                    }
                    _dc_idempotency_key = compute_draft_idempotency_key(
                        _dc_user_id, _dc_capability, _dc_source, _dc_business,
                    )
                    # source_hash 用 idempotency_key 衍生（前 32 位），business_key 用完整 key
                    _dc_source_hash = _dc_idempotency_key[:32]
                    _dc_business_key = _dc_idempotency_key

                    _dc_evidence = _dc_build(
                        extracted=extracted,
                        items=items_info,
                        delivery_match=delivery_match_info,
                        material_governance=material_governance_info,
                        query_existing_drafts=_ai_dc_query_existing_drafts,
                        source_hash=_dc_source_hash,
                        business_key=_dc_business_key,
                    )
                    _g_dc.ai_document_confirmation = _dc_evidence.to_dict()
                    document_confirmation_info = _dc_evidence.to_dict()
                except Exception as _dc_exc:  # noqa: BLE001 - 证据聚合失败不阻塞草稿创建
                    app.logger.warning(f'文档确认台证据聚合异常，降级走原草稿流程: {_dc_exc}')
                    document_confirmation_info = None

                # AI_TASK: AI-R09
                # 计算字段反馈元数据（模型/提示词/Schema 版本），供前端提交反馈时回传。
                # 不在此处记录反馈（反馈在确认台用户修正后由 /api/ai/document_feedback 记录）。
                _ff_prompt_hash = ''
                _ff_schema_version = 'document-extraction-v1'
                try:
                    from ai.documents.provider_evaluation import (
                        compute_prompt_hash as _ff_compute_ph,
                        compute_schema_version as _ff_compute_sv,
                        SCHEMA_VERSION as _ff_sv_const,
                    )
                    _ff_schema_version = _ff_compute_sv() or _ff_sv_const
                    # 提示词指纹：用当前文档提取提示词（若有），否则用空串占位
                    _ff_prompt_hash = _ff_compute_ph(getattr(_g_dc, 'ai_extraction_prompt', '') or '')
                except Exception:
                    pass

                if matched_items:
                    # 构建草稿消息
                    lines = []
                    for m in matched_items:
                        code = m['code'] or m['name']
                        qty_str = str(int(m['quantity'])) if m['quantity'] == int(m['quantity']) else str(m['quantity'])
                        lines.append(f'{code} {qty_str}')
                    draft_message = ' '.join(lines)

                    draft, error = _ai_create_in_order_draft(draft_message)
                    if not error and draft:
                        draft_info = {
                            'order_no': draft['order_no'],
                            'url': draft['url'],
                            'matched_count': len(matched_items),
                            'unmatched_count': len(unmatched_items)
                        }

        return jsonify({
            'status': 'success',
            'reply': reply,
            'extracted': extracted,
            'items': items_info,
            'draft': draft_info,
            'image_warnings': preprocess_result.warnings if preprocess_result else [],
            'delivery_match': delivery_match_info,
            'material_governance': material_governance_info,
            'document_confirmation': document_confirmation_info,
            'field_feedback_meta': {
                'model': _ai_llm_model()[:100] if _ai_llm_configured() else 'local-rules',
                'prompt_hash': _ff_prompt_hash,
                'schema_version': _ff_schema_version,
                'source': 'ocr_upload',
                'feedback_url': '/api/ai/document_feedback',
            },
        })
        
    except Exception as e:
        app.logger.error(f'单据OCR识别失败: {e}')
        return jsonify({'status': 'error', 'msg': f'识别失败：{str(e)}'}), 500


@app.route('/api/ai/document_feedback', methods=['POST'])
@login_required
def api_ai_document_feedback():
    """AI-R09 字段级反馈记录端点 + AI-R08-F01 字段确认记录。

    前端在文档确认台用户修正字段后调用，传入 evidence_fields + corrections +
    model/prompt_hash/schema_version/source + document_job_id，后端：
    1. 调用 build_field_correction_records 持久化到 AIFieldFeedback 表（AI-R09）
    2. 同时写入 AIDocumentFieldConfirmation 表（AI-R08-F01），供门禁校验使用
    
    验收：记录字段名/原值/新值/修正原因/是否采纳/模型/提示词/Schema 版本；
    不保存不必要的敏感原文（脱敏后存储）。
    """
    if current_user.role not in ('admin', 'warehouse', 'purchase'):
        return jsonify({'status': 'error', 'msg': '无权限'}), 403
    try:
        payload = request.get_json(silent=True) or {}
        evidence_fields = payload.get('evidence_fields') or []
        corrections = payload.get('corrections') or {}
        document_job_id = payload.get('document_job_id')
        model = str(payload.get('model') or (_ai_llm_model() if _ai_llm_configured() else 'local-rules'))[:100]
        prompt_hash = str(payload.get('prompt_hash') or '')[:20]
        schema_version = str(payload.get('schema_version') or 'document-extraction-v1')[:40]
        source = str(payload.get('source') or 'ocr_upload')[:30]

        if not isinstance(evidence_fields, list) or not evidence_fields:
            return jsonify({'status': 'error', 'msg': 'evidence_fields 不能为空'}), 400
        if not isinstance(corrections, dict):
            return jsonify({'status': 'error', 'msg': 'corrections 必须是字典'}), 400

        # AI-R09: 保存到 AIFieldFeedback 表
        from ai.documents.field_feedback import (
            build_field_correction_records as _ff_build,
        )
        records = _ff_build(
            evidence_fields=evidence_fields,
            corrections=corrections,
            model=model,
            prompt_hash=prompt_hash,
            schema_version=schema_version,
            source=source,
            save_feedback_record=_ai_ff_save_feedback_record,
        )
        
        # AI-R08-F01: 同时写入 AIDocumentFieldConfirmation 表（供门禁校验）
        confirmation_records_saved = 0
        if document_job_id:
            from datetime import datetime
            from ai.documents.document_confirmation_status import (
                STATUS_CORRECTED,
                STATUS_CONFIRMED_ORIGINAL,
            )
            
            user_id = current_user.id if current_user.is_authenticated else None
            now = datetime.now()
            
            # 遍历 corrections，为每个修正字段创建确认记录
            for field_key, correction_data in corrections.items():
                if not isinstance(correction_data, dict):
                    continue
                
                original_value = correction_data.get('original_value', '')
                confirmed_value = correction_data.get('confirmed_value', '')
                correction_reason = correction_data.get('reason', '')
                line_id = correction_data.get('line_id')  # 表头字段为 None
                
                # 判断确认状态
                if confirmed_value and confirmed_value != original_value:
                    confirmation_status = STATUS_CORRECTED
                else:
                    confirmation_status = STATUS_CONFIRMED_ORIGINAL
                
                # 创建确认记录
                confirmation_record = AIDocumentFieldConfirmation(
                    job_id=document_job_id,
                    item_id=None,  # 行级字段用 field_name 区分
                    field_name=field_key,
                    confirmation_status=confirmation_status,
                    original_value=str(original_value)[:500],
                    confirmed_value=str(confirmed_value)[:500],
                    correction_reason=(correction_reason or '')[:500],
                    evidence_source=source,
                    model=model,
                    prompt_version=prompt_hash,
                    schema_version=schema_version,
                    confirmed_by=user_id,
                    confirmed_at=now,
                )
                db.session.add(confirmation_record)
                confirmation_records_saved += 1
            
            if confirmation_records_saved > 0:
                db.session.commit()
                app.logger.info(f'文档任务 {document_job_id} 保存了 {confirmation_records_saved} 条字段确认记录')
        
        return jsonify({
            'status': 'success',
            'recorded_count': len(records),
            'confirmation_records_saved': confirmation_records_saved,
            'records': [r.to_dict() for r in records],
        })
    except Exception as e:
        db.session.rollback()
        app.logger.error(f'字段反馈记录失败: {e}')
        return jsonify({'status': 'error', 'msg': f'记录失败：{str(e)}'}), 500


@app.route('/api/ai/document_quality')
@login_required
def api_ai_document_quality():
    """AI-R09 文档质量指标聚合端点。

    查询 AIFieldFeedback 表，按来源/模型/Schema版本/字段名聚合准确率和修正率，
    检测质量下降。验收：可定位质量下降的字段和版本。
    支持查询参数：source/model/schema_version/field_name/baseline_schema_version。
    """
    if current_user.role not in ('admin', 'warehouse', 'purchase'):
        return jsonify({'status': 'error', 'msg': '无权限'}), 403
    try:
        source = str(request.args.get('source') or '')
        model = str(request.args.get('model') or '')
        schema_version = str(request.args.get('schema_version') or '')
        field_name = str(request.args.get('field_name') or '')
        baseline_schema_version = str(request.args.get('baseline_schema_version') or '')

        # 查当前版本记录
        current_dicts = _ai_ff_query_feedback_records(
            source=source, model=model, schema_version=schema_version,
            field_name=field_name, limit=2000,
        )
        baseline_dicts: list[dict] = []
        if baseline_schema_version:
            baseline_dicts = _ai_ff_query_feedback_records(
                source=source, model=model, schema_version=baseline_schema_version,
                field_name=field_name, limit=2000,
            )

        from ai.documents.field_feedback import (
            FieldCorrectionRecord,
            aggregate_quality_metrics as _ff_aggregate,
        )
        current_records = [
            FieldCorrectionRecord(
                field_name=d.get('field_name', ''),
                line_index=int(d.get('line_index') or -1),
                original_value=d.get('original_value', ''),
                corrected_value=d.get('corrected_value', ''),
                correction_reason=d.get('correction_reason', ''),
                adopted=bool(d.get('adopted')),
                model=d.get('model', ''),
                prompt_hash=d.get('prompt_hash', ''),
                schema_version=d.get('schema_version', ''),
                source=d.get('source', ''),
                created_at=d.get('created_at', ''),
            )
            for d in current_dicts
        ]
        baseline_records = [
            FieldCorrectionRecord(
                field_name=d.get('field_name', ''),
                line_index=int(d.get('line_index') or -1),
                original_value=d.get('original_value', ''),
                corrected_value=d.get('corrected_value', ''),
                correction_reason=d.get('correction_reason', ''),
                adopted=bool(d.get('adopted')),
                model=d.get('model', ''),
                prompt_hash=d.get('prompt_hash', ''),
                schema_version=d.get('schema_version', ''),
                source=d.get('source', ''),
                created_at=d.get('created_at', ''),
            )
            for d in baseline_dicts
        ] if baseline_dicts else None

        snapshot = _ff_aggregate(
            current_records,
            baseline_records=baseline_records,
        )
        return jsonify({
            'status': 'success',
            'snapshot': snapshot.to_dict(),
            'filters': {
                'source': source, 'model': model,
                'schema_version': schema_version,
                'field_name': field_name,
                'baseline_schema_version': baseline_schema_version,
            },
        })
    except Exception as e:
        app.logger.error(f'文档质量指标聚合失败: {e}')
        return jsonify({'status': 'error', 'msg': f'聚合失败：{str(e)}'}), 500


