@app.route('/material/export')
@login_required
def export_material():
    from openpyxl import Workbook
    wb = Workbook()
    ws = wb.active
    ws.title = '物料数据'
    headers = ['物料编码', '物料名称', '规格', '单位', '分类', '供应商', '当前库存', '单价']
    if inventory_alert_enabled():
        headers.extend(['最低库存', '安全库存'])
    ws.append(headers)
    search = request.args.get('search', '').strip()
    stock_filter = (request.args.get('stock_filter') or '').strip()
    if not inventory_alert_enabled() and stock_filter in {'low', 'normal'}:
        stock_filter = ''
    sort_by = request.args.get('sort', 'created_at')
    sort_order = request.args.get('order', 'desc')
    allowed_sorts = {'code', 'name', 'spec', 'category_id', 'supplier_id', 'stock', 'price', 'created_at'}
    if sort_by not in allowed_sorts:
        sort_by = 'created_at'
    if sort_order not in ('asc', 'desc'):
        sort_order = 'desc'
    query = Material.query.options(joinedload(Material.category), joinedload(Material.unit), joinedload(Material.supplier))
    if search:
        query = query.filter(
            db.or_(
                Material.code.like(f'%{search}%'),
                Material.name.like(f'%{search}%'),
                Material.spec.like(f'%{search}%')
            )
        )
    if stock_filter == 'low':
        query = query.filter(_material_low_stock_filter())
    sort_column = getattr(Material, sort_by, Material.created_at)
    query = query.order_by(sort_column.asc() if sort_order == 'asc' else sort_column.desc())
    max_rows = export_max_rows()
    total_rows = query.count()
    if total_rows > max_rows:
        flash(f'当前筛选结果 {total_rows} 条，超过系统参数设置的导出上限 {max_rows} 条，请缩小筛选范围后再导出。', 'warning')
        return redirect(url_for('material_list', search=search, stock_filter=stock_filter, sort=sort_by, order=sort_order))
    for m in query.all():
        row = [m.code, m.name, m.spec or '', m.unit.name if m.unit else '', m.category.name if m.category else '', m.supplier.name if m.supplier else '', m.stock or 0, m.price or 0]
        if inventory_alert_enabled():
            safety_stock = max(m.reorder_point or 0, m.min_stock or 0)
            row.extend([m.min_stock or 0, safety_stock])
        ws.append(row)
    output = io.BytesIO()
    wb.save(output)
    output.seek(0)
    return send_file(output, download_name='materials.xlsx', as_attachment=True)

@app.route('/material/import', methods=['POST'])
@require_role('warehouse')
@login_required
def import_material():
    file = request.files.get('file')
    if not file:
        if request.is_json or request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            return jsonify({'status': 'error', 'msg': '请选择要导入的物料文件'})
        flash('请选择要导入的物料文件', 'danger')
        return redirect(url_for('material_list'))
    _ext_ok, _ext_msg = validate_excel_extension(file.filename)
    if not _ext_ok:
        if request.is_json or request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            return jsonify({'status': 'error', 'msg': _ext_msg})
        flash(_ext_msg, 'danger')
        return redirect(url_for('material_list'))
    try:
        from openpyxl import load_workbook
        wb = load_workbook(file)
        ws = wb.active
        header_row = [str(cell).strip() if cell else '' for cell in next(ws.iter_rows(min_row=1, max_row=1, values_only=True))]
        col_map = {}
        for idx, h in enumerate(header_row):
            if not h:
                continue
            if '编码' in h or '代码' in h:
                col_map['code'] = idx
            elif '名称' in h or '名字' in h:
                col_map['name'] = idx
            elif h == '规格' or '规格' in h:
                col_map['spec'] = idx
            elif h == '单位' or '单位' in h:
                col_map['unit'] = idx
            elif h == '分类' or '类别' in h or '分类' in h:
                col_map['category'] = idx
            elif '供应商' in h:
                col_map['supplier'] = idx
            elif '单价' in h or '价格' in h:
                col_map['price'] = idx
            elif '安全库存' in h or '再订购点' in h or '再订货点' in h:
                col_map['safety_stock'] = idx
            elif '最低库存' in h or '最小库存' in h:
                col_map['min_stock'] = idx
        if 'code' not in col_map or 'name' not in col_map:
            if request.is_json or request.headers.get('X-Requested-With') == 'XMLHttpRequest':
                return jsonify({'status': 'error', 'msg': f'Excel表头缺少必要列（物料编码、物料名称）。检测到的表头：{", ".join(header_row)}'})
            flash(f'Excel表头缺少必要列（物料编码、物料名称）。检测到的表头：{", ".join(header_row)}', 'danger')
            return redirect(url_for('material_list'))
        data_rows = max((ws.max_row or 1) - 1, 0)
        max_rows = import_max_rows()
        if data_rows > max_rows:
            msg = f'本次导入 {data_rows} 行，超过系统参数设置的导入上限 {max_rows} 行，请拆分文件后再导入'
            if request.is_json or request.headers.get('X-Requested-With') == 'XMLHttpRequest':
                return jsonify({'status': 'error', 'msg': msg})
            flash(msg, 'danger')
            return redirect(url_for('material_list'))
        count = 0
        skip = 0
        skip_details = []
        warnings = []
        for row_idx, row in enumerate(ws.iter_rows(min_row=2, values_only=True), start=2):
            code = str(row[col_map['code']]).strip() if len(row) > col_map['code'] and row[col_map['code']] else ''
            name = str(row[col_map['name']]).strip() if len(row) > col_map['name'] and row[col_map['name']] else ''
            if not code or not name:
                skip += 1
                skip_details.append(f'第{row_idx}行：编码或名称为空')
                continue
            if Material.query.filter_by(code=code).first():
                skip += 1
                skip_details.append(f'第{row_idx}行：编码{code}已存在')
                continue
            spec = str(row[col_map['spec']]).strip() if 'spec' in col_map and len(row) > col_map['spec'] and row[col_map['spec']] else ''
            unit_name = str(row[col_map['unit']]).strip() if 'unit' in col_map and len(row) > col_map['unit'] and row[col_map['unit']] else ''
            unit = None
            if unit_name:
                unit = Unit.query.filter_by(name=unit_name).first()
                if not unit:
                    unit = Unit.query.filter_by(code=unit_name).first()
                if not unit:
                    unit = Unit.query.filter(db.func.lower(Unit.name) == db.func.lower(unit_name)).first()
                if not unit:
                    unit = Unit.query.filter(db.func.lower(Unit.code) == db.func.lower(unit_name)).first()
            if unit_name and not unit:
                unit = Unit(code=unit_name, name=unit_name)
                db.session.add(unit)
                db.session.flush()
                warnings.append(f'自动创建单位：{unit_name}')
            cat_name = str(row[col_map['category']]).strip() if 'category' in col_map and len(row) > col_map['category'] and row[col_map['category']] else ''
            category = None
            if cat_name:
                category = MaterialCategory.query.filter_by(name=cat_name).first()
                if not category:
                    category = MaterialCategory.query.filter_by(code=cat_name).first()
                if not category:
                    category = MaterialCategory.query.filter(db.func.lower(MaterialCategory.name) == db.func.lower(cat_name)).first()
                if not category:
                    category = MaterialCategory.query.filter(db.func.lower(MaterialCategory.code) == db.func.lower(cat_name)).first()
            if cat_name and not category:
                category = MaterialCategory(code=cat_name, name=cat_name)
                db.session.add(category)
                db.session.flush()
                warnings.append(f'自动创建分类：{cat_name}')
            sup_name = str(row[col_map['supplier']]).strip() if 'supplier' in col_map and len(row) > col_map['supplier'] and row[col_map['supplier']] else ''
            supplier = None
            if sup_name:
                supplier = Supplier.query.filter_by(name=sup_name).first()
                if not supplier:
                    supplier = Supplier.query.filter_by(code=sup_name).first()
                if not supplier:
                    supplier = Supplier.query.filter(db.func.lower(Supplier.name) == db.func.lower(sup_name)).first()
                if not supplier:
                    supplier = Supplier.query.filter(db.func.lower(Supplier.code) == db.func.lower(sup_name)).first()
            if sup_name and not supplier:
                supplier = Supplier(code=sup_name, name=sup_name)
                db.session.add(supplier)
                db.session.flush()
                warnings.append(f'自动创建供应商：{sup_name}')
            try:
                price_val = float(row[col_map['price']]) if 'price' in col_map and len(row) > col_map['price'] and row[col_map['price']] else 0
            except (ValueError, TypeError):
                price_val = 0
            min_stock_val = 0
            safety_stock_val = 0
            if inventory_alert_enabled():
                try:
                    min_stock_val = float(row[col_map['min_stock']]) if 'min_stock' in col_map and len(row) > col_map['min_stock'] and row[col_map['min_stock']] else 0
                except (ValueError, TypeError):
                    min_stock_val = 0
                try:
                    safety_stock_val = float(row[col_map['safety_stock']]) if 'safety_stock' in col_map and len(row) > col_map['safety_stock'] and row[col_map['safety_stock']] else min_stock_val
                except (ValueError, TypeError):
                    safety_stock_val = min_stock_val
                if safety_stock_val < min_stock_val:
                    safety_stock_val = min_stock_val
            material = Material(
                code=code,
                name=name,
                spec=spec,
                stock=0,
                price=price_val,
                min_stock=min_stock_val,
                reorder_point=safety_stock_val,
                unit_id=unit.id if unit else None,
                category_id=category.id if category else None,
                supplier_id=supplier.id if supplier else None
            )
            db.session.add(material)
            count += 1
        try:
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            if request.is_json or request.headers.get('X-Requested-With') == 'XMLHttpRequest':
                return jsonify({'status': 'error', 'msg': f'导入失败：{str(e)}'})
            flash(f'导入失败：{str(e)}', 'danger')
            return redirect(url_for('material_list'))
        msg = f'物料导入成功，共导入 {count} 条'
        if skip:
            msg += f'，跳过 {skip} 条'
        if skip_details:
            warnings.append(f'跳过详情：{"; ".join(skip_details[:20])}')
        if request.is_json or request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            resp = {'status': 'success', 'msg': msg, 'count': count}
            if warnings:
                resp['warnings'] = '；'.join(warnings)
            return jsonify(resp)
        flash(msg, 'success')
        for w in warnings:
            flash(w, 'warning')
    except Exception as e:
        db.session.rollback()
        if request.is_json or request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            return jsonify({'status': 'error', 'msg': f'物料导入失败：{str(e)}'})
        flash('物料导入失败，请稍后重试', 'danger')
    return redirect(url_for('material_list'))


@app.route('/import/out_order', methods=['POST'])
@require_role('warehouse', 'purchase')
@login_required
def import_out_order():
    file = request.files.get('file')
    if not file:
        if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            return jsonify({'status': 'error', 'msg': '请选择要导入的领料单文件'})
        flash('请选择要导入的领料单文件', 'danger')
        return redirect(url_for('batch_import_page'))
    _ext_ok, _ext_msg = validate_excel_extension(file.filename)
    if not _ext_ok:
        if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            return jsonify({'status': 'error', 'msg': _ext_msg})
        flash(_ext_msg, 'danger')
        return redirect(url_for('batch_import_page'))
    try:
        from openpyxl import load_workbook
        wb = load_workbook(file)
        ws = wb.active
        header_row = [str(cell).strip() if cell else '' for cell in next(ws.iter_rows(min_row=1, max_row=1, values_only=True))]
        col_map = {}
        for idx, h in enumerate(header_row):
            if not h:
                continue
            if '单据编号' in h or '领料单号' in h or '出库单号' in h or '订单编号' in h:
                col_map['order_no'] = idx
            elif h == '日期' or '日期' in h:
                col_map['date'] = idx
            elif h == '用途' or '用途' in h:
                col_map['purpose'] = idx
            elif '部门' in h or '领料' in h:
                col_map['department'] = idx
            elif '物料编码' in h or '编码' in h:
                col_map['material_code'] = idx
            elif '物料名称' in h or '名称' in h:
                col_map['material_name'] = idx
            elif h == '规格' or '规格' in h:
                col_map['spec'] = idx
            elif h == '单位' or '单位' in h:
                col_map['unit'] = idx
            elif '数量' in h:
                col_map['quantity'] = idx
            elif '单价' in h or '价格' in h:
                col_map['price'] = idx
            elif '金额' in h or '总额' in h:
                col_map['amount'] = idx
            elif '备注' in h:
                col_map['remark'] = idx
        if 'order_no' not in col_map:
            if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
                return jsonify({'status': 'error', 'msg': f'Excel表头缺少"单据编号"列。检测到的表头：{", ".join(header_row)}'})
            flash(f'Excel表头缺少"单据编号"列', 'danger')
            return redirect(url_for('batch_import_page'))
        count = 0
        skip = 0
        skip_details = []
        warnings = []
        current_order = None
        current_items = []
        for row_idx, row in enumerate(ws.iter_rows(min_row=2, values_only=True), start=2):
            def get_val(key):
                if key not in col_map:
                    return ''
                idx = col_map[key]
                if idx >= len(row):
                    return ''
                return str(row[idx]).strip() if row[idx] is not None else ''
            def get_num(key):
                if key not in col_map:
                    return 0
                idx = col_map[key]
                if idx >= len(row) or row[idx] is None:
                    return 0
                try:
                    return round_to_2_decimals(row[idx])
                except (ValueError, TypeError):
                    return 0
            order_no = get_val('order_no')
            if not order_no:
                skip += 1
                skip_details.append(f'第{row_idx}行：单据编号为空')
                continue
            if current_order and order_no != current_order.order_no:
                for item in current_items:
                    db.session.add(item)
                count += 1
                current_order = None
                current_items = []
            if not current_order:
                dept_name = get_val('department')
                department = Department.query.filter_by(name=dept_name).first() if dept_name else None
                if not department and dept_name:
                    department = Department.query.filter_by(code=dept_name).first()
                date_str = get_val('date')
                date_val = None
                if date_str:
                    try:
                        date_val = datetime.strptime(date_str, '%Y-%m-%d').date()
                    except ValueError:
                        try:
                            date_val = datetime.strptime(date_str, '%Y/%m/%d').date()
                        except ValueError:
                            try:
                                date_val = datetime.strptime(date_str, '%Y-%m-%d %H:%M:%S').date()
                            except ValueError:
                                pass
                if date_val is None and 'date' in col_map:
                    raw_date = row[col_map['date']] if col_map['date'] < len(row) else None
                    if raw_date is not None:
                        if hasattr(raw_date, 'date'):
                            date_val = raw_date.date()
                        elif hasattr(raw_date, 'year'):
                            date_val = raw_date
                current_order = OutOrder(
                    order_no=order_no,
                    date=date_val,
                    purpose='领料单' if get_val('purpose') == '生产出库' else get_val('purpose'),
                    business_type='领料单',
                    department_id=department.id if department else None,
                    remark=get_val('remark'),
                    operator_id=current_user.id
                )
                if OutOrder.query.filter_by(order_no=order_no).first():
                    skip += 1
                    skip_details.append(f'第{row_idx}行：单据编号{order_no}已存在')
                    current_order = None
                    continue
                db.session.add(current_order)
                db.session.flush()
            material_code = get_val('material_code')
            if material_code:
                material = Material.query.filter_by(code=material_code).first()
                if not material:
                    material = Material(
                        code=material_code,
                        name=get_val('material_name'),
                        spec=get_val('spec')
                    )
                    db.session.add(material)
                    db.session.flush()
                    warnings.append(f'自动创建物料：{material_code}')
                unit_name = get_val('unit')
                unit = Unit.query.filter_by(name=unit_name).first() if unit_name else None
                if not unit and unit_name:
                    unit = Unit.query.filter_by(code=unit_name).first()
                if not unit and unit_name:
                    unit = Unit(code=unit_name, name=unit_name)
                    db.session.add(unit)
                    db.session.flush()
                    warnings.append(f'自动创建单位：{unit_name}')
                if material and unit and not material.unit_id:
                    material.unit_id = unit.id
                qty = get_num('quantity')
                prc = get_num('price')
                amt = get_num('amount')
                if amt == 0:
                    amt = round_to_2_decimals(qty * prc)
                item = OutOrderItem(
                    out_order_id=current_order.id,
                    material_id=material.id if material else None,
                    quantity=qty,
                    price=prc,
                    amount=amt,
                    remark=(get_val('remark') or '').strip() or None
                )
                current_items.append(item)
        if current_order and current_items:
            for item in current_items:
                db.session.add(item)
            count += 1
        try:
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
                return jsonify({'status': 'error', 'msg': f'导入失败：{str(e)}'})
            flash(f'导入失败：{str(e)}', 'danger')
            return redirect(url_for('batch_import_page'))
        msg = f'领料单导入成功，共导入 {count} 张单据'
        if skip:
            msg += f'，跳过 {skip} 条'
        if skip_details:
            warnings.append(f'跳过详情：{"; ".join(skip_details[:20])}')
        if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            resp = {'status': 'success', 'msg': msg, 'count': count}
            if warnings:
                resp['warnings'] = '；'.join(warnings)
            return jsonify(resp)
        flash(msg, 'success')
        for w in warnings:
            flash(w, 'warning')
    except Exception as e:
        db.session.rollback()
        if request.headers.get('X-Requested-With') == 'XMLHttpRequest':
            return jsonify({'status': 'error', 'msg': f'领料单导入失败：{str(e)}'})
        flash(f'领料单导入失败：{str(e)}', 'danger')
    return redirect(url_for('batch_import_page'))


