# ==================== Print template ====================

def _normalize_html_template_content(content):
    content = (content or '').strip()
    if not content:
        return ''
    # Older help text documented {order.order_no}; support it while also accepting Jinja {{ ... }} and {% ... %}.
    return re.sub(
        r'(?<!\{)\{(?![%#\{])\s*((?:order|item|template|now)\b[\w\.\|\'"\(\), =+\-*/%]*)\s*\}(?!\})',
        r'{{ \1 }}',
        content,
    )


def _render_html_print_content(content, **context):
    content = _normalize_html_template_content(content)
    if not content:
        return ''
    try:
        # 使用沙箱环境渲染用户自定义模板，阻止访问 config、request 等 Flask 上下文敏感对象，
        # 防 SSTI 攻击（仅允许 order/item/template/now 等业务上下文变量）
        from jinja2.sandbox import SandboxedEnvironment
        from jinja2 import Environment
        env = SandboxedEnvironment(autoescape=True, trim_blocks=True, lstrip_blocks=True)
        # 仅暴露业务上下文，不暴露 Flask 全局（config/request/url_for 等）
        template = env.from_string(content)
        rendered = template.render(**context)
        # 渲染后用白名单净化器二次过滤，移除 <script>/<iframe>/on* 事件属性等
        # 危险内容，防止管理员账号被攻破后通过打印模板注入存储型 XSS
        return sanitize_print_html(rendered)
    except Exception as exc:
        app.logger.warning(f'打印HTML模板渲染失败: {exc}')
        return f'<div style="color:#b91c1c;border:1px solid #fecaca;padding:12px;">打印模板渲染失败：{escape(str(exc))}</div>'


def create_print_template(model, prefix):
    name = (request.form.get('name') or '').strip()
    template_type = (request.form.get('template_type') or 'excel').strip().lower()
    is_default = bool(request.form.get('is_default'))

    if not name:
        return jsonify({'status': 'error', 'msg': 'Template name is required'})

    excel_template_path = ''
    html_template_content = ''

    if template_type == 'excel':
        excel_file = request.files.get('excel_file')
        if not excel_file or not excel_file.filename:
            return jsonify({'status': 'error', 'msg': 'Excel template file is required'})
        excel_template_path = save_print_template_file(excel_file, prefix)
    else:
        html_template_content = (request.form.get('html_content') or '').strip()
        if not html_template_content:
            return jsonify({'status': 'error', 'msg': 'HTML template content is required'})

    try:
        if is_default:
            for template in model.query.filter_by(is_default=True).all():
                template.is_default = False

        template = model(
            name=name,
            template_type=template_type,
            excel_template_path=excel_template_path,
            html_template_content=html_template_content,
            is_default=is_default
        )
        db.session.add(template)
        try:
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            app.logger.error(f'数据库操作失败: {e}')
            return jsonify({'status': 'error', 'msg': '操作失败'}), 500
        return jsonify({'status': 'success', 'id': template.id})
    except Exception as e:
        db.session.rollback()
        return jsonify({'status': 'error', 'msg': '操作失败，请稍后重试'})


def set_default_print_template(model, template_id):
    template = model.query.get_or_404(template_id)
    try:
        for current in model.query.filter_by(is_default=True).all():
            current.is_default = False
        template.is_default = True
        db.session.commit()
        return jsonify({'status': 'success'})
    except Exception as e:
        db.session.rollback()
        return jsonify({'status': 'error', 'msg': '操作失败，请稍后重试'})


def delete_print_template(model, template_id):
    template = model.query.get_or_404(template_id)
    try:
        db.session.delete(template)
        db.session.commit()
        return jsonify({'status': 'success'})
    except Exception as e:
        db.session.rollback()
