@app.route('/stock_query')
@login_required
def stock_query():
    """库存查询"""
    search = (request.args.get('search') or '').strip()
    category_id = request.args.get('category_id', type=int)
    stock_filter = (request.args.get('stock_filter') or '').strip()
    sort_by = request.args.get('sort', 'code')
    sort_order = request.args.get('order', 'asc')
    allowed_sorts = {'code', 'name', 'spec', 'stock', 'min_stock', 'price', 'created_at', 'category_id', 'supplier_id'}
    if sort_by not in allowed_sorts:
        sort_by = 'code'
    if sort_order not in ('asc', 'desc'):
        sort_order = 'asc'
    if stock_filter not in ('low', 'normal'):
        stock_filter = ''
    if not inventory_alert_enabled() and stock_filter in {'low', 'normal'}:
        stock_filter = ''

    query = Material.query.options(joinedload(Material.unit), joinedload(Material.category), joinedload(Material.supplier))
    if search:
        search_like = f'%{search}%'
        query = query.filter(
            db.or_(
                Material.code.like(search_like),
                Material.name.like(search_like),
                Material.spec.like(search_like),
                Material.purpose.like(search_like),
                Supplier.name.like(search_like),
                MaterialCategory.name.like(search_like),
                Unit.name.like(search_like)
            )
        ).outerjoin(Supplier, Material.supplier_id == Supplier.id).outerjoin(
            MaterialCategory, Material.category_id == MaterialCategory.id
        ).outerjoin(Unit, Material.unit_id == Unit.id)
    if category_id:
        query = query.filter(Material.category_id == category_id)
    if stock_filter == 'low':
        query = query.filter(_material_low_stock_filter())
    elif stock_filter == 'normal':
        query = query.filter(_material_normal_stock_filter())
    sort_col = getattr(Material, sort_by, Material.code)
    query = query.order_by(sort_col.asc() if sort_order == 'asc' else sort_col.desc())
    materials = query.all()
    location_map = {}
    if location_management_enabled() and materials:
        material_ids = [material.id for material in materials]
        rows = LocationInventory.query.filter(LocationInventory.material_id.in_(material_ids)).order_by(
            LocationInventory.location.asc()
        ).all()
        for row in rows:
            if not row.quantity:
                continue
            location_map.setdefault(row.material_id, []).append(row)
    categories = MaterialCategory.query.order_by(MaterialCategory.code.asc(), MaterialCategory.name.asc()).all()
    filters = {'search': search, 'category_id': category_id or '', 'stock_filter': stock_filter}
    return render_template('stock_query.html', materials=materials, categories=categories, filters=filters, sort_by=sort_by, sort_order=sort_order, location_map=location_map)


@app.route('/api/query/search', methods=['POST'])
@login_required
def api_query_search():
    """模糊查询物料"""
    keyword = request.form.get('keyword', '').strip()
    if not keyword:
        return jsonify({'status': 'error', 'msg': '请输入搜索关键词'})

    keyword_like = f'%{keyword}%'
    materials = Material.query.outerjoin(Supplier, Material.supplier_id == Supplier.id).outerjoin(
        MaterialCategory, Material.category_id == MaterialCategory.id
    ).outerjoin(Unit, Material.unit_id == Unit.id).filter(
        db.or_(
            Material.code.like(keyword_like),
            Material.name.like(keyword_like),
            Material.spec.like(keyword_like),
            Material.purpose.like(keyword_like),
            Supplier.name.like(keyword_like),
            MaterialCategory.name.like(keyword_like),
            Unit.name.like(keyword_like)
        )
    ).order_by(Material.code.asc()).all()
    
    data = []
    for m in materials:
        data.append({
            'id': m.id,
            'code': m.code,
            'name': m.name,
            'spec': m.spec or '',
            'stock': m.stock or 0,
            'unit': m.unit.name if m.unit else '',
            'supplier': m.supplier.name if m.supplier else ''
        })
    
    return jsonify({'status': 'success', 'data': data})


@app.route('/alert')
@login_required
def alert_list():
    if not inventory_alert_enabled():
        flash('库存预警/安全库存尚未启用，当前不显示库存不足预警。', 'info')
        return redirect(url_for('material_list'))

    search = (request.args.get('search') or '').strip()
    status_filter = (request.args.get('status') or '').strip()
    category_id = request.args.get('category_id', type=int) or 0
    supplier_id = request.args.get('supplier_id', type=int) or 0
    sort_by = request.args.get('sort', 'code')
    sort_order = request.args.get('order', 'asc')
    if status_filter not in ('low', 'danger', 'normal', 'disabled'):
        status_filter = ''
    if sort_by not in {'code', 'name', 'spec', 'category', 'supplier', 'stock', 'min_stock', 'safety_stock', 'status'}:
        sort_by = 'code'
    if sort_order not in ('asc', 'desc'):
        sort_order = 'asc'

    material_query = Material.query.options(
        joinedload(Material.category),
        joinedload(Material.supplier)
    )
    if category_id:
        material_query = material_query.filter(Material.category_id == category_id)
    if supplier_id:
        material_query = material_query.filter(Material.supplier_id == supplier_id)
    materials = material_query.order_by(Material.code.asc(), Material.id.asc()).all()
    low_stock = []
    danger_stock = []
    normal_stock = []
    alert_materials = []

    status_terms = {
        'low': {'low', '最低', '低于最低库存', '低于最小库存', '库存不足', '不足'},
        'danger': {'danger', '安全', '低于安全库存', '预警'},
        'normal': {'normal', '正常', '库存正常'},
        'disabled': {'disabled', 'ignore', '忽略', '不预警', '无需预警', '未启用预警'},
    }
    status_labels = {
        'low': '低于最低库存',
        'danger': '低于安全库存',
        'normal': '正常',
        'disabled': '未启用预警',
    }
    search_status = ''
    if search:
        search_lower = search.lower()
        for key, terms in status_terms.items():
            if any(search_lower == term.lower() or search_lower in term.lower() or term.lower() in search_lower for term in terms):
                search_status = key
                break

    for material in materials:
        stock, min_stock, safety_stock, alert_status = _material_alert_status_values(material)

        display_item = {
            'id': material.id,
            'code': material.code,
            'name': material.name,
            'spec': material.spec,
            'category': material.category.name if material.category else '',
            'supplier': material.supplier.name if material.supplier else '',
            'stock': stock,
            'min_stock': min_stock,
            'safety_stock': safety_stock,
            'status': alert_status,
            'status_label': status_labels[alert_status],
        }

        if alert_status == 'low':
            low_stock.append(display_item)
        elif alert_status == 'danger':
            danger_stock.append(display_item)
        elif alert_status == 'normal':
            normal_stock.append(display_item)

        include_item = alert_status in ('low', 'danger')
        if status_filter:
            include_item = alert_status == status_filter
        if search:
            haystack = ' '.join([
                str(material.code or ''),
                str(material.name or ''),
                str(material.spec or ''),
                str(material.category.name if material.category else ''),
                str(material.supplier.name if material.supplier else ''),
                status_labels[alert_status],
                alert_status,
            ]).lower()
            include_item = include_item and (search.lower() in haystack or search_status == alert_status)
        if include_item:
            alert_materials.append(display_item)

    reverse = sort_order == 'desc'
    if sort_by == 'status':
        status_rank = {'low': 0, 'danger': 1, 'normal': 2, 'disabled': 3}
        alert_materials.sort(key=lambda item: (status_rank.get(item['status'], 9), item['code'] or ''), reverse=reverse)
    else:
        alert_materials.sort(key=lambda item: (item.get(sort_by) if item.get(sort_by) is not None else ''), reverse=reverse)

    disabled_stock_count = len(materials) - len(low_stock) - len(danger_stock) - len(normal_stock)
    filters = {'search': search, 'status': status_filter, 'category_id': category_id, 'supplier_id': supplier_id}
    categories = MaterialCategory.query.order_by(MaterialCategory.code.asc(), MaterialCategory.id.asc()).all()
    suppliers = Supplier.query.order_by(Supplier.code.asc(), Supplier.id.asc()).all()
    return render_template('alert.html',
                         alert_materials=alert_materials,
                         low_stock_count=len(low_stock),
                         danger_stock_count=len(danger_stock),
                         normal_stock_count=len(normal_stock),
                         disabled_stock_count=disabled_stock_count,
                         categories=categories,
                         suppliers=suppliers,
                         filters=filters,
                         sort_by=sort_by,
                         sort_order=sort_order)


def _parse_alert_threshold_value(payload, key, label):
    value = payload.get(key)
    if isinstance(value, list):
        value = value[0] if value else None
    if value is None or str(value).strip() == '':
        return False, None, None
    try:
        parsed = float(str(value).strip())
    except (TypeError, ValueError):
        return False, None, f'{label}必须是数字'
    if parsed < 0:
        return False, None, f'{label}不能小于 0'
    return True, round_to_2_decimals(parsed), None


def _parse_alert_material_ids(raw_ids):
    ids = []
    seen = set()
    for raw_id in raw_ids or []:
        try:
            material_id = int(raw_id)
        except (TypeError, ValueError):
            continue
        if material_id <= 0 or material_id in seen:
            continue
        seen.add(material_id)
        ids.append(material_id)
    return ids


@app.route('/alert/batch_update_thresholds', methods=['POST'])
@require_role('warehouse')
@login_required
def batch_update_alert_thresholds():
    if not inventory_alert_enabled():
        return jsonify({'status': 'error', 'msg': '库存预警/安全库存尚未启用'}), 400

    payload = request.get_json(silent=True) if request.is_json else request.form.to_dict(flat=False)
    payload = payload or {}
    action = payload.get('action')
    if isinstance(action, list):
        action = action[0] if action else ''
    action = (action or '').strip()
    raw_ids = payload.get('ids', [])
    if isinstance(raw_ids, str):
        try:
            raw_ids = json.loads(raw_ids)
        except (TypeError, ValueError, json.JSONDecodeError):
            raw_ids = [raw_ids]
    ids = _parse_alert_material_ids(raw_ids)
    if not ids:
        return jsonify({'status': 'error', 'msg': '请先选择要设置的物料'}), 400

    disable_alert = action == 'disable'
    if disable_alert:
        update_min = True
        update_safety = True
        min_stock = 0
        safety_stock = 0
    else:
        update_min, min_stock, min_error = _parse_alert_threshold_value(payload, 'min_stock', '最低库存')
        if min_error:
            return jsonify({'status': 'error', 'msg': min_error}), 400
        update_safety, safety_stock, safety_error = _parse_alert_threshold_value(payload, 'safety_stock', '安全库存')
        if safety_error:
            return jsonify({'status': 'error', 'msg': safety_error}), 400
        if not update_min and not update_safety:
            return jsonify({'status': 'error', 'msg': '最低库存和安全库存至少填写一项'}), 400
        if update_min and update_safety and safety_stock < min_stock:
            return jsonify({'status': 'error', 'msg': '安全库存不能低于最低库存'}), 400

    materials = Material.query.filter(Material.id.in_(ids)).order_by(Material.code.asc(), Material.id.asc()).all()
    if not materials:
        return jsonify({'status': 'error', 'msg': '选择的物料不存在'}), 404

    if update_safety and not update_min:
        max_min_stock = max((material.min_stock or 0) for material in materials)
        if safety_stock < max_min_stock:
            return jsonify({
                'status': 'error',
                'msg': f'安全库存不能低于已选物料中的最高最低库存（{round_to_2_decimals(max_min_stock)}）'
            }), 400

    updated_codes = []
    for material in materials:
        if update_min:
            material.min_stock = min_stock
            if not update_safety and (material.reorder_point or 0) < min_stock:
                material.reorder_point = min_stock
        if update_safety:
            material.reorder_point = safety_stock
        updated_codes.append(material.code)

    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        app.logger.error(f'批量更新库存预警值失败: {e}')
        return jsonify({'status': 'error', 'msg': '批量设置失败，请稍后重试'}), 500

    changes = []
    if disable_alert:
        changes.append('取消预警')
    else:
        if update_min:
            changes.append(f'最低库存={min_stock:g}')
        if update_safety:
            changes.append(f'安全库存={safety_stock:g}')
    log_operation(
        '批量取消库存预警' if disable_alert else '批量设置库存预警值',
        f'物料 {len(materials)} 个，{", ".join(changes)}',
        'material'
    )
    return jsonify({
        'status': 'success',
        'msg': f'已取消 {len(materials)} 个物料的库存预警' if disable_alert else f'已更新 {len(materials)} 个物料的预警值',
        'updated': len(materials),
        'codes': updated_codes[:20],
    })


@app.route('/pending_documents')
@login_required
def pending_documents():
    module_filter = (request.args.get('module') or '').strip()
    status_filter = (request.args.get('status') or '').strip()
    search = (request.args.get('search') or '').strip()
    allowed_modules = {item['key'] for item in PENDING_DOCUMENT_MODULES}
    if module_filter not in allowed_modules:
        module_filter = ''
    allowed_statuses = {'pending', 'approved', 'processing'}
    if status_filter not in allowed_statuses:
        status_filter = ''

    rows = _build_pending_document_rows(module_filter, status_filter, search)
    module_counts = []
    total_count = 0
    for config in PENDING_DOCUMENT_MODULES:
        count = config['model'].query.filter(config['model'].status.in_(config['status'])).count()
        module_counts.append({
            'key': config['key'],
            'label': config['label'],
            'icon': config.get('icon') or 'bi-file-earmark-text',
            'count': count,
        })
        total_count += count

    status_counts = {
        'pending': sum(config['model'].query.filter_by(status='pending').count() for config in PENDING_DOCUMENT_MODULES if 'pending' in config['status']),
        'approved': PurchaseRequest.query.filter_by(status='approved').count(),
        'processing': SubcontractOrder.query.filter_by(status='processing').count(),
    }
    return render_template(
        'pending_documents.html',
        rows=rows,
        module_counts=module_counts,
        total_count=total_count,
        status_counts=status_counts,
        filters={'module': module_filter, 'status': status_filter, 'search': search},
    )


