# ==================== Sales management ====================
def generate_sales_order_no():
    prefix = 'SO'
    month = datetime.now().strftime('%y%m')
    last = SalesOrder.query.filter(SalesOrder.order_no.like(f'{prefix}{month}%')).order_by(SalesOrder.id.desc()).first()
    sequence = 1
    if last:
        try:
            sequence = int(last.order_no[-4:]) + 1
        except (TypeError, ValueError):
            sequence = SalesOrder.query.filter(SalesOrder.order_no.like(f'{prefix}{month}%')).count() + 1
    return f'{prefix}{month}{sequence:04d}'


def sales_status_label(status):
    return {
        'draft': '草稿',
        'confirmed': '已确认',
        'closed': '已完成',
        'cancelled': '已取消',
    }.get(status, status or '-')


def sales_shipment_status_label(status):
    return {'pending': '待发货', 'partial': '部分发货', 'shipped': '已发货'}.get(status, status or '-')


def recalculate_sales_order(order):
    """重新计算销售订单的金额、税额和发货状态。

    - price 视为含税单价；tax_included_amount = quantity * price
    - untaxed_price = price / (1 + tax_rate)；untaxed_amount = tax_included_amount / (1 + tax_rate)
    - tax_amount = tax_included_amount - untaxed_amount
    - amount 字段保留为含税金额，兼容旧逻辑
    """
    total_included = 0
    total_untaxed = 0
    total_tax = 0
    shipped_total_qty = 0
    total_quantity = 0
    shipped_amount = 0
    for item in order.items:
        qty = max(item.quantity or 0, 0)
        price = item.price or 0
        tax_rate = item.tax_rate if item.tax_rate is not None else 0.13
        if tax_rate < 0:
            tax_rate = 0
        included = round_to_2_decimals(qty * price)
        untaxed = round_to_2_decimals(included / (1 + tax_rate)) if (1 + tax_rate) > 0 else included
        tax = round_to_2_decimals(included - untaxed)
        untaxed_price = round(price / (1 + tax_rate), 4) if (1 + tax_rate) > 0 and qty > 0 else 0
        item.untaxed_price = untaxed_price
        item.untaxed_amount = untaxed
        item.tax_amount = tax
        item.tax_included_amount = included
        item.amount = included  # 兼容旧逻辑：amount = 含税金额
        item.shipped_quantity = min(max(item.shipped_quantity or 0, 0), qty)
        total_included += included
        total_untaxed += untaxed
        total_tax += tax
        total_quantity += qty
        shipped_total_qty += item.shipped_quantity or 0
        shipped_amount += round_to_2_decimals((item.shipped_quantity or 0) * price)
    order.total_amount = round_to_2_decimals(total_included)
    order.untaxed_amount = round_to_2_decimals(total_untaxed)
    order.tax_amount = round_to_2_decimals(total_tax)
    order.shipped_amount = round_to_2_decimals(shipped_amount)
    order.remaining_amount = round_to_2_decimals(total_included - shipped_amount)
    if total_quantity <= 0 or shipped_total_qty <= 0:
        order.shipment_status = 'pending'
        if order.status not in ('draft', 'cancelled'):
            order.status = 'confirmed'
    elif shipped_total_qty + STOCK_COMPARE_EPSILON >= total_quantity:
        order.shipment_status = 'shipped'
        order.status = 'closed'
    else:
        order.shipment_status = 'partial'
        order.status = 'confirmed'


def sync_sales_order_shipment(outbound, quantity_sign=1):
    # 优先使用外键关联，兜底 purpose 字符串解析
    order = None
    if outbound.source_sales_order_id:
        order = SalesOrder.query.get(outbound.source_sales_order_id)
    if not order:
        source_match = re.search(r'来源销售订单\s+([^\s]+)', outbound.purpose or '')
        if source_match:
            order = SalesOrder.query.filter_by(order_no=source_match.group(1)).first()
    if not order:
        return None
    item_by_material = {item.material_id: item for item in order.items}
    for outbound_item in outbound.items:
        sales_item = item_by_material.get(outbound_item.material_id)
        if not sales_item:
            continue
        sales_item.shipped_quantity = max(0, (sales_item.shipped_quantity or 0) + quantity_sign * (outbound_item.quantity or 0))
    recalculate_sales_order(order)
    return order

def build_sales_outbound_draft(order):
    # 优先通过外键查找待完成草稿，兜底 purpose 字符串
    pending_draft = OutOrder.query.filter(
        db.or_(
            OutOrder.source_sales_order_id == order.id,
            OutOrder.purpose == f'来源销售订单 {order.order_no}',
        ),
        OutOrder.status == 'pending',
    ).order_by(OutOrder.id.desc()).first()
    if pending_draft:
        return pending_draft, 'existing'
    remaining_items = [item for item in order.items if (item.quantity or 0) - (item.shipped_quantity or 0) > STOCK_COMPARE_EPSILON]
    if not remaining_items:
        recalculate_sales_order(order)
        return None, 'completed'
    outbound = OutOrder(order_no=generate_order_no('OU'), date=order.date, customer=order.customer.name if order.customer else '', business_type='销售出库', warehouse=order.warehouse, purpose=f'来源销售订单 {order.order_no}', source_sales_order_id=order.id, remark=order.remark, status='pending', operator_id=current_user.id)
    db.session.add(outbound)
    db.session.flush()
    for item in remaining_items:
        remaining_quantity = round_to_2_decimals((item.quantity or 0) - (item.shipped_quantity or 0))
        db.session.add(OutOrderItem(out_order_id=outbound.id, material_id=item.material_id, quantity=remaining_quantity, price=item.price, amount=round_to_2_decimals(remaining_quantity * (item.price or 0)), remark=f'来源销售订单 {order.order_no}'))
    order.shipment_order_no = outbound.order_no
    order.shipment_status = 'pending'
    return outbound, 'created'


